def minimumTotal(triangle):
    if not triangle:
        return 0
    memo = triangle[-1]
    for i in range(len(triangle) - 2, -1, -1):
        for j in range(len(triangle[i])):
            memo[j] = min(memo[j], memo[j + 1]) + triangle[i][j]
    return memo[0]

