class Solution:
    def racecar(self, target: int) -> int:
        q = [(0, 1)]
        steps = 0
        
        while q:
            num = len(q)
            for i in range(num):
                pos, speed = q.pop(0)
                if pos == target:
                    return steps
                q.append((pos+speed, speed*2))
                rev_speed = -1 if speed > 0 else 1
                if (pos+speed) < target and speed < 0 or (pos+speed) > target and speed > 0:
                    q.append((pos, rev_speed))
            steps += 1

class Solution:
    def hasPathSum(self, root: TreeNode, targetSum: int) -> bool:
	
		# Recursive dfs. 
		# Accumulate the number as you traverse the tree and compare with targetSum
		# T: O(N)
		# S: O(N)
		
        return self.dfs(root, targetSum, 0)
        
    def dfs(self, root, targetSum, total):
        if not root:
            return False
        
        total += root.val
        #print(total)
        
        if not root.left and not root.right:
            return total == targetSum
        
        return self.dfs(root.left, targetSum, total) or self.dfs(root.right, targetSum, total) 
        
        
    def hasPathSum(self, root: TreeNode, targetSum: int) -> bool:
        
        # Iterative DFS
		# Same logic
        # T: O(N)
        # S: O(N)
        
        if not root:
            return False
        
        stack = [root]
        total = root.val
        while stack:
            node = stack.pop()
            #print(node.val)
            if node.left:
                node.left.val += node.val
                stack.append(node.left)
                
            if node.right:
                node.right.val += node.val
                stack.append(node.right)
            
            if not node.right and not node.left:
                if node.val == targetSum:
                    return True
        return False
		
	def hasPathSum(self, root: TreeNode, targetSum: int) -> bool:
        
        # Optimized recursive DFS
		# Instead of accumulation, we substract the value of node from the targetSum
        # T: O(N)
        # S: O(N)
        
        if not root:
            return False
        
        targetSum -= root.val
        if not root.left and not root.right:
            return targetSum == 0
        
        return self.hasPathSum(root.left, targetSum) or self.hasPathSum(root.right, targetSum)

