class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        if maxChoosableInteger >= desiredTotal:
            return True
        if (1 + maxChoosableInteger) * maxChoosableInteger / 2 < desiredTotal:
            return False
        memo = {}

        def dfs(used, total):
            if used in memo:
                return memo[used]
            if total >= desiredTotal:
                return False
            for i in range(maxChoosableInteger):
                cur = 1 << i
                if cur & used == 0:
                    if not dfs(used | cur, total + i + 1):
                        memo[used] = True
                        return True
            memo[used] = False
            return False

        return dfs(0, 0)

def collect_points(grid):
    n = len(grid[0])
    points = 0
    
    # first robot moves
    r, c = 0, 0
    while c < n - 1:
        points += grid[r][c]
        grid[r][c] = 0
        if grid[1-r][c+1] >= grid[r+1][c]:
            c += 1
        else:
            r = 1 - r
    
    # second robot moves
    r, c = 0, 0
    while c < n - 1:
        points += grid[r][c]
        grid[r][c] = 0
        if grid[1-r][c+1] <= grid[r+1][c]:
            c += 1
        else:
            r = 1 - r
    
    return points

