def minimumBalls(board, hand):
    def removeGroups(board):
        i, n = 0, len(board)
        while i < n:
            j = i
            while j < n and board[j] == board[i]: j += 1
            if j - i >= 3: return removeGroups(board[:i] + board[j:])
            i = j
        return board
    def backtrack(board, count, hand):
        if not board: return count
        if not hand: return -1
        ans = float('inf')
        for i, c in enumerate(hand):
            for j in range(len(board) + 1):
                new_board = removeGroups(board[:j] + c + board[j:])
                new_hand = hand[:i] + hand[i+1:]  # remove used ball from hand
                ans = min(ans, backtrack(new_board, count+1, new_hand))
        return ans
    res = backtrack(board, 0, hand)
    return res if res < float('inf') else -1

class Solution:
    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:
        m, n = len(mat), len(mat[0])
        queue = []
        for i in range(m):
            for j in range(n):
                if mat[i][j] == 0:
                    queue.append((i, j))
                else:
                    mat[i][j] = float('inf')
        dirs = [(1, 0), (0, 1), (-1, 0), (0, -1)]
        while queue:
            x, y = queue.pop(0)
            for dx, dy in dirs:
                nx, ny = x+dx, y+dy
                if 0 <= nx < m and 0 <= ny < n and mat[nx][ny] > mat[x][y] + 1:
                    mat[nx][ny] = mat[x][y] + 1
                    queue.append((nx, ny))
        return mat

class Solution:
    def leastBricks(self, wall: List[List[int]]) -> int:
        hashmap = {}
        max_count = 0
        for row in wall:
            count = 0
            for brick in row[:-1]:
                count += brick
                if count not in hashmap:
                    hashmap[count] = 0
                hashmap[count] += 1
                max_count = max(max_count, hashmap[count])
        return len(wall) - max_count

