class Solution:
    def numBusesToDestination(self, routes: List[List[int]], source: int, target: int) -> int:
        if source == target:
            return 0
        # create a hashmap to store stops by bus numbers
        stop_by_bus = collections.defaultdict(set)
        for i in range(len(routes)):
            for j in range(len(routes[i])):
                stop_by_bus[routes[i][j]].add(i)
                
        queue = collections.deque()
        seen = set()
        # start with source bus stop and initialize count to 1
        queue.append(source)
        seen.add(source)
        count = 1
        
        # BFS
        while queue:
            for i in range(len(queue)):
                stop = queue.popleft()
                for bus in stop_by_bus[stop]:
                    if bus in seen:
                        continue
                    for next_stop in routes[bus]:
                        if next_stop == target:
                            return count
                        if next_stop not in seen:
                            queue.append(next_stop)
                            seen.add(next_stop)
                    # mark the bus as seen
                    seen.add(bus)
            count += 1
        # if target is unreachable
        return -1

