class Solution:
    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        total = sum(nums)
        if total < abs(target) or (total + target) % 2 != 0:
            return 0
        s = (total + target)//2
        dp = [0] * (s+1)
        dp[0] = 1
        for num in nums:
            for i in range(s, num-1, -1):
                dp[i] += dp[i-num]
        return dp[s]

def updateBoard(board, click):
    row, col = click
    if board[row][col] == 'M':
        board[row][col] = 'X'
        return board
    elif board[row][col] == 'E':
        revealSquare(board, row, col)
    return board

def revealSquare(board, row, col):
    if (row < 0 or row >= len(board) or col < 0 or col >= len(board[0])) or board[row][col] != 'E':
        return
    count = countAdjacentMines(board, row, col)
    if count == 0:
        board[row][col] = 'B'
        for i in range(-1, 2):
            for j in range(-1, 2):
                if i != 0 or j != 0:
                    revealSquare(board, row + i, col + j)
    else:
        board[row][col] = str(count)

def countAdjacentMines(board, row, col):
    count = 0
    for i in range(-1, 2):
        for j in range(-1, 2):
            if i == 0 and j == 0:
                continue
            r = row + i
            c = col + j
            if r < 0 or r >= len(board) or c < 0 or c >= len(board[0]):
                continue
            if board[r][c] == 'M' or board[r][c] == 'X':
                count += 1
    return count

