class Solution:
    def deserialize(self, s: str) -> NestedInteger:
        stack = []
        i, n = 0, len(s)
        while i < n:
            if s[i] == '[':
                stack.append(NestedInteger())
                i += 1
            elif s[i] == ']':
                top = stack.pop()
                if stack:
                    stack[-1].add(top)
                else:
                    return top
                i += 1
            elif s[i] == ',':
                i += 1
            else:
                j = i
                while j < n and s[j].isdigit() or s[j] == '-':
                    j += 1
                stack[-1].add(int(s[i:j]))
                i = j

def slowestKey(keyPressed, releaseTimes):
    durations = [releaseTimes[0]]
    for i in range(1,len(releaseTimes)):
        durations.append(releaseTimes[i] - releaseTimes[i-1])
    keyDurations = dict(zip(keyPressed,durations))
    maxDuration = max(keyDurations.values())
    candidates = [key for key, value in keyDurations.items() if value == maxDuration]
    return max(candidates)

