def max_jump(arr, d):
    max_visits = 0
    for i in range(len(arr)):
        j = i + 1
        while j < len(arr) and j - i <= d and arr[i] > arr[j]:
            k = j + 1
            while k < len(arr) and k <= j + d:
                if arr[i] > arr[k] and arr[j] > arr[k]:
                    max_visits = max(max_visits, k - i)
                k += 1
            j += 1
    return max_visits

class Node:
    def __init__(self, val, neighbors):
        self.val = val
        self.neighbors = neighbors
        
def cloneGraph(node):
    if not node:
        return None

    nodes = {}
    queue = [node]
    # Create a new node with the same value as the given node
    # and add it to the nodes dictionary
    new_node = Node(node.val, [])
    nodes[node] = new_node

    while queue:
        curr_node = queue.pop(0)
        for neighbor in curr_node.neighbors:
            if neighbor not in nodes:
                # Create a new node with the same value as the neighbor
                # and add it to the nodes dictionary
                new_neighbor = Node(neighbor.val, [])
                nodes[neighbor] = new_neighbor
                # Add the new node to the current node's neighbors list
                nodes[curr_node].neighbors.append(new_neighbor)
                # Add the neighbor to the queue to be processed
                queue.append(neighbor)
            else:
                # If the neighbor has already been created, just add it
                # to the current node's neighbors list
                nodes[curr_node].neighbors.append(nodes[neighbor])

    return nodes[node]

