def last_number(nums):
    while len(nums) > 1:
        n = len(nums)
        newNums = [0] * (n // 2)
        for i in range(n // 2):
            if i % 2 == 0:
                newNums[i] = min(nums[2*i], nums[2*i + 1])
            else:
                newNums[i] = max(nums[2*i], nums[2*i + 1])
        nums = newNums
    return nums[0]

class Solution:
    def rob(self, nums: List[int]) -> int:
        
        prev_max = curr_max = 0
        
        for num in nums:
            temp = curr_max
            curr_max = max(prev_max + num, curr_max)
            prev_max = temp
            
