def findMinXor(num1, num2):
    count = 0
    while num2 > 0:
        if num2 & 1:
            count += 1
        num2 >>= 1
    xor_val = num1 ^ num2
    bit_count = 0
    while xor_val > 0:
        if xor_val & 1:
            bit_count += 1
        xor_val >>= 1
    x = 2 ** count - bit_count - 1
    return x

def find_follows_pattern(s):
    pattern = []
    i = 0
    while i < len(s):
        if s[i] not in pattern:
            pattern.append(s[i])
        i += 1
    for j in range(len(pattern)):
        s = s.replace(pattern[j], str(j))
    return s

