class Solution:
    def isSubset(self, word1, word2):
        """
        Returns True if word1 is a subset of word2, False otherwise
        """
        w1 = list(word1)
        w2 = list(word2)
        for char in w1:
            if char in w2:
                w2.remove(char)
            else:
                return False
        return True
    
    def wordSubsets(self, words1, words2):
        """
        Returns the universal strings from words1
        """
        # Create a dictionary to store the maximum frequency of each letter in words2
        max_freq = {}
        for word in words2:
            freq = {}
            for char in word:
                freq[char] = freq.get(char, 0) + 1
                max_freq[char] = max(max_freq.get(char, 0), freq[char])
                
        # Check if each word in words1 is universal
        res = []
        for word in words1:
            freq = {}
            for char in word:
                freq[char] = freq.get(char, 0) + 1
            if all(freq.get(char, 0) >= max_freq[char] for char in max_freq):
                res.append(word)
        return res

