class Solution:
    def getCollisionTimes(self, cars: List[List[int]]) -> List[float]:
        n = len(cars)
        res = [-1] * n
        stack = []

        for i in range(n - 1, -1, -1):
            p, s = cars[i]
            while stack and (s <= cars[stack[-1]][1] or (cars[stack[-1]][0] - p) / (s - cars[stack[-1]][1]) >= res[stack[-1]] > 0):
                stack.pop()
            if stack:
                res[i] = (cars[stack[-1]][0] - p) / (s - cars[stack[-1]][1])
            stack.append(i)
        return res

def closestRoom(rooms: List[List[int]], queries: List[List[int]]) -> List[int]:
    sorted_rooms = sorted(rooms, key=lambda x: x[1], reverse=True)
    res = []
    for pref, size in queries:
        curr_rooms = []
        for r, s in sorted_rooms:
            if size <= s:
                curr_rooms.append(r)
        if not curr_rooms:
            res.append(-1)
            continue
        curr_rooms.sort(key=lambda x: (abs(x-pref), x))
        res.append(curr_rooms[0])
    return res

class Solution:
    def stoneGameV(self, stoneValue: List[int]) -> int:
        n = len(stoneValue)
        prefix_sum = [0]*(n+1)
        for i in range(1,n+1):
            prefix_sum[i] = prefix_sum[i-1] + stoneValue[i-1]
        
        memo = {}
        def dfs(left, right):
            if left == right: return 0
            if (left, right) in memo: return memo[(left, right)]
            
            ans = 0
            for mid in range(left+1, right+1):
                sumL = prefix_sum[mid]-prefix_sum[left]
                sumR = prefix_sum[right]-prefix_sum[mid-1]
                
                if sumL < sumR:
                    ans = max(ans, sumL + dfs(left, mid-1))
                elif sumL > sumR:
                    ans = max(ans, sumR + dfs(mid, right))
                else:
                    ans = max(ans, sumL + dfs(left, mid-1), sumR + dfs(mid, right))
            
            memo[(left, right)] = ans
            return ans
        
        return dfs(0, n-1)

