def reorderList(head):
    if not head:
        return None
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    prev, curr = None, slow
    while curr:
        curr.next, prev, curr = prev, curr, curr.next
    l1, l2 = head, prev
    while l2.next:
        l1.next, l1 = l2, l1.next
        l2.next, l2 = l1, l2.next
    return head

def count_primes(n):
    if n <= 2:
        return 0
    primes = [True] * n
    primes[0] = primes[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if primes[i]:
            primes[i*i:n:i] = [False] * ((n-1-i*i)//i + 1)
    return sum(primes)

def power_of_two(n):
