def minSteps(arr):
    n = len(arr)
    if n == 1:
        return 0

    visited = set()
    queue = [(0, 0)]
    visited.add(0)

    while queue:
        index, steps = queue.pop(0)

        for i in [index+1, index-1]:
            if i >= n or i < 0:
                continue
            if i == n-1:
                return steps+1
            if i in visited:
                continue
            visited.add(i)
            queue.append((i, steps+1))

        for j, val in enumerate(arr):
            if val != arr[index] or index == j:
                continue
            if j == n-1:
                return steps+1
            if j in visited:
                continue
            visited.add(j)
            queue.append((j, steps+1))

