def alice_wins(n):
    # Alice starts first
    alice_turn = True
    
    while True:
        # Alice's turn
        if alice_turn:
            for x in range(1, n):
                if n % x == 0:
                    n -= x
                    alice_turn = False
                    break
        # Bob's turn
        else:
            can_make_move = False
            for x in range(1, n):
                if n % x == 0:
                    n -= x
                    alice_turn = True
                    can_make_move = True
                    break
            # If Bob cannot make a move, Alice wins
            if not can_make_move:
                return True
            
        # If n <= 0, Bob wins
        if n <= 0:
            return False

