def removeBoxes(boxes: List[int]) -> int:
    memo = {}

    def dfs(boxes):
        if not boxes:
            return 0
        if tuple(boxes) in memo:
            return memo[tuple(boxes)]
        points = 0
        i = 0
        while i < len(boxes):
            j = i
            while j < len(boxes) and boxes[j] == boxes[i]:
                j += 1
            k = j
            while k < len(boxes) and boxes[k] != boxes[i]:
                k += 1
            points = max(points, dfs(boxes[:i] + boxes[j:k]) + (j-i) * (j-i) + dfs(boxes[k:]))
            i = k
        memo[tuple(boxes)] = points
        return points

    return dfs(boxes)

