class Solution:
    def pathSum(self, root: TreeNode, targetSum: int) -> int:
        if not root:
            return 0
        return self.countPaths(root, targetSum) + self.pathSum(root.left, targetSum) + self.pathSum(root.right, targetSum)
    
    def countPaths(self, node: TreeNode, targetSum: int) -> int:
        if not node:
            return 0
        return int(node.val == targetSum) + self.countPaths(node.left, targetSum - node.val) + self.countPaths(node.right, targetSum - node.val)

def swap(num):
    num_str = str(num)
    max_num = num
    for i in range(len(num_str)):
        for j in range(i+1, len(num_str)):
            new_num_str = num_str[:i] + num_str[j] + num_str[i+1:j] + num_str[i] + num_str[j+1:]
            new_num = int(new_num_str)
            if new_num > max_num:
                max_num = new_num
