def cherryPickup(grid):
    n = len(grid)
    memo = {}
    def dfs(r, c1, c2):
        if (r, c1, c2) in memo: return memo[(r, c1, c2)]
        if r == n: return 0
        ans = 0
        for nc1 in [c1, c1-1, c1+1]:
            for nc2 in [c2, c2-1, c2+1]:
                if 0 <= nc1 < n and 0 <= nc2 < n and grid[r][nc1] != -1 and grid[r][nc2] != -1:
                    ans = max(ans, dfs(r+1, nc1, nc2))
        if c1 == c2: ans += grid[r][c1]
        else: ans += grid[r][c1] + grid[r][c2]
        memo[(r, c1, c2)] = ans
        return ans
    return dfs(0, 0, n-1)

def can_reach_end(s: str, min_jump: int, max_jump: int) -> bool:
    if s[-1] != '0':
        return False
    dp = [False] * len(s)
    dp[0] = True
    for i in range(1, len(s)):
        if s[i] == '0':
            for j in range(max(min_jump, i - max_jump), i):
                if j >= 0 and dp[j]:
                    dp[i] = True
                    break
    return dp[-1]

