def quarantine(isInfected):
    walls = 0
    m, n = len(isInfected), len(isInfected[0])
    
    def dfs(i, j):
        if i < 0 or j < 0 or i == m or j == n or isInfected[i][j] == 0:
            return
        
        isInfected[i][j] = 0
        dfs(i+1, j)
        dfs(i-1, j)
        dfs(i, j+1)
        dfs(i, j-1)
    
    for i in range(m):
        for j in range(n):
            if isInfected[i][j] == 1:
                walls += 1
                dfs(i, j)
    
    return walls

class Solution:
    def loudAndRich(self, richer: List[List[int]], quiet: List[int]) -> List[int]:
        graph = [[] for _ in range(len(quiet))]
        for u, v in richer:
            graph[v].append(u)
        
        ans = [None] * len(quiet)
        def dfs(node):
            if ans[node] is not None:
                return ans[node]
            ans[node] = node
            for nei in graph[node]:
                candidate = dfs(nei)
                if quiet[candidate] < quiet[ans[node]]:
                    ans[node] = candidate
            return ans[node]
        
        for i in range(len(quiet)):
            dfs(i)
        
        return ans

def search(nums, target):
    left, right = 0, len(nums) - 1
    
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
            
    return -1

