class Solution:
    def reversePairs(self, nums: List[int]) -> int:
        def mergeSort(l, r):
            if l >= r: return 0
            m = (l + r) // 2
            count = mergeSort(l, m) + mergeSort(m+1, r)
            j = m + 1
            for i in range(l, m+1):
                while j <= r and nums[i] > 2 * nums[j]: j += 1
                count += j - (m + 1)
            nums[l:r+1] = sorted(nums[l:r+1])
            return count
        
        return mergeSort(0, len(nums) - 1)

