def largest_overlap(img1: List[List[int]], img2: List[List[int]]) -> int:
    n = len(img1)
    max_overlap = 0
    
    def count_overlap(x_offset: int, y_offset: int) -> int:
        count = 0
        for i in range(n):
            for j in range(n):
                if i + y_offset < 0 or i + y_offset >= n or j + x_offset < 0 or j + x_offset >= n:
                    continue
                count += img1[i][j] & img2[i + y_offset][j + x_offset]
        return count
    
    for y_offset in range(-n + 1, n):
        for x_offset in range(-n + 1, n):
            max_overlap = max(max_overlap, count_overlap(x_offset, y_offset))
    return max_overlap

