def open_lock(deadends, target):
    visited = set(deadends)
    if '0000' in visited or target in visited:
        return -1
    queue = [('0000', 0)]
    while queue:
        node, turns = queue.pop(0)
        if node == target:
            return turns
        for i in range(4):
            for move in [-1, 1]:
                new_node = node[:i] + str((int(node[i]) + move) % 10) + node[i+1:]
                if new_node not in visited:
                    visited.add(new_node)
                    queue.append((new_node, turns + 1))
    return -1

def merge(left, right):
    result = []
    i, j = 0, 0
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result += left[i:]
    result += right[j:]
    return result

def merge_sort(nums):
    if len(nums) <= 1:
        return nums
    mid = len(nums) // 2
    left = merge_sort(nums[:mid])
    right = merge_sort(nums[mid:])
    return merge(left, right)

def sortArray(nums):
