class Solution:
    def oddEvenJumps(self, arr: List[int]) -> int:
        n = len(arr)
        higher, lower = [0] * n, [0] * n
        stack = []
        for a, i in sorted([a, i] for i, a in enumerate(arr)):
            while stack and stack[-1] < i:
                higher[stack.pop()] = i
            if stack:
                lower[i] = stack[-1]
            stack.append(i)
        odd, even = [False] * n, [False] * n
        odd[-1], even[-1] = True, True
        for i in range(n - 2, -1, -1):
            if higher[i]:
                odd[i] = even[higher[i]]
            if lower[i]:
                even[i] = odd[lower[i]]
        return sum(odd)

