class Solution:
    def shiftGrid(self, grid: List[List[int]], k: int) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        k %= m * n
        if k == 0:
            return grid
        flat_grid = [num for row in grid for num in row]
        flat_grid = flat_grid[-k:] + flat_grid[:-k]
        shifted_grid = [flat_grid[i:i+n] for i in range(0, len(flat_grid), n)]
        return shifted_grid

from random import choices

def serve(soup, soupB):
    prob = [0.25, 0.25, 0.25, 0.25]
    operations = [[100,0], [75,25], [50,50], [25,75]]
    op = choices(operations, prob)[0]
    if op == [100,0] and soupB > 0:
        soupB -= op[0]
    else:
        soup -= op[0]
        soupB -= op[1] if soupB > op[1] else soupB
    return soup, soupB

def simulate(soup, soupB):
    cnt, cntB = 0, 0
    while soup > 0 or soupB > 0:
        cnt += 1
        soup, soupB = serve(soup, soupB)
        if soupB == 0:
            cntB = cnt
    return cnt, cntB

def probability_empty(n):
    soup, soupB = n, 0
    cntSum, cntBSum = 0, 0
    for i in range(100000):
        cnt, cntB = simulate(soup, soupB)
        cntSum += cnt
        cntBSum += cntB
    return cntSum / 100000 / (cntSum / 100000 + cntBSum / 100000 / 2)

print("%.5f" % probability_empty(1000))

