def is_crossing(distance):
    x = 0
    y = 0
    direction = 0
    for i in range(len(distance)):
        # move in direction
        if direction == 0:
            y += distance[i]
        elif direction == 1:
            x -= distance[i]
        elif direction == 2:
            y -= distance[i]
        elif direction == 3:
            x += distance[i]
        # update direction
        direction = (direction + 1) % 4
        # check if crossed path
        if direction == 0 and (x != 0 or y != 0):
            return True
    return False

