class Solution:
    def pushDominoes(self, dominoes: str) -> str:
        dominoes = list(dominoes)
        n = len(dominoes)
        forces = [0] * n
        force = 0
        for i in range(n):
            if dominoes[i] == 'R':
                force = n
            elif dominoes[i] == 'L':
                force = 0
            else:
                force = max(force - 1, 0)
            forces[i] += force
        force = 0
        for i in range(n - 1, -1, -1):
            if dominoes[i] == 'L':
                force = n
            elif dominoes[i] == 'R':
                force = 0
            else:
                force = max(force - 1, 0)
            forces[i] -= force
        for i in range(n):
            if forces[i] > 0:
                dominoes[i] = 'R'
            elif forces[i] < 0:
                dominoes[i] = 'L'
        return ''.join(dominoes)

def integer_break(n):
    dp = [1] * (n+1)
    for i in range(2, n+1):
        for j in range(1, i//2 + 1):
            dp[i] = max(dp[i], max(j * dp[i-j], j * (i-j)))
    return dp[n]

def cat_mouse_game(graph):
    n = len(graph)
    dp = [[[None] * n for _ in range(n)] for _ in range(2)]
    
    def dfs(mouse, cat, turn):
        if mouse == 0:
            return 1
        if cat == mouse:
            return 2
        if turn == 2*n:
            return 0
        if dp[turn%2][mouse][cat] != None:
            return dp[turn%2][mouse][cat]
        if turn % 2 == 0:
            res = 2
            for nxt in graph[cat]:
                if nxt == 0:
                    continue
                tmp = dfs(mouse, nxt, turn+1)
                if tmp == 1:
                    return 1
                if tmp == 0:
                    res = 0
            return res
        else:
            res = 1
            for nxt in graph[mouse]:
                tmp = dfs(nxt, cat, turn+1)
                if tmp == 2:
                    return 2
                if tmp == 0:
                    res = 0
            return res
    
    return dfs(1, 2, 1)

