        def divisors(n):
            divisor_set = set()
            for i in range(1,int(n**0.5)+1):
                if n % i == 0:
                    divisor_set.add(i)
                    divisor_set.add(n//i)
                    if len(divisor_set) > 4:
                        return []
            return list(divisor_set) if len(divisor_set) == 4 else []
        
        ans = 0
        for num in nums:
            divs = divisors(num)
            ans += sum(divs)
        
        return ans

