import re

def is_valid_code(code):
    stack = []
    pattern = r'<([A-Z]{1,9})>[^<]*(<\/\1>)'
    cdata_pattern = r'<!\[CDATA\[(.*?)\]\]>'

    for match in re.findall(pattern, code):
        stack.append(match[0])
    for match in re.findall(cdata_pattern, code):
        code = code.replace(match, ' '*len(match))

    while stack:
        tag = stack.pop()
        pattern = r'<{}>(.*?)<\/{}>'.format(tag, tag)
        match = re.search(pattern, code)
        if match:
            code = code.replace(match.group(), ' '*len(match.group()))
        else:
            return False

    return not bool(re.search(r'<([A-Z]{1,9})>', code) or re.search(r'<\/([A-Z]{1,9})>', code))

