import random

class Solution:
    def findSecretWord(self, words: List[str], master: 'Master') -> None:
        
        def match(w1, w2):
            return sum(c1 == c2 for c1, c2 in zip(w1, w2))
        
        n = 6
        guesses = 10
        while guesses > 0:
            guess = random.choice(words)
            matches = master.guess(guess)
            if matches == n:
                return
            words = [word for word in words if match(word, guess) == matches]
            guesses -= 1
        return "Either took too many guesses or could not find the secret word."

