    def stoneGameVII(self, stones: List[int]) -> int:
        n = len(stones)
        dp = [[0]*n for _ in range(n)]

        for i in range(n-2,-1,-1):
            s = stones[i]
            for j in range(i+1,n):
                s += stones[j]
                dp[i][j] = max(s-stones[i]-dp[i+1][j], s-stones[j]-dp[i][j-1])

