def minimumMoves(target: int, numMoves: int) -> int:
    # case 1: target is already at position 0
    if target == 0:
        return 0
    # case 2: target is at a distance less than or equal to numMoves
    if abs(target) <= numMoves:
        return 1
    # case 3: target is at a distance greater than numMoves
    else:
        # find the maximum possible distance we can move in numMoves moves
        max_distance = numMoves*(numMoves+1)//2
        # if target is on the same side as the maximum distance we can move
        if target % 2 == max_distance % 2:
            return numMoves
        # if target is on the opposite side as the maximum distance we can move
        else:
            return numMoves + 1

