def sliding_puzzle(board):
    def find_blank(board):
        for row in range(2):
            for col in range(3):
                if board[row][col] == 0:
                    return (row, col)
    
    def generate_moves(row, col):
        moves = []
        if row > 0:
            moves.append((row-1, col))
        if row < 1:
            moves.append((row+1, col))
        if col > 0:
            moves.append((row, col-1))
        if col < 2:
            moves.append((row, col+1))
        return moves
    
    def swap_tiles(board, pos1, pos2):
        new_board = [row[:] for row in board]
        r1, c1 = pos1
        r2, c2 = pos2
        new_board[r1][c1], new_board[r2][c2] = new_board[r2][c2], new_board[r1][c1]
        return new_board
    
    def bfs(start, goal):
        queue = [(start, 0)]
        visited = set()
        while queue:
            node, depth = queue.pop(0)
            if node == goal:
                return depth
            blank_pos = find_blank(node)
            for move_pos in generate_moves(*blank_pos):
                successor = swap_tiles(node, blank_pos, move_pos)
                successor = tuple(map(tuple, successor))
                if successor not in visited:
                    visited.add(successor)
                    queue.append((successor, depth+1))
        return -1
    
    start = tuple(map(tuple, board))
    goal = ((1,2,3),(4,5,0))
    return bfs(start, goal)

