def imageSmoother(img):
    m, n = len(img), len(img[0])
    res = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            summ, cnt = 0, 0
            for r in range(max(0, i-1), min(m, i+2)):
                for c in range(max(0, j-1), min(n, j+2)):
                    summ += img[r][c]
                    cnt += 1
            res[i][j] = summ // cnt
    return res

from collections import defaultdict

class Solution:
    def accountsMerge(self, accounts: List[List[str]]) -> List[List[str]]:
        email_dict = defaultdict(list)
        name_dict = {}
        
        for account in accounts:
            name = account[0]
            emails = account[1:]
            name_dict[emails[0]] = name
            
            for email in emails:
                email_dict[email].append(emails[0])
                email_dict[emails[0]].append(email)
        
        visited = set()
        result = []
        
        for email in email_dict:
            if email not in visited:
                visited.add(email)
                stack = [email]
                curr_emails = []
                
                while stack:
                    curr_email = stack.pop()
                    curr_emails.append(curr_email)
                    
                    for neighbor in email_dict[curr_email]:
                        if neighbor not in visited:
                            visited.add(neighbor)
                            stack.append(neighbor)
                
                result.append([name_dict[email]] + sorted(curr_emails))
        
        return result

def maximalSquare(matrix):
    m, n = len(matrix), len(matrix[0])
    dp = [[0] * n for _ in range(m)]
    max_area = 0
    for i in range(m):
        for j in range(n):
            if matrix[i][j] == '1':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_area = max(max_area, dp[i][j] * dp[i][j])
    return max_area

