def magical_string(n):
    if n == 0:
        return 0
    if n <= 3:
        return 1
    s = [0] * (n+1)
    s[0] = 1
    s[1] = 2
    s[2] = 2
    head = 2
    tail = 3
    num = 1
    count = 1
    while tail < n:
        for i in range(s[head]):
            s[tail] = num
            tail += 1
            if tail == n:
                return count
        num = 3 - num
        head += 1
        count += 1
    if tail == n:
        return count
    else:
        return count-1

def reverseString(s):
    left, right = 0, len(s) - 1
    while left < right:
        s[left], s[right] = s[right], s[left]
        left += 1
        right -= 1

class Solution:
    def leastInterval(self, tasks: List[str], n: int) -> int:
        task_counts = [0] * 26
        for task in tasks:
            task_counts[ord(task) - ord('A')] += 1
        task_counts.sort(reverse=True)
        max_count = task_counts[0]
        idle_time = (max_count - 1) * n
        for i in range(1, 26):
            if task_counts[i] == 0:
                break
            if task_counts[i] == max_count:
                idle_time -= max_count - 1
            else:
                idle_time -= task_counts[i]
        idle_time = max(0, idle_time)
        return len(tasks) + idle_time

