def egg_drop(k, n):
    dp = [[float('inf') for _ in range(n+1)] for _ in range(k+1)]
    for i in range(1, k+1):
        dp[i][0] = 0
        for j in range(1, n+1):
            dp[i][j] = 1 + dp[i-1][j-1] + dp[i][j-i]
            if dp[i][j] >= n:
                return j
    return n

