class Solution:
    def removeKdigits(self, num: str, k: int) -> str:
        stack = []
        for digit in num:
            while k and stack and stack[-1] > digit:
                stack.pop()
                k -= 1
            stack.append(digit)
        
        while k:
            stack.pop()
            k -= 1
        
        return "".join(stack).lstrip("0") or "0"

def removeComments(source: List[str]) -> List[str]:
    ans = []
    in_block_comment = False
    for line in source:
        i = 0
        if not in_block_comment:
            new_line = []
        while i < len(line):
            if line[i:i+2] == '/*' and not in_block_comment:
                in_block_comment = True
                i += 1
            elif line[i:i+2] == '*/' and in_block_comment:
                in_block_comment = False
                i += 1
            elif line[i:i+2] == '//':
                break    # line comment, ignore rest of the line
            elif not in_block_comment:
                new_line.append(line[i])
            i += 1
        if new_line and not in_block_comment:
            ans.append("".join(new_line))
    return ans

def nthUglyNumber(n: int, a: int, b: int, c: int) -> int:
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x
    def lcm(x, y):
        return x * y // gcd(x, y)
    def count(x):
        return x // a + x // b + x // c - x // ab - x // ac - x // bc + x // abc
    ab, ac, bc = lcm(a, b), lcm(a, c), lcm(b, c)
    abc = lcm(a, bc)
    left, right = 1, 2 * 10**9
    while left < right:
        mid = (left + right) // 2
        if count(mid) >= n:
            right = mid
        else:
            left = mid + 1
    return left


