def outerTrees(trees):
    def orientation(i, j, k):
        return (j[1] - i[1]) * (k[0] - j[0]) - (j[0] - i[0]) * (k[1] - j[1])

    trees.sort()
    left = []
    for p in trees:
        while len(left) >= 2 and orientation(left[-2], left[-1], p) < 0:
            left.pop()
        left.append(p)

    right = []
    for p in reversed(trees):
        while len(right) >= 2 and orientation(right[-2], right[-1], p) < 0:
            right.pop()
        right.append(p)

    return list(set(left + right))

