class Solution:
    def isToeplitzMatrix(self, matrix: List[List[int]]) -> bool:
        #let initial status be True
        status = True
        #iterating through the matrix leaving the last elements and last row
        #top rightmost and bottom leftmost element will always satisfy the solution
        #rest all the elements unexplored by loop had been already explored by their diagonal elements
        for i in range(len(matrix)-1):
            for j in range(len(matrix[0])-1):
                #set status to False if the diagonal element is not equal
                if matrix[i][j]==matrix[i+1][j+1]:
                    continue
                else:
                    status = False
                    break
            #check if status is false to break out of the loop and prevent any further proceedings
            if status == False:
                break
        #return the status whether it is Toeplitz Matrix or not        
        return status

