def deleteAndEarn(nums: List[int]) -> int:
    if not nums:
        return 0
    max_val = max(nums)
    freq = [0] * (max_val + 1)
    for num in nums:
        freq[num] += num
    prev, curr = 0, 0
    for i in range(max_val + 1):
        temp = max(curr, prev + freq[i])
        prev = curr
        curr = temp
    return curr

def steps_to_water(plants, capacity):
    steps = 0
    current_water = 0
    for i in range(len(plants)):
        if plants[i] > capacity:
            return -1
        if current_water < plants[i]:
            steps += 2*(i) #Move to the plant and back to the river
