class Square:
    def __init__(self, left, side_length):
        self.left = left
        self.right = left + side_length
        self.height = 0
        self.frozen = False

def get_height(positions, dropped_index):
    squares = [Square(left, side_length) for left, side_length in positions]
    dropped_square = squares[dropped_index]
    dropped_square.height = dropped_square.right
    tallest_height = dropped_square.height
    
    for i in range(dropped_index-1, -1, -1):
        curr_square = squares[i]
        while not curr_square.frozen and curr_square.height >= dropped_square.left and curr_square.left < dropped_square.right:
            curr_square.frozen = True
            dropped_square.height = max(dropped_square.height, curr_square.height + dropped_square.right - curr_square.left)
            tallest_height = max(tallest_height, dropped_square.height)
        if curr_square.frozen and curr_square.right > dropped_square.left:
            dropped_square.height = max(dropped_square.height, curr_square.height + dropped_square.right - curr_square.left)
            tallest_height = max(tallest_height, dropped_square.height)
    return tallest_height
        

