def min_cost(houses, n, cost, target):
    # Initialize dp array with large values
    dp = [[float('inf') for _ in range(target)] for _ in range(n)]
    
    # Update the dp array for first house
    if houses[0] == 0:
        for j in range(n):
            dp[j][0] = cost[0][j]
    else:
        dp[houses[0]-1][0] = 0
    
    # Update the dp array for remaining houses and neighborhoods
    for i in range(1, len(houses)):
        for j in range(n):
            for k in range(target):
                if k == 0:
                    # If it's a new neighborhood
                    if houses[i] == 0:
                        dp[j][k] = min(dp[p][k] + cost[i][j] for p in range(n))
                    else:
                        dp[j][k] = min(dp[p][k] for p in range(n) if p != houses[i]-1)
                else:
                    # If it's the same neighborhood
                    if houses[i] == 0:
                        dp[j][k] = min(dp[p][k] + cost[i][j] for p in range(n) if p == j)
                    else:
                        dp[j][k] = dp[houses[i]-1][k-1] if houses[i]-1 == j else float('inf')
                        
    # Return the minimum cost if all houses are painted and number of neighborhoods is target
    min_cost = min(dp[j][target-1] for j in range(n))
    return min_cost if min_cost != float('inf') else -1

