    def sortPeople(self, names: List[str], heights: List[int]) -> List[str]:
        hashmap = {}
        for i in range(len(names)):
            hashmap[heights[i]] = names[i]
        self.mergeSort(heights)
        result = [hashmap[i] for i in heights] 
