def champagneTower(poured: int, row: int, glass: int) -> float:
    tower = [[0] * (i+1) for i in range(row+1)]
    tower[0][0] = poured
    
    for i in range(row):
        for j in range(i+1):
            if tower[i][j] > 1:
                overflow = (tower[i][j] - 1) / 2
                tower[i+1][j] += overflow
                tower[i+1][j+1] += overflow
                tower[i][j] = 1
                
    return tower[row][glass]

class Solution:
    def lemonadeChange(self, bills: List[int]) -> bool:
        five, ten = 0, 0
        for bill in bills:
            if bill == 5:
                five += 1
            elif bill == 10:
                if five == 0:
                    return False
                five -= 1
                ten += 1
            else:
                if ten > 0 and five > 0:
                    ten -= 1
                    five -= 1
                elif five >= 3:
                    five -= 3
                else:
                    return False
        return True

