def countOfAtoms(formula):
    stack = [collections.Counter()]
    i = 0
    n = len(formula)
    while i < n:
        if formula[i] == '(':
            stack.append(collections.Counter())
            i += 1
        elif formula[i] == ')':
            i += 1
            num = 0
            while i < n and formula[i].isdigit():
                num = num * 10 + int(formula[i])
                i += 1
            num = max(1, num)
            top = stack.pop()
            for k, v in top.items():
                stack[-1][k] += v * num
        else:
            j = i
            i += 1
            while i < n and formula[i].islower():
                i += 1
            name = formula[j:i]
            num = 0
            while i < n and formula[i].isdigit():
                num = num * 10 + int(formula[i])
                i += 1
            num = max(1, num)
            stack[-1][name] += num
    
    ans = []
    for name, count in stack[-1].items():
        ans.append(name)
        if count > 1:
            ans.append(str(count))
    return ''.join(ans)

