def strange_printer(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    
    for i in range(n-1, -1, -1):
        dp[i][i] = 1
        for j in range(i+1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i][j-1]
            else:
                dp[i][j] = dp[i][j-1] + 1
                for k in range(i, j):
                    if s[k] == s[j]:
                        dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j-1])
    
    return dp[0][n-1]

class Solution:
    def orangesRotting(self, grid: List[List[int]]) -> int:
        fresh = set()
        rotten = set()
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    fresh.add((i, j))
                elif grid[i][j] == 2:
                    rotten.add((i, j))
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        minutes = 0
        while len(fresh) > 0:
            infected = set()
            for r in rotten:
                for d in directions:
                    nextPos = (r[0] + d[0], r[1] + d[1])
                    if nextPos in fresh:
                        infected.add(nextPos)
                        fresh.remove(nextPos)
            if len(infected) == 0:
                return -1
            rotten = infected
            minutes += 1
        return minutes

