class Solution:
    def findPoisonedDuration(self, timeSeries: List[int], duration: int) -> int:
        
        i = 0
        ans = 0
        while i < len(timeSeries)-1:
            if (timeSeries[i] + duration) <= timeSeries[i+1]:
                ans += duration            #If Teemo does not attack again before the effect of poison wears off
                i += 1                     #He will be poisoned for the duration
            else:
                ans += timeSeries[i+1] - timeSeries[i]
                i+=1                       #If he attacks again before poison effect ends, duration will reset.
        return ans + duration

