def stone_game(stones):
    n = len(stones)
    dp = [[(0, 0)] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = (stones[i], 0)
    for l in range(2, n + 1):
        for i in range(n - l + 1):
            j = i + l - 1
            left = stones[i:j + 1]
            for k in range(i, j):
                x = dp[i][k][1] + dp[k + 1][j][1] + sum(left)
                if dp[i][j][0] < x - dp[k + 1][j][0]:
                    dp[i][j] = (x - dp[k + 1][j][0], dp[i][k][0])
                left = left[:-1]
    return dp[0][n - 1][0] - dp[0][n - 1][1]

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next
        
class Solution:
    def addTwoNumbers(self, l1: ListNode, l2: ListNode) -> ListNode:
        dummy = ListNode()
        curr = dummy
        carry = 0
        
        while l1 or l2 or carry:
            sum_ = 0
            if l1:
                sum_ += l1.val
                l1 = l1.next
            if l2:
                sum_ += l2.val
                l2 = l2.next
                
            sum_ += carry
            carry = sum_ // 10
            sum_ %= 10
            
            curr.next = ListNode(sum_)
            curr = curr.next
            
        return dummy.next

def minimum_flips(grid):
    n = len(grid)
    island1, island2 = None, None
    
    # step 1: find the two islands
    visited = set()
    def find_islands(i, j):
        if (i, j) in visited:
            return False
        visited.add((i, j))
        if grid[i][j] == 0:
            return False
        if island1 is None:
            island1.append((i, j))
        else:
            island2.append((i, j))
        if len(island1) > 0 and len(island2) > 0:
            return True
        if i > 0:
            find_islands(i-1, j)
        if i < n-1:
            find_islands(i+1, j)
        if j > 0:
            find_islands(i, j-1)
        if j < n-1:
            find_islands(i, j+1)
        return False
    
    for i in range(n):
        for j in range(n):
            if find_islands(i, j):
                break
    
    # step 2: find the minimum number of flips
    def get_neighbors(i, j):
        return [(x, y) for x, y in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]
                if x >= 0 and x < n and y >= 0 and y < n]
    
    queue = [(i, j, True, 0), (i, j, False, 0)]
    visited = {(i, j, True), (i, j, False)}
    while queue:
        x, y, val, flips = queue.pop(0)
        for neighbor in get_neighbors(x, y):
            if neighbor in island1:
                if val:
                    continue
                elif len(island1) == 1:
                    return flips
                queue.append((neighbor[0], neighbor[1], True, flips))
                visited.add((neighbor[0], neighbor[1], True))
            elif neighbor in island2:
                if not val:
                    continue
                elif len(island2) == 1:
                    return flips
                queue.append((neighbor[0], neighbor[1], False, flips))
                visited.add((neighbor[0], neighbor[1], False))
            elif neighbor not in visited:
                queue.append((neighbor[0], neighbor[1], val, flips+1))
                visited.add(neighbor+(val,))
    
    return -1

