import datetime

def find_day_week(day, month, year):
    date = datetime.datetime(year, month, day)
    return date.strftime("%A")

class Solution:
    def shoppingOffers(self, price: List[int], special: List[List[int]], needs: List[int]) -> int:
        def canBuy(needs, offer):
            for i in range(len(needs)):
                if needs[i] < offer[i]:
                    return False
            return True
        
        def updateNeeds(needs, offer):
            for i in range(len(needs)):
                needs[i] -= offer[i]
        
        def calculatePrice(needs, price):
            cost = 0
            for i in range(len(needs)):
                cost += needs[i] * price[i]
            return cost
        
        memo = {}
        def dfs(needs):
            if tuple(needs) in memo:
                return memo[tuple(needs)]
            price = calculatePrice(needs, price)
            for offer in special:
                if canBuy(needs, offer):
                    updateNeeds(needs, offer)
                    price = min(price, offer[-1] + dfs(needs))
                    updateNeeds(needs, [-x for x in offer[:-1]])
            memo[tuple(needs)] = price
            return price
        
        return dfs(needs)

