class Solution:
    def bestHand(self, ranks: List[int], suits: List[str]) -> str:

        # check the suits
        if len(set(suits)) == 1:
            return "Flush"

        # count the ranks
        cn = collections.defaultdict(int)
        max_cn = 0

        # go through the ranks
        for rank in ranks:
            
            # increase the amount
            cn[rank] += 1

            # check for maximum
            max_cn = max(max_cn, cn[rank])
        
        # return the result
        if max_cn >= 3:
            return "Three of a Kind"
        elif max_cn == 2:
            return "Pair"
        else:
            return "High Card"

