def max_like_time_coeff(n, satisfaction):
    satisfaction.sort(reverse=True)
    max_sum = 0
    for i in range(n):
        curr_sum = sum([(j+1)*satisfaction[j] for j in range(i,n)])
        if curr_sum > max_sum:
            max_sum = curr_sum
        else:
            break
    return max_sum

