def find_permutations(s, n):
    permutations = []
    nums = list(range(n+1))
    def backtrack(perm, remaining):
        if not remaining:
            permutations.append(list(perm))
        else:
            i = len(perm) - len(remaining)
            if s[i] == 'I':
                for j in range(i, len(perm)):
                    if perm[j] > perm[i-1]:
                        perm[i], perm[j] = perm[j], perm[i]
                        backtrack(perm, remaining[1:])
                        perm[i], perm[j] = perm[j], perm[i]
            else:
                for j in range(i, len(perm)):
                    if perm[j] < perm[i-1]:
                        perm[i], perm[j] = perm[j], perm[i]
                        backtrack(perm, remaining[1:])
                        perm[i], perm[j] = perm[j], perm[i]
                        
    backtrack(nums, nums)
    return permutations

