class Solution:
    def rotateTheBox(self, box: List[List[str]]) -> List[List[str]]:
        
        ## RC ##
        ## TIME COMPLEXITY: O(N) ##
        ## LOGIC ##
        ## 1. For each row, go through all columns till you hit blocker/end
        ## 2. when you hit that, rearrange the row till that position
        ## 3. repeat and finally rotate by 90
        
        def rearrange(stones, arr):
            if len(arr) == stones:
                return arr
            if stones == 0:
                return arr
            empty = len(arr) - stones
            for i in range(empty):
                arr[i] = "."
            for i in range(empty, len(arr)):
                arr[i] = "#"
            return arr
        
        def transpose(rows, cols, box):
            res = [ [ "" for _ in range(rows) ] for _ in range(cols) ]
            for x in range(rows):
                for y in range(cols):
                    res[y][rows - x - 1] = box[x][y]
            return res
        
        rows, cols = len(box), len(box[0])
        r = 0
        while( r < rows ):
            c = 0
            while( c < cols):
                stones = 0
                start = c
                while( c < cols and box[r][c] != "*"):
                    if box[r][c] == "#":
                        stones += 1
                    c += 1
                box[r][start:c] = rearrange(stones, box[r][start:c])
                c += 1
            r += 1
        return transpose(rows, cols, box)

