class Solution:
    def rangeSumBST(self, root: TreeNode, L: int, R: int) -> int:
        # Stack to keep track of nodes is key to iterative solution
		stack = []
        rangedSum = 0
        
		# Check that tree is not empty (never specified edge case)
        if root is None:
            return 0
        
		# Make root of tree the first node to check
        stack.append(root)
        
		# Iteratively simulate recursion by appending and popping stack until it is empty
        while len(stack) > 0:
		    # Set up the next node to traverse
		    # stack.pop(0) will turn solution into BFS
            root = stack.pop()
			
			# Check if the solution is within range
            if L <= root.val <= R:
			    # Add value to sum
                rangedSum += root.val
				
				# Set the both children to be explored, if they exist
                if not root.left is None:
                    stack.append(root.left)
                if not root.right is None:
                    stack.append(root.right)
			# Some values within range may have parent nodes outside the desired range
            else:
			    # Value is larger than R, but left child (and its children) may be less than R
                if root.val >= L:
                    if not root.left is None:
                        stack.append(root.left)
			    # Value is smaller than L, but right child (and its children) may be greater than L
                elif root.val <= R:
                    if not root.right is None:
                        stack.append(root.right)
        
		# Return the sum of values within the given inclusive range
        return rangedSum

