class Solution:
    def islandPerimeter(self, grid: List[List[int]]) -> int:
        
        #iterate from top and check where first piece of land can be found
        def findfirst():
            for i in range(len(grid)):
                for j in range(len(grid[0])):
                    if grid[i][j] == 1:
                        return [i,j]
            return [-1,-1]
        
        arr = grid
        
        #for every block of land you meet, check the surroundings
        #if it has neighboring land, the perimeter cannot be counter
        #so countable perimeter for given block will be (total edges - total neighbors)
        def checkneighbors(i,j):
            cnt = 0
            #check top
            if i-1 >= 0:
                if arr[i-1][j] != 0:
                    cnt += 1
            #check bottom
            if i+1 <= len(arr)-1:
                if arr[i+1][j] != 0:
                    cnt += 1
            
            #check left
            if j-1 >= 0:
                if arr[i][j-1] != 0:
                    cnt += 1
            
            #check right:
            if j+1 <= len(arr[i])-1:
                if arr[i][j+1] != 0:
                    cnt += 1
                    
            return 4-cnt
        
        
        #recursive function
        def counting(arr,i,j,tot,cal):
            #print(i,j) first block where land is found
            cal += 1
            neigh = checkneighbors(i,j)
            #print(arr,tot,neigh,cal,i,j)
            
            if arr[i][j] == -1:    #return if already visited
                return tot
            
            arr[i][j] = -1    #mark as visited
            
            # check neighbor edges for current node and add to total
            tot += neigh 
            
            #check for adjacent land and repeat
            
            ## if top is valid
            if i-1 >= 0:
                #if not visited
                if arr[i-1][j] != -1:
                    #if there is land
                    if arr[i-1][j] == 1:
                        #call the same function
                        tot = counting(arr,i-1,j,tot,cal)
                        
                        
            ## if bottom is valid
            if i+1 <= len(arr)-1:
                #if not already visited
                if arr[i+1][j] != -1:
                    #if there is land
                    if arr[i+1][j] == 1:
                        #call the same function
                        tot = counting(arr,i+1,j,tot,cal)
                        
                        
            # if left is valid
            if j-1 >= 0:
                #if not visited
                if arr[i][j-1] != -1:
                    #if there is land
                    if arr[i][j-1] == 1:
                        #call the same function
                        tot = counting(arr,i,j-1,tot,cal)
                        
            #if right is valid            
            if j+1 <= len(arr[0])-1:
                #if not visited
                if arr[i][j+1] != -1:
                    #if there is land
                    if arr[i][j+1] == 1:
                        #call the same function
                        tot = counting(arr,i,j+1,tot,cal)
            
            return tot
        
        tot = 0
        land = findfirst() #to find first block where land starts
        if land[0] == -1:
            return 0
        
        tot += counting(arr,land[0],land[1],tot,cal = 0)
        
        return tot

