class Solution:
    def findTilt(self, root: TreeNode) -> int:
        self.tilt = 0
        
        def nodeSum(node):
            if not node:
                return 0
            left_sum = nodeSum(node.left)
            right_sum = nodeSum(node.right)
            self.tilt += abs(left_sum - right_sum)
            return left_sum + right_sum + node.val
        
        nodeSum(root)
        return self.tilt

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

