class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        self.noc=0 #no of non-obstacle cell
        self.ans=0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j]==0:
                    self.noc+=1  #counting no of non-obstacle cell
        visited=[[False for i in range(len(grid[0]))] for j in range(len(grid))]
        cell_cnt=0 #for counting how many cells we travelled
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j]==1:
                    self.solve(i,j,grid,visited,cell_cnt) #function call
                    break #there is only one starting point so we break after one-call
        return self.ans
    def solve(self,row,col,grid,visited,cell_cnt):
        if grid[row][col]==2: #if we reach destination cell
            if cell_cnt-1==self.noc: #compare no of travelled cells V/S no of cells we have to travel (minus because we are including 1 also in non-obstacle cells)
                self.ans+=1 #incrementing answer by 1 as we got one path
            return
        if self.isvalid(row,col,grid,visited):
            visited[row][col]=True #marked as visited
            cell_cnt+=1 #increment travelled cell by 1
            if row-1>=0 and visited[row-1][col]==False: #upper cell check
                self.solve(row-1,col,grid,visited,cell_cnt)
                visited[row-1][col]=False #marking previous cell as unvisited so we can visit in next path also (same for next 4 checks) 
            if row+1<len(grid) and visited[row+1][col]==False: #lower cell check
                self.solve(row+1,col,grid,visited,cell_cnt)
                visited[row+1][col]=False
            if col-1>=0 and visited[row][col-1]==False: #left cell check
                self.solve(row,col-1,grid,visited,cell_cnt)
                visited[row][col-1]=False
            if col+1<len(grid[0]) and visited[row][col+1]==False: #right cell check
                self.solve(row,col+1,grid,visited,cell_cnt)
                visited[row][col+1]=False
            visited[row][col]=False #marking current cell unvisited so we can visit in next path also
        return
    def isvalid(self,row,col,grid,visited): #checking cell Validity
        if grid[row][col]!=-1 and visited[row][col]==False:
            return True
        else:
            return False

