class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        start, end, zeros = None, None, 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    start = (i, j)
                elif grid[i][j] == 2:
                    end = (i, j)
                elif grid[i][j] == 0:
                    zeros += 1
                    
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        def dfs(x, y, visited):
            if (x, y) == end:
                return 1 if len(visited) == zeros + 2 else 0
            res = 0
            for dx, dy in directions:
                nx, ny = x+dx, y+dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] != -1 and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    res += dfs(nx, ny, visited)
                    visited.remove((nx, ny))
            return res
        
        visited = {start}
        return dfs(start[0], start[1], visited)

def shiftingLetters(s: str, shifts: List[int]) -> str:
    for i in range(len(shifts)-2, -1, -1):
        shifts[i] += shifts[i+1]
    
    res = ""
    for i in range(len(s)):
        res += chr((ord(s[i]) - 97 + shifts[i]) % 26 + 97)
    
    return res

