class Solution:
    def __init__(self, nums: List[int]):
        self.nums=nums
        self.lists=self.getList()
    def reset(self) -> List[int]:
        a=sorted(self.nums)
        return a
    def getList(self):
        nums=self.nums
        res=[]
        path=[]
        used=[0]*len(nums)
        def backtracking(nums):
            if len(path)==len(nums):
                res.append(path[:])
                return
            for i in range(len(nums)):
                if used[i]==0:
                    if i>0 and nums[i]==nums[i-1] and used[i-1]==0:
                        continue
                    used[i]=1
                    path.append(nums[i])
                    backtracking(nums)
                    used[i]=0
                    path.pop()
            return res
        backtracking(nums)
        return res
    def shuffle(self) -> List[int]:
        n=random.randint(0,len(self.nums)-1)
        return self.lists[n]

