       for word in words:
           testCondenseWord, testWordTable = condenseWord(word)
           if sampleCondenseWord == testCondenseWord:
               for i in range(len(sampleCondenseWord)):
                   if sampleWordTable[i] >= 3 and sampleWordTable[i] < testWordTable[i]:
                       break
                   if sampleWordTable[i] < 3 and sampleWordTable[i] != testWordTable[i]:
                       break
               else:
                   matchCounter += 1
       
