def expressiveWords(S: str, words: List[str]) -> int:
    def decompose(S):
        decom = []
        i = 0
        while i < len(S):
            j = i
            while j < len(S) and S[j] == S[i]:
                j += 1
            decom.append((S[i], j-i))
            i = j
        return decom
    
    def compare(a, b):
        if len(a) != len(b):
            return False
        for i in range(len(a)):
            if a[i][0] != b[i][0]:
                return False
            if a[i][1] < 3 and a[i][1] != b[i][1] or a[i][1] < b[i][1]:
                return False
        return True
    
    S_decom = decompose(S)
    count = 0
    for w in words:
        w_decom = decompose(w)
        if compare(S_decom, w_decom):
            count += 1
    return count

class Solution:
    def rearrangeBarcodes(self, barcodes: List[int]) -> List[int]:
        
        code_count = {}
        max_count = 0
        for code in barcodes:
            if code not in code_count:
                code_count[code] = 0
            code_count[code] += 1
            if code_count[code] > max_count:
                max_count = code_count[code]
                max_code = code
                
        index = 0
        result = [0] * len(barcodes)
        while code_count[max_code] > 0:
            result[index] = max_code
            index += 2
            code_count[max_code] -= 1
            
        del code_count[max_code]
        
        for code in code_count:
            while code_count[code] > 0:
                if index >= len(barcodes):
                    index = 1
                result[index] = code
                index += 2
                code_count[code] -= 1
            
        return result

