def romanToInt(s):
    romanToIntDict = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = romanToIntDict[s[-1]]
    for i in range(len(s)-2, -1, -1):
        if romanToIntDict[s[i]] < romanToIntDict[s[i+1]]:
            result -= romanToIntDict[s[i]]
        else:
            result += romanToIntDict[s[i]]
    return result

