class Solution:
    def findMaxLength(self, nums: List[int]) -> int:
        dic = {0: -1}
        count = 0
        max_len = 0
        for i in range(len(nums)):
            count += 1 if nums[i] == 1 else -1
            if count in dic:
                max_len = max(max_len, i - dic[count])
            else:
                dic[count] = i
        return max_len

