class Solution:
    def __init__(self):
        self.used = {} #used mark the node and its maximum possible value with root.val used
        self.unused = {} #unused marks the node and its maximum value with root.val unused
    
    def rob(self, root: Optional[TreeNode]) -> int:
        def helper(root, allow):
            #print(root)
            if not root:return 0
            default = 0 #default mark the case that root.val unused
            if root in self.unused.keys():
                default = self.unused[root] #memo
            else:
                default += helper(root.left, True)
                default += helper(root.right, True)
                self.unused[root] = default
            possible = 0 #possible stands for the case that root.val used, would be evaluated only if allow == True
            if allow:
                if root in self.used.keys():
                    possible = self.used[root]
                else:
                    possible = root.val
                    possible += helper(root.left, False)
                    possible += helper(root.right, False)
                    self.used[root] = possible
            return max(default, possible)
        return helper(root, True)

