def rob(root):
    memo = {}
    def helper(node):
        if not node:
            return 0, 0
        if node in memo:
            return memo[node]
        rob_left, skip_left = helper(node.left)
        rob_right, skip_right = helper(node.right)
        rob_node = node.val + skip_left + skip_right
        skip_node = max(rob_left, skip_left) + max(rob_right, skip_right)
        memo[node] = (rob_node, skip_node)
        return rob_node, skip_node
    return max(helper(root))

class Solution:
    def matrixBlockSum(self, mat: List[List[int]], k: int) -> List[List[int]]:
        m, n = len(mat), len(mat[0])
        preSum = [[0] * (n+1) for _ in range(m+1)]
        for i in range(1, m+1):
            for j in range(1, n+1):
                preSum[i][j] = mat[i-1][j-1] + preSum[i-1][j] + preSum[i][j-1] - preSum[i-1][j-1]
        ans = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                r1, c1 = max(0, i-k), max(0, j-k)
                r2, c2 = min(m-1, i+k), min(n-1, j+k)
                ans[i][j] = preSum[r2+1][c2+1] - preSum[r2+1][c1] - preSum[r1][c2+1] + preSum[r1][c1]
        return ans

