def bulbSwitch(n: int, presses: int) -> int:
    bulbs = [False] * n
    for _ in range(presses):
        for i in range(1, n + 1):
            if i == 1:
                bulbs = [not bulb for bulb in bulbs]
            elif i == 2:
                for j in range(2, n + 1, 2):
                    bulbs[j - 1] = not bulbs[j - 1]
            elif i == 3:
                for j in range(1, n + 1, 2):
                    bulbs[j - 1] = not bulbs[j - 1]
            else:
                for j in range(1, n + 1):
                    if (j % 3 == 1):
                        bulbs[j - 1] = not bulbs[j - 1]
    return len(set(bulbs))

class Solution:
    def clumsy(self, n: int) -> int:
        if n == 1:
            return 1
        elif n == 2:
            return 2
        elif n == 3:
            return 6
        else:
            res = n * (n - 1) // (n - 2) + (n - 3)
            n -= 4
            while n >= 4:
                res -= n * (n - 1) // (n - 2) - (n - 3)
                n -= 4
            if n == 3:
                return res - 6
            elif n == 2:
                return res - 2
            else:
                return res - 1

