class Solution:
    def cherryPickup(self, grid: List[List[int]]) -> int:
        
        rows, cols = len(grid), len(grid[0])
        dp = [[[-1 for _ in range(cols)] for _ in range(cols)] for _ in range(rows)]
        
        def dfs(row, col1, col2):
            if row == rows or col1 < 0 or col1 >= cols or col2 < 0 or col2 >= cols:
                return 0
            if dp[row][col1][col2] != -1:
                return dp[row][col1][col2]
            
            cherries = grid[row][col1]
            if col1 != col2:
                cherries += grid[row][col2]
            
            result = 0
            
            for new_col1 in range(col1-1, col1+2):
                for new_col2 in range(col2-1, col2+2):
                    result = max(result, dfs(row+1, new_col1, new_col2))
            
            if col1 == col2:
                result += cherries
            else:
                result += cherries + grid[row][col2]
            
            dp[row][col1][col2] = result
            return result
        
        return dfs(0, 0, cols-1)

