from math import sqrt, ceil

def closest_two_integers(num):
    # find the range for iterating possible values of x
    r = ceil(sqrt(num+2))
    
    # initialize variables for storing the closest integers found so far
    closest_diff = float("inf")
    closest_x, closest_y = 0, 0
    
    # iterate through possible values of x and calculate corresponding value of y
    for x in range(1, r+1):
        y = (num + x) / x - 1
        # check if y is an integer
        if y.is_integer():
            # calculate the absolute difference and check if it's closer than the current closest difference
            diff = abs(x - y)
            if diff < closest_diff:
                closest_diff = diff
                closest_x, closest_y = x, int(y)
    
    # return the closest integers in ascending order    
    if closest_x <= closest_y:
        return (closest_x, closest_y)
    else:
        return (closest_y, closest_x)

