from math import gcd

def get_closest_coprime_ancestor(nums, edges):
    n = len(nums)
    tree = [[] for _ in range(n)]
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)
    
    def dfs(node, parent):
        for neighbor in tree[node]:
            if neighbor != parent:
                dfs(neighbor, node)
                if ans[node] == -1 and ans[neighbor] != -1 and gcd(nums[node], nums[neighbor]) == 1:
                    ans[node] = neighbor
        if ans[node] == -1 and gcd(nums[node], nums[parent]) == 1:
            ans[node] = parent
    
    ans = [-1] * n
    dfs(0, 0)
    return ans

