from functools import lru_cache

class Solution:
    def optimalDivision(self, nums: List[int]) -> str:
        @lru_cache
        def dfs(left, right):
            if left == right:
                return str(nums[left])
            if left + 1 == right:
                return str(nums[left]) + '/' + str(nums[right])
            res = str(nums[left]) + '/('
            for i in range(left + 1, right):
                res += str(nums[i]) + '/'
            res += str(nums[right]) + ')'
            for i in range(left + 1, right):
                temp = str(nums[left]) + '/('
                for j in range(left + 1, i):
                    temp += str(nums[j]) + '/'
                temp += str(nums[i]) + '/('
                for j in range(i + 1, right):
                    temp += str(nums[j]) + '/'
                temp = temp[:-1] + ')' * (right - i) + ')'
                if eval(temp) > eval(res):
                    res = temp
            return res

        return dfs(0, len(nums) - 1)

