    def majorityElementOptimal(self, nums):
        if not nums:
            return nums
        
        count = 1
        majority = nums[0]
        
        for i in range(1, len(nums)):
            num = nums[i]
            
            if count == 0:
                count = 1
                majority = num
            elif majority == num:
                count += 1
                
            else:
                count -= 1
                
        return majority
    
