# runtime: 313ms 12.52%
    def majorityElementWithHashMap(self, nums):
        if not nums:
            return nums
        
        hashMap = dict()
        n = len(nums)
        for i in nums:
            hashMap[i] = 1 + hashMap.get(i, 0)
            if hashMap[i] > (n//2):
                return i

