class Solution:
    def fib(self, n: int) -> int:
        # base cases to consider 
        if n == 0 : 
            return 0
        elif 0 < n <= 2 : 
            return int(1) 
        # binet's formula for higher values 
        else : 
            # binet's formula is 
            # ((1+sqrt(5))/2)^n - ((1-sqrt5)/2)^2 * (1/sqrt(5))
            # this is the value of square root of 5 
            s5 = 2.23606797749979
            # left and right points 
            left = (1+s5)/2
            right = (1-s5)/2
            # here's our 1/sqrt(5)
            divisor = 1/s5
            # int cast to satisfy problem 
            return int(divisor*(math.pow(left, n) - math.pow(right, n)))

