def gridIllumination(n: int, lamps: List[List[int]], queries: List[List[int]]) -> List[int]:
    def turn_on(row, col):
        for i in [-1, 0, 1]:
            for j in [-1, 0, 1]:
                new_row, new_col = row+i, col+j
                if new_row >= 0 and new_row < n and new_col >= 0 and new_col < n:
                    if (new_row, new_col) in lamps:
                        lamps.remove((new_row, new_col))
                        if (new_row+i, new_col+j) not in turned_off_lamps:
                            turned_off_lamps.append((new_row+i, new_col+j))
    
    def turn_off(row, col):
        for i in [-1, 0, 1]:
            for j in [-1, 0, 1]:
                new_row, new_col = row+i, col+j
                if new_row >= 0 and new_row < n and new_col >= 0 and new_col < n:
                    if (new_row, new_col) not in lamps:
                        if (new_row, new_col) not in turned_off_lamps:
                            turned_off_lamps.append((new_row, new_col))
    
    def is_illuminated(row, col):
        if (row, col) in lamps:
            return 1
        for i in [-1, 0, 1]:
            for j in [-1, 0, 1]:
                new_row, new_col = row+i, col+j
                if new_row >= 0 and new_row < n and new_col >= 0 and new_col < n:
                    if (new_row, new_col) in lamps:
                        return 1
        return 0
    
    lamps = set(tuple(lamp) for lamp in lamps)
    turned_off_lamps = []
    for lamp in lamps:
        turn_on(*lamp)
    
    ans = []
    for query in queries:
        row, col = query
        illuminated = is_illuminated(row, col)
        ans.append(illuminated)
        turn_off(row, col)
        for turned_off_lamp in turned_off_lamps:
            turn_on(*turned_off_lamp)
        turned_off_lamps = []
        
    return ans

