            map(lambda x: x[0], 
			    # this function terminates loop when all bits from num are counted
                takewhile(lambda x: x[1] > 0, 
                      (
					    # 3-part tuple:
						#  - positional bit
						#  - leftover from num, it is used to exit infinite loop
						#  - third element we keep only to increase next bit
                        ((power if data[1] == 0 else 0), data[0], (power := power * 2))
						# infinite loop 
                        for _ in count()       
						# compute next bit and reduce data[0]
                        if (data := divmod(data[0], 2))[0] >= 0
