def max_integers_matrix(n, ops):
    matrix = [[0] * n for _ in range(n)]
    
    for op in ops:
        for i in range(op[0]):
            for j in range(op[1]):
                matrix[i][j] += 1
    
    return max([max(row) for row in matrix])

