class Solution:
    def reverseStr(self, s: str, k: int) -> str:
        counter = 0
        ans = [c for c in s]
        
        # number of iterations that we will make in s
        iterations = len(s) // (2 * k)
        # if s is not perfectly divisible by 2k, add 1 extra iteration
        if len(s) % (2 * k):
            iterations += 1
            
        while counter < iterations:
            # initialize left and right positions
            left = counter * (2 * k)
            right = left + (2 * k) - 1
            
            if right >= len(s):
                right = len(s) - 1
            
            # case 1: if remaining part of string is smaller than k in size, reverse it entirely
            if (right - left + 1) < k:
                while left < right:
                    ans[left], ans[right] = ans[right], ans[left]
                    left += 1
                    right -= 1

            # case 2: if remaining part of string is in range [k, 2k], reverse first k elements
            elif k <= (right - left + 1) <= (2 * k):
                # update the right pointer to make the current range's size equal to k
                right = left + k - 1
                while left < right:
                    ans[left], ans[right] = ans[right], ans[left]
                    left += 1
                    right -= 1
            
            # print(ans)
            counter += 1
        
        return "".join(ans)

