            if 0 <= i+1 < len(mat) and mat[i+1][j] == colour[0] and (i+1, j) not in been:
                been.add((i+1, j))
                dfs(mat, i+1, j, been, colour, center)
            if 0 <= i-1 < len(mat) and mat[i-1][j] == colour[0] and (i-1, j) not in been:
                been.add((i-1, j))
                dfs(mat, i-1, j, been, colour, center)
            if 0 <= j+1 < len(mat[i]) and mat[i][j+1] == colour[0] and (i, j+1) not in been:
                been.add((i, j+1))
                dfs(mat, i, j+1, been, colour, center)
            if 0 <= j-1 < len(mat[i]) and mat[i][j-1] == colour[0] and (i, j-1) not in been:
                been.add((i, j-1))
                dfs(mat, i, j-1, been, colour, center)


