def colorBorder(grid, row, col, color):
    def dfs(grid, r, c, visited, component, border):
        if r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0]) or grid[r][c] not in component or (r, c) in visited:
            return
        visited.add((r, c))
        if r == 0 or r == len(grid) - 1 or c == 0 or c == len(grid[0]) - 1 or any((nr, nc) not in visited or grid[nr][nc] not in component for nr, nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1))):
            border.add((r, c))
        dfs(grid, r+1, c, visited, component, border)
        dfs(grid, r-1, c, visited, component, border)
        dfs(grid, r, c+1, visited, component, border)
        dfs(grid, r, c-1, visited, component, border)
            
