class Solution:
    def reorganizeString(self, s: str) -> str:
        n = len(s)
        s = Counter(s)
        max_l = s.most_common(1)[0][1]
        # if  the number of any letter larger then the haft length (or plus1 when it is even) of the string
		# impossible to reorganize
		if (n+1)//2<max_l:
            return ""
        
        # using odd/even insert
        oddIndex=0
        evenIndex=1
		out=[""]*n # create slot
        
        for k,v in s.most_common():
            while v and oddIndex<n: # fill the most letter in all odd places
                out[oddIndex] = k
                oddIndex+=2
                v-=1
            while v: # then fill the remain in evenIndex
                out[evenIndex] = k
                evenIndex+=2
                v-=1
        return "".join(out)
        
        
        
        # using heapq
        q = []
        out=""
        for k,v in s.items():
            heapq.heappush(q,(-v,k))
        
        while len(q)>1:
            v,l=heapq.heappop(q)
            if not len(out):
                out+=l
                if v+1<0:
                    heapq.heappush(q,(v+1,l))
            elif l!=out[-1]:
                out+=l
                if v+1<0:
                    heapq.heappush(q,(v+1,l))
            else:
                v2,l2=heapq.heappop(q)
                out+=l2
                if v2+1<0:
                    heapq.heappush(q,(v2+1,l2))
                heapq.heappush(q,(v,l))
        
        if q[0][0]<-1:
            return ""
        else:
            return out+q[0][1]

