class Solution:
    def reorganizeString(self, s: str) -> str:
        freq = collections.Counter(s)
        heap = [(-value, key) for key, value in freq.items()]
        heapq.heapify(heap)
        ans = []
        while len(ans) < len(s):
            if not heap:
                return ""
            f, c = heapq.heappop(heap)
            if ans and ans[-1] == c:
                if not heap:
                    return ""
                f2, c2 = heapq.heappop(heap)
                ans.append(c2)
                heapq.heappush(heap, (f, c))
                if f2+1 < 0:
                    heapq.heappush(heap, (f2+1, c2))
            else:
                ans.append(c)
                if f+1 < 0:
                    heapq.heappush(heap, (f+1, c))
        return "".join(ans)

