import heapq

class Solution:
    def nthSuperUglyNumber(self, n: int, primes: List[int]) -> int:
        uglies = [1]
        def generate(prime):
            for ugly in uglies:
                yield ugly * prime
        
        merged = heapq.merge(*map(generate, primes))
        while len(uglies) < n:
            ugly = next(merged)
            if ugly != uglies[-1]:
                uglies.append(ugly)
        
        return uglies[-1]

def is_palindrome(num):
    return str(num) == str(num)[::-1]

def is_super_palindrome(num):
    if is_palindrome(num):
        sqrt_num = int(num ** 0.5)
        return is_palindrome(sqrt_num) and sqrt_num ** 2 == num
    return False

def superpalindromesInRange(left, right):
    left_num = int(left)
    right_num = int(right)
    res = 0
    for i in range(1, 100000):
        if i ** 2 > right_num:
            break
        if is_super_palindrome(i ** 2) and left_num <= i ** 2 <= right_num:
            res += 1
    for i in range(1, 100000):
        if i > right_num:
            break
        for j in [0, 1, 2, 3, 4]:
            num = int(str(i) + str(j) + str(i)[::-1])
            if num ** 2 > right_num:
                break
            if is_super_palindrome(num ** 2) and left_num <= num ** 2 <= right_num:
                res += 1
    return res

