MOD = 10**9 + 7

def count_arrays(k):
    if k == '1':
        return 9
    n = len(k)
    dp = [0] * n
    dp[0] = 9  # number of arrays for k = '1'
    for i in range(1, n):
        dp[i] = (dp[i-1] * 10 - dp[i-1]) % MOD
    ans = dp[-1]
    for i, digit in enumerate(k):
        if digit == '0' or digit == '1':
            continue
        ans = (ans + dp[n-i-1] * (int(digit)-1)) % MOD
    return ans

