        rec1HozlRight = rec1[2]
        rec2HozlLeft = rec2[0]
        rec2HozlRight = rec2[2]
        
        #All Vertical coordinates of Rec1 and Rec2;
        rec1VerBottom = rec1[1]
        rec1VerTop = rec1[3]
        rec2VerBottom = rec2[1]
