class Solution:
    def calcEquation(self, equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:
        graph = {}
        
        # Step 1: Build the graph
        for i in range(len(equations)):
            a = equations[i][0]
            b = equations[i][1]
            val = values[i]
            
            # Add edges in both directions
            if a not in graph:
                graph[a] = {}
            graph[a][b] = val
            
            if b not in graph:
                graph[b] = {}
            graph[b][a] = 1/val
            
        # Step 2: For each query, try to find a path between the two variables using DFS
        def dfs(x, y, visited):
            if x == y:
                return 1.0
            
            if x not in graph or y not in graph:
                return -1.0
            
            if y in graph[x]:
                return graph[x][y]
            
            for neighbor in graph[x]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    val = dfs(neighbor, y, visited)
                    if val != -1.0:
                        return graph[x][neighbor] * val
            
            return -1.0
        
        # Step 3: Calculate the answer for each query using DFS
        results = []
        for query in queries:
            x = query[0]
            y = query[1]
            visited = set()
            results.append(dfs(x, y, visited))
        
        return results

def convert(s, numRows):
    if numRows == 1 or numRows >= len(s):
        return s
    res = [''] * numRows
    index, step = 0, 1
    for char in s:
        res[index] += char
        if index == 0:
            step = 1
        elif index == numRows - 1:
            step = -1
        index += step
    return ''.join(res)

def countSubIslands(grid1: List[List[int]], grid2: List[List[int]]) -> int:
    def dfs(i: int, j: int) -> bool:
        if i < 0 or i >= m or j < 0 or j >= n or grid2[i][j] == 0:
            return True
        res = True
        if grid1[i][j] == 0:
            res = False
        grid2[i][j] = 0
        res &= dfs(i+1, j)
        res &= dfs(i-1, j)
        res &= dfs(i, j+1)
        res &= dfs(i, j-1)
        return res
    
    m, n = len(grid2), len(grid2[0])
    cnt = 0
    for i in range(m):
        for j in range(n):
            if grid2[i][j] == 1 and dfs(i, j):
                cnt += 1
    return cnt

from typing import List

def lastStoneWeight(stones: List[int]) -> int:
    while len(stones) > 1:
        stones.sort()
        x = stones.pop()
        y = stones.pop()
        if x != y:
            stones.append(y - x)
    if stones:
        return stones[0]
    else:
        return 0

class Solution:
    def findPeakElement(self, nums: List[int]) -> int:
        left = 0
        right = len(nums) - 1
        while left < right:
            mid = (left + right) // 2
            if nums[mid] < nums[mid+1]:
                left = mid + 1
            else:
                right = mid
        return left

def rearrangeCards(hand, groupSize):
    hand.sort()
    i = 0
    while i < len(hand):
        if i + groupSize > len(hand):
            return False
        for j in range(i+1, i+groupSize):
            if hand[j] != hand[i]:
                return False
        i = i + groupSize
    return True

def printTree(root):
    """
    :type root: TreeNode
    :rtype: List[List[str]]
    """
    def get_height(root):
        if not root:
            return 0
        return 1 + max(get_height(root.left), get_height(root.right))
    
    def fill(root, level, left, right, res):
        if not root:
            return
        mid = (left + right) // 2
        res[level][mid] = str(root.val)
        fill(root.left, level+1, left, mid-1, res)
        fill(root.right, level+1, mid+1, right, res)

    height = get_height(root)
    res = [["" for i in range((2**height)-1)] for j in range(height)]
    fill(root, 0, 0, len(res[0])-1, res)
    return res

