class Solution:
    def singleNumber(self, nums: List[int]) -> List[int]:
        # XOR all elements in the array
        xor_result = 0
        for num in nums:
            xor_result ^= num
        
        # Find the rightmost set bit
        rightmost_set_bit = 1
        while xor_result & rightmost_set_bit == 0:
            rightmost_set_bit = rightmost_set_bit << 1
        
        # Divide the nums array into two subarrays based on the rightmost set bit
        num1, num2 = 0, 0
        for num in nums:
            if num & rightmost_set_bit == 0:
                num1 ^= num
            else:
                num2 ^= num
        
        return [num1, num2]

