def threeEqualParts(arr):
    ones = arr.count(1)
    if ones % 3 != 0:
        return [-1, -1]
    if ones == 0:
        return [0, len(arr) - 1]
    target_ones = ones // 3
    i = 0
    while arr[i] == 0:
        i += 1
    ones_count = 0
    while ones_count < target_ones:
        ones_count += arr[i]
        i += 1
    j = i
    ones_count = 0
    while ones_count < target_ones:
        ones_count += arr[j]
        j += 1
    while arr[i] == 0:
        i += 1
    while j < len(arr):
        if arr[j] != arr[i] or arr[j] != arr[i]:
            return [-1, -1]
        i += 1
        j += 1
    return [i - 1, j]

