class Solution:
    def orderOfLargestPlusSign(self, n: int, mines: List[List[int]]) -> int:
        grid = [[1] * n for _ in range(n)]
        for mine in mines:
            grid[mine[0]][mine[1]] = 0

        left, right, up, down = [[0] * n for _ in range(n)], [[0] * n for _ in range(n)], [[0] * n for _ in range(n)], [[0] * n for _ in range(n)]

        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    left[i][j] = left[i][j - 1] + 1 if j > 0 else 1
                    up[i][j] = up[i - 1][j] + 1 if i > 0 else 1

        for i in reversed(range(n)):
            for j in reversed(range(n)):
                if grid[i][j] == 1:
                    right[i][j] = right[i][j + 1] + 1 if j < n - 1 else 1
                    down[i][j] = down[i + 1][j] + 1 if i < n - 1 else 1

        res = 0
        for i in range(n):
            for j in range(n):
                res = max(res, min(left[i][j], right[i][j], up[i][j], down[i][j]))

        return res

class Solution:
    def isRectangleCover(self, rectangles: List[List[int]]) -> bool:
        points = set()

        area = 0

        for rect in rectangles:
            x1, y1, x2, y2 = rect
            area += (x2 - x1) * (y2 - y1)

            p1 = (x1, y1)
            p2 = (x1, y2)
            p3 = (x2, y1)
            p4 = (x2, y2)

            for p in [p1, p2, p3, p4]:
                if p in points:
                    points.remove(p)
                else:
                    points.add(p)

        if len(points) != 4:
            return False

        points = sorted(list(points))

        x1, y1 = points[0]
        x2, y2 = points[-1]

        return area == (x2 - x1) * (y2 - y1) and (x2 - x1) * (y2 - y1) == sum((x2 - x1) * (y2 - y1) for (x1, y1), (x2, y2) in zip(points, points[1:]))

