def can_fit_stamps(grid, stampHeight, stampWidth):
    def can_fit(row, col, stamp):
        for i in range(stampHeight):
            for j in range(stampWidth):
                if not (0 <= row+i < len(grid) and 0 <= col+j < len(grid[0]) and
                        (stamp[i][j] == 0 or grid[row+i][col+j] == 0)):
                    return False
        return True
    
    def apply_stamp(row, col, stamp):
        for i in range(stampHeight):
            for j in range(stampWidth):
                if stamp[i][j] == 1:
                     grid[row+i][col+j] = 1
    
    def remove_stamp(row, col, stamp):
        for i in range(stampHeight):
            for j in range(stampWidth):
                if stamp[i][j] == 1:
                     grid[row+i][col+j] = 0
    
    def rotate_stamp(stamp):
        return [list(reversed(x)) for x in zip(*stamp)]
    
    def backtrack():
        nonlocal possible
        if not any(0 in row for row in grid): 
            possible = True # all cells have been filled
            return
        
        for row in range(len(grid)):
            for col in range(len(grid[0])):
                if grid[row][col] == 1:
                    for i in range(4): # try all 4 rotations
                        stamp = rotate_stamp(stamp) if i > 0 else stamp
                        if can_fit(row, col, stamp):
                            apply_stamp(row, col, stamp)
                            backtrack()
                            if possible: return
                            remove_stamp(row, col, stamp)

    possible = False
    for row in range(len(grid)):
        for col in range(len(grid[0])):
            stamp = [[1]*stampWidth for _ in range(stampHeight)]
            if can_fit(row, col, stamp):
                apply_stamp(row, col, stamp)
                backtrack()
                if possible: return True
                remove_stamp(row, col, stamp)
    return False

