        else:
            if meeting[0] >= min(rooms):
                rooms[rooms.index(min(rooms))] = meeting[1]
            else:
                rooms.append(meeting[1])
    return len(rooms)

def flipAndInvertImage(image):
    for row in image:
        row.reverse()
        for i in range(len(row)):
            row[i] = 1 - row[i]
    return image

class Solution:
    def countRangeSum(self, nums: List[int], lower: int, upper: int) -> int:
        presum = [0]
        for i in range(len(nums)):
            presum.append(presum[-1]+nums[i])
        self.res = 0
        def merge(start, end):
            if start >= end:
                return
            mid = (start+end) // 2
            merge(start, mid)
            merge(mid+1, end)
            # counting
            i = j = mid+1
            for left in presum[start:mid+1]:
                while i <= end and presum[i]-left < lower:
                    i += 1
                while j <= end and presum[j]-left <= upper:
                    j += 1
                self.res += j-i
            # merging
            L, R = presum[start:mid+1], presum[mid+1:end+1]
            i = j = 0
            for k in range(start, end+1):
                if j == len(R) or (i < len(L) and L[i] <= R[j]):
                    presum[k] = L[i]
                    i += 1
                else:
                    presum[k] = R[j]
                    j += 1
        merge(0, len(presum)-1)
        return self.res

