def isBipartite(graph: List[List[int]]) -> bool:
    colors = {}
    def dfs(node, color):
        if node in colors:
            return colors[node] == color
        colors[node] = color
        for neighbor in graph[node]:
            if not dfs(neighbor, 1 - color):
                return False
        return True
    for node in range(len(graph)):
        if node not in colors:
            if not dfs(node, 0):
                return False
    return True

