def is_isomorphic(t1: str, t2: str) -> bool:
    if len(t1) != len(t2):
        return False
    mapping = {}
    mapped_chars = set()
    for i in range(len(t1)):
        if t1[i] not in mapping:
            if t2[i] in mapped_chars:
                return False
            mapping[t1[i]] = t2[i]
            mapped_chars.add(t2[i])
        elif mapping[t1[i]] != t2[i]:
            return False
    return True

