class Solution:
    def camelMatch(self, queries: List[str], pattern: str) -> List[bool]:

        results = []

        for query in queries:

            pIndex = 0
            qIndex = 0
            matched = False
            flag = False

            while pIndex < len(pattern) and qIndex < len(query):

                pchar = pattern[pIndex]
                qchar = query[qIndex]

                if pchar == qchar:
                    pIndex = pIndex + 1
                    qIndex = qIndex + 1
                else:
                    if qchar.isupper():
                        matched = False
                        flag  = True
                        break
                    qIndex = qIndex + 1


            if not flag:

                if pIndex < len(pattern):
                    matched = False

                elif qIndex < len(query):
                    matched = True
                    while qIndex < len(query):
                        if query[qIndex].isupper():
                            matched = False
                            break
                        qIndex = qIndex + 1

                elif pIndex >= len(pattern) and qIndex >= len(query):
                    matched = True

            results.append(matched)

        return results

