class Solution:
    def leafSimilar(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
        
        #Lists for each path
        #I append to them during the recursion
		#This will work because lists are mutable
		#And will keep the changes made to them throughout
		#The recursions
		
        firstPath = [];
        secondPath = [];
        
        #Call the helper function on both roots each with their respective path list
        self.findLeafSeq( root1, firstPath );
        self.findLeafSeq( root2, secondPath );
        
        #See if they are equal
        return firstPath == secondPath;
        
    
        #At each level
    def findLeafSeq( self, root , leafPath ):
        
        #Look at the children
        leftChild = root.left;
        rightChild = root.right;
        
        #If they are both None, we are a leaf
        if leftChild is None and rightChild is None:
            #So we take the current value and append it to the path
            current = root.val;
            leafPath.append( current );
            return;
        
        #Otherwise we dig down into the recursion
        #If there is only one child, because the other is none
        #take the valid path
        elif leftChild is None:
            self.findLeafSeq( rightChild, leafPath );
        elif rightChild is None:
            self.findLeafSeq( leftChild, leafPath );
        #If there are two children, call the left and then the right child
        else:
            self.findLeafSeq( leftChild, leafPath );
            self.findLeafSeq( rightChild, leafPath );

