def leafSimilar(root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
    def get_leaf_values(node):
        if not node:
            return []
        if not node.left and not node.right:
            return [node.val]
        return get_leaf_values(node.left) + get_leaf_values(node.right)

    return get_leaf_values(root1) == get_leaf_values(root2)

class Solution:
    def maxAreaOfIsland(self, grid: List[List[int]]) -> int:
        def dfs(i, j):
            nonlocal area
            if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == 0:
                return
            area += 1
            grid[i][j] = 0
            dfs(i+1, j)
            dfs(i-1, j)
            dfs(i, j+1)
            dfs(i, j-1)

        max_area = 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    area = 0
                    dfs(i, j)
                    max_area = max(max_area, area)
        return max_area

class Solution:
    def minOperations(self, logs: List[str]) -> int:
        stack = []
