def R(expr):
    if len(expr) == 1:
        return {expr}
    elif ',' in expr:
        expr = expr[1:-1]
        sub_expr = []
        count = 0
        for i in range(len(expr)):
            if expr[i] == '{':
                count += 1
            elif expr[i] == '}':
                count -= 1
            if count == 0 and expr[i] == ',':
                sub_expr.append(expr[:i])
                expr = expr[i+1:]
        sub_expr.append(expr)
        result = set()
        for e in sub_expr:
            result.update(R(e))
        return result
    else:
        i = 0
        count = 0
        while i < len(expr):
            if expr[i] == '{':
                count += 1
            elif expr[i] == '}':
                count -= 1
            elif count == 0:
                break
            i += 1
        if i < len(expr)-1:
            a = R(expr[:i+1])
            b = R(expr[i+1:])
            result = set()
            for x in a:
                for y in b:
                    result.add(x+y)
            return result
        else:
            return R(expr[:-1])

