def maximum_width_ramp(nums):
    stack = []
    max_width = 0
    for i in range(len(nums)):
        if not stack or nums[i] < nums[stack[-1]]:
            stack.append(i)
        else:
            while stack and nums[i] >= nums[stack[-1]]:
                j = stack.pop()
                max_width = max(max_width, i - j)
    return max_width

