from collections import defaultdict
import heapq

def networkDelayTime(times, n, k):
    graph = defaultdict(list)
    for u, v, w in times:
        graph[u].append((v, w))
        
    pq = [(0, k)]
    dist = {}
    while pq:
        time, node = heapq.heappop(pq)
        if node in dist:
            continue
        dist[node] = time
        for neighbor, neighbor_time in graph[node]:
            if neighbor not in dist:
                heapq.heappush(pq, (time + neighbor_time, neighbor))
                
    if len(dist) == n:
        return max(dist.values())
    
    return -1

def num_walking_cells(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    boundary = set()
    
    def dfs(r, c):
        nonlocal visited
        nonlocal boundary
        visited.add((r,c))
        for (dr, dc) in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= rows or nc < 0 or nc >= cols or grid[nr][nc] == 0:
                boundary.add((r,c))
            elif (nr,nc) not in visited:
                dfs(nr, nc)
    
    for r in [0, rows-1]:
        for c in range(cols):
            if grid[r][c] == 1:
                dfs(r,c)
    for r in range(1,rows-1):
        for c in [0, cols-1]:
            if grid[r][c] == 1:
                dfs(r,c)
    
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r,c) not in boundary:
                count += 1
    
    return (count, len(boundary))

def spellchecker(wordlist, queries):
    def process(word):
        return "".join(['*' if c in "aeiouAEIOU" else c for c in word.lower()])
    
    words_dict = {}
    for word in wordlist:
        words_dict[word] = word
        words_dict[word.lower()] = word
        words_dict[process(word)] = word
    
    ans = []
    for query in queries:
        if query in words_dict:
            ans.append(words_dict[query])
            continue
            
        query_lower = query.lower()
        if query_lower in words_dict:
            ans.append(words_dict[query_lower])
            continue
            
        query_processed = process(query)
        if query_processed in words_dict:
            ans.append(words_dict[query_processed])
            continue
            
        ans.append("")
        
    return ans

