def solve_equation(equation: str) -> Union[str, int]:
    equation_split = equation.split("=")
    left = equation_split[0]
    right = equation_split[1]
    left_x = 0
    left_val = 0
    right_x = 0
    right_val = 0
    for l in left.split("+"):
        if "x" in l:
            if len(l) == 1:
                left_x += 1
            else:
                left_x += int(l.strip("x"))
        else:
            left_val += int(l)
    for r in right.split("+"):
        if "x" in r:
            if len(r) == 1:
                right_x += 1
            else:
                right_x += int(r.strip("x"))
        else:
            right_val += int(r)
    x_coefficient = left_x - right_x
    value = right_val - left_val
    if x_coefficient == 0 and value != 0:
        return "No solution"
    elif x_coefficient == 0 and value == 0:
        return "Infinite solutions"
    else:
        return value // x_coefficient

