def compress(chars):
    """
    :type chars: List[str]
    :rtype: int
    """
    index = 0
    count = 1
    for i in range(1, len(chars) + 1):
        if i < len(chars) and chars[i] == chars[i - 1]:
            count += 1
        else:
            chars[index] = chars[i - 1]
            index += 1
            if count > 1:
                for digit in str(count):
                    chars[index] = digit
                    index += 1
            count = 1
    return index

def reshape(mat, r, c):
    rows = len(mat)
    cols = len(mat[0])
    
    if rows * cols == r * c:
        flattened = [elem for row in mat for elem in row]
        reshaped = [flattened[i*c:(i+1)*c] for i in range(r)]
        return reshaped
    else:
        return mat

