def entity_parser(text):
    specials = {
        "&quot;": "\"",
        "&apos;": "\'",
        "&amp;": "&",
        "&gt;": ">",
        "&lt;": "<",
        "&frasl;": "/"
    }
    for special in specials:
        text = text.replace(special, specials[special])
    return text

