def refill_count(plants, capacityA, capacityB):
    refill = 0
    waterA = capacityA
    waterB = capacityB
    left = 0
    right = len(plants) - 1
    
    while left <= right:
        if waterA < plants[left]:
            waterA = capacityA
            refill += 1
        else:
            waterA -= plants[left]
            left += 1
        
        if left > right:
            break
        
        if waterB < plants[right]:
            waterB = capacityB
            refill += 1
        else:
            waterB -= plants[right]
            right -= 1
        
