        right = len(s) - 1
        while left < right:
            if s[left] != s[right]:
                return self.isPalindrome(s, left + 1, right) or self.isPalindrome(s, left, right - 1)
            left += 1
            right -= 1
        return True
    
    def isPalindrome(self, s: str, left: int, right: int) -> bool:
        while left < right:
            if s[left] != s[right]:
                return False
            left += 1
            right -= 1
        return True

class Solution:
    def twoCitySchedCost(self, costs: List[List[int]]) -> int:
        sorted_costs = sorted(costs, key=lambda x: x[0] - x[1])
        n = len(costs) // 2
        min_cost = 0
        for i in range(n):
            min_cost += sorted_costs[i][0] + sorted_costs[i + n][1]
        return min_cost

def circularArray(nums):
    n = len(nums)
    visited = [False for _ in range(n)]
    for i in range(n):
        if not visited[i]:
            cycle = set()
            while i not in cycle:
                cycle.add(i)
                visited[i] = True
                i = (i + nums[i]) % n
            if len(cycle) > 1:
                return True
    return False

def countDigitOne(n):
    count, x, k = 0, 1, 1
    while n >= x:
        d = int((n//x) % 10)
        count += (n//x//10 * x)
        if d > k:
            count += x
        elif d == k:
            count += n % x + 1
        k = d
        x *= 10
    return count

