class Solution:
    def majorityElement(self, nums: List[int]) -> List[int]:
        count1 = count2 = 0
        candidate1, candidate2 = 0, 1 # testcase: [0, 0, 0]
        
        for num in nums:
            if num == candidate1:
                count1 += 1
            elif num == candidate2:
                count2 += 1
            elif count1 == 0:
                candidate1, count1 = num, 1
            elif count2 == 0:
                candidate2, count2 = num, 2
            else:
                count1 -= 1
                count2 -= 1
        
        res = []
        for candidate in [candidate1, candidate2]:
            cnt = 0
            for num in nums:
                if num == candidate:
                    cnt += 1
            
            if cnt > len(nums) // 3:
                res.append(candidate)
            
        return res

