from collections import Counter

def find_frequent_elements(arr):
    n = len(arr)
    freq = n // 3
    counter = Counter(arr)
    res = []
    for num, count in counter.items():
        if count > freq:
            res.append(num)
    return res

def rankTeams(votes):
    ranks = {}
    for vote in votes:
        for i, team in enumerate(vote):
            if team not in ranks:
                ranks[team] = [0]*len(vote)
            ranks[team][i] += 1
    sorted_teams = sorted(ranks.keys(), key=lambda x: (-ranks[x], x))
    return ''.join(sorted_teams)

