from heapq import heappop, heappush

def getSkyline(buildings):
    events = [(l, -h, r) for l, r, h in buildings]
    events += list({(r, 0, None) for _, r, _ in buildings})
    events.sort()
    ans, heap = [[0, 0]], [(0, float('inf'))]
    for l, h, r in events:
        while l >= heap[0][1]:
            heappop(heap)
        if h:
            heappush(heap, (h, r))
        if ans[-1][1] != -heap[0][0]:
            ans += [[l, -heap[0][0]]]
    return ans[1:]


