class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def insertionSortList(head: ListNode) -> ListNode:
    if not head or not head.next:
        return head
    
    dummy = ListNode(0) # create dummy node
    dummy.next = head # point dummy to head
    
    current = head
    while current.next:
        if current.val > current.next.val:
            pre = dummy
            while pre.next.val < current.next.val:
                pre = pre.next
            temp = current.next
            current.next = temp.next
            temp.next = pre.next
            pre.next = temp
        else:
            current = current.next
    return dummy.next

