def remove_node(root):
    result = []
    
    def traverse(node):
        if node is None:
            return False
        
        left = traverse(node.left)
        right = traverse(node.right)
        
        if left or right:
            node.left = None
            node.right = None
            result.append(node)
            return True
        
        if node.val == 1:
            if node.left is not None:
                result.append(node.left)
            if node.right is not None:
                result.append(node.right)
            return True
        
        return False
    
    traverse(root)
    if root.val != 1:
        result.append(root)
    return result

def shortest_palindrome(s: str) -> str:
    if s == s[::-1]:
        return s
    for i in range(1, len(s)+1):
        if s[:i] == s[i-1::-1]:
            return s[i:][::-1] + s[:i] + s[i:]

