class Solution:
    def kthFactor(self, n: int, k: int) -> int:
        factors = dict() #taking a dictionary here so that the factors do not get repeated.
        count = 0
        for i in range(1, int(n**0.5)+1):
            if n%i == 0:
                if not factors.get(i): #enter in the dictionary only if the factor hasn't already been added to the dict, you can put any value corresponding to the factor(key) in the dictionary.
                    factors[i] = 1
        for i in range(int(n**0.5), 0, -1):
            if n%i == 0:
                if not factors.get(n//i):
                    count += 1
                    factors[n//i] = count
        factors = list(factors.keys())
        if len(factors) < k:
            return -1
        return factors[k-1]

