def min_semesters(n, relations, k):
    prerequisites = {}
    for relation in relations:
        if relation[1] not in prerequisites:
            prerequisites[relation[1]] = set()
        prerequisites[relation[1]].add(relation[0])
    
    semesters = 0
    courses_left = set(range(1, n+1))
    while courses_left:
        courses_taken = set()
        for course in courses_left:
            if course not in prerequisites or prerequisites[course].issubset(courses_taken):
                courses_taken.add(course)
        courses_left -= courses_taken
        semesters += 1
        if len(courses_taken) > k:
            return -1
    return semesters

