def minimum_operations(n):
    count = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
            count += 1
        else:
            if (n - 1) % 2 == 0 or n == 3:
                n -= 1
                count += 1
            else:
                n += 1
                count += 1
    return count

