class Solution:
    "BFS"
    def bfs(self, isConnected):
        n = len(isConnected)
        visited = set()
        ans = 0
        for i in range(n):
            if i in visited:
                continue
            q = deque([i])
            while q:
                n = q.popleft()
                visited.add(n)
                for n_i, status in enumerate(isConnected[n]):
                    if status and n_i not in visited:
                        q.append(n_i)
            ans += 1
        return ans

    "Union-Find"
    def union_find(self, isConnected):
        n = len(isConnected)
        parent = [i for i in range(n)]
        size = [1 for i in range(n)]
        def find_parent(i):
            if i != parent[i]:
                parent[i] = find_parent(parent[i])  # path compression
            return parent[i]

        def find_parent_iterate(i):
            while i != parent[i]:
                parent[i] == parent[parent[i]]
                i = parent[i]
            return i

        def union(i, j):
            p_i = find_parent(i)
            p_j = find_parent(j)
            if p_i != p_j:  # size balance
                if size[p_i] > size[p_j]:
                    parent[p_j] = p_i
                    size[p_i] += size[p_j]
                else:
                    parent[p_i] = p_j
                    size[p_j] += size[p_i]
            return 

        for i in range(n):
            for j, adj in enumerate(isConnected[i]):
                if adj and i > j:
                    union(i, j)
        component = set()
        for i in range(n):
            component.add(find_parent(i)) # should find "root" of i, instead of parent
        return len(component)

    "DFS"
    def dfs(self, isConnected):
        def helper_iterate(i, isConnected, visited):
            stack = [i]
            while stack:
                node = stack.pop()
                visited.add(node)
                for j, adj in enumerate(isConnected[node]):
                    if adj and j not in visited:
                        stack.append(j)
            return 

        def helper(i, isConnected, visited):
            visited.add(i)
            for j, adj in enumerate(isConnected[i]):
                if adj and j not in visited:
                    helper(j, isConnected, visited)
        n = len(isConnected)
        visited = set()
        ans = 0
        for i in range(n):
            if i in visited:
                continue
            helper(i, isConnected, visited)
            ans += 1
        return ans


    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        #return self.bfs(isConnected)
        #return self.union_find(isConnected)
        return self.dfs(isConnected)

