class Solution:
    def findJudge(self, n: int, trust: List[List[int]]) -> int:
        trustCounts = [0] * (n + 1)
        for t in trust:
            trustCounts[t[0]] -= 1
            trustCounts[t[1]] += 1
        
        for i in range(1, n + 1):
            if trustCounts[i] == n - 1:
                return i
        
        return -1

def scheduleCourse(courses: List[List[int]]) -> int:
    courses.sort(key=lambda x: x[1])
    current_day = 0
    count = 0
    for course in courses:
        if current_day + course[0] <= course[1]:
            current_day += course[0]
            count += 1
        else:
            max_duration = max(courses[:courses.index(course)], key=lambda x: x[0])[0]
            if course[0] < max_duration:
                current_day = current_day - max_duration + course[0]
    return count

class Solution:
    def shiftingLetters(self, s: str, shifts: List[int]) -> str:
        total_shift = sum(shifts)
        new_str = ""
        for i, char in enumerate(s):
            shift = total_shift % 26
            new_char = chr(ord('a') + (ord(char) - ord('a') + shift) % 26)
            new_str += new_char
            total_shift -= shifts[i]
        return new_str

def findRightInterval(intervals):
    n = len(intervals)
    res = [-1] * n
    starts = {}
    for i in range(n):
        starts[intervals[i][0]] = i

    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    for i in range(n):
        target = intervals[i][1]
        left, right = 0, n-1
        while left <= right:
            mid = left + (right - left) // 2
            if sorted_intervals[mid][0] == target:
                res[i] = starts[sorted_intervals[mid][0]]
                break
            elif sorted_intervals[mid][0] < target:
                left = mid + 1
            else:
                if mid == 0 or sorted_intervals[mid-1][0] < target:
                    res[i] = starts[sorted_intervals[mid][0]]
                    break
                else:
                    right = mid - 1

    return res

