def combine_items(items1, items2):
    combined_items = items1 + items2
    combined_items = sorted(combined_items, key=lambda x:x[0])
    combined_items_dict = {}
    for i in combined_items:
        if i[0] not in combined_items_dict.keys():
            combined_items_dict[i[0]] = i[1]
        else:
            combined_items_dict[i[0]] += i[1]
    ret = [[k, v] for k,v in combined_items_dict.items()]
    ret = sorted(ret, key=lambda x:x[0])
    return ret

