class Solution:
    def getOrder(self, tasks: List[List[int]]) -> List[int]:
        n = len(tasks)
        queue = []
        for i in range(n):
            queue.append((tasks[i][0], tasks[i][1], i))
        queue.sort(key=lambda x: x[0])
        res = []
        time = 0
        i = 0
        while i < n or queue:
            if not queue:
                time = tasks[i][0]
                queue.append((tasks[i][0], tasks[i][1], i))
