            curr = None
            for j in range(len(queue)):
                if queue[j][0] <= time:
                    if curr is None or queue[j][1] < curr[1]:
                        curr = queue[j]
            if curr is not None:
                queue.remove(curr)
                time += curr[1]
                res.append(curr[2])
