def group_numbers(n):
    number_groups = {}
    for i in range(1, n+1):
        digit_sum = sum(int(digit) for digit in str(i))
        if digit_sum in number_groups:
            number_groups[digit_sum].append(i)
        else:
            number_groups[digit_sum] = [i]
    largest_size = 0
    largest_groups = []
    for group in number_groups.values():
        if len(group) > largest_size:
            largest_size = len(group)
            largest_groups = [group]
        elif len(group) == largest_size:
            largest_groups.append(group)
    return largest_groups[0] if len(largest_groups) == 1 else largest_groups

