class Solution:
    def minCameraCover(self, root: TreeNode) -> int:
        def dfs(node):
            if not node:
                return 0, 0, float('inf')
            
            l_val, l_mon, l_cam = dfs(node.left)
            r_val, r_mon, r_cam = dfs(node.right)
            
            val = l_mon + r_mon + 1
            if node.left:
                val += l_cam
            if node.right:
                val += r_cam
                
            mon = min(val, l_val + r_val)
            cam = min(val, l_val + r_mon, l_mon + r_val, l_cam + r_cam + 1)
            
            return val, mon, cam
        
        val, mon, cam = dfs(root)
        return min(val, cam)

