def addRow(root: TreeNode, val: int, depth: int) -> TreeNode:
    if depth == 1:
        new_root = TreeNode(val)
        new_root.left = root
        return new_root
    queue = [(root, 1)]
    while queue:
        node, node_depth = queue.pop(0)
        if node_depth == depth - 1:
            left = node.left
            right = node.right
            node.left = TreeNode(val)
            node.right = TreeNode(val)
            node.left.left = left
            node.right.right = right
        elif node_depth < depth - 1:
            if node.left:
                queue.append((node.left, node_depth + 1))
            if node.right:
                queue.append((node.right, node_depth + 1))
    return root

class Solution:
    def reformat(self, s: str) -> str:
        letters = []
        digits = []
        for char in s:
            if char.isdigit():
                digits.append(char)
            else:
                letters.append(char)
        if abs(len(letters)-len(digits)) > 1:
            return ''
        formatted_str = ''
        if len(digits) > len(letters):
            for i in range(len(digits)):
                formatted_str += digits[i]
                if i < len(letters):
                    formatted_str += letters[i]
        else:
            for i in range(len(letters)):
                formatted_str += letters[i]
                if i < len(digits):
                    formatted_str += digits[i]
        return formatted_str

def xorGame(nums):
