def is_reachable(source, target, blocked):
    q = [(source[0], source[1])]
    visited = set(q)
    while q:
        x, y = q.pop(0)
        if x == target[0] and y == target[1]:
            return True
        for dx, dy in ((1,0), (-1,0), (0,1), (0,-1)):
            nx, ny = x + dx, y + dy
            if (nx, ny) not in blocked and 1 <= nx <= 1000000 and 1 <= ny <= 1000000 and (nx, ny) not in visited:
                visited.add((nx, ny))
                q.append((nx, ny))
    return False

