class Solution:
    def alphabetBoardPath(self, target: str) -> str:
        board = ["abcde", "fghij", "klmno", "pqrst", "uvwxy", "z"]
        pos = {board[i][j]: (i, j) for i in range(6) for j in range(5)}
        curr_pos = (0, 0)
        moves = []
        for c in target:
            target_pos = pos[c]
            delta_r = target_pos[0] - curr_pos[0]
            delta_c = target_pos[1] - curr_pos[1]
            if c == "z" and curr_pos != (5, 0):
                moves.append("U" * (curr_pos[0] - 5))
                moves.append("L" * curr_pos[1])
                moves.append("D" * (5 - curr_pos[0]))
                moves.append("R" * (curr_pos[1] - 0))
            else:
                moves.append("U" * max(delta_r, 0))
                moves.append("L" * max(delta_c, 0))
                moves.append("D" * max(-delta_r, 0))
                moves.append("R" * max(-delta_c, 0))
            moves.append("!")
            curr_pos = target_pos
        return "".join(moves)

