def is_magic_square(matrix):
    """
    Returns True if the matrix is a magic square, False otherwise.
    """
    n = len(matrix)

    # calculate the magic sum
    magic_sum = n * (n**2 + 1) // 2

    # check rows and columns
    for i in range(n):
        if sum(matrix[i]) != magic_sum:
            return False
        if sum(matrix[j][i] for j in range(n)) != magic_sum:
            return False

    # check diagonals
    if sum(matrix[i][i] for i in range(n)) != magic_sum:
        return False
    if sum(matrix[i][n-i-1] for i in range(n)) != magic_sum:
        return False

    return True


def largest_magic_square(grid):
    """
    Returns the size of the largest magic square found in the grid.
    """
    n = len(grid)

    # iterate over all possible square sizes, starting from the largest
    for k in range(n, 0, -1):

        # iterate over all possible top-left corner positions
        for i in range(n-k+1):
            for j in range(n-k+1):

                # extract the k x k submatrix
                submatrix = [grid[i+r][j:j+k] for r in range(k)]

                # check if it is a magic square
                if is_magic_square(submatrix):
                    return k

    # if no magic square was found, return 1 (the trivial solution)
    return 1

