class Solution:
    def topKFrequent(self, words: List[str], k: int) -> List[str]:
        counts = collections.Counter(words)
        
        freq_arr = [[] for i in range(counts.most_common(1)[0][1] + 1)]
        
        for key in counts:
            freq_arr[counts[key]].append(key)

        res = []
        idx = len(freq_arr) - 1
        while k > 0:
            for s in sorted(freq_arr[idx]):
                res.append(s)
                k -= 1
                    
                if k == 0:
                    break
                        
            idx -= 1
        
        return res

class CompareWrapper:
    def __init__(self, word, freq):
        self.word = word
        self.freq = freq
        
    def __lt__(self, other):
        if self.freq == other.freq:
            return self.word > other.word
        return self.freq < other.freq

class Solution:
    def topKFrequent(self, words: List[str], k: int) -> List[str]:
        counts = collections.Counter(words)

        heap = []
        
        for key, val in counts.items():
            heapq.heappush(heap, CompareWrapper(key, val))
            if len(heap) > k:
                heapq.heappop(heap)
        
        res = [""] * k
        for i in range(k):
            res[k - i - 1] = heapq.heappop(heap).word
        return res

