    def maximalNetworkRank(self, n: int, roads: List[List[int]]) -> int:
        indegree=[0]*n
        for i,j in roads:
            indegree[i]+=1
            indegree[j]+=1
        fMax,sMax=0,0
        fCt,sCt=0,0
        for i in indegree:
            if i>fMax:
                sMax=fMax
                fMax=i
                sCt=fCt
                fCt=1
            elif i<fMax and i>sMax:
                sMax=i
                sCt=1
            else:
                if i==fMax:
                    fCt+=1
                elif i==sMax:
                    sCt+=1
        # print(fMax,fCt)
