def maxPizza(slices):
    def helper(slices):
        n = len(slices)
        dp = [[0 for i in range((n+1)//2+1)] for j in range(n+1)]
        for i in range(1, n+1):
            for j in range(1, (n+1)//2+1):
                if i == 1:
                    dp[i][j] = slices[i-1]
                elif j == 1:
                    dp[i][j] = max(dp[i-1][j], dp[i-2][j-1]+slices[i-1])
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i-2][j-1]+slices[i-1])
        return dp[n][(n+1)//2]
    
    return helper(slices[:-1]), helper(slices[1:])

class Solution:
    def maxPoints(self, points: List[List[int]]) -> int:
        if len(points) < 3:
            return len(points)
        
        max_points = 2
        
        for i in range(len(points)):
            slope_count = {'inf': 0}
            same_points = 1
            for j in range(i+1,len(points)):
                if points[i] == points[j]:
                    same_points += 1
                    continue
                    
                dx = points[j][0] - points[i][0]
                dy = points[j][1] - points[i][1]
                
                if dx == 0:
                    slope = 'inf'
                else:
                    slope = dy / dx
                    
                if slope not in slope_count:
                    slope_count[slope] = 1
                else:
                    slope_count[slope] += 1
            
            max_points = max(max_points, max(slope_count.values()) + same_points)
                    
        return max_points

