class Solution:
    def possibleBipartition(self, n: int, dislikes: List[List[int]]) -> bool:
        def constructGraph(n: int, pairs: List[List[int]]):
            graph = []
            for i in range(n):
                graph.append([])
            for pair in pairs:
                personA = pair[0] - 1
                personB = pair[1] - 1
                graph[personA].append(personB)
                graph[personB].append(personA)
            return graph
        
        graph = constructGraph(n, dislikes)
        
        visited = [False] * n
        marked = [False] * n
        
        def traverse(cur):
            visited[cur] = True
            for neighbor in graph[cur]:
                if visited[neighbor]:
                    if marked[neighbor] == marked[cur]:
                        return False
                else:
                    marked[neighbor] = not marked[cur]
                    traverse(neighbor)
        
        for i in range(n):
            if not visited[i]:
                if False == traverse(i):
                    return False
        
        return True

