class Solution:
    def possible_bipartition(self, n: int, dislikes: List[List[int]]) -> bool:
        graph = [[] for _ in range(n+1)]
        for a, b in dislikes:
            graph[a].append(b)
            graph[b].append(a)
            
        colors = [0]*(n+1)
        def dfs(i, color):
            colors[i] = color
            for nei in graph[i]:
                if colors[nei] == color:
                    return False
                if colors[nei] == 0 and not dfs(nei, -color):
                    return False
            return True
        
        for i in range(1, n+1):
            if colors[i] == 0 and not dfs(i, 1):
                return False
        return True

