def minimumMonths(n, relations, time):
    graph = [[] for _ in range(n+1)]
    in_degree = [0 for _ in range(n+1)]
    for x, y in relations:
        graph[x].append(y)
        in_degree[y] += 1
    queue = collections.deque()
    for i in range(1, n+1):
        if in_degree[i] == 0:
            queue.append(i)
    ans = [0] * (n + 1)
    while queue:
        cur = queue.popleft()
        ans[cur] = ans[cur - 1] + time[cur - 1]
        for nxt in graph[cur]:
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                queue.append(nxt)
    return max(ans)

