        for j in range(len(points)):
            if i != j:
                dx = points[i][0]-points[j][0]
                dy = points[i][1]-points[j][1]
                d = dx*dx + dy*dy
                if d in distance:
                    distance[d] += 1
                else:
                    distance[d] = 1
        for d in distance.values():
            if d > 1:
                count += d*(d-1)
    return count

