        n = len(nums[0])
        result = []

        for i in range(m + n - 1):
            temp = []
            for j in range(max(0, i - n + 1), min(i + 1, m)):
                temp.append(nums[j][i - j])
            if i % 2 == 0:
                result += temp[::-1]
            else:
                result += temp

