class Solution:
    def validMountainArray(self, arr: List[int]) -> bool:
        
        # using two elements to keep a memory of past ascent or descent
        up = [None, None]
        down = [None, None]
        
        for idx in range(len(arr) - 1):
            
            # return False if the adjacent elements are of same value
            if arr[idx] == arr[idx+1]:
                return False
            
            # change the values when the ascent of the mountain begins
            elif arr[idx] < arr[idx+1] and not up[0]:
                up[0] = 1
                down[0] = 0
            
            # return False if the descent has begun and we encounter an ascent
            elif arr[idx] < arr[idx+1] and down[1]:
                return False
            
            # change the values when the descent begins
            elif arr[idx] > arr[idx+1] and up[0]:
                down[1] = 1
                up[1] = 0
                # up[0], down[0] = 1, 0
            
            # return False if we get a descent before an ascent
            elif arr[idx] > arr[idx+1] and not down[1]:
                return False
        
        # first condition is when there is only increasing elements
        # second condition is when there is only decreasing elements
        if (up[0] == 1 and up[1] == None) or (up[0] == None and up[1] == None):
            return False
        else:
            return True

