class Solution:
    def findRedundantConnection(self, edges: List[List[int]]) -> List[int]:
        p = [i for i in range(len(edges)+1)]
        for e in edges:
            p1,p2 = self.find(p, e[0]),self.find(p, e[1])
            if p1 != p2:
                p[p1] = p2
            else:
                return e

    def find(self, p, x):
        if p[x] != x:
            p[x] = self.find(p, p[x])
        return p[x]

def closest_cost(baseCosts, toppingCosts, target):
    result = float('inf')
    for b in baseCosts:
        for i in range(3):
            dfs(toppingCosts, 0, i, b, target, result)
    return result

def dfs(toppingCosts, idx, count, total, target, result):
    if count == 0:
        result[0] = min(result[0], total, key=lambda x: (abs(x - target), x))
        return
    if idx == len(toppingCosts): return
    dfs(toppingCosts, idx + 1, count, total, target, result)
    dfs(toppingCosts, idx + 1, count - 1, total + toppingCosts[idx], target, result)

