class Solution:
    def sumFloorDiv(self, nums: List[int]) -> int:
        mod = 10**9 + 7
        freq = collections.Counter(nums)
        nums.sort()
        res = 0
        n = len(nums)
        for i in range(n):
            for j in range(i+1, n):
                res += nums[i] // nums[j] * freq[nums[i]]
                res += nums[j] // nums[i] * freq[nums[j]]
        return res % mod

