def asteroid_collision(mass, asteroids):
    i = 0
    while i < len(asteroids):
        if asteroids[i] < 0 and (i == 0 or asteroids[i - 1] <= 0):
            i += 1
        elif asteroids[i] > mass:
            return False
        elif asteroids[i] == mass or (i < len(asteroids) - 1 and asteroids[i+1] <= 0) or i == len(asteroids) - 1:
            mass += asteroids[i]
            i += 1
        else:
            if asteroids[i] < asteroids[i+1]:
                del asteroids[i]
            elif asteroids[i] > asteroids[i+1]:
                del asteroids[i+1]
            else:
                del asteroids[i:i+2]
    return True

