def invalidTransactions(transactions):
    invalid = set()
    trans = []
    for i in range(len(transactions)):
        name, time, amount, city = transactions[i].split(",")
        if int(amount) > 1000:
            invalid.add(i)
        trans.append((name, int(time), int(amount), city, i))
        
    trans.sort(key=lambda x: x[1])
    for i in range(len(trans)):
        for j in range(i+1, len(trans)):
            if trans[j][1] - trans[i][1] > 60:
                break
            if trans[j][0] != trans[i][0] and trans[j][3] != trans[i][3]:
                invalid.add(trans[j][4])
                invalid.add(trans[i][4])
    
    return [transactions[i] for i in invalid]

def score_of_parentheses(s):
    stack = [0]
    for c in s:
        if c == '(':
            stack.append(0)
        else:
            last = stack.pop()
            stack[-1] += max(2 * last, 1)
    return stack.pop()

