class Solution:
    def findMinHeightTrees(self, n: int, edges: List[List[int]]) -> List[int]:
        if n == 1:
            return [0]
        
        adj_list = defaultdict(list)
        
        for u, v in edges:
            adj_list[u].append(v)
            adj_list[v].append(u)
        
        leaves = [i for i in range(n) if len(adj_list[i]) == 1]
        
        while n > 2:
            n -= len(leaves)
            new_leaves = []
            for leaf in leaves:
                parent_node = adj_list[leaf][0]
                adj_list[parent_node].remove(leaf)
                if len(adj_list[parent_node]) == 1:
                    new_leaves.append(parent_node)
            leaves = new_leaves
        
        return leaves

