def reverse_string(s):
    chars = []
    letters = []
    for char in s:
        if char.isalpha():
            letters.append(char)
        else:
            chars.append(char)
    letters = list(reversed(letters))
    result = ''
    for char in s:
        if char.isalpha():
            result += letters.pop(0)
        else:
            result += chars.pop(0)
    return result

