def lastStoneWeight(stones: List[int]) -> int:
    while len(stones)>1:
        stones.sort(reverse=True)
        y = stones.pop(0)
        x = stones.pop(0)
        if x!=y:
            stones.append(y-x)
    if len(stones)==0:
        return 0
    else:
        return stones[0]

