class Solution:
    def minFlips(self, target: str) -> int:
        s = '0'*len(target)
        i = 0
        count = 0
        while s != target and i < len(s):
            if s[i] != target[i] and s[i] == '0':
                s = s[:i] + '1' * (len(s)-i)
                count += 1
            if s[i] != target[i] and s[i] == '1':
                s = s[:i] + '0' * (len(s)-i)
                count += 1
            i += 1
        return count

