def dieSimulator(n: int, rollMax: List[int]) -> int:
    dp = [[0] * (max(rollMax) + 1) for _ in range(n)]
    for j in range(max(rollMax) + 1):
        if j <= rollMax[0]:
            dp[0][j] = 1
    for i in range(1, n):
        prefix_sum = sum(dp[i-1])
        for j in range(max(rollMax) + 1):
            dp[i][j] = prefix_sum
            if j == 0:
                dp[i][j] -= dp[i - 1][rollMax[i - 1]]
            elif j <= rollMax[i]:
                dp[i][j] -= dp[i - 1][rollMax[i - 1]] - dp[i - j][j - 1]
                if i < j:
                    dp[i][j] += 1
            dp[i][j] %= 1000000007
            prefix_sum = (prefix_sum + dp[i][j] - dp[i-1][j]) % 1000000007
    return sum(dp[-1]) % 1000000007

