class Solution:
    def longestStrChain(self, words: List[str]) -> int:
        memo = {}
        words.sort(key=len)
        for word in words:
            memo[word] = 1
            for i in range(len(word)):
                predecessor = word[:i] + word[i+1:]
                if predecessor in memo:
                    memo[word] = max(memo[word], memo[predecessor] + 1)
        return max(memo.values())

