def find_different_string(words):
    n = len(words[0])
    for i in range(n-1):
        diff_set = set()
        for j in range(len(words)):
            diff = ord(words[j][i+1]) - ord(words[j][i])
            diff_set.add(diff)
        if len(diff_set) > 1:
            for j in range(len(words)):
                diff = ord(words[j][i+1]) - ord(words[j][i])
                if diff != min(diff_set):
                    return words[j]

