def longest_path(root):
    if not root:
        return 0, []
    left_length, left_path = longest_path(root.left)
    right_length, right_path = longest_path(root.right)
    if left_length + right_length + 2 > len(left_path) + len(right_path):
        return left_length + right_length + 2, [root.value] + left_path + right_path
    else:
        return len(left_path) + len(right_path), left_path + right_path

