class Solution:
    def minSwapsCouples(self, row: List[int]) -> int:
        n = len(row) // 2
        pos = [0] * (n * 2)
        for i in range(n * 2):
            pos[row[i]] = i
        
        ans = 0
        for i in range(0, n * 2, 2):
            couple = row[i] // 2
            if row[i + 1] != row[i] ^ 1:
                pos[row[i] ^ 1], pos[row[couple * 2 + 1]] = pos[row[couple * 2 + 1]], pos[row[i] ^ 1]
                row[i + 1], row[couple * 2 + 1] = row[couple * 2 + 1], row[i + 1]
                ans += 1
        
        return ans

class Solution:
    def largestIsland(self, grid: List[List[int]]) -> int:
        
        # Define a recursive function to calculate island size
        def dfs(i, j, index):
            if i < 0 or j < 0 or i >= n or j >= n or grid[i][j] != 1:
                return 0
            grid[i][j] = index  # mark island as visited
            return 1 + dfs(i-1, j, index) + dfs(i+1, j, index) + dfs(i, j-1, index) + dfs(i, j+1, index)
        
        # Store size of each island in a dictionary
        island_sizes = {}
        n = len(grid)
        index = 2  # index 1 is used for marked water cells
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    island_sizes[index] = dfs(i, j, index)
                    index += 1
        
        # Check if there are no islands or only one island
        if len(island_sizes) == 0:
            return 1
        if len(island_sizes) == 1:
            return island_sizes[2]
        
        # Try changing each water cell to 1, and calculate island size
        max_size = 0
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 0:
                    # Calculate island sizes of neighboring islands
                    neighbor_sizes = set(grid[i-1][j] for i,j in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)) if 0<=i<n and 0<=j<n and grid[i][j]>1)
                    size = 1 + sum(island_sizes[index] for index in neighbor_sizes)
                    max_size = max(max_size, size)
        
        # If all cells are land, return total area
        if max_size == 0:
            return n*n
        
        return max_size

