def compress(s):
    result = ""
    i = 0
    while i < len(s):
        count = 1
        while i < len(s)-1 and s[i] == s[i+1]:
            count += 1
            i += 1
        if count > 1:
            result += s[i] + str(count)
        else:
            result += s[i]
        i += 1
    return result

def min_compressed_length(s, k):
    compressed = compress(s)
    if k >= len(compressed):
        return 0
    counts = {}
    for char in compressed:
        if char in counts:
            counts[char] += 1
        else:
            counts[char] = 1
    for i in range(k):
        min_count = float('inf')
        min_char = None
        for char in counts:
            if counts[char] < min_count:
                min_count = counts[char]
                min_char = char
        counts[min_char] -= 1
        if counts[min_char] == 0:
            del counts[min_char]
    return sum(counts.values())

