def goodIndices(nums: List[int], k: int) -> List[int]:
    res = []
    for i in range(k, len(nums)-k):
        decreasing = all(nums[j] >= nums[j+1] for j in range(i-k, i))
        increasing = all(nums[j] <= nums[j+1] for j in range(i, i+k))
        if decreasing and increasing:
            res.append(i)
    return res

