MOD = 10 ** 9 + 7

def gen_powers(n, p):
    powers = [1]
    for i in range(n):
        powers.append((powers[-1] * p) % MOD)
    return powers

def count_good_strings(s1, s2, n, evil):
    powers = gen_powers(n + 1, 26)

    def good_string_helper(i, geq_s1, leq_s2, has_evil):
        if i == n:
            return has_evil

        if (i, geq_s1, leq_s2, has_evil) in mem:
            return mem[(i, geq_s1, leq_s2, has_evil)]

        res = 0
        lo = ord(s1[i]) - ord('a') if geq_s1 else 0
        hi = ord(s2[i]) - ord('a') if leq_s2 else 25

        for c in range(lo, hi + 1):
            geq_s1_next = geq_s1 or c > lo
            leq_s2_next = leq_s2 or c < hi
            has_evil_next = has_evil or (i >= len(evil) or evil[i] == chr(c + ord('a')))
            res += good_string_helper(i + 1, geq_s1_next, leq_s2_next, has_evil_next)

        mem[(i, geq_s1, leq_s2, has_evil)] = res % MOD
        return mem[(i, geq_s1, leq_s2, has_evil)]

    mem = {}
    return count_good_string_helper(0, False, False, False) % MOD

