def maxNumber(nums1, nums2, k):
    def getMax(nums, k):
        stack, popCount, numsLen = [], len(nums) - k, len(nums)
        for i in range(numsLen):
            while stack and popCount and nums[i] > stack[-1]:
                stack.pop()
                popCount -= 1
            stack.append(nums[i])
        return stack[:k]
    
    def merge(nums1, nums2, k):
        res = []
        while nums1 or nums2:
            if nums1 > nums2:
                res.append(nums1[0])
                nums1 = nums1[1:]
            else:
                res.append(nums2[0])
                nums2 = nums2[1:]
        return res[:k]
    
    res = []
    for i in range(k+1):
        if i <= len(nums1) and k-i <= len(nums2):
            temp = merge(getMax(nums1, i), getMax(nums2, k-i), k)
            res = max(res, temp)
    return res

