class Solution:
    def minSideJumps(self, obstacles: List[int]) -> int:
        n = len(obstacles) - 1
        dp = [0] * 3
        for i in range(1, n):
            if obstacles[i] != 0:
                dp[obstacles[i]-1] = float('inf')
            for j in range(3):
                if obstacles[i] != j+1:
                    dp[j] = min(dp[j], dp[(j+1)%3]+1, dp[(j+2)%3]+1)
        return min(dp)

