class Solution:
    def countArrangement(self, n: int) -> int:
        self.count = 0
        nums = set(range(1, n + 1))
        self.helper(nums, 1)
        return self.count
    
    def helper(self, nums, index):
        if index == len(nums) + 1:
            self.count += 1
            return
        for num in list(nums):
            if num % index == 0 or index % num == 0:
                nums.remove(num)
                self.helper(nums, index + 1)
                nums.add(num)

