import statistics

def medianSlidingWindow(nums, k):
    medians = []
    for i in range(len(nums) - k + 1):
        window = nums[i:i+k]
        middle = len(window) // 2
        if len(window) % 2 == 0:
            median = (window[middle-1] + window[middle]) / 2
        else:
            median = window[middle]
        medians.append(median)
    return medians

from collections import Counter

def check_inclusion(s1, s2):
    count = Counter(s1)
    left, right = 0, 0
    freq = len(s1)
    while right < len(s2):
        if s2[right] in count and count[s2[right]] > 0:
            count[s2[right]] -= 1
            freq -= 1
            right += 1
        elif left == right:
            left += 1
            right += 1
        else:
            count[s2[left]] += 1
            freq += 1
            left += 1
        if freq == 0:
            return True
    return False

def search_matrix(matrix, target):
    if not matrix:
        return False
    row, col = 0, len(matrix[0]) - 1
    while row < len(matrix) and col >= 0:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] > target:
            col -= 1
        else:
            row += 1
    return False

