def mix_colors(colors):
    mixed = set()
    for color in colors:
        mixed |= {color}
    return mixed

def merge_segments(segments):
    if not segments:
        return []
    segments.sort(key=lambda x: x[0])
    merged = [segments[0]]
    for segment in segments[1:]:
        if segment[0] <= merged[-1][1]:
            merged[-1][2] |= segment[2]
            merged[-1][1] = max(merged[-1][1], segment[1])
        else:
            merged.append(segment)
    return merged

def paint_number_line(segments):
    painted = []
    for segment in segments:
        painted.append([segment[0], segment[1], mix_colors(segment[2])])
    return merge_segments(painted)

