    @staticmethod
    def substract(c1, c2):
	    # remove intersection of c1 and c2 from c2 and encode the c1 to string
        remove_keys = []
        result = ""
        for k in c1.keys():
            if k in c2:
                c1[k] -= c2[k]
                if c1[k] <= 0:
                    remove_keys.append(k)
            if c1[k] > 0:
                result += k + str(c1[k])
        
