def findInMountainArray(target: int, mountainArr: 'MountainArray') -> int:
    def binary_search(l, r, key, check):
        while l <= r:
            mid = (l + r) // 2
            if check(mountainArr.get(mid), key):
                r = mid - 1
            else:
                l = mid + 1
        return l if check(mountainArr.get(l), key) else -1
    
    n = mountainArr.length()
    peak = binary_search(0, n-1, None, lambda x, y: x > y)
    
    left = binary_search(0, peak, target, lambda x, y: x >= y)
    if left != -1:
        return left
    
    right = binary_search(peak, n-1, target, lambda x, y: x >= y)
    return right

