class Solution:
    def nextGreaterElement(self, nums1: List[int], nums2: List[int]) -> List[int]:
        # Method 1: Brute Force T.C: O(nÃÂÃÂ3) S.C: O(1)
        
        ans = [-1] * len(nums1) 
        for i in range(len(nums1)):
            for j in range(len(nums2)):
                if nums1[i] == nums2[j]:
                    for k in range(j+1,len(nums2)):
                        if nums2[k] > nums2[j]:
                            ans[i] = nums2[k]
                            break
        return ans
    
        # Method 2: Improved Brute Force        
        
        d = {}
        ans = [-1] * len(nums1)
        for i in range(len(nums1)):
            d[nums1[i]] = i
        
        for i in range(len(nums2)):
            if nums2[i] in d:
                for j in range(i+1,len(nums2)):
                    if nums2[j] > nums2[i]:
                        ans[d[nums2[i]]] = nums2[j]
                        break
        return ans
        
        # Method 3: Optimal Solution T.C: O(m+n) S.C: O(m)
    
        stack = []
        d = {}
        ans = [-1] * len(nums1)
        
        for i in range(len(nums1)):
            d[nums1[i]] = i
        
        for i in range(len(nums2)):
            while stack and stack[-1] < nums2[i]:
                ans[d[stack[-1]]] = nums2[i]
                stack.pop()
            
            if nums2[i] in d:
                stack.append(nums2[i])
        
        return ans
		
