def kthGrammar(n: int, k: int) -> int:
    if n == 1:
        return 0
    else:
        parent = kthGrammar(n-1, (k+1)//2)
        if parent == 0:
            return 1 if k%2 == 0 else 0
        else:
            return 0 if k%2 == 0 else 1

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
        
class Solution:
    def isCousins(self, root: TreeNode, x: int, y: int) -> bool:
        if not root:
            return False
        queue = [(root, None)]
        found_x = found_y = False
        while queue:
            size = len(queue)
            parents = {}
            for i in range(size):
                node, parent = queue.pop(0)
                parents[node.val] = parent
                if node.val == x:
                    found_x = True
                if node.val == y:
                    found_y = True
                if node.left:
                    queue.append((node.left, node))
                if node.right:
                    queue.append((node.right, node))
            if found_x and found_y:
                return parents[x] != parents[y]
            elif found_x or found_y:
                return False
        return False

