class Solution:
    def printVertically(self, s: str) -> List[str]:
        words = s.split()
        max_len = max(len(word) for word in words)
        res = [' ' * len(words) for _ in range(max_len)]
        for i, word in enumerate(words):
            for j, c in enumerate(word):
                res[j] = res[j][:i] + c + res[j][i + 1:]
        return res

def construct_max_tree(a):
    if not a:
        return None
    max_val = max(a)
    max_idx = a.index(max_val)
    root = TreeNode(max_val)
    root.left = construct_max_tree(a[:max_idx])
    root.right = construct_max_tree(a[max_idx+1:])
    return root

def insert_into_max_tree(root, val):
    if not root:
        return TreeNode(val)
    if val > root.val:
        new_root = TreeNode(val)
        new_root.left = root
        return new_root
    root.right = insert_into_max_tree(root.right, val)
    return root

def max_tree_from_list(a, val):
    a.append(val)
    root = construct_max_tree(a)
    return root

