def find_peak_element(mat):
    m = len(mat)
    n = len(mat[0])
    
    # binary search
    def bs(left, right, vertical):
        while left <= right:
            mid = (left + right) // 2
            max_i = vertical.index(max(vertical))
            if mat[max_i][mid] < max(vertical):
                if max_i > 0:
                    return bs(left, mid-1, vertical[:max_i])
                else:
                    return bs(left, mid-1, vertical[max_i+1:])
            elif mat[max_i][mid] < max(vertical[:max_i]+vertical[max_i+1:]):
                return bs(left, mid-1, vertical[:max_i]+vertical[max_i+1:])
            elif mat[max_i][mid] < mat[max_i][mid+1]:
                return bs(mid+1, right, [mat[i][mid+1] for i in range(m)])
            elif mat[max_i][mid] < mat[max_i][mid-1]:
                return bs(left, mid-1, [mat[i][mid-1] for i in range(m)])
            else:
                return [max_i, mid]
                
    return bs(0, n-1, [mat[i][n//2] for i in range(m)])

