def threeSumMulti(self, arr: List[int], target: int) -> int:
    count = [0] * 101
    for a in arr:
        count[a] += 1

    ans = 0
    # All different
    for x in range(101):
        for y in range(x+1, 101):
            z = target - x - y
            if y < z <= 100:
                ans += count[x] * count[y] * count[z]

    # x == y != z
    for x in range(101):
        z = target - 2*x
        if x < z <= 100:
            ans += count[x] * (count[x]-1) // 2 * count[z]

    # x != y == z
    for x in range(101):
        if (target-x) % 2 == 1:
            continue
        y = (target - x) // 2
        if x < y <= 100:
            ans += count[x] * count[y] * (count[y]-1) // 2

    # x == y == z
    if target % 3 == 0:
        x = target // 3
        if 0 <= x <= 100:
            ans += count[x] * (count[x]-1) * (count[x]-2) // 6

    return ans % MOD

