def max_profit(n: int, prices: List[List[int]]) -> int:
    dp = [0] * (n+1)
    for i in range(1,n+1):
        max_profit = 0
        for j in range(len(prices)):
            if prices[j][0] <= i:
                max_profit = max(max_profit, prices[j][2] + dp[i-prices[j][0]])
            if prices[j][1] <= i:
                max_profit = max(max_profit, prices[j][2] + dp[i-prices[j][1]])
        dp[i] = max(dp[i-1], max_profit)
    return dp[n]

