class Solution:
    def findMinMoves(self, machines: List[int]) -> int:
        total = sum(machines)
        n = len(machines)
        if total % n != 0:
            return -1
        avg = total // n
        moves = 0
        left_sum = 0
        for i in range(n):
            left_sum += machines[i]
            left_expected = i * avg
            right_expected = (n - i - 1) * avg
            if left_sum < left_expected and machines[i] < avg:
                moves += left_expected - left_sum
            elif left_sum > left_expected + machines[i] and machines[i] < avg:
                moves += left_sum - left_expected - machines[i]
            else:
                continue
        return moves

def plates_candles(s: str, queries: List[List[int]]) -> List[int]:
    n = len(s)
    prefix_candles = [0] * n
    suffix_candles = [0] * n
    plates_candles = [0] * n
    
    for i in range(n):
        if s[i] == '|':
            prefix_candles[i] = 1
        if i > 0:
            prefix_candles[i] += prefix_candles[i-1]
    
    for i in range(n-1, -1, -1):
        if s[i] == '|':
            suffix_candles[i] = 1
        if i < n-1:
            suffix_candles[i] += suffix_candles[i+1]
    
    for i in range(n):
        if s[i] == '*':
            plates_candles[i] = min(prefix_candles[i], suffix_candles[i])
    
    result = []
    for query in queries:
        left, right = query
        result.append(sum(plates_candles[left:right+1]))
    
    return result

