class Solution:
    def containsNearbyAlmostDuplicate(self, nums: List[int], indexDiff: int, valueDiff: int) -> bool:
        """Sliding window + BST: O(N*log(indexDiff))"""

        bst = BinarySearchTree()

        for i in range(len(nums)):

            if i > 0:
                closest = bst.search_closest(nums[i])
                if abs(nums[i] - closest) <= valueDiff:
                    return True

            if i >= indexDiff:
                bst.delete(nums[i - indexDiff])

            bst.insert(nums[i])

        return False
        

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class BinarySearchTree:

    def __init__(self):
        self.root = None

    def search_closest(self, val: int) -> int:

        if not self.root:
            return None

        closest = self.root.val
        node = self.root

        while node:

            if abs(node.val - val) < abs(closest - val):
                closest = node.val

            if node.val == val:
                break
            elif val < node.val:
                node = node.left
            else:
                node = node.right

        return closest

    def insert(self, val: int):
        
        if not self.root:
            self.root = TreeNode(val)
            return 
        
        node = self.root
        while node:
            if val < node.val:
                if not node.left:
                    node.left = TreeNode(val)
                    break
                else:
                    node = node.left
            else:
                if not node.right:
                    node.right = TreeNode(val)
                    break
                else:
                    node = node.right

    def delete(self, key: int):
        
        def __deleteNode(root, key):

            if not root: 
                return None

            if root.val == key:
                if not root.right: 
                    return root.left

                if not root.left:
                    return root.right

                temp = root.right
                while temp.left: 
                    temp = temp.left
                root.val = temp.val
                root.right = __deleteNode(root.right, root.val)

            elif key < root.val:
                root.left = __deleteNode(root.left, key)

            else:
                root.right = __deleteNode(root.right, key)

            return root
        
        self.root = __deleteNode(self.root, key)

