class Solution:
    def mergeTrees(self, root1: TreeNode, root2: TreeNode) -> TreeNode:
        
        if not root1:
            return root2
        
        if not root2:
            return root1
        
        root1.val += root2.val
        root1.left = self.mergeTrees(root1.left, root2.left)
        root1.right = self.mergeTrees(root1.right, root2.right)
        
        return root1

def get_max_gold(grid):
    def backtrack(i, j, visited):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == 0 or (i, j) in visited:
            return 0
        visited.add((i, j))
        gold = grid[i][j]
        max_gold = max(backtrack(i+1, j, visited), backtrack(i-1, j, visited), 
                       backtrack(i, j+1, visited), backtrack(i, j-1, visited))
        visited.remove((i, j))
        return gold + max_gold
    
    max_gold = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != 0:
                max_gold = max(max_gold, backtrack(i, j, set()))
    return max_gold

def maxSlidingWindow(nums, k):
    if not nums:
        return []
    if k == 1:
        return nums
    dq = collections.deque()
    res = []
    for i in range(k):
        while dq and nums[i] >= nums[dq[-1]]:
            dq.pop()
        dq.append(i)
    for i in range(k, len(nums)):
        res.append(nums[dq[0]])
        while dq and nums[i] >= nums[dq[-1]]:
            dq.pop()
        if dq and dq[0] <= i - k:
            dq.popleft()
        dq.append(i)
    res.append(nums[dq[0]])
    return res

