import heapq

def trapRainWater(heightMap):
    n, m = len(heightMap), len(heightMap[0])
    pq = []
    visited = [[False for _ in range(m)] for _ in range(n)]
    water = 0
    
    # Add boundary cells to the priority queue
    for i in range(n):
        for j in range(m):
            if i == 0 or j == 0 or i == n-1 or j == m-1:
                heapq.heappush(pq, (heightMap[i][j], i, j))
                visited[i][j] = True
    
    # Process cells in order of increasing height
    while pq:
        h, i, j = heapq.heappop(pq)
        for ni, nj in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)):
            if ni >= 0 and ni < n and nj >= 0 and nj < m and not visited[ni][nj]:
                visited[ni][nj] = True
                if heightMap[ni][nj] < h:
                    heapq.heappush(pq, (heightMap[ni][nj], ni, nj))
                else:
                    water += heightMap[ni][nj] - h
                    heightMap[ni][nj] = h
                    
    return water

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def isPalindrome(head: ListNode) -> bool:
    if not head or not head.next:
        return True
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    prev, curr = None, slow
    while curr:
        nxt = curr.next
        curr.next = prev
        prev = curr
        curr = nxt
    while prev:
        if head.val != prev.val:
            return False
        head, prev = head.next, prev.next
    return True

