class Solution:
    def countSubstrings(self, s: str) -> int:
        # /////////// Solution 1 iterative /////////////
        '''
		   The first approach is very easy to understand and even efficient then DP.
           Idea is very simple we will expand from middle of any ith element and will keep checking 
           boundary and palindromic condition.
           Let say,   a b a
                     <- ^ -> expanding in this way  from the ith element of the string.
           Hope got the idea else go through code it will be easy to understand.
        '''
        
        def countPalindrome(s,l,r):
            res = 0
            while l >= 0 and r <= len(s)-1 and s[l] == s[r]:
                res += 1
                l -= 1
                r += 1
            return res
        
        res = 0
        # //////// for odd length string ////////
        for i in range(len(s)):
            l = r = i
            res += countPalindrome(s,l,r)
        # ////// for even length string ///////////
        for i in range(len(s)):
            l = i
            r = i + 1
            res += countPalindrome(s,l,r)
        return res
    
    # ///////////  Solution 2 Using DP ////////////
    
        res = 0
        slen = len(s)
        dp = [[False for _ in range(slen)] for _ in range(slen)]
        
        for i in range(slen-1,-1,-1):
            dp[i][i] = True
            res = res + 1
            for j in range(i+1,slen):
                if j - i == 1 :
                    if s[i] == s[j]:
                        dp[i][j] = True
                    else:
                        dp[i][j] = False
                else:
                    if s[i] == s[j] and dp[i+1][j-1] == True:
                        dp[i][j] = True
                    else:
                        dp[i][j] = False

                if dp[i][j] == True:
                    res = res + 1
        return res

