def possible_reorder(arr):
    n = len(arr)
    freq = {}
    for i in arr:
        freq[i] = freq.get(i, 0) + 1
    for i in range(n//2):
        if freq.get(arr[2*i]*2, 0) < freq.get(arr[2*i+1], 0):
            return False
        freq[arr[2*i]*2] -= freq[arr[2*i+1]]
    return True

