def sumSubarrayMins(nums):
    stack = []
    nums = [0] + nums + [0]
    res = 0
    for i in range(len(nums)):
        while stack and nums[stack[-1]] > nums[i]:
            cur = stack.pop()
            res += nums[cur] * (i - cur) * (cur - stack[-1])
        stack.append(i)
    return res % (10**9 + 7)

