def is_valid_rational(t):
    integer_part = ""
    non_repeating_part = ""
    repeating_part = ""
    repeating = False
    
    for c in t:
        if not repeating and c.isdigit():
            integer_part += c
        elif not repeating and c == ".":
            non_repeating_part += c
        elif not repeating and c == "(":
            repeating = True
        elif repeating and c == ")":
            break
        elif repeating and c.isdigit():
            repeating_part += c
        else:
            return False
        
    if integer_part == "":
        integer_part = "0"
        
    if not non_repeating_part.startswith("."):
        non_repeating_part = ""
        
    if len(repeating_part) == 0:
        repeating_part = "0"
        
    return True

