class Solution:
    def getConcatenation(self, nums: List[int]) -> List[int]:
        
        ans = []
        length = (len(nums))*2     #double actual of length
        n = len(nums)            
        for i in range(length):
            if i < n:
                ans.append(nums[i])
            else:
                mod = i % n         # because modulus would be always less than "n"
                ans.append(nums[mod])
        return ans

