def max_building_height(n, restrictions):
    heights = [0] * n
    
    for i in range(1, n):
        max_height = heights[i-1] + 1
        for r in restrictions:
            if r[0] == i+1:
                max_height = min(max_height, r[1])
        
        heights[i] = max_height
    
    return max(heights)

def consecutive_numbers(n):
    count = 0
    for i in range(1, n+1):
        j = i
        total = 0
        while total < n:
            total += j
            j += 1
        if total == n:
            count += 1
    return count

