class Solution:
    def findDuplicateSubtrees(self, root: Optional[TreeNode]) -> List[Optional[TreeNode]]:
        mapped = {}
        ans = set()
        def duplicated(node):
            if not node:
                return '#'
            s = ''
            if not node.left and not node.right:
                s += str(node.val)
                mapped[s] = mapped.get(s,0)+1
                if mapped[s]==2:
                    ans.add(node)
                return s
            s  = s + str(node.val)
            s = s + "," + duplicated(node.left)
            s = s+ "," + duplicated(node.right)
            mapped[s]  = mapped.get(s,0)+1
            if mapped[s]==2:
                ans.add(node)
            return s
        
        duplicated(root)
        return ans

class Solution:
    def isSubtree(self, root: Optional[TreeNode], subRoot: Optional[TreeNode]) -> bool:  # Time: O(root * subRoot) and Space: O(1)
        
		if not subRoot:  # when subRoot is Null, root will always have Null values   
            return True
        if not root:     # when root is Null, subRoot might not only have Null values but if it does then previous command will get executed
            return False

        if self.sameTree(root, subRoot):  # when r and s have some values we need to check is that the same or not, and their children's will be checked too
            return True

        # when root doesn't match we will ignore it and take its children's as root and compare them with subRoot,
        # and if any one of the children matches with the subRoot we will return True
        return self.isSubtree(root.left, subRoot) or self.isSubtree(root.right, subRoot)

    def sameTree(self, root, subRoot):
	
        if not root and not subRoot:  # when both of them are Null return True, as Null is a subset of Null
            return True
			
        if root and subRoot and root.val == subRoot.val:
            # when the node values matches then we will compare their left and right children's to check that the subTree matches or not
            return self.sameTree(root.left, subRoot.left) and self.sameTree(root.right, subRoot.right)
			
        return False  # when both the previous if conditions fails means the nodes does not match

