class Solution:
    def sumBase(self, num: int, base: int) -> int:
            tot = 0
            base_num = ""
            while num>0:
                dig = int(num%base)
                if dig<10:
                    base_num += str(dig)
                else:
                    base_num += chr(ord('A')+dig-10)  
                num //= base

            base_num = base_num[::-1]  
            tot = 0
            for i in base_num:
                tot += int(i)
            return tot

