class Solution:
    def countBinarySubstrings(self, s: str) -> int:
		# Find the index where each change occurs, pick this apart by trying out `list(zip(s, s[1:]))` and then the enumeration
		# Note we need to add index 0 and index len(s) for this to calculate correctly
        indexes = [0] + [i for i, (l, r) in enumerate(zip(s, s[1:]), start=1) if l != r] + [len(s)]
		
		# Find the length of the group by grouping the above indexes and finding the difference
        groups = [b - a for a, b in zip(indexes, indexes[1:])]
		
		# Get the grouping (again in pairs) of the above group lengths, find the min, and then take the sum of all the mins
        return sum(min(x, y) for x, y in zip(groups, groups[1:]))

