def find_closest_elements(arr, k, x):
    left, right = 0, len(arr) - 1
    while right - left >= k:
        if abs(arr[left] - x) > abs(arr[right] - x):
            left += 1
        else:
            right -= 1
    return sorted(arr[left:left+k])

