class Solution:
    def diameterOfBinaryTree(self, root: TreeNode) -> int:
        self.res = 0
        
        def dfs(node):
            if not node:
                return 0
            left_height = dfs(node.left)
            right_height = dfs(node.right)
            self.res = max(self.res, left_height + right_height)
            return max(left_height, right_height) + 1
            
        dfs(root)
        return self.res

