class Solution:
    def validTicTacToe(self, board: List[str]) -> bool:
        # create function to determine number of wins for a player
        # keep track of number of tiles for each player
        # validate different edge cases for how players are allowed to win
        # time O(m * n) space O(1)

        def find_win(player):
            total = 0
            return diagonal(player) + horizontal(player) + vertical(player)

        def diagonal(player):
            total = 0
            flat = ""
            # tl diagnal
            for i, j in zip(range(3), range(3)):
                flat += board[i][j]
            if flat == player * 3:
                total += 1
            flat = ""
            # bl diagonal
            for i, j in zip(reversed(range(3)), range(3)):
                flat += board[i][j]
            if flat == player * 3:
                total += 1

            return total
            
        def horizontal(player):
            total = 0
            for i in range(3):
                if board[i] == player * 3:
                    total += 1
            return total

        def vertical(player):
            total = 0
            flat = ""
            for j in range(3):
                for i in range(3):
                    flat += board[i][j]
                if flat == player * 3:
                    total += 1
                flat = ""
            return total

        x_win, o_win = find_win("X"), find_win("O")
        x = o = 0
        for row in board:
            for space in row:
                if space == "X":
                    x += 1
                elif space == "O":
                    o += 1

        if x_win > 2:
            return False
        if o_win > 2:
            return False
        if x_win > 0 and o_win > 0:
            return False
        if x_win and x == o or o_win and x > o:
            return False
        if x < o or abs(x - o) > 1:
            return False

        return True

