class Solution:
    def compareVersion(self, version1: str, version2: str) -> int:
        v1 = version1.split('.')
        v2 = version2.split('.')
        n1, n2 = len(v1), len(v2)
        i, j = 0, 0
        while i < n1 or j < n2:
            a = int(v1[i]) if i < n1 else 0
            b = int(v2[j]) if j < n2 else 0
            if a < b:
                return -1
            elif a > b:
                return 1
            i, j = i + 1, j + 1
        return 0

def min_abs_difference(nums, goal):
    n = len(nums)
    best = abs(sum(nums) - goal)
    for i in range(1, 2**n):
        sub = [nums[j] for j in range(n) if (i & (1<<j))]
        diff = abs(sum(sub) - goal)
        if diff < best:
            best = diff
    return best

