import random

class Solution:
    def __init__(self, w: List[int]):
        self.prefixSum = []
        prefixSum = 0
        for weight in w:
            prefixSum += weight
            self.prefixSum.append(prefixSum)
        self.totalSum = prefixSum
    
    def pickIndex(self) -> int:
        target = self.totalSum * random.random()
        left, right = 0, len(self.prefixSum) - 1
        while left < right:
            mid = (left + right) // 2
            if target > self.prefixSum[mid]:
                left = mid + 1
            else:
                right = mid
        return left

