class Solution:
    def sortArrayByParityII(self, nums: List[int]) -> List[int]:
        odd = 1
        even = 0
        while max(odd, even) < len(nums):
			# for the termination contition, if all odd numbers are in correct places, the even numbers must also have been correctly placed. 
			# thus, when one of them are done, we can say with confidence that the other one is also done
            if nums[odd] % 2:
                odd += 2
            else:
				# nums[odd] is even. needs to be swapped with an odd number.
                for i in range(odd + 1, len(nums), 2):
					# the step is 2 because we're swapping odd numbers with even index to this place.
					# this means we're correcting a misplaced odd number and a misplaced even number at the same time
					# if the step is 1, it is possible that we put the even number (nums[odd]) into an odd index, which would require at least one extra swap to fix.
					# The same principle applies to below.
                    if nums[i] % 2:
                        nums[odd], nums[i] = nums[i], nums[odd]
                        odd += 2
                        break
            if nums[even] % 2 == 0:
                even += 2
            else:
                for i in range(even + 1, len(nums), 2):
                    if nums[i] % 2 == 0:
                        nums[even], nums[i] = nums[i], nums[even]
                        even += 2
                        break
        return nums

