def shortestReferenceString(words: List[str], indices: List[int]) -> str:
    word_dict = {}
    for i in range(len(words)):
        sub_str = words[i][indices[i]:] + "#"
        if sub_str in word_dict:
            word_dict[sub_str].append(i)
        else:
            word_dict[sub_str] = [i]
    reference_str = ""
    for key in sorted(word_dict.keys()):
        if len(word_dict[key]) == 1:
            i = word_dict[key][0]
            reference_str += words[i][indices[i]:] + "#"
    return reference_str[:-1]

