class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        def count(mid):
            total = 0
            count = 1
            for num in nums:
                if total + num > mid:
                    total = num
                    count += 1
                else:
                    total += num
            return count
        
        left = max(nums)
        right = sum(nums)
        while left < right:
            mid = (left + right) // 2
            if count(mid) > k:
                left = mid + 1
            else:
                right = mid
        return left

