def largest_sum_of_averages(nums: List[int], k: int) -> float:
    dp = [[0] * len(nums) for _ in range(k)]
    for i in range(len(nums)):
        dp[0][i] = sum(nums[:i+1]) / (i + 1)
    for i in range(1, k):
        for j in range(i, len(nums)):
            for m in range(i-1, j):
                dp[i][j] = max(dp[i][j], dp[i-1][m] + sum(nums[m+1:j+1]) / (j-m))
    return dp[-1][-1]

def calculate_dimensions(area):
    target_area = area
    min_difference = float('inf')
    min_dimensions = [0, 0]
    for width in range(1, int(area**0.5)+1):
        if area % width == 0:
            length = area // width
            if length >= width and length - width < min_difference:
                min_difference = length - width
                min_dimensions = [length, width]
    return min_dimensions

