def minimumIncompatibility(nums, k):
    n = len(nums)
    if n % k != 0:
        return -1
    
    nums.sort()
    subset_size = n // k
    incompatibility = 0
    
    for i in range(k):
        subset = nums[i*subset_size:(i+1)*subset_size]
        if len(set(subset)) < subset_size:
            return -1
        incompatibility += subset[-1] - subset[0]
    
    return incompatibility

