    for i in range(len(rains)):
        lake = rains[i]
        if lake > 0:
            if lake in full_lakes:
                dry_day = bisect.bisect_left(dry_days, full_lakes[lake])
                if dry_day == len(dry_days):
                    return []
                else:
                    ans[dry_days[dry_day]] = lake
                    dry_days.pop(dry_day)
            full_lakes[lake] = i
            ans[i] = -1
        else:
            dry_days.append(i)

    for dry_day in dry_days:
        ans[dry_day] = 1

    return ans

