def decodeAtIndex(s: str, k: int) -> str:
    tape = ""
    for char in s:
        if char.isalpha():
            tape += char
        elif char.isdigit():
            tape *= int(char) - 1
        if len(tape) >= k:
            return tape[k-1]
    return ""

