def malware_spread(graph, initial):
    infected = set(initial)
    queue = list(infected)
    while queue:
        node = queue.pop(0)
        for adjacent_node in range(len(graph[node])):
            if graph[node][adjacent_node] == 1 and adjacent_node not in infected:
                infected.add(adjacent_node)
                queue.append(adjacent_node)
    return len(infected)

def min_malware_node(graph, initial):
    initial_infected = set(initial)
    min_malware = float('inf')
    min_node = -1
    for node in initial:
        infected = initial_infected.difference({node})
        malware_count = malware_spread(graph, infected)
        if malware_count < min_malware:
            min_malware = malware_count
            min_node = node
    return min_node

