def movesToChessboard(board):
    n = len(board)
    row_sum = sum(board[0])
    col_sum = sum(board[i][0] for i in range(n))
    row_change = col_change = 0
    if row_sum != n // 2 and row_sum != (n + 1) // 2:
        return -1
    if col_sum != n // 2 and col_sum != (n + 1) // 2:
        return -1
    for i in range(n):
        if board[0][i] != i % 2:
            row_change += 1
        if board[i][0] != i % 2:
            col_change += 1
    if n % 2 == 0:
        row_change = min(row_change, n - row_change)
        col_change = min(col_change, n - col_change)
    else:
        if row_change % 2 == 1:
            row_change = n - row_change
        if col_change % 2 == 1:
            col_change = n - col_change
    return (row_change + col_change) // 2

class Solution:
    def partition(self, s: str) -> List[List[str]]:
        res = []
        self.dfs(s, [], res)
        return res
    
    def dfs(self, s, path, res):
        if not s:
            res.append(path)
            return
        for i in range(1, len(s)+1):
            if self.isPalindrome(s[:i]):
                self.dfs(s[i:], path+[s[:i]], res)
                
    def isPalindrome(self, s):
        return s == s[::-1]

