def findAndReplacePattern(words, pattern):
    res = []
    for word in words:
        if len(word) != len(pattern):
            continue
        mapping = {}
        used = set()
        match = True
        for i in range(len(word)):
            if pattern[i] not in mapping:
                if word[i] in used:
                    match = False
                    break
                else:
                    mapping[pattern[i]] = word[i]
                    used.add(word[i])
            elif mapping[pattern[i]] != word[i]:
                match = False
                break
        if match:
            res.append(word)
    return res

class Solution:
    def longestOnes(self, nums: List[int], k: int) -> int:
        left, right = 0, 0
        zeros = 0
        res = 0
        while right < len(nums):
            if nums[right] == 0:
                zeros += 1
            while zeros > k:
                if nums[left] == 0:
                    zeros -= 1
                left += 1
            res = max(res, right - left + 1)
            right += 1
        return res

