def decode(encoded: List[int]) -> List[int]:
    n = len(encoded) + 1
    total_xor = 0
    for i in range(1, n+1):
        total_xor ^= i
    odd_xor = 0
    for i in range(1, n-1, 2):
        odd_xor ^= encoded[i]
    perm = [total_xor ^ odd_xor]
    for i in range(n-1):
        perm.append(perm[-1] ^ encoded[i])
    return perm

