def isSolvable(words, result):
    unique_chars = set(''.join(words) + result)
    if len(unique_chars) > 10:
        return False
    
    char_map = {}
    used_digits = set()
    
    def backtrack(i, carry):
        if i == len(words):
            return carry == 0
        
        word = words[i]
        for j in range(len(word)):
            char = word[j]
            if j == 0 and len(word) > 1:
                if char in char_map or carry == 0:
                    continue
                char_map[char] = carry % 10
                used_digits.add(carry % 10)
                if backtrack(i+1, carry // 10):
                    return True
                del char_map[char]
                used_digits.remove(carry % 10)
            else:
                for digit in range(10):
                    if digit in used_digits or (digit == 0 and j == len(word) - 1):
                        continue
                    char_map[char] = digit
                    used_digits.add(digit)
                    if backtrack(i+1, carry):
                        return True
                    del char_map[char]
                    used_digits.remove(digit)
        return False
    
    return backtrack(0, 0)

def minimumEffortPath(heights):
    rows, cols = len(heights), len(heights[0])
    minEfforts = [[float('inf')] * cols for _ in range(rows)]
    minEfforts[0][0] = 0
    
    heap = [(0, 0, 0)]
    visited = set()
    
    while heap:
        effort, row, col = heapq.heappop(heap)
        if (row, col) in visited:
            continue
        if row == rows - 1 and col == cols - 1:
            return effort
        visited.add((row, col))
        
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            newR, newC = row + dr, col + dc
            if 0 <= newR < rows and 0 <= newC < cols:
                newEffort = max(effort, abs(heights[newR][newC] - heights[row][col]))
                if newEffort < minEfforts[newR][newC]:
                    minEfforts[newR][newC] = newEffort
                    heapq.heappush(heap, (newEffort, newR, newC))

from collections import OrderedDict

def remove_duplicates(s):
    # Using OrderedDict to preserve the order of characters in the string
    od = OrderedDict()
    for c in s:
        od[c] = None
    # Returning the final string with duplicate characters removed and sorted
    return ''.join(sorted(od.keys()))

