        #Two pointers starting at the beginning of each list
        push_pointer = 0;
        pop_pointer = 0;
        
        #Actions tell me the operations requried to 
        #Complete all push and pop operations
        ACTIONS = (LENGTH - 1) * 2;
        
        #We use the pointers to keep track of actions
        while ( push_pointer + pop_pointer ) <=  ACTIONS :
            
            #At each level, look at the current push and pop
            current_pop = popped[ pop_pointer ];
            current_push = pushed[ push_pointer ];
            
            #See if we have either a valid pop or push operation
            
            #A valid pop will be if there is a matching with our stack's top
            validPop = ( current_pop == stackTracker[ - 1 ] );
            
            #A valid push will be if there is room in our push pointer
            #To move it again ( if not, it will be at the sentinel )
            validPush = push_pointer < LENGTH;
            
            #If we can pop
            if validPop:
                #Pop from our stack, and move the pointer
                stackTracker.pop();
                pop_pointer += 1;
				
            #If we can't pop, but can push 
            #Push that value onto the top of our stack
            #And move the pointer
            elif validPush:
                stackTracker.append( pushed [ push_pointer ] );
                push_pointer += 1;
				
            #If we can neither push nor pop
            #Return False
            elif not validPop and not validPush:
                return False;
        
        #Once we make it to the end,
        #And have succesfully completed all actions
        #The while loop will exit
        #We can return True
        return True;

