class Solution:
    def longestCycle(self, edges: List[int]) -> int:
        
        lookup = defaultdict(list)
        self.max_depth = -1
        
		# optimization
        # calculating the lookup for only edges that have indegree and outdegree.
        # Because if nodes do not have both indegree and outdegree, then they can't form a cycle.
        indegree, outdegree = set(), set()
        for i in range(0, len(edges)):
            indegree.add(edges[i])
            outdegree.add(i)
            
        all_nodes = indegree &amp; outdegree
        for i in range(0, len(edges)):
            if i in all_nodes and edges[i] in all_nodes:
                lookup[i].append(edges[i])
                
        def dfs(i, cnt, curr_dict):
            if i not in seen:
                seen.add(i)
                curr_dict[i] = cnt
                for each in lookup[i]:
                    del lookup[i]           # optimization # this can be applied because every node has
                                            # at most one outgoing edge.
                    dfs(each, cnt + 1, curr_dict)
            else:
                self.max_depth = max(self.max_depth, cnt - curr_dict.get(i, float("inf"))) 
                
        seen = set()
        for each in all_nodes:
            if each not in seen:        # optimization # avoiding visiting the nodes multiple times.
                dfs(each, 0, {})
                
        return self.max_depth

class Solution:
    def dfs1(self, v):
        self.visited.add(v)
        self.results[v] = [0, 0]
        for u in self.graph[v]:
            if u not in self.visited:
                self.dfs1(u)
                self.results[v][1] += self.results[u][1] + (self.results[u][0] + 1)
                self.results[v][0] += self.results[u][0] + 1
                
    def dfs2(self, v, parent):
        self.visited.add(v)
        if parent != -1:
            self.results[v][1] += self.results[parent][1] - (self.results[v][1] + self.results[v][0] + 1) + (
                self.results[parent][0] - (self.results[v][0] + 1) + 1)
            self.results[v][0] += self.results[parent][0] - (self.results[v][0] + 1) + 1
        for u in self.graph[v]:
            if u not in self.visited:
                self.dfs2(u, v)
                
    def sumOfDistancesInTree(self, n: int, edges: List[List[int]]) -> List[int]:
        self.results = defaultdict(int)
        self.graph = defaultdict(set)
        for v, u in edges:
            self.graph[v].add(u)
            self.graph[u].add(v)
        self.visited = set()
        self.dfs1(0)
        self.visited = set()
        self.dfs2(0, -1)
        return [self.results[k][1] for k in range(n)]

