class Solution:
    def findPairs(self, nums: List[int], k: int) -> int:
        res = set()
        n = len(nums)
        count1, count2 = defaultdict(set), defaultdict(set)
        # nums[j] = nums[i] + k or nums[j] = nums[i] - k
        for i in range(n):
            count1[nums[i] + k].add(i)
            count2[nums[i] - k].add(i)
            
        for j in range(n):
            x = nums[j]
            if x in count1:
                if len(count1[x]) >= 2:
               
                    res.add((x, x-k))
                elif len(count1[x]) == 1:
                    i = -1
                    for c in count1[x]:
                        i = c
                    if i != j:
                        res.add((x, x-k))
            if x in count2:
                if len(count2[x]) >= 2:
                
                    res.add((x+k, x))
                elif len(count2[x]) == 1:
                    i = -1 
                    for c in count2[x]:
                        i = c
                    if i != j:
                        res.add((x+k, x))
        
        return len(res)

