class Solution:
    def findPairs(self, nums: List[int], k: int) -> int:
        if k < 0:
            return 0
        if k == 0:
            return len([i for i in collections.Counter(nums).values() if i > 1])
        nums_set = set(nums)
        pairs = set()
        for num in nums_set:
            if num + k in nums_set:
                pairs.add((num, num + k))
            if num - k in nums_set:
                pairs.add((num - k, num))
        return len(pairs)

def closedIsland(grid):
    def dfs(i, j):
        if 0 <= i < m and 0 <= j < n and grid[i][j] == 0:
            grid[i][j] = 1
            dfs(i+1, j)
            dfs(i-1, j)
            dfs(i, j+1)
            dfs(i, j-1)
            return True
        return False

    m, n = len(grid), len(grid[0])
    count = 0
    for i in range(m):
        for j in range(n):
            if i == 0 or j == 0 or i == m-1 or j == n-1:
                dfs(i, j)
    for i in range(1, m-1):
        for j in range(1, n-1):
            if grid[i][j] == 0:
                if dfs(i, j):
                    count += 1
    return count

