def max_sum(nums, numSlots):
    slot_dict = {}
    for i in range(1, numSlots + 1):
        slot_dict[i] = []
    for i, num in enumerate(nums):
        slot = (i % numSlots) + 1
        slot_dict[slot].append(num)
    max_sum = 0
    for slot, nums_in_slot in slot_dict.items():
        slot_sum = sum([(num & slot) for num in nums_in_slot])
        max_sum += slot_sum
    return max_sum

