class Solution:
    def minMutation(self, start: str, end: str, bank: List[str]) -> int:
        v = {"ACGT"[i]: i for i in range(4)}
        c = lambda x: sum([v[x[i]] * (4**i) for i in range(len(x))])
        d = {c(x): inf for x in bank}
        
        st = c(start)
        en = c(end)
        if en not in d:
            return -1
        d[st] = 0

        mutations = {v: [] for v in d.keys()}

        for k1 in d.keys():
            for k2 in d.keys():
                if k2 > k1:
                    cnt = 0
                    bm = 3
                    for i in range(8):
                        if (k1 &amp; bm) != (k2 &amp; bm):
                            cnt += 1
                        if cnt == 2:
                            break
                        bm <<= 2
                    if cnt == 1:
                        mutations[k1].append(k2)
                        mutations[k2].append(k1)
        
        visited = [st]

        while visited:
            cur = visited.pop(0)
            cd = d[cur]
            assert cd <= len(d)
            for dest in mutations[cur]:
                if d[dest]>cd:  # it's BFS, so it should be inf unless visited
                    if dest == en:
                        return cd + 1
                    d[dest] = cd + 1
                    visited.append(dest)
        return -1

