def minMutation(startGene, endGene, geneBank):
    if endGene not in geneBank:
        return -1
    
    queue = [(startGene, 0)]
    visited = set([startGene])
    
    while queue:
        gene, mutations = queue.pop(0)
        if gene == endGene:
            return mutations
        
        for i in range(len(gene)):
            for c in ['A', 'C', 'G', 'T']:
                mutated_gene = gene[:i] + c + gene[i+1:]
                if mutated_gene in geneBank and mutated_gene not in visited:
                    visited.add(mutated_gene)
                    queue.append((mutated_gene, mutations+1))
    
    return -1

