class Solution:
    def checkValidString(self, s: str) -> bool:
        open = 0 
        closed = 0 
        any = 0 
        for c in s:
            if c == '(':
                open += 1
            elif c == ')':
                closed += 1 
            else:
                any += 1 
			
			# at the end of each loop check to see if the number of closed brackets 
			# up until that point are greater than the number of open brackets
			# also check to see if we can change that by changing the *'s to 
			# open brackets
            if closed > open + any:
                return False 

		# at the very end of the first loop do a similar check but to see if there are 
		# too many open brackets 
        if closed + any < open:
            return False 

        open, closed, any = 0, 0, 0
        for c in s[::-1]:
            if c == '(':
                open += 1 
            elif c == ')':
                closed += 1 
            else:
                any += 1 

			# this time iterate backwards and check to see if the number of 
			# open brackets is greater than the number of max closed brackets
			# we can produce. If it is, then an excess amount of brackets were
			# "opened" without being able to be closed by the end
            if open > closed + any:
                return False 


		#don't have to recheck again because open, closed, and any since the same 
		# values from the first loop 
		
        return True

