    def titleToNumber(self, columnTitle: str) -> int:
        # main idea (example)
        # columnTitle = "ZY"
        # columnTitle == 2
        # total alphabet * (current index char + 1) + (index next char + 1)
        # 26 * 26 + 25 = 701
        
        c = list(columnTitle)
