class Solution:
    def trimBST(self, root: Optional[TreeNode], low: int, high: int) -> Optional[TreeNode]:
        return trim(root, low, high)
    
def trim(node, low, high):
	# node is empty
	if node is None:
		return None

	# node is a leaf (no children)
	if node.left is None and node.right is None:
		if low <= node.val <= high:
			return node
		return None
	
	# Apply the trim function on the left subtree and get the trimmed left subtree
	left = trim(node.left, low, high)
	# Similarly, trim the right subtree
	right = trim(node.right, low, high)

	# If the node values is within the limits, create a new tree with the current node and modified left and right subtrees of this node
	if low <= node.val <= high:
		node.left, node.right = left, right
		return node

	# If the node value is less than the lower limit, we excluse the node value.
	# Also note that all the values in the left subtree are less than the node. So, we remove the left subtree.
	# What remains is the right subtree
	elif node.val < low:
		return right

	# Similarly, here the node is greater than the upper limit. So the entire right subtree is also greater than the upper limit
	# What remains is the left sub tree
	elif node.val > high:
		return left
	return None

