                    else:
                        if grid[i][j+1] != 0:
                            x += min(grid[i][j], grid[i][j+1])
                        if grid[i][j-1] != 0:
                            x += min(grid[i][j], grid[i][j-1])
                elif i == n-1:
                    if grid[i-1][j] != 0:
                        x += min(grid[i-1][j], grid[i][j])
                    if j == 0:
                        if grid[i][j+1] != 0:
                            x += min(grid[i][j], grid[i][j+1])
                    elif j == n-1:
                        if grid[i][j-1] != 0:
                            x += min(grid[i][j], grid[i][j-1])
                    else:
                        if grid[i][j+1] != 0:
                            x += min(grid[i][j], grid[i][j+1])
                        if grid[i][j-1] != 0:
                            x += min(grid[i][j], grid[i][j-1])
                
                else:
                    if grid[i-1][j] != 0:
                        x += min(grid[i-1][j], grid[i][j])
                    if grid[i+1][j] != 0:
                        x += min(grid[i+1][j], grid[i][j])
                    if j == 0:
                        if grid[i][j+1] != 0:
