class Solution:
    def corpFlightBookings(self, bookings: List[List[int]], n: int) -> List[int]:
        res, diffs = [0]*n, [0]*n
        
        for i in range(0, len(bookings)):
            first = bookings[i][0] - 1
            last = bookings[i][1] - 1
            k = bookings[i][2]
            # increment res[first..] by k
            diffs[first] += k
            # decrement res[last+1..] by k
            if (last+1 < n):
                diffs[last+1] -= k
        
        res[0] = diffs[0]
        for i in range(1, n):
            res[i] = res[i-1] + diffs[i]
            
        return res

