def countNodes(root):
    if not root:
        return 0
    left_depth = get_depth(root.left)
    right_depth = get_depth(root.right)
    if left_depth == right_depth:
        return 2 ** left_depth - 1
    else:
        return countNodes(root.left) + countNodes(root.right) + 1
        
def get_depth(root):
    depth = 0
    while root:
        depth += 1
        root = root.left
    return depth

