class Solution:
    def countRoutes(self, locations: List[int], start: int, finish: int, fuel: int) -> int:
        
        @lru_cache(None)
        def dfs(city, rem_fuel):
            if rem_fuel < 0:
                return 0
            if city == finish:
                return 1
            res = 0
            for j in range(len(locations)):
                if j != city:
                    res += dfs(j, rem_fuel - abs(locations[city] - locations[j]))
            return res % MOD
        
        return dfs(start, fuel)

