class Solution:
    def luckyNumbers(self, matrix: List[List[int]]) -> List[int]:

        # Get row, col tuple of minimum value of a row in this array. Row number is implicit in array index, save column as value
        row_min_cols = [0] * len(matrix)
        # Get row, col tuple of maximum value of a col in this array. Column number is implicit in array index, save row as value
        col_min_rows = [0] * len(matrix[0])

        # Find minimum and maximum
        for row in range(len(matrix)):
            for col in range(len(matrix[0])):
                row_min_val = matrix[row][row_min_cols[row]]
                col_min_val = matrix[col_min_rows[col]][col]

                if matrix[row][col] < row_min_val:
                    row_min_cols[row] = col

                if matrix[row][col] > col_min_val:
                    col_min_rows[col] = row

        result_arr = []

        # If match found in both arrays, return
        for idx, val in enumerate(row_min_cols):
            if idx == col_min_rows[val]:
                result_arr.append(matrix[idx][val])

        return result_arr

