class Solution:
    def findTarget(self, root: TreeNode, k: int) -> bool:
        vals = []
        self.traverse(root,vals)
        left = 0
        right = len(vals) - 1
        while left < right:
            current_sum = vals[left] + vals[right]
            if current_sum == k:
                return True
            elif current_sum < k:
                left += 1
            else:
                right -= 1
        return False
    
    def traverse(self,root,vals):
        if root is None:
            return
        self.traverse(root.left,vals)
        vals.append(root.val)
        self.traverse(root.right,vals)

