def get_max_time(grid):
    m = len(grid)
    n = len(grid[0])
    steps = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = [(0, 0, 0)]
    visited = {(0, 0)}
    max_time = 0
    
    while queue:
        x, y, time = queue.pop(0)
        max_time = max(max_time, time)
        
        if x == m - 1 and y == n - 1:
            return max_time
        
        for dx, dy in steps:
            new_x = x + dx
            new_y = y + dy
            
            if 0 <= new_x < m and 0 <= new_y < n and grid[new_x][new_y] != 2 and (new_x, new_y) not in visited:
                visited.add((new_x, new_y))
                
                if grid[new_x][new_y] == 0:
                    queue.append((new_x, new_y, time+1))
                elif grid[new_x][new_y] == 1:
                    queue.append((new_x, new_y, time+2))
                    grid[new_x][new_y] = 2
                    
    return -1 if max_time == 0 else 109

