def trailingZeroes(n):
    count = 0
    while n >= 5:
        n //= 5
        count += n
    return count

def reorder_logs(logs):
    letter_logs = []
    digit_logs = []

    for log in logs:
        if log.split()[1].isdigit():
            digit_logs.append(log)
        else:
            letter_logs.append(log)

    letter_logs.sort(key=lambda x: (x.split()[1:], x.split()[0]))

    return letter_logs + digit_logs

def min_subarray(nums, target):
    if not nums:
        return 0
    start = end = 0
    cur_sum = 0
    min_len = float('inf')
    while end < len(nums):
        while cur_sum < target and end < len(nums):
            cur_sum += nums[end]
            end += 1
        while cur_sum >= target and start <= end:
            min_len = min(min_len, end - start)
            cur_sum -= nums[start]
            start += 1
    return min_len if min_len != float('inf') else 0

