def num_playlists(n: int, goal: int, k: int) -> int:
    mod = 10**9 + 7
    dp = [[0] * (k+1) for _ in range(goal+1)]
    dp[0][0] = 1
    
    for i in range(1, goal+1):
        for j in range(1, k+1):
            dp[i][j] = (dp[i-1][j-1] * (n-j+1)) % mod
            if j > i:
                dp[i][j] = (dp[i][j] + dp[i][j-1] * (j-i)) % mod
    
    return dp[goal][k] % mod

def numTilePossibilities(tiles):
    def dfs(curr):
        if curr:
            seen.add(curr)
        for i in range(len(tiles)):
            if used[i]:
                continue
            used[i] = True
            dfs(curr + tiles[i])
            used[i] = False
    
    used = [False] * len(tiles)
    seen = set()
    dfs('')
    return len(seen) - 1

