def find_missing_rolls(rolls, mean, n):
    total_sum = mean*(n+len(rolls)) - sum(rolls)
    if total_sum % n != 0:
        return []
    else:
        missing_sum = total_sum//n
        missing_rolls = []
        for i in range(1, n+1):
            if i not in rolls:
                missing_rolls.append(missing_sum-i+sum(rolls)//len(rolls))
        return missing_rolls

