class Solution:
    def largestMultipleOfThree(self, nums: List[int]) -> str:
        nums.sort(reverse = True)
      
        if sum(nums)%3 == 1:
            # we need to remove one minimum or two with remainder == 2
            flag = False
            for i in reversed(range(len(nums))):
                if nums[i]%3 == 1:
                    nums[i] = -1
                    flag = True
                    break
            if not flag:
                count = 2
                for i in reversed(range(len(nums))):
                    if count == 0:
                        break
                    if nums[i]%3 == 2:
                        nums[i] = -1
                        count-=1
        elif sum(nums)%3 == 2:
            flag = False
            for i in reversed(range(len(nums))):
                if nums[i]%3 == 2:
                    nums[i] = -1
                    flag = True
                    break
            if not flag:
                # remove 2 elements having 1 remainder 
                count = 2
                for i in reversed(range(len(nums))):
                    if count == 0:
                        break
                    if nums[i]%3 == 1:
                        nums[i] = -1
                        count-=1
                        
            
        ans = ''
        for i in nums:
            if i!=-1:
                ans+=str(i)
        if ans:
            return str(int(ans))
        else:
            return ans

