class Solution:
    def largestMultipleOfThree(self, digits: List[int]) -> str:
        digits.sort(reverse=True)
        s = sum(digits)
        if s == 0:
            return "0"
        if s % 3 == 1:
            to_remove = []
            for i in range(len(digits)):
                if digits[i] % 3 == 1:
                    to_remove.append(i)
                    if len(to_remove) == 2:
                        break
            if len(to_remove) == 0:
                to_remove = [i for i in range(len(digits)) if digits[i] % 3 == 2][:2]
            if len(to_remove) == 1:
                to_remove += [i for i in range(len(digits)) if digits[i] % 3 == 2][:1]
            to_remove.sort(reverse=True)
            for i in to_remove:
                digits.pop(i)
        elif s % 3 == 2:
            to_remove = []
            for i in range(len(digits)):
                if digits[i] % 3 == 2:
                    to_remove.append(i)
                    if len(to_remove) == 2:
                        break
            if len(to_remove) == 0:
                to_remove = [i for i in range(len(digits)) if digits[i] % 3 == 1][:2]
            if len(to_remove) == 1:
                to_remove += [i for i in range(len(digits)) if digits[i] % 3 == 1][:1]
            to_remove.sort(reverse=True)
            for i in to_remove:
                digits.pop(i)
        digits.sort(reverse=True)
        if digits and digits[0] == 0:
            return "0"
        return "".join(map(str, digits))

def xorOperation(n: int, start: int) -> int:
    nums = [start + 2*i for i in range(n)]
    result = 0
    for num in nums:
        result ^= num
    return result

