def kthSmallestPath(destination: List[int], k: int) -> str:
    rows, cols = destination
    total_moves = rows + cols
    h_moves = cols
    v_moves = rows

    def factorial(n):
        if n == 0 or n == 1:
            return 1
        return n * factorial(n-1)

    def find_combinations(n, r):
        return factorial(n) // (factorial(r) * factorial(n-r))

    def find_kth_path(k, h_moves, v_moves, total_moves):
        if total_moves == 0:
            return ""
        total_combinations = find_combinations(h_moves + v_moves - 1, h_moves)
        if k <= total_combinations:
            return "H" + find_kth_path(k, h_moves-1, v_moves, total_moves-1)
        else:
            return "V" + find_kth_path(k-total_combinations, h_moves, v_moves-1, total_moves-1)

    return find_kth_path(k, h_moves, v_moves, total_moves)

