class Solution:
    def largeGroupPositions(self, s: str) -> List[List[int]]:
        
        #Sentinel at the end
        s = s + '!';
        
        #Then find the length
        LENGTH = len ( s );
        
        #Make a list for the solution
        soln = [ ];
        
        #Initialize the previous as the first character at zeroth index
        prev = s[ 0 ];
        prevIndex = 0;
        
        #Pointer will be at the first index
        pointer = 1;
        
        #Streak default is one
        streak = 1;
        
        #While we have a vald index
        while pointer < LENGTH:
            #Look at the character using the pointer
            current = s[ pointer ];
            
            #If we match, we proceed
            if current == prev:
                #By increasing our streak
                #And increasing the pointer, 
                streak += 1;
                pointer += 1;
                continue;
                
            #If we have a mismatch and a streak of 3 or higher
            elif current != prev and streak >= 3 :
                #We append the indices to the solution
                soln.append( [ prevIndex, pointer - 1 ] );
            
            #Each time we don't have a match
            #We reset the streak to one
            #Update previous and its index
            #And increment the pointer
            streak = 1;
            prev = current;
            prevIndex = pointer;
            pointer += 1;
            
        #Return the soln
        return soln ;

