def prisonAfterNDays(cells: List[int], n: int) -> List[int]:
    def getNextDay(cells):
        new_cells = [0] * len(cells)
        for i in range(1, len(cells)-1):
            if cells[i-1] == cells[i+1]:
                new_cells[i] = 1
        return new_cells
    
    seen = {}
    for i in range(n):
        cell_tuple = tuple(cells)
        if cell_tuple in seen:
            loop_len = i - seen[cell_tuple]
            return prisonAfterNDays(cells, (n - i) % loop_len)
        else:
            seen[cell_tuple] = i
            cells = getNextDay(cells)
    
    return cells

MOD = 10**9 + 7

def num_of_binary_trees(arr):
    freq = {}
    for num in arr:
        freq[num] = freq.get(num, 0) + 1
    dp = {}
    return dfs(arr, freq, dp) % MOD

def dfs(arr, freq, dp):
    if len(arr) == 0:
        return 1
    if len(arr) == 1:
        return 1
    if str(arr) in dp:
        return dp[str(arr)]
    res = 0
    for i in range(len(arr)):
        left_tree = arr[:i]
        right_tree = arr[i+1:]
        left = dfs(left_tree, freq, dp)
        right = dfs(right_tree, freq, dp)
        res += (left * right * arrange(freq[arr[i]]-1, left+len(left_tree)+right)) % MOD
    dp[str(arr)] = res
    return res

def arrange(a, b):
    res = 1
    for i in range(b-a+1, b+1):
        res = (res * i) % MOD
    return res

