def construct_pyramid(base):
    pattern_lst = ["ABC", "ACB", "BAC", "BCA", "CAB", "CBA"]
    rows = [base]
    while len(rows[-1]) > 1:
        row = rows[-1]
        new_row = ""
        for i in range(len(row)-1):
            block1, block2 = row[i], row[i+1]
            for pattern in pattern_lst:
                if block1 == pattern[0] and block2 == pattern[1]:
                    new_row += pattern[2]
                    break
            else:
                return False
        rows.append(new_row)
    return True

