def can_win(root, n, x):
    red_nodes = set([x])
    blue_nodes = set()
    stack = [root]
    while stack:
        node = stack.pop()
        if node.left:
            stack.append(node.left)
            if node.left.val in red_nodes:
                red_nodes.add(node.val)
            elif node.left.val in blue_nodes:
                blue_nodes.add(node.val)
        if node.right:
            stack.append(node.right)
            if node.right.val in red_nodes:
                red_nodes.add(node.val)
            elif node.right.val in blue_nodes:
                blue_nodes.add(node.val)
        if node.val == x:
            if node.left:
                blue_nodes.add(node.left.val)
            if node.right:
                blue_nodes.add(node.right.val)
    if len(red_nodes) <= len(blue_nodes):
        return True
    else:
        return False

