class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        n = len(graph)
        color = [0] * n
        
        def dfs(node):
            if color[node] == 1:
                return False
            if color[node] == 2:
                return True
            color[node] = 1
            for nei in graph[node]:
                if not dfs(nei):
                    return False
            color[node] = 2
            return True
        
        ans = []
        for i in range(n):
            if dfs(i):
                ans.append(i)
        return ans

