def isLinkedListPathInBinaryTree(root: TreeNode, head: ListNode) -> bool:
    if not root or not head:
        return False
    
    def dfs(node, curr):
        if not node:
            return False
        if node.val != curr.val:
            return False
        if not curr.next:
            return True
        
        return dfs(node.left, curr.next) or dfs(node.right, curr.next)
    
    if dfs(root, head):
        return True
    
    return isLinkedListPathInBinaryTree(root.left, head) or isLinkedListPathInBinaryTree(root.right, head)

