def rank_matrix(matrix):
    n = len(matrix)
    m = len(matrix[0])
    ranks = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            rank = 1
            for k in range(n):
                for l in range(m):
                    if matrix[k][l] > matrix[i][j]:
                        rank += 1
            ranks[i][j] = rank
    return ranks

def min_seed_value(nums: List[int], space: int) -> int:
    nums.sort() # sort the array
    result = float('inf')
    n = len(nums)
    for i in range(n):
        cnt_targets = 0
        for j in range(i, n):
            if nums[j] - nums[i] <= space * (j - i):
                cnt_targets += 1
        if cnt_targets == n - i:
            result = min(result, nums[i])
    return result

def count_hidden_sequences(differences, lower, upper):
    n = len(differences)
    dp = [[0] * (upper + 1) for _ in range(n + 1)]
    dp[0][1:] = [1] * upper
    for i in range(1, n + 1):
        for j in range(1, upper + 1):
            for k in range(max(1, j - differences[i - 1]), j):
                dp[i][j] += dp[i - 1][k]
        for j in range(1, upper + 1):
            dp[i][j] -= dp[i - 1][j - 1]
        for j in range(1, upper + 1):
            dp[i][j] += dp[i][j - 1]
    return dp[-1][upper] - dp[-1][lower - 1] if lower > 1 else dp[-1][upper]

