def remove_node(n, graph):

    def infected_count(node):
        visited = set()
        stack = [node]
        while stack:
            curr = stack.pop()
            if curr in visited:
                continue
            visited.add(curr)
            for i in range(n):
                if graph[curr][i] == 1 and i not in visited:
                    stack.append(i)
        return len(visited)

    min_infected = float('inf')
    min_node = -1

    for i in range(n):
        temp = graph[i][:]
        for j in range(n):
            if temp[j] == 1:
                temp[j] = 0
                temp[i] = 0
                infected = infected_count(j)
                if infected < min_infected:
                    min_infected = infected
                    min_node = j

    return min_node

