class Solution:
    def largestPerimeter(self, A: List[int]) -> int:
        # Sort the array
        A.sort()
        # start with 3 less than len(A), keep going until you get to just before -1, by steps of -1.
        for i in range(len(A)-3,-1,-1):
            # Sum of 2 sides of a triangle is > than the 3rd side
            if(A[i] + A[i+1] > A[i+2]):
                # largest perimeter
                return A[i] + A[i+1] + A[i+2]
        # If it is impossible to form any triangle of non-zero area, return 0
        return 0

