class Solution:
    def numSquarefulPerms(self, nums: List[int]) -> int:
        def dfs(used, curr, count):
            nonlocal res
            if count == n:
                res += 1
                return
            
            for i in range(n):
                if used[i]:
                    continue
                if i > 0 and not used[i-1] and nums[i] == nums[i-1]:
                    continue
                next_num = nums[i]
                if not curr or ((curr + next_num)**0.5).is_integer():
                    used[i] = True
                    dfs(used, next_num, count + 1)
                    used[i] = False
        
        res = 0
        n = len(nums)
        nums.sort()
        dfs([False]*n, None, 0)
        return res

