def frequent_even(nums):
    even_num_freq = {}
    for num in nums:
        if num % 2 == 0:
            if num in even_num_freq:
                even_num_freq[num] += 1
            else:
                even_num_freq[num] = 1
    if not even_num_freq:
        return -1
    max_freq = max(even_num_freq.values())
    most_frequent_evens = [num for num, freq in even_num_freq.items() if freq == max_freq]
    return min(most_frequent_evens) if most_frequent_evens else -1

