from itertools import combinations

def maximum_score(values, labels, numWanted, useLimit):
    items = list(zip(values, labels))
    items_by_label = {}
    for value, label in items:
        items_by_label[label] = items_by_label.get(label, []) + [value]
    subsets = []
    for label, items in items_by_label.items():
        for limit in range(1, useLimit+1):
            for subset in combinations(items, limit):
                subsets.append((sum(subset), subset))
    subsets.sort(reverse=True)
    score = 0
    selected = set()
    for s, subset in subsets:
        if len(selected) >= numWanted:
            break
        new_items = set(labels[i] for i, v in enumerate(values) if v in subset)
        if len(selected.union(new_items)) <= useLimit:
            selected = selected.union(new_items)
            score += s
    return score

class Solution:
    def maxAverageRatio(self, classes: List[List[int]], extraStudents: int) -> float:
        heap = []
        for p, t in classes:
            heapq.heappush(heap, (-((p + 1) / (t + 1) - p / t), p, t))
        for _ in range(extraStudents):
            r, p, t = heapq.heappop(heap)
            p, t = p + 1, t + 1
            heapq.heappush(heap, (-((p + 1) / (t + 1) - p / t), p, t))
        return sum(p / t for _, p, t in heap) / len(heap)

