def kthLargestSum(nums, k):
    n = len(nums)
    sums = [0] * (n + 1)
    for i in range(n):
        sums[i+1] = sums[i] + nums[i]
    heap = []
    for i in range(1, n+1):
        for j in range(i):
            heap.append(sums[i] - sums[j])
    heap = sorted(heap, reverse=True)
    return heap[k-1:k]

