class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def splitListToParts(self, head: ListNode, k: int) -> List[ListNode]:
        curr = head
        count = 0
        while curr:
            count += 1
            curr = curr.next
        size, remainder = divmod(count, k)
        result = []
        curr = head
        for i in range(k):
            part_head = part = ListNode(None)
            for j in range(size + (i < remainder)):
                part.next = part = ListNode(curr.val)
                if curr:
                    curr = curr.next
            result.append(part_head.next)
        return result

class Solution:
    def maxProfitAssignment(self, difficulty: List[int], profit: List[int], worker: List[int]) -> int:
        jobs = sorted(zip(difficulty, profit), key=lambda x: x[0])
        worker.sort()
        i, max_profit, total_profit = 0, 0, 0
        for ability in worker:
            while i < len(jobs) and ability >= jobs[i][0]:
                max_profit = max(max_profit, jobs[i][1])
                i += 1
            total_profit += max_profit
        return total_profit

