class Solution:
	def findMaxAverage(self, nums: List[int], k: int) -> float:

		# If the array contains only one element
		# then average would certainly be equal 
		# to the element itself.
		if len(nums) == 1: return float(nums[0])

		sumK  = -math.inf    # stores the maximum sum of k elements.
		calcSumK = 0         # calculates sum of k elements

		left = 0
		for pos, num in enumerate(nums):
			# If the size exceeds k elements
			# then substract the magnitude of
			# the leftmost element
			if (pos - left + 1) > k:
				print(pos - left + 1)
				calcSumK -= nums[left]
				left += 1

			calcSumK += num
			# compute max sum of k elements.
			if (pos - left + 1) == k:
				sumK = max(sumK,calcSumK)

		return (sumK / k)

