class Solution:
    def countVowelStrings(self, target_n: int) -> int:
        memo = {}
        def countVowel(n, prev_v):
            if n > target_n: return 0           
            if n == target_n: return 1
            
            if (n, prev_v) in memo:
                return memo[(n, prev_v)]
            
            count = 0
            for v in ['a', 'e', 'i', 'o', 'u']:
                if ord(prev_v) <= ord(v):
                    count += countVowel(n+1, v)  
					
            memo[(n, prev_v)] = count
            return memo[(n, prev_v)]
                
        return countVowel(0, 'a')

