def is_valid_binary_tree(n, leftChild, rightChild):
    seen = set()
    for i in range(n):
        if leftChild[i] != -1:
            if leftChild[i] in seen:
                return False
            else:
                seen.add(leftChild[i])
        if rightChild[i] != -1:
            if rightChild[i] in seen:
                return False
            else:
                seen.add(rightChild[i])
    root_count = 0
    for i in range(n):
        if i not in seen:
            root_count += 1
            if root_count > 1:
                return False
    if root_count == 0:
        return False
    return True

