from collections import deque

def remove_invalid_parentheses(s):
    def is_valid(s):
        count = 0
        for c in s:
            if c == '(':
                count += 1
            elif c == ')':
                count -= 1
                if count < 0:
                    return False
        return count == 0
    
    visited = set()
    q = deque()
    q.append(s)
    visited.add(s)
    
    res = []
    found_valid = False
    
    while q:
        s = q.popleft()
        if is_valid(s):
            res.append(s)
            found_valid = True
        if found_valid:
            continue
        for i in range(len(s)):
            if s[i] not in '()':
                continue
            new_s = s[:i] + s[i+1:]
            if new_s not in visited:
                visited.add(new_s)
                q.append(new_s)
    
    return res

def waiting_time(n, tickets, k):
    time = 0
    queue = [(i, t) for i, t in enumerate(tickets)]
    while queue:
        person, num_tickets = queue.pop(0)
        if person == k:
            time += tickets[k]
            break
        if num_tickets > 1:
            queue.append((person, num_tickets - 1))
        time += 1
    return time

def longestCommonSubsequence(text1: str, text2: str) -> int:
    m = len(text1)
    n = len(text2)
    
    # create a matrix to store lengths of longest common subsequences
    lcs = [[0] * (n+1) for _ in range(m+1)]
    
    # fill the matrix using dynamic programming approach
    for i in range(1, m+1):
        for j in range(1, n+1):
            if text1[i-1] == text2[j-1]:
                lcs[i][j] = lcs[i-1][j-1] + 1
            else:
                lcs[i][j] = max(lcs[i][j-1], lcs[i-1][j])
    
    return lcs[m][n]

