class Solution:  
    def distanceBetweenBusStops(self, distance: List[int], start: int, destination: int) -> int:  
        # corner/edge case  
        if start == destination:  
            return 0  
          
        n = len(distance)  
        ''' Number of stop'''  
          
        def dist_clockwise(s, e):  
            return distance[s:e]  
          
        def get_previous_stop(s):  
            s = s - 1  
            return n + s if s < 0 else s  
          
        def dist_counterclockwise(s, e):  
            dist = 0  
            s = get_previous_stop(s)  
            dist += distance[s]  
            while s != e:  
                s = get_previous_stop(s)  
                dist += distance[s]  
                  
            return dist  
          
          
        # Keep start stop before destination stop for easy process          
        if start > destination:  
            start ,destination = destination, start  
              
              
        # Calculate the distances of clockwise/counterclockwise and return the shorter one  
        return min(dist_clockwise(start, destination), dist_counterclockwise(start, destination))

