def shortest_distance(start, dest, stops):
    n = len(stops)
    dist = [float('inf')] * n
    dist[start] = 0
    queue = [start]
    while queue:
        curr_stop = queue.pop(0)
        for i in [-1, 1]:
            next_stop = (curr_stop + i) % n
            if dist[next_stop] > dist[curr_stop] + stops[curr_stop][i]:
                dist[next_stop] = dist[curr_stop] + stops[curr_stop][i]
                queue.append(next_stop)
    return dist[dest]

