class Solution:
    def maxTaxiEarnings(self, n: int, rides: List[List[int]]) -> int:
        rides.sort(key=lambda x:x[1])
        earnings = [0]*(n+1)
        idx = 0
        for i in range(1,n+1):
            earnings[i] = earnings[i-1]
            while idx<len(rides) and rides[idx][1] == i:
                start, end, tip = rides[idx]
                earnings[i] = max(earnings[i], earnings[start] + end - start + tip)
                idx += 1
        return earnings[-1]

def find_original_array(nums, n):
    arr = [0] * n
    nums.sort()
    used = [False] * (2 * n)
    for i in range(n):
        j = bisect_left(nums, nums[i] - n, 0, 2 * n)
        while j < 2 * n and (used[j] or nums[j] < nums[i]):
            j += 1
        if j == 2 * n or nums[j] != nums[i] - n:
            return []
        used[j] = True
        arr[i] = nums[j]
    for i in range(n):
        j = bisect_left(nums, arr[i] + n, 0, 2 * n)
        while j < 2 * n and (used[j] or nums[j] < arr[i]):
            j += 1
        if j == 2 * n or nums[j] != arr[i] + n:
            return []
        used[j] = True
    return arr

