class Solution:
    def kClosest(self, points: List[List[int]], k: int) -> List[List[int]]:
        ans = []
        for point in points:
            ans.append(point)
            self.heapifyUp(ans, len(ans)-1)
            if len(ans) > k:
                ans[0], ans[-1] = ans[-1], ans[0]
                ans.pop()
                self.heapifyDown(ans, 0)
        return ans
    
    def heapifyDown(self, ans, index):
        if index < len(ans):
            pointDis = ans[index][0]*ans[index][0] + ans[index][1]*ans[index][1]
            leftDis = rightDis = -1
            if index*2 + 1 < len(ans):
                left = ans[index*2 + 1]
                leftDis = left[0]*left[0] + left[1]*left[1]
            if index*2 + 2 < len(ans):
                right = ans[index*2 + 2]
                rightDis = right[0]*right[0] + right[1]*right[1]
            if pointDis < max(leftDis, rightDis):
                if leftDis >= rightDis:
                    ans[index], ans[index*2 + 1] = ans[index*2 + 1], ans[index]
                    self.heapifyDown(ans, index*2 + 1)
                else:
                    ans[index], ans[index*2 + 2] = ans[index*2 + 2], ans[index]
                    self.heapifyDown(ans, index*2 + 2)
            
    def heapifyUp(self, ans, index):
        if index > 0:
            point = ans[index]
            pointDis = point[0]*point[0] + point[1]*point[1]
            parent = ans[(index-1)//2]
            parentDis = parent[0]*parent[0] + parent[1]*parent[1]
            if pointDis > parentDis:
                ans[index], ans[(index-1)//2] = ans[(index-1)//2], ans[index]
                self.heapifyUp(ans, (index-1)//2)

class Solution:
    def maximumDetonation(self, bombs: List[List[int]]) -> int:
        
        # make a dict to connect bombs
        connections = {idx: set() for idx in range(len(bombs))}
        
        # make the computations
        for id1, (x1, y1, r1) in enumerate(bombs):
            for id2, (x2, y2, r2) in enumerate(bombs[id1+1:], id1+1):
                
                # compute the distance
                distance = (x1-x2)**2 + (y1-y2)**2
                
                # check whether they are within radius
                if distance <= r1**2:
                    connections[id1].add(id2)
                if distance <= r2**2:
                    connections[id2].add(id1)
        
        # make the DFS
        self.max = 0
        
        # save bombs we already solved
        self.solved = {}
        
        # start at every bomb
        for idx in range(len(bombs)):
            
            # get the reachable bombs
            visited = set([idx])
            self.dfs(idx, visited, connections)
            
            # save the reachable bombs
            self.solved[idx] = visited
            
            # count reachable bombs
            self.max = max(self.max, len(visited))
            
        return self.max
    
    def dfs(self, current, visited, connections):
        
        # check if we already solved for this bomb
        if current in self.solved:
            # extend our path
            visited.update(self.solved[current])
            return
        
        # go deeper
        for idx in connections[current]:
            if idx not in visited:
                
                # update visited
                visited.add(idx)

                # go deeper
                self.dfs(idx, visited, connections)

