    for bomb in bombs:
        x, y, r = bomb
        count = 1
        for other in bombs:
            if other == bomb:
                continue
            ox, oy, orad = other
            if (ox-x)**2 + (oy-y)**2 <= r**2:
                count += 1
        if count > maxDet:
