def minimum_abs_difference(arr):
    arr.sort()
    diff = arr[-1]
    for i in range(len(arr) - 1):
        if arr[i+1] - arr[i] < diff:
            diff = arr[i+1] - arr[i]
    pairs = []
    for i in range(len(arr) - 1):
        if arr[i+1] - arr[i] == diff:
            pairs.append([arr[i], arr[i+1]])
    return pairs

class Solution:
    def pacificAtlantic(self, heights: List[List[int]]) -> List[List[int]]:
        
        if not heights:
            return []
        
        m, n = len(heights), len(heights[0])
        
        pacific = set()
        atlantic = set()
        
        def dfs(i, j, visited):
            if (i, j) in visited:
                return
            visited.add((i, j))
            
            if i == 0 or j == 0:
                pacific.add((i, j))
            if i == m-1 or j == n-1:
                atlantic.add((i, j))
            
            direction = [(0, 1), (0, -1), (1, 0), (-1, 0)]
            for d in direction:
                x, y = i + d[0], j + d[1]
                if 0 <= x < m and 0 <= y < n and heights[x][y] >= heights[i][j]:
                    dfs(x, y, visited)
                        
        for i in range(m):
            dfs(i, 0, pacific)
            dfs(i, n-1, atlantic)
        
        for j in range(n):
            dfs(0, j, pacific)
            dfs(m-1, j, atlantic)
        
        result = list(pacific.intersection(atlantic))
        return result

