    def intervalIntersection(self, firstList: List[List[int]], secondList: List[List[int]]) -> List[List[int]]:
        
        # A function which defines all criteria
        # possible between two intervals. This function
        # also help in deciding which index to increment
        # which to not increment.
        # x : First Interval at ith index of firstList
        # y : Second Interval at jth index of secondList
        def commonInterval(x,i,y,j):
            
            x1, x2 = x
            y1, y2 = y

            if x1 <= y1 <= y2 <= x2:
                return y,i,j+1
            elif y1 <= x1 <= x2 <= y2:
                return x,i+1,j
            elif x1 <= y1 <= x2 <= y2:
                return [y1,x2],i+1,j
            elif y1 <= x1 <= y2 <= x2:
                return [x1,y2],i,j+1
            elif x2 == y1:
                return [x2,y1],i+1,j
            elif x2 < y1:
                return None,i+1,j
            elif y2 == x1:
                return [y2,x1],i,j+1
            elif y2 < x1:
                return None,i,j+1
            else:
                return None,i,j
        
        # Init
        n = len(firstList)
        m = len(secondList)
        output = []
        
        # Minimum conidition
        if n and m:
            
            # Indexes
            i = 0 # for firstList
            j = 0 # for secondList
            
            # Loop for each possiblilities till
            # both the indexes are valid
            while i < n and j < m:
                
                # get interval at index i of firstList
                x = firstList[i]
                
                # get interval at index j of secondList
                y = secondList[j]
                
                # find common interval and increment indexes
                c,i,j = commonInterval(x,i,y,j)
                
                # If interval is not none, append to output
                if c: output.append(c)
       
        return output

