class Solution:
    def intervalIntersection(self, firstList: List[List[int]], secondList: List[List[int]]) -> List[List[int]]:
        i, j = 0, 0
        intersection = []
        
        while i < len(firstList) and j < len(secondList):
            start = max(firstList[i][0], secondList[j][0])
            end = min(firstList[i][1], secondList[j][1])
            
            if start <= end:
                intersection.append([start, end])
                
            if firstList[i][1] < secondList[j][1]:
                i += 1
            else:
                j += 1
                
        return intersection

class BSTIterator:
    def __init__(self, root: TreeNode):
        self.stack = []
        self.leftmost_inorder(root)

    def leftmost_inorder(self, node):
        while node:
            self.stack.append(node)
            node = node.left

    def hasNext(self) -> bool:
        return self.stack

    def next(self) -> int:
        node = self.stack.pop()
        if node.right:
            self.leftmost_inorder(node.right)
        return node.val

def choose_team(scores, ages):
    team = []
    for i in range(len(scores)):
        team.append((scores[i], ages[i]))
    team.sort(reverse=True)
    chosen = []
    for player in team:
        conflict = False
        for chosen_player in chosen:
            if chosen_player[1] < player[1] and chosen_player[0] > player[0]:
                conflict = True
                break
        if not conflict:
            chosen.append(player)
    return sum([player[0] for player in chosen])

