class Solution:
    def rightSideView(self, root: TreeNode) -> List[int]:
        
        if not root: return []
        
        res = []
        q = [root]
        
        while q:
            size = len(q)
            for i in range(size):
                if i == size-1: res.append(q[i].val)
                    
                if q[i].left: q.append(q[i].left)
                if q[i].right: q.append(q[i].right)
            
            q = q[size:]
            
        return res

def exclusiveTime(n: int, logs: List[str]) -> List[int]:
    stack = []
    exclusive_time = [0] * n
    prev_time = 0
    
    for log in logs:
        log_info = log.split(":")
        func_id, status, timestamp = int(log_info[0]), log_info[1], int(log_info[2])
        
        if status == "start":
            if stack:
                exclusive_time[stack[-1]] += timestamp - prev_time
            stack.append(func_id)
            prev_time = timestamp
        else:
            exclusive_time[stack.pop()] += timestamp - prev_time + 1
            prev_time = timestamp + 1
    
    return exclusive_time

