            hourglass_sums.append(hourglass_sum)
    return max(hourglass_sums)

def minCostPath(grid, moveCost):
    n = len(grid[0])
    memo = {}
    
    def helper(x, y):
        if x == len(grid) - 1:
            return grid[x][y]
        if (x, y) in memo:
            return memo[(x, y)]
        min_cost = float('inf')
        for i in range(n):
            if i != y and x+1 < len(grid):
                cost = moveCost[grid[x][y]*n+y][i] + helper(x+1, i)
                min_cost = min(min_cost, cost)
        memo[(x, y)] = min_cost + grid[x][y]
        return memo[(x, y)]
    
    res = float('inf')
    for i in range(n):
        res = min(res, helper(0, i))
    return res

