class Solution:
    def maxRepeating(self, sequence: str, word: str) -> int:
        # record the index of every match using kmp
        # then find the longest consecutive sequence (with diff = len(word))
        # this is not an easy problem
        
        def kmp_failure(p):
            m = len(p)
            f = [0] * m
            i = 1
            j = 0
            while i < m:
                if p[j] == p[i]:
                    f[i] = j+1
                    j += 1
                    i += 1
                elif j > 0:
                    j = f[j-1]
                else:
                    f[i] = 0
                    i += 1
            return f
        
        if len(word) > len(sequence):
            return 0
        
        m = len(word)
        n = len(sequence)
        f = kmp_failure(word)
        i = 0
        j = 0
        res = 0
        matches = dict()
        while i < n:
            if word[j] == sequence[i]:
                if j == m-1:
                    if i-m in matches:
                        matches[i] = matches[i-m] + 1
                    else:
                        matches[i] = 1
                    if matches[i] > res: 
                        res = matches[i]
                        
                    # note that you shouldn't just go j += 1 here!
                    # because you might skip a match
                    if j > 0:
                        j = f[j-1]
                    else:
                        i += 1
                    continue 
                    
                j += 1
                i += 1
            elif j > 0:
                j = f[j-1]
            else:
                i += 1
        
        return res

