import heapq

def minimumDeviation(nums):
    n = len(nums)
    pq = []
    for num in nums:
        if num % 2 == 0:
            heapq.heappush(pq, -num)
        else:
            heapq.heappush(pq, -num * 2)
    ans = float('inf')
    while True:
        a = -heapq.heappop(pq)
        ans = min(ans, a - pq[0])
        if a % 2 == 0:
            heapq.heappush(pq, -a // 2)
        else:
            break
    return ans

