def min_jumps(forbidden: List[int], a: int, b: int, x: int) -> int:
    forward, backward = set(), set()
    for i in forbidden:
        if i > x:
            backward.add(i)
        else:
            forward.add(i)
    queue = [(x, 0)]
    visited = set()
    visited.add((x, 0))
    while queue:
        pos, jumps = queue.pop(0)
        if pos == 0:
            return jumps
        if jumps % 2 == 0:
            nxt = pos - a
            if nxt not in backward and nxt >= 0 and (nxt, jumps+1) not in visited:
                queue.append((nxt, jumps+1))
                visited.add((nxt, jumps+1))
        else:
            nxt = pos + b
            if nxt not in forward and (nxt, jumps+1) not in visited:
                queue.append((nxt, jumps+1))
                visited.add((nxt, jumps+1))
    return -1

