def is_strictly_palindromic(n):
    for b in range(2, n):
        num_in_base_b = ''
        num = n
        while num > 0:
            num_in_base_b += str(num % b)
            num //= b
        if num_in_base_b != num_in_base_b[::-1]:
            return False
    return True

def findFarmland(land: List[List[int]]) -> List[List[int]]:
    groups = []
    for i in range(len(land)):
        for j in range(len(land[0])):
            if land[i][j] == 1:
                # Check if this farmland is part of an existing group
                foundGroup = False
                for group in groups:
                    if (i >= group[0] and i <= group[2] and j >= group[1] and j <= group[3]):
                        foundGroup = True
                        break
                if not foundGroup:
                    # Find the bottom right corner of the group
                    r2 = i
                    c2 = j
                    while(c2 < len(land[0]) and land[r2][c2] == 1):
                        c2 += 1
                    c2 -= 1
                    while(r2 < len(land) and land[r2][j] == 1):
                        r2 += 1
                    r2 -= 1
                    groups.append([i, j, r2, c2])
    return groups

def numFriendRequests(ages):
    def requestable(a, b):
        return not (b <= 0.5 * a + 7 or b > a or (b > 100 and a < 100))
    
    counts = [0] * 121
    for age in ages:
        counts[age] += 1

    res = 0
    for ageA in range(121):
        countA = counts[ageA]
        for ageB in range(ageA+1):
            countB = counts[ageB]
            if not requestable(ageA, ageB): continue
            res += countA * countB
            if ageA == ageB: res -= countA

    return res

