class Solution:
    def checkXMatrix(self, grid: List[List[int]]) -> bool:
        firstDiagnol = 0
        secondDiagnol = 0
        remaining = 0
        
        
        m, n = len(grid), len(grid[0])
        
        for i in range(m):
            if grid[i][i] != 0:
                firstDiagnol += 1
        
        for i in range(m):
            if grid[i][n - i - 1] != 0:
                secondDiagnol += 1
        
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 0:
                    remaining += 1
        
        if n%2 == 0:
            return firstDiagnol == n and secondDiagnol == n and remaining == (n**2 - 2*n)
        else:
            return firstDiagnol == n and secondDiagnol == n and remaining == (n**2 - (2*n - 1))

