def minFallingPathSum(grid):
    n = len(grid)
    dp = [[0 for _ in range(n)] for _ in range(n)]
    
    for j in range(n):
        dp[0][j] = grid[0][j]
    
    for i in range(1, n):
        for j in range(n):
            shifts = []
            if j > 0:
                shifts.append(dp[i-1][j-1])
            if j < n-1:
                shifts.append(dp[i-1][j+1])
            dp[i][j] = grid[i][j] + min(shifts)
    
    return min(dp[-1])

