def isIdealPermutation(nums):
    num_globals = 0
    num_locals = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] > nums[j]:
                num_globals += 1
                if j == i+1:
                    num_locals += 1
    return num_globals == num_locals

def closest_palindrome(n):
    def is_palindrome(x):
        return str(x) == str(x)[::-1]
    
    if int(n) < 10:
        return str(int(n) - 1)
    
    half_len = (len(n) + 1) // 2
    left_half = int(n[:half_len])
    
    candidate_nums = [left_half - 1, left_half, left_half + 1]
    
    if len(n) % 2 == 0:
        candidate_palindromes = [int(str(num) + str(num)[::-1]) for num in candidate_nums]
    else:
        candidate_palindromes = [int(str(num) + str(num)[:-1][::-1]) for num in candidate_nums]
        
    closest_palindrome = min(candidate_palindromes, key=lambda x: abs(int(n) - x) if x != int(n) else float('inf'))
    
    return str(closest_palindrome)

class Solution:
    def findBottomLeftValue(self, root: TreeNode) -> int:
        queue = [root]
        while queue:
            node = queue.pop(0)
            if node.right:
                queue.append(node.right)
            if node.left:
                queue.append(node.left)
        return node.val

