def max_students(seats: List[List[str]]) -> int:
    def can_seat(i, j, mask):
        if seats[i][j] == '#' or mask & (1 << j):
            return False
        if j > 0 and (mask & (1 << (j - 1))):
            return False
        if j < cols - 1 and (mask & (1 << (j + 1))):
            return False
        if i > 0 and j > 0 and (mask & (1 << (j - 1 - cols))):
            return False
        if i > 0 and j < cols - 1 and (mask & (1 << (j + 1 - cols))):
            return False
        return True
    
    rows, cols = len(seats), len(seats[0])
    dp = [0] * (1 << cols)
    
    for mask in range(1 << cols):
        count = 0
        for j in range(cols):
            if mask & (1 << j):
                count += 1
            
        for i in range(rows):
            if count > dp[mask]:
                dp[mask] = count
                
            valid = True
            for j in range(cols):
                if not can_seat(i, j, mask):
                    valid = False
                    break
            
            if valid:
                new_mask = 0
                for j in range(cols):
                    if mask & (1 << j):
                        continue
                    if can_seat(i, j, mask):
                        new_mask |= (1 << j)
                
                dp[new_mask] = max(dp[new_mask], dp[mask] + count)
                
    return max(dp)

