def subarraysDivByK(nums: List[int], k: int) -> int:
    count = 0
    prefix_sum = 0
    mod_counts = {0: 1}
    for num in nums:
        prefix_sum += num
        modulo = prefix_sum % k
        if modulo in mod_counts:
            count += mod_counts[modulo]
        mod_counts[modulo] = mod_counts.get(modulo, 0) + 1
    return count

