    prev2 = 1
    ans = 0
    for i in range(3, n+1):
        ans = (prev1 + prev2) % MOD
        ans = (ans + prev2) % MOD
        prev2 = prev1
        prev1 = ans
    count = 0
    for i in range(3):
        st = ["A", "L", "P"][i]
        if checkValid(st):
            count += 1
    for i in range(27):
        st = ""
        x = i
        for j in range(n):
            st += ["A", "L", "P"][x % 3]
            x //= 3
        if checkValid(st):
            count += 1
    return ans * count % MOD

