class Solution:
    def removeOuterParentheses(self, s: str) -> str:
        collect_primitives = []
        
        counter = 0
        start = 0
        end = 0 
        for i in range(0, len(s)):
            
            # When counter is 0, the expression is balanced. Either it indicates that a new primitive expression can start in the string, or indicates that a primtive expression has been examined. 
            if s[i] == "(":
                if counter == 0: # Mark the start of primitive expression.
                    start = i
                counter+=1
            elif s[i] == ")":
                counter-=1
                if counter == 0:
                    end = i  # Mark the end of primitive expression
            
            # Once a primitive expression has been read, slice the primitive expression. start plus one, because start index points to opening bracket of the pair which encloses a primitive expression. 
            if counter == 0:
                collect_primitives.append(s[start + 1:end])
                start = 0
                end = 0
        
            
        return "".join(collect_primitives)

