class Solution:
    def arrayChange(self, nums: List[int], operations: List[List[int]]) -> List[int]:
        # traverse from the end to the front!
        n = len(operations)
        dic = defaultdict()
        
        for i in range(n-1, -1, -1):
            key, value = operations[i]
            
            if value in dic:
                tmp = dic[value]
                del dic[value]
                dic[key] = tmp
                
            else:
                dic[key] = value
        
        for i, num in enumerate(nums):
            if num in dic:
                nums[i] = dic[num]
        
        return nums

