class Solution:
    def maxPathSum(self, root: Node) -> int:
        def maxSum(node):
            nonlocal max_sum
            if not node:
                return 0
            left = max(maxSum(node.left), 0)
            right = max(maxSum(node.right), 0)
            max_sum = max(max_sum, left + right + node.val)
            return max(left, right) + node.val
        max_sum = float('-inf')
        maxSum(root)
        return max_sum

