class Solution:
    def findSmallestHighestScore(self, n: int, edges: List[int], labels: str) -> int:
        graph = defaultdict(list)
        for i, j in edges:
            graph[i].append(j)
        node_scores = [0] * n
        visited = set()
        
        def dfs(node):
            visited.add(node)
            score = Counter()
            score[labels[node]] += 1
            for neighbor in graph[node]:
                if neighbor not in visited:
                    neighbor_score = dfs(neighbor)
                    score += neighbor_score
            node_scores[node] = score[labels[node]]
            return score
        
        for node in range(n):
            if node not in visited:
                dfs(node)
        
        max_score = float('-inf')
        res_node = n
        for node in range(n):
            if node_scores[node] > max_score:
                max_score = node_scores[node]
                res_node = node
            elif node_scores[node] == max_score:
                res_node = min(res_node, node)
        return res_node

