def has_repeated_digit(num):
    digits = set()
    while num > 0:
        digit = num % 10
        if digit in digits:
            return True
        digits.add(digit)
        num //= 10
    return False

def has_duplicate_digits(n):
    for i in range(1, n+1):
        if has_repeated_digit(i):
            return True
    return False

def find_smallest_integer_with_duplicate_digits(n):
    i = 1
    while i <= n:
        if has_repeated_digit(i):
            return i
        i += 1
    return -1

