def cut_trees_forest(matrix):
    trees = []
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] > 1:
                trees.append((i, j, matrix[i][j]))
    trees = sorted(trees, key=lambda x: x[2])
    steps = 0
    current_position = (0, 0)
    for tree in trees:
        path = bfs(matrix, current_position, (tree[0], tree[1]))
        if path is None:
            return -1
        steps += len(path)
        current_position = (tree[0], tree[1])
        matrix[tree[0]][tree[1]] = 1
    return steps

def bfs(matrix, start, end):
    queue = [(start, [start])]
    visited = set()
    while queue:
        vertex, path = queue.pop(0)
        if vertex == end:
            return path
        if vertex not in visited:
            visited.add(vertex)
            for neighbor in get_neighbors(matrix, vertex):
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))
    return None

def get_neighbors(matrix, vertex):
    i, j = vertex
    neighbors = []
    if i > 0 and matrix[i-1][j] != 0:
        neighbors.append((i-1, j))
    if j > 0 and matrix[i][j-1] != 0:
        neighbors.append((i, j-1))
    if i < len(matrix)-1 and matrix[i+1][j] != 0:
        neighbors.append((i+1, j))
    if j < len(matrix[0])-1 and matrix[i][j+1] != 0:
        neighbors.append((i, j+1))
    return neighbors

def reorder_string(s):
    sorted_str = ''.join(sorted(s))
    result = []
    i, j = 0, len(sorted_str) - 1
    last_appended_char = ""
    while i <= j:
        if (not last_appended_char or sorted_str[i] > last_appended_char) and sorted_str[i] not in result:
            result.append(sorted_str[i])
            last_appended_char = sorted_str[i]
            i += 1
        elif (not last_appended_char or sorted_str[j] < last_appended_char) and sorted_str[j] not in result:
            result.append(sorted_str[j])
            last_appended_char = sorted_str[j]
            j -= 1
        else:
            if sorted_str.count(sorted_str[i]) > sorted_str.count(sorted_str[j]):
                result.append(sorted_str[i])
                last_appended_char = sorted_str[i]
                i += 1
            else:
                result.append(sorted_str[j])
                last_appended_char = sorted_str[j]
                j -= 1
    return "".join(result)

def max_distance(grid):
    max_dist = -1
    land_cells = []
    water_cells = []
    n = len(grid)
    
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                land_cells.append((i,j))
            else:
                water_cells.append((i,j))

    if len(land_cells) == 0 or len(water_cells) == 0:
        return -1

    for water in water_cells:
        dist = n*n
        for land in land_cells:
            dist = min(dist, abs(water[0]-land[0]) + abs(water[1]-land[1]))
        max_dist = max(max_dist, dist)

    return max_dist

def merge_zeroes(head):
    if not head or not head.next:
        return head
    dummy = ListNode(0)
    dummy.next = head
    slow, fast = dummy, head
    while fast and fast.next:
        while fast and fast.val != 0:
            slow = slow.next
            fast = fast.next
        if not fast:
            break
        if fast.val == 0 and fast.next.val == 0:
            while fast and fast.next and fast.val == 0 and fast.next.val == 0:
                fast = fast.next
            temp = slow.next
            while temp != fast.next:
                slow.val += temp.val
                temp = temp.next
            slow.next = fast
        else:
            slow = slow.next
            fast = fast.next
    return dummy.next

