def shift_zeros(nums):
    n = len(nums)
    for i in range(n - 1):
        if nums[i] == nums[i + 1]:
            nums[i] *= 2
            nums[i + 1] = 0
    new_nums = [num for num in nums if num != 0]
    new_nums += [0] * (n - len(new_nums))
    return new_nums

def maxXor(nums: List[int], number: int) -> int:
    for i in range(number):
        max_num = max(nums)
        for j in range(len(nums)):
            if nums[j] == max_num:
                nums[j] = nums[j] ^ ((1 << (len(bin(max_num))-2))-1)
                break
    return max(nums)

