class Solution:
    def parseBoolExpr(self, expression: str) -> bool:
        """
        Recursive definition:
        Two types of input:
            1- op(args) -> return op[f(arg1), f(arg2), ...]
            2- arg -> return bool(arg)
        """
        def parse_args(expression):
            current_arg = ''
            open_count = 0
            args = []
            for c in expression:
                if c in {'f','t'}:
                    current_arg +=c
                    if open_count == 0:
                        args.append(current_arg)
                        current_arg = ''                
                if c in {'!','|','&amp;'}:
                    current_arg += c
                if c == ',' and open_count!=0:
                    current_arg +=c
                if c == '(':
                    current_arg += c
                    open_count +=1
                if c == ')':
                    current_arg +=c
                    open_count -= 1
                    if open_count == 0:
                        args.append(current_arg)
                        current_arg = ''
            return args
        
        bool_mp = {'f': False, 't': True}
        if len(expression) == 1:
            return bool_mp[expression]
        
        if expression[0] == '!':
            return not self.parseBoolExpr(expression[2:-1])
        
        if expression[0] == '|':
            args = parse_args(expression[2:-1])
            return any(self.parseBoolExpr(arg) for arg in args)
        
        if expression[0] == '&amp;':
            args = parse_args(expression[2:-1])
            return all(self.parseBoolExpr(arg) for arg in args)

