def evaluate_expression(expression):
    stack = []
    for char in expression:
        if char == 't':
            stack.append(True)
        elif char == 'f':
            stack.append(False)
        elif char == '!':
            sub_expr = stack.pop()
            result = not sub_expr
            stack.append(result)
        elif char == '&':
            sub_expr_list = []
            while stack[-1] != '&':
                sub_expr_list.append(stack.pop())
            stack.pop() # remove '&'
            result = all(sub_expr_list)
            stack.append(result)
        elif char == '|':
            sub_expr_list = []
            while stack[-1] != '|':
                sub_expr_list.append(stack.pop())
            stack.pop() # remove '|'
            result = any(sub_expr_list)
            stack.append(result)
    return stack.pop()

