class Solution:
    def mergeStones(self, stones: List[int], k: int) -> int:
        n = len(stones)
        if (n-1) % (k-1) != 0:
            return -1
        prefix_sum = [0]*(n+1)
        for i in range(n):
            prefix_sum[i+1] = prefix_sum[i] + stones[i]
        memo = {}
        def dfs(i, j, piles):
            if (i, j, piles) in memo:
                return memo[(i, j, piles)]
            if j - i + 1 == piles*k:
                memo[(i, j, piles)] = dfs(i, j, 1) + prefix_sum[j+1] - prefix_sum[i]
                return memo[(i, j, piles)]
            if piles == 1:
                memo[(i, j, piles)] = dfs(i, j, k) - prefix_sum[i] + prefix_sum[j+1]
                return memo[(i, j, piles)]
            ans = float('inf')
            for mid in range(i, j, k-1):
                ans = min(ans, dfs(i, mid, piles-1) + dfs(mid+1, j, 1))
            memo[(i, j, piles)] = ans
            return ans
        return dfs(0, n-1, 1)

