class Solution:
    def widthOfBinaryTree(self, root: TreeNode) -> int:
        if not root:
            return 0
        width = 1
        level = [(root,1)]
        while level:
            next_level = []
            width = max(width, level[-1][1]-level[0][1]+1)
            for node, pos in level:
                if node.left:
                    next_level.append((node.left, pos*2))
                if node.right:
                    next_level.append((node.right, pos*2+1))
            level = next_level
        return width

