def getValues(root):
    values = []
    def inorderTraversal(node):
        nonlocal values
        if node:
            inorderTraversal(node.left)
            values.append(node.val)
            inorderTraversal(node.right)
    inorderTraversal(root)
    return values

def balanceBST(root):
    values = getValues(root)
    return sortedListToBST(values)

