class Solution:
    def minimumXORSum(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        
        @cache 
        def fn(mask, k): 
            """Return min xor sum."""
            if not mask: return 0 
            ans = inf 
            for i in range(n): 
                if mask &amp; (1<<i): 
                    ans = min(ans, (nums1[i]^nums2[k]) + fn(mask^(1<<i), k+1))
            return ans 
        
        return fn((1<<n)-1, 0)

GPT Answer:
def minimumXORSum(nums1: List[int], nums2: List[int]) -> int:
    n = len(nums1)
    dp = [[float('inf')] * (1 << n) for _ in range(n)]

    def solve(cur: int, mask: int) -> int:
        if mask == (1 << n) - 1:
            return 0
        if dp[cur][mask] != float('inf'):
            return dp[cur][mask]
        for j in range(n):
            if not mask & (1 << j):
                dp[cur][mask] = min(
                    dp[cur][mask],
                    solve(cur + 1, mask | (1 << j)) + (nums1[cur] ^ nums2[j])
                )
        return dp[cur][mask]

    return solve(0, 0)

