class Solution:
    def bitwiseComplement(self, n: int) -> int:
        # convert int to a binary textual representation without the 0b-prefix
        get_binary = lambda n: format(n, 'b')
        input_b = get_binary(n) #e.g.,'101'
        
        # get output in binary representation
        output_b = ""
        for i in input_b:
            if i == "1":
                output_b += "0"
            else: 
                output_b += "1"
        
        # convert output from binary to int 
        get_int = lambda n: int(n, 2) #binary base 2
        result = get_int(output_b)
        
        return result

