def copyRandomList(head):
    if not head:
        return None
    
    visited = {}
    
    def helper(node):
        if not node:
            return None
        if node in visited:
            return visited[node]
        new_node = Node(node.val, None, None)
        visited[node] = new_node
        new_node.next = helper(node.next)
        new_node.random = helper(node.random)
        return new_node
    
    return helper(head)

