def arrange_sentence(sentence):
    sentence = sentence.split()
    sentence.sort(key=len)
    sentence[-1] = sentence[-1].replace(".", "")
    sentence[0] = sentence[0].capitalize()
    for i in range(len(sentence)):
        if i == len(sentence)-1:
            sentence[i] = sentence[i] + "."
        elif len(sentence[i]) == len(sentence[i+1]):
            continue
        else:
            sentence[i] = sentence[i] + " "
    return "".join(sentence)

def findAnagrams(p: str, s: str) -> List[int]:
    result = []
    p_len = len(p)
    s_len = len(s)
    if p_len > s_len:
        return result
    p_count = [0] * 26
    s_count = [0] * 26
    for i in range(p_len):
        p_count[ord(p[i]) - ord('a')] += 1
        s_count[ord(s[i]) - ord('a')] += 1
    if p_count == s_count:
        result.append(0)
    for i in range(p_len, s_len):
        s_count[ord(s[i]) - ord('a')] += 1
        s_count[ord(s[i - p_len]) - ord('a')] -= 1
        if p_count == s_count:
            result.append(i - p_len + 1)
    return result

