import itertools

def latestTime(arr):
    perms = itertools.permutations(arr)
    valid_times = []
    for perm in perms:
        hours = 10*perm[0] + perm[1]
        mins = 10*perm[2] + perm[3]
        if hours < 24 and mins < 60:
            valid_times.append(f"{hours:02}:{mins:02}")
    if valid_times:
        return max(valid_times)
    else:
        return ""

