def shortestSubsequence(str1, str2):
    def allSubsequences(s):
        n = len(s)
        subs = set()
        for i in range(2**n):
            sub = ''
            for j in range(n):
                if i & (1 << j):
                    sub += s[j]
            subs.add(sub)
        return list(subs)

    subs1 = allSubsequences(str1)
    subs2 = allSubsequences(str2)

    shortest = float('inf')
    shortestSubs = []
    for sub1 in subs1:
        for sub2 in subs2:
            combined = sub1 + sub2
            if len(combined) < shortest:
                shortest = len(combined)
                shortestSubs = [combined]
            elif len(combined) == shortest:
                shortestSubs.append(combined)

    return shortestSubs

