def max_operations(s):
    max_ops = 0
    for i in range(1, len(s) // 2 + 1):
        j = 0
        ops = 0
        while j <= len(s) - 2 * i:
            if s[j:j+i] == s[j+i:j+2*i]:
                ops += 1
                j += 2 * i
            else:
                j += 1
        max_ops = max(max_ops, ops)
    return max_ops

