def shortestPath(grid):
    from collections import deque
    
    keys = {chr(i): None for i in range(ord('a'), ord('a')+26)}
    locks = {chr(i): None for i in range(ord('A'), ord('A')+26)}
    
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '@':
                start = (i,j)
            elif grid[i][j] in keys:
                keys[grid[i][j]] = (i,j)
            elif grid[i][j] in locks:
                locks[grid[i][j]] = (i,j)
    
    q = deque([(start[0], start[1], '')])
    visited = set()
    while q:
        x, y, k = q.popleft()
        if (x,y,k) in visited:
            continue
        visited.add((x,y,k))
        for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
            nx, ny = x+dx, y+dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                if grid[nx][ny] == '#':
                    continue
                elif grid[nx][ny] in keys:
                    nk = ''.join(sorted(k+grid[nx][ny]))
                    q.append((nx, ny, nk))
                elif grid[nx][ny].islower() or grid[nx][ny] == '.':
                    q.append((nx, ny, k))
                elif grid[nx][ny].isupper():
                    if grid[nx][ny].lower() in k:
                        q.append((nx, ny, k))
                    else:
                        continue
                elif grid[nx][ny] == '@':
                    continue
                if all(keys[l] is not None for l in k):
                    return len(k)
    
    return -1

