class Solution:
    def reverseWords(self, s: str) -> str:
        chars = [ch for ch in s]
        start, end, N = 0, 0, len(chars)
        
        # 0. While both <start> and <end> within range
        while start < N and end < N:
            # 1. Get <start> to the first valid char
            while chars[start] == ' ':
                start += 1
            # 2. Start <end> immediately after <start>
            end = start + 1
            # 3. Move <end> until either past last char or reached whitespace (invalid char)
            while end < N and chars[end] != ' ':
                end += 1
            # 4. Send chars[<start>:<end>-1] to helper <reverse()> function
            self.reverse(chars, start, end-1)
            # 5. Reset <start> to immediately after <end>
            start = end + 1

        return ''.join(chars)
        
    def reverse(self, chars, lo, hi):
        while lo <= hi:
            chars[lo], chars[hi] = chars[hi], chars[lo]
            lo, hi = lo + 1, hi - 1

