from collections import defaultdict
from functools import lru_cache

def frog_positions(n, edges, target):
    graph = defaultdict(set)
    for a, b in edges:
        graph[a].add(b)
        graph[b].add(a)
        
    @lru_cache(None)
    def dfs(curr, time):
        if curr == target:
            return 1 if time > 0 else 0
        if time == 0:
            return 0
        
        total_prob = 0
        num_neighbors = len(graph[curr])
        for neighbor in graph[curr]:
            total_prob += dfs(neighbor, time-1) / num_neighbors
        total_prob += dfs(curr, time-1) / num_neighbors
        return total_prob
        
    return dfs(1, n)

