def awesome_substring(s):
    max_len = 0
    for i in range(len(s)):
        for j in range(i+1, len(s)+1):
            sub = s[i:j]
            if len(sub) <= max_len:
                continue
            swaps = sum(1 for x,y in zip(sub, sub[::-1]) if x != y) // 2
            if swaps == 0 and len(sub) > max_len:
                max_len = len(sub)
            elif swaps > 0 and len(sub) - swaps > max_len:
                sub_list = list(sub)
                for k in range(len(sub_list)//2):
                    if swaps == 0:
                        break
                    if sub_list[k] != sub_list[len(sub_list)-1-k]:
                        sub_list[k] = sub_list[len(sub_list)-1-k]
                        swaps -= 1
                if is_palindrome(''.join(sub_list)) and len(sub) > max_len:
                    max_len = len(sub)
    return max_len

