        nums.sort()
        ind = 0
        tup = (None, None)
        ans = 0
        while(ind < len(nums)):
            st = None
            if tup[0] is not None:
                st = tup[0]
                while(st <= ind):
                    if nums[ind] - nums[st] > 1:
                        st += 1
                    else:
                        break
            start = st if st is not None else ind
