class Solution:
    def goodDaysToRobBank(self, sec: List[int], time: int) -> List[int]:
        result = []
        
        n = len(sec) - 1
        
        if time == 0:
            copied = sec
            copied.sort()
            if copied == sec:
                return list(range(n+1))
        
        if n <= time:
            return
        
        else:
            t = time
            while t - time >= 0 and t + time <= n:
                temp = time
                s = t - time
                u = t + time
                flag = True
				
                while temp:
                    if sec[s] < sec[s+1]:
                        flag = False
                        break
                    else:
                        s += 1
        
                    if sec[u] < sec[u-1]:
                        flag = False
                        break
                    else:
                        u -= 1
						
                    temp -= 1
					
                if flag == True:
                    result.append(t)
                t += 1
        
        return result

