def calculate_tax(brackets, income):
    tax = 0
    previous_bracket_upper = 0
    
    for i in range(len(brackets)):
        bracket = brackets[i]
        bracket_upper = bracket[0]
        bracket_percent = bracket[1]
        
        if income <= bracket_upper:
            taxable_income = income - previous_bracket_upper
            tax += taxable_income * bracket_percent
            break
        
        else:
            taxable_income = bracket_upper - previous_bracket_upper
            tax += taxable_income * bracket_percent
            previous_bracket_upper = bracket_upper
    
    return round(tax, 5)

