def latest_arrival_time(buses, passengers, capacity):
    buses.sort()
    passengers.sort()
    bus_idx, pass_idx = 0, 0
    while bus_idx < len(buses) and pass_idx < len(passengers):
        if passengers[pass_idx] <= buses[bus_idx]:
            pass_idx += 1
        elif pass_idx - bus_idx * capacity >= capacity:
            bus_idx += 1
        else:
            pass_idx += (capacity - pass_idx % capacity)
    return passengers[pass_idx - 1] if pass_idx % capacity == 0 else buses[-1]

def max_income(n, edges, amount):
    tree = [[] for _ in range(n)]
    for a, b in edges:
        tree[a].append(b)
        tree[b].append(a)
        
    def dfs(node, parent):
        if node == 0:
            return 0
        
        max_profit = amount[node]
        for child in tree[node]:
            if child != parent:
                profit = dfs(child, node)
                if profit >= 0:
                    max_profit += profit
        
        return max_profit
    
    return dfs(1, 0)

