class Solution:
    def binarysearch(self,arr):
        l,r = 0,len(arr)
        while(l<=r and l<len(arr) and r>=0):
            m = (l+r)//2
            if m == len(arr)-1:
                if arr[m] == 1:
                    return len(arr)
                else:
                    r = m-1
            elif arr[m] == 0:
                r = m-1
            
            elif arr[m] == 1:
                if arr[m+1] == 0:
                    return m+1
                else:
                    l = m+1
        return 0
    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:
        d = {}
        for i in range(len(mat)):
            count = self.binarysearch(mat[i])
            if count in d:
                d[count].append([mat[i],i])
            
            else:
                d[count] = [[mat[i],i]]
                
        output = []
        for i in sorted(d.keys()):
            for j in range(len(d[i])):
                output.append(d[i][j][1])
                
                if len(output)==k:
                    break
            if len(output)==k:
                    break
        return output

