class Solution:
    def reorderSpaces(self, text: str) -> str:
        space = 0
        # Count number of spaces
        for char in list(text):
            if char ==' ':
                space += 1
                
        words = text.split()
        num_words = len(words)
        # Count number of spaces after each word
        spaces_per_word = space // (num_words-1) if num_words > 1 else num_words
        output = []
        
        # Append the words, followed by the spaces (also keep a count of the number of spaces reduced)
        for idx in range(len(words)-1):
            output.append(words[idx])
            for _ in range(spaces_per_word):
                output.append(' ')
                space -= 1
                
        # Append the last word followed by the remaining spaces
        if len(words) > 0:
            output.append(words[-1])
        while space > 0:
            output.append(' ')
            space -= 1
        
        # Return the string
        return ''.join(output)

