import heapq

def minTimeToCompleteTrips(time, totalTrips):
    heap = []
    for t in time:
        heapq.heappush(heap, t)    
    while len(heap) > totalTrips:
        t1 = heapq.heappop(heap)
        t2 = heapq.heappop(heap)
        heapq.heappush(heap, t1 + t2)
    return sum(heap)

