def count_wonderful_substrings(word):
    count = 0
    for i in range(len(word)):
        for j in range(i+1, len(word)+1):
            sub_string = word[i:j]
            freq = [0] * 10
            for letter in sub_string:
                freq[ord(letter) - ord('a')] += 1
            odd_count = 0
            for f in freq:
                if f % 2 != 0:
                    odd_count += 1
            if odd_count <= 1:
