def shortestPathBinaryMatrix(grid):
    n = len(grid)
    if grid[0][0] == 1 or grid[n-1][n-1] == 1:
        return -1
    queue = [(0,0,1)]
    visited = set((0,0))
    while queue:
        x, y, dist = queue.pop(0)
        if x == n-1 and y == n-1:
            return dist
        for dx, dy in [(1,1), (1,0), (0,1), (-1,-1), (-1,0), (0,-1), (1,-1), (-1,1)]:
