            if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 0 and (nx,ny) not in visited:
                visited.add((nx,ny))
                queue.append((nx,ny,dist+1))
    return -1

def get_maximum_sum_paths(board):
    MOD = 1000000007
    
    n = len(board)
    m = len(board[0])

    # function to check if a cell is valid
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and board[x][y] != 'X'

    # initialize the dp table
    dp = [[(0, []) for j in range(m)] for i in range(n)]

    # initialize the starting point
    dp[n-1][m-1] = (0 if board[n-1][m-1] == 'X' else int(board[n-1][m-1]), [[n-1, m-1]])

    # populate the dp table
    for i in range(n-1, -1, -1):
        for j in range(m-1, -1, -1):
            if board[i][j] == 'X':
                continue
            if is_valid(i-1, j-1):
                val = int(board[i][j]) + dp[i-1][j-1][0]
                if val > dp[i][j][0]:
                    dp[i][j] = (val, [[i, j]] + dp[i-1][j-1][1])
                elif val == dp[i][j][0]:
                    dp[i][j][1] += [[i, j]] + dp[i-1][j-1][1]
            if is_valid(i-1, j):
                val = int(board[i][j]) + dp[i-1][j][0]
                if val > dp[i][j][0]:
                    dp[i][j] = (val, [[i, j]] + dp[i-1][j][1])
                elif val == dp[i][j][0]:
                    dp[i][j][1] += [[i, j]] + dp[i-1][j][1]
            if is_valid(i, j-1):
                val = int(board[i][j]) + dp[i][j-1][0]
                if val > dp[i][j][0]:
                    dp[i][j] = (val, [[i, j]] + dp[i][j-1][1])
                elif val == dp[i][j][0]:
                    dp[i][j][1] += [[i, j]] + dp[i][j-1][1]

    # calculate the result
    result = dp[0][0]
    if result[0] == 0:
        return [0, 0]
    paths = []
    for path in result[1]:
        tmp = ''
        for p in path:
            tmp += str(p[0]) + ',' + str(p[1]) + ';'
        paths.append(tmp[:-1])
    return [result[0], len(set(paths)) % MOD]

