class Solution:
    # Recursive: T = O(log N) and S = O(log N) for stack created recursively
    def searchBST(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:
        if not root: return None

        # if target value matched, return root    
        if root.val == val: return root

        # if target val is smaller, check in left subtree
        if val < root.val:
            return self.searchBST(root.left, val)
        
        # else check in right sub tree
        return self.searchBST(root.right, val)

    # Iterative: T = O(log N) and S = O(1)
    def searchBST(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:
        while root:
            if root.val == val:
                return root

            # go left if target val is less than cur val, else go right
            root = root.left if val < root.val else root.right

        return None

