import heapq

def findLowestCost(n, quality, wage, k):
    workers = sorted([(wage[i]/quality[i], quality[i], wage[i]) for i in range(n)])
    heap = []
    sumq = 0
    res = float("inf")
    for r, q, w in workers:
        sumq += q
        heapq.heappush(heap, -q)
        if len(heap) > k: 
            sumq += heapq.heappop(heap)
        if len(heap) == k: 
            res = min(res, r * sumq)
    return round(res,5)

