MOD = 10**9 + 7

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            return False
    return True

def beautiful_partitions(s, k, minLength):
    dp = [[0]*(len(s)+1) for i in range(k+1)]
    dp[0][0] = 1
    for i in range(1, k+1):
        for j in range(minLength, len(s)+1):
            for l in range(minLength-1, j):
                if is_prime(int(s[l])) and not is_prime(int(s[j-1])):
                    dp[i][j] += dp[i-1][l]
                    dp[i][j] %= MOD
    return dp[k][len(s)]

