class Solution:
    def minimumSize(self, nums: List[int], maxOperations: int) -> int:
        def countOperations(mid: int) -> int:
            count = 0
            for num in nums:
                count += (num - 1) // mid
            return count
    
        left, right = 1, max(nums)
        while left < right:
            mid = (left + right) // 2
            if countOperations(mid) > maxOperations:
                left = mid + 1
            else:
                right = mid
        return left

def largest_variance(s):
    counts = [[0] * 26]
    for i, c in enumerate(s):
        count = counts[i].copy()
        count[ord(c) - ord('a')] += 1
        counts.append(count)

    max_diff = 0
    for i in range(len(s)):
        for j in range(i+1, len(s)):
            count = [counts[j+1][k] - counts[i][k] for k in range(26)]
            count.sort(reverse=True)
            diff = count[0] - count[1]
            if diff > max_diff:
                max_diff = diff

    return max_diff

