def toHex(num):
    if num == 0:
        return "0"
    elif num < 0:
        num = 2**32 + num
    hex_chars = "0123456789abcdef"
    hex_str = ""
    while num > 0:
        hex_str = hex_chars[num % 16] + hex_str
        num = num // 16
    return hex_str

def count_good_nodes(root: TreeNode, X: int) -> int:
    count = 0
    stack = [(root, float('-inf'))]
    while stack:
        node, max_val = stack.pop()
        if node.val >= max_val and node.val >= X:
            count += 1
        if node.left:
            stack.append((node.left, max(node.val, max_val)))
        if node.right:
            stack.append((node.right, max(node.val, max_val)))
    return count

