class Solution:
    def getNumberOfBacklogOrders(self, orders: List[List[int]]) -> int:
        backlog = defaultdict(list)
        for price, amount, ordertype in orders:
            #sell
            if ordertype == 1:
                if backlog[0]:
                    condition = True
                    while condition and backlog[0]:
                        bp, ba = heapq.heappop(backlog[0])
                        if -bp >= price:
                            if amount < ba:
                                ba -= amount
                                amount = 0
                                heapq.heappush(backlog[0], [bp, ba])
                                condition = False
                            elif amount > ba:
                                amount -=ba 
                            else:
                                amount = 0
                        else:
                            heapq.heappush(backlog[0], [bp,ba])
                            heapq.heappush(backlog[1], [price, amount])
                            amount = 0
                            condition = False
                    if amount:
                        heapq.heappush(backlog[1], [price, amount])
                else:
                    heapq.heappush(backlog[1], [price, amount])
            #buy
            if ordertype == 0:
                if backlog[1]:
                    condition = True
                    while condition and backlog[1]:
                        sp, sa = heapq.heappop(backlog[1])
                        if sp <= price:
                            if amount < sa:
                                sa -= amount
                                amount = 0
                                heapq.heappush(backlog[1], [sp, sa])
                                condition = False
                            elif amount > sa:
                                amount -=sa
                            else:
                                amount = 0
                        else:
                            heapq.heappush(backlog[1], [sp, sa])
                            heapq.heappush(backlog[0], [-price, amount])
                            amount = 0
                            condition = False
                    if amount:
                        heapq.heappush(backlog[0], [-price, amount])
                else:
                    heapq.heappush(backlog[0], [-price, amount])
            #print(backlog[0], backlog[1])
        res = 0
        for i,j in backlog[0]:
            res += j
        for i,j in backlog[1]:
            res += j
        return res % (10**9 + 7)

