class Solution:
    def getNumberOfBacklogOrders(self, orders: List[List[int]]) -> int:
        buy_orders = []  # stores all the buy orders
        sell_orders = []  # stores all the sell orders
        for order in orders:
            price, amount, order_type = order
            if order_type == 0:  # buy order
                while amount > 0 and sell_orders and sell_orders[0][0] <= price:
                    # if a sell order exists with price less than or equal to current buy order price
                    # then execute the trade and remove the sell order
                    if amount >= sell_orders[0][1]:
                        amount -= sell_orders[0][1]
                        sell_orders.pop(0)
                    else:
                        sell_orders[0][1] -= amount
                        amount = 0
                if amount > 0:
                    # if there are still remaining orders, then add the buy order to the backlog
                    bisect.insort(buy_orders, [price, amount])
            else:  # sell order
                while amount > 0 and buy_orders and buy_orders[-1][0] >= price:
                    # if a buy order exists with price greater than or equal to current sell order price
                    # then execute the trade and remove the buy order
                    if amount >= buy_orders[-1][1]:
                        amount -= buy_orders[-1][1]
                        buy_orders.pop()
                    else:
                        buy_orders[-1][1] -= amount
                        amount = 0
                if amount > 0:
                    # if there are still remaining orders, then add the sell order to the backlog
                    bisect.insort(sell_orders, [price, amount])
        return sum(order[1] for order in buy_orders+sell_orders) % (10**9+7)

