    for word in words:
        if word[0] not in word_dict:
            word_dict[word[0]] = []
        word_dict[word[0]].append(word)
    count = 0
    for c in s:
        if c in word_dict:
            words_with_c = word_dict[c]
            word_dict[c] = []
            for word in words_with_c:
                if is_subsequence(word, s):
                    count += 1
                else:
                    if len(word) > 1:
                        if word[1] not in word_dict:
                            word_dict[word[1]] = []
                        word_dict[word[1]].append(word[1:])
    return count

