def countPairs(root: TreeNode, distance: int) -> int:
        
        def dfs(node):
            if not node:
                return []
            if not node.left and not node.right:
                return [0]
            left, right = dfs(node.left), dfs(node.right)
            for i in range(len(left)):
                left[i] += 1
            for i in range(len(right)):
                right[i] += 1
            res = []
            for l in left:
                for r in right:
                    if l + r <= distance:
                        res.append(l + r)
            return res
        
        res = dfs(root)
        return len([x for x in res if x <= distance])

