class Solution:
    def create_prefix_sum(self, result):
        def get_prefix_sum(arr):
            n = len(arr)
            prefix_sum = [0] * (n + 1)
            for i in range(1, n + 1):
                prefix_sum[i] = prefix_sum[i - 1] + arr[i - 1]
            return prefix_sum

        A = []
        for r in result:
            if 's' in r:
                A.append(1)
            else:
                A.append(-1)
        output = get_prefix_sum(A)
        return output
        
    
    def fullBloomFlowers(self, intervals: List[List[int]], persons: List[int]) -> List[int]:
        result = [] 
        sort_first = sorted(intervals, key=lambda interval: interval[0]) 
        sort_second = sorted(intervals, key=lambda interval: interval[1])	 
        
        for i in range(0, len(intervals)): 
            result.append(str(sort_first[i][0]) + 's') 
            result.append(str(sort_second[i][1]+1) + 'e') 
        
        result = sorted(result, key=lambda word:int("".join(c for c in word if c.isdigit()))) 
        PS = self.create_prefix_sum(result)
        result = [int(c.rstrip(c[-1])) for c in result]
        res = []
        for p in persons:
            idx = bisect_right(result, p)
            res.append(PS[idx])
        return res

class Solution:
    def goodTriplets(self, nums1: List[int], nums2: List[int]) -> int:
        N = len(nums1)
        BIT = [0] * (N+1)
        nums = [0] * N
        num1 = [0] * N
        num2 = [0] * N
        for i, n in enumerate(nums1):
            num1[n]=i
        for i, n in enumerate(nums2):
            num2[n]=i
        for i, n in enumerate(num1):
            nums[n] = num2[i]
        def lowbit(i):
            return i&amp;(-i)
        def add(i):
            i+=1
            while i <= N:
                BIT[i]+=1
                i+=lowbit(i)
        def query(i):
            i += 1
            re = 0
            while i:
                re += BIT[i]
                i -= lowbit(i)
            return re
        smaller = []
        bigger = []
        for i, n in enumerate(nums):
            smaller.append(query(n))
            bigger.append(N-1-i-n+smaller[-1])
            add(n)
        return sum(i*j for i, j in zip(smaller, bigger))

