class Solution:
    def __init__(self):
        self.modeCount = 0
        self.currCount = 0
        self.lastVal = None
        self.modes = []
    def findMode(self, root):
        """
        :type root: TreeNode
        :rtype: List[int]
        """
        self.traverse(root)
        return self.modes
    
    def traverse(self, node):
        if node is None:
            return
        self.traverse(node.left)
        if self.lastVal is None or self.lastVal != node.val:
            self.currCount = 1
            self.lastVal = node.val
        else:
            self.currCount += 1
        if self.currCount > self.modeCount:
            self.modeCount = self.currCount
            self.modes = [node.val]
        elif self.currCount == self.modeCount:
            self.modes.append(node.val)
        self.traverse(node.right)

