def find_length(k):
    if k == 1:
        return 1
    elif k % 2 == 0 or k % 5 == 0:
        return -1
    else:
        remainder = 1 % k
        length = 1
        while remainder != 0:
            remainder = (10 * remainder + 1) % k
            length += 1
        return length

