class Solution:
    def minimumTotalDistance(self, robot: List[int], factory: List[List[int]]) -> int:        
        robot.sort()
        factory.sort()
        cap = []
        for x, limit in factory:
            cap.extend([x] * limit)
        m = len(robot)
        n = len(cap)
        indices = list(range(m))
        ans = sum(abs(x - y) for x, y in zip(robot, cap))
        
        def increment(i):
            diff = 0
            while i < m:
                if indices[i] + 1 < n:
                    diff -= abs(robot[i] - cap[indices[i]])
                    diff += abs(robot[i] - cap[indices[i] + 1])
                else:
                    return math.inf, i + 1
                if i + 1 < m and indices[i] + 1 == indices[i + 1]:
                    i += 1
                else:
                    return diff, i + 1
        for i in reversed(range(m)):
            while True:
                diff, j = increment(i)
                if diff <= 0:
                    ans += diff
                    for x in range(i, j):
                        indices[x] += 1
                else:
                    break
        return ans

class Solution:
    def minimumFinishTime(self, tires: List[List[int]], changeTime: int, numLaps: int) -> int:
        @cache
        def lapTime(tire,x):
            f,r = tire
            return f*(r**(x-1))
        
        best_laps = {}
        
        for tire in tires:
            tire = tuple(tire)
            time = 0
            # stop at max time for a tire without changing
            for i in range(1,1001):
                currtime = lapTime(tire,i)
                if currtime >= lapTime(tire,1)+changeTime:
                    break
                time += currtime
                
                # update dictionary
                if i in best_laps:
                    best_laps[i] = min(best_laps[i],time+changeTime)
                else:
                    best_laps[i] = time+changeTime
        
        # dynamic programming
        dp = [float('inf') for _ in range(numLaps)]
        for i in range(numLaps):
            # if could get lap i using a single tire
            if i+1 in best_laps:
                dp[i] = best_laps[i+1]
                
            # or get lap i changing from last tire
            for k,v in best_laps.items():
                if i-k>=0:
                    dp[i] = min(dp[i], dp[i-k]+v)
        
		# subtract change time because first tire doesn't need to change
        return dp[numLaps-1] - changeTime

