def minTime(tires, changeTime, numLaps):
    dp = [[float('inf') for _ in range(numLaps+1)] for _ in range(len(tires))]
    for i in range(len(tires)):
        dp[i][0] = 0
    for lap in range(1, numLaps+1):
        for i in range(len(tires)):
            for j in range(len(tires)):
                currTime = tires[i][0]*tires[i][1]*(lap-1) + changeTime
                if i == j:
                    dp[i][lap] = min(dp[i][lap], dp[j][lap-1]+currTime)
                else:
                    dp[i][lap] = min(dp[i][lap], dp[j][lap-1]+currTime+tires[j][0]*tires[j][1]*(lap-1))
    return min(dp[i][-1] for i in range(len(tires)))

