import heapq

def kSmallestPairs(nums1, nums2, k):
    heap = []
    for i in nums1:
        for j in nums2:
            pair_sum = i + j
            pair = (pair_sum, (i, j))
            heapq.heappush(heap, pair)
    pairs = []
    for _ in range(min(k, len(heap))):
        pairs.append(heapq.heappop(heap)[1])
    return pairs

