# Runtime: 128ms 26.36% || Memory: 14.4mb 6.60%
    def solTwo(self, nums):
        n = len(nums)
        
        hashMap = {}
        
        for i in range(len(nums)):
            for j in range(len(nums[i])):
                num = nums[i][j]
                hashMap[num] = hashMap.get(num, 0) + 1
                
        return sorted([key for key in hashMap.keys() if hashMap[key] >= n])

