from collections import defaultdict

def max_sum_path(n: int, values: List[int], edges: List[List[int]], maxTime: int) -> int:
    graph = defaultdict(list)
    for u, v, t in edges:
        graph[u].append((v, t))
        graph[v].append((u, t))
    
    dp = [[0]*n for _ in range(maxTime+1)]
    dp[0][0] = values[0]
    ans = values[0]
    
    for t in range(maxTime):
        for u in range(n):
            for v, w in graph[u]:
                if t + w <= maxTime:
                    dp[t+w][v] = max(dp[t+w][v], dp[t][u] + values[v])
                    ans = max(ans, dp[t+w][v])
    
    return ans

