def maxCompatibilitySum(students: List[List[int]], mentors: List[List[int]]) -> int:
    def score(student: List[int], mentor: List[int]) -> int:
        return sum([1 for i in range(len(student)) if student[i] == mentor[i]])
    def dfs(students: List[List[int]], mentors: List[List[int]], curr: int, memo: Dict[Tuple[Tuple[int, ...], Tuple[int, ...]], int]) -> int:
        if curr == len(students):
            return 0
        key = (tuple(students[curr]), tuple(mentors[0]))
        if key in memo:
            return memo[key]
        ans = 0
        for mentor in mentors:
            ans = max(ans, score(students[curr], mentor) + dfs(students, [m for m in mentors if m != mentor], curr+1, memo))
        memo[key] = ans
        return ans
    return dfs(students, mentors, 0, {})

