class Solution:
    def minAbsoluteSumDiff(self, nums1: List[int], nums2: List[int]) -> int:
	   ## Sort the array to prepare for binary search
        snums1 = sorted(nums1)
        
        ## Binary search solution for finding the closest value based on absolute difference is picked up as block from here (since already exists). 
        ## https://tutorialspoint.dev/algorithm/divide-and-conquer/find-closest-number-array
        def find_closest_abs_diff(arr, n, target):
            if (target <= arr[0]): 
                return arr[0] 
            if (target >= arr[n - 1]): 
                return arr[n - 1] 

            i = 0; j = n; mid = 0
            while (i < j):  
                mid = (i + j) // 2

                if (arr[mid] == target): 
                    return arr[mid] 

                if (target < arr[mid]) : 
                    if (mid > 0 and target > arr[mid - 1]): 
                        return getClosest(arr[mid - 1], arr[mid], target) 
                    j = mid 
                else : 
                    if (mid < n - 1 and target < arr[mid + 1]): 
                        return getClosest(arr[mid], arr[mid + 1], target) 

                    i = mid + 1

            return arr[mid] 

        def getClosest(val1, val2, target): 
            if (target - val1 >= val2 - target): 
                return val2 
            else: 
                return val1 
            
        
        ## Find absolute difference values of array's 
        absdiffarr = [abs(nums1[idx] - nums2[idx]) for idx in range(len(nums1))]
        
        ## Find the sum of absolute differences, we are trying to minimize this value.
        absdiff = sum(absdiffarr)
        
        output = float('inf')
        
        ## go over the arrays and find the value that can be replaced to minimize absolute difference.
        for idx in range(len(nums1)):
            change = find_closest_abs_diff(snums1, len(nums1), nums2[idx])
            ## remove the current absolute difference at index and check for minimized value, 
            ## if we replace that with the closest value found in the array. 
            output = min(output, absdiff-absdiffarr[idx]+(abs(change - nums2[idx])))
                    
        return output % (10**9+7)

class Solution:
    def __init__(self):
        self.heap=[]
        self.capacity=0
        self.length=0

    def findKthLargest(self, nums: List[int], k: int) -> int:
        self.capacity=len(nums)
        self.heap=[0]*self.capacity
        
        for i in nums:
            self.heap[self.length] = i
            self.length += 1
            self.fixUp(self.length - 1)
        
        for i in range(k):
            item=self.remove_heap()
        return item
    
    def remove_heap(self):
        self.heap[0],self.heap[self.length-1]=self.heap[self.length-1],self.heap[0]
        item = self.heap.pop()
        self.length-=1
        self.fixDown(0)
        return item
    
    def fixDown(self, index):
        leftIdx = (2*index) + 1
        rightIdx=(2*index) +2
        
        largerIdx=index
        
        if leftIdx< self.length and self.heap[largerIdx]<self.heap[leftIdx]:
            largerIdx=leftIdx
        if rightIdx < self.length and self.heap[largerIdx]<self.heap[rightIdx]:
            largerIdx=rightIdx
            
        if index!=largerIdx:
            self.heap[index], self.heap[largerIdx]=self.heap[largerIdx], self.heap[index]
            self.fixDown(largerIdx)
            
    def fixUp(self,index):
        parentIdx=(index-1)//2
        if parentIdx>=0 and self.heap[parentIdx]<self.heap[index]:
            self.heap[parentIdx], self.heap[index] = self.heap[index], self.heap[parentIdx]
            self.fixUp(parentIdx)

