MOD = 10**9+7

def min_powers(n):
    powers = []
    while n > 0:
        p = 1
        while p*2 <= n:
            p *= 2
        powers.append(p)
        n -= p
    return powers

def product_of_powers(powers, left, right):
    prod = 1
    for i in range(left, right+1):
        prod = (prod * powers[i]) % MOD
    return prod

def answer_queries(n, queries):
    powers = min_powers(n)
    answers = []
    for left, right in queries:
        prod = product_of_powers(powers, left, right)
        answers.append(prod % MOD)
    return answers

