class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next
        
def swapNodes(head: ListNode, k: int) -> ListNode:
    curr, len = head, 0
    while curr:
        curr = curr.next
        len += 1
    first, second = head, head
    for i in range(1, k):
        first = first.next
    for i in range(1, len-k+1):
        second = second.next
    first.val, second.val = second.val, first.val
    return head

