class Solution:
    def maximumScore(self, nums: List[int], k: int) -> int:
        
        N = len(nums)
        
        def next_small_left():
            
            i = 0
            left=[-1]*N
            stack=[]
            for i in range(N):
                while stack and nums[stack[-1]] >= nums[i]:
                    stack.pop()
                if stack:
                    left[i] = stack[-1]
                stack.append(i)
            
            return left
            
        
        def next_small_right():
            right=[N]*N
            stack=[]
            for i in range(N-1,-1,-1):
                while stack and nums[stack[-1]] >= nums[i]:
                    stack.pop()
                if stack:
                    right[i] = stack[-1]
                stack.append(i)
            
            return right
        
        left = next_small_left()
        right = next_small_right()
        # print(left,right)
        N = len(left)
        ans=-1
        for i in range(N):
            if left[i]+1 <= k <= right[i]-1:
                ans = max(ans,(right[i]-left[i]-1)*nums[i])
                # print(i,ans)
        return ans

class Solution:
    def nextLargerNodes(self, head: Optional[ListNode]) -> List[int]:
        
        #reverse it
        r = None
        curr = head
        while curr:
            tmp = curr.next
            curr.next = r
            r = curr
            curr = tmp
        
        curr = r
		'''
		#use double ended queue because we are using decresing monotonic stack
		and the higher values will get appended to the begining of the queue
		and the lower values will be appended to the front of the queue
        
		'''
		stack = deque()
        res = []
        while curr:
            if stack and stack[-1] > curr.val:
                res.append(stack[-1])
                # stack.append(curr.val)
            else:
                while stack:
                    if curr.val < stack[-1]:
                        break
                    stack.pop()
                if stack:
                    res.append(stack[-1])
                else:
                    res.append(0)
            #if the stack is empty just append the current value
			if not stack: 
				stack.append(curr.val)
            #else if the curr.val is higher than what we have in the stack 
			#it get's appended to the beginning of stack(or queue) else to the front
			else:    
                if curr.val > stack[-1]:
                    stack.appendleft(curr.val)
                else:
                    stack.append(curr.val)
                    
            curr = curr.next
            
        return res[::-1]

class Solution:
    
    def leap_year(self,year):
        
        return not(year % 400) or year % 100 and not(year % 4) # Leap year Condition
    
    def count_years_days(self,year):
        
        year_days = 0
        
        for i in range(1971,year): # We need some reference 1971 is reference here lowest possible year in constairnts. You can take anything which will be lesser than given two dates.
            
            # To find distance between a and b. We are taking some reference which is smaller than both a and b. like if we need to find 100 - 200 we can take 0 as reference and find  0 - 100 and 0- 200 then find 100 - 200 which is -100 easily.
            
            # Directly if we try to find a - b many conditions will be there and it will end up having an headache
            
            if self.leap_year(i):
                
                year_days += 366
                
            else:
                
                year_days +=  365
        
        return year_days
    
    def count_month_days(self,m,year):
        
        month = [0,31,28,31,30,31,30,31,31,30,31,30,31]
        
        month_days = 0
        
        for i in range(1,m):
            
            if i==2: # i is number of month like 1 for Jan and 2 for feb
                
                # for leap year feb will have 29 days i.e. x will be 1
                
                month_days += month[i] + int(self.leap_year(year))
                
            else:
                
                month_days += month[i]
        
        return month_days
        
        
    def daysBetweenDates(self, date1: str, date2: str) -> int:
        
        
        year1,month1,date1 = map(int,date1.split("-"))
        
        year2,month2,date2 = map(int,date2.split("-"))
        
        return abs ((self.count_years_days(year1) + self.count_month_days(month1,year1) + date1) - (self.count_years_days(year2) + self.count_month_days(month2,year2) + date2))

class Solution:
    def averageOfLevels(self, root: Optional[TreeNode]) -> List[float]:
        # Create dictionaries with levels {level: sum} and {level: count}
		levels_with_sums, levels_with_counts = {}, {}
        root_level = 0
        # Recursive pre-order traversal
        def preorder_traverse(root, levels_with_sums, levels_with_counts, root_level):
            if not root:
                return
            # Set 0 if there isn't value for the level else add in both dictionaries
            levels_with_sums[root_level] = levels_with_sums.get(root_level, 0) + root.val
            levels_with_counts[root_level] = levels_with_counts.get(root_level, 0) + 1
            
            preorder_traverse(root.left, levels_with_sums, levels_with_counts, root_level + 1)
            preorder_traverse(root.right, levels_with_sums, levels_with_counts, root_level + 1)
            
        preorder_traverse(root, levels_with_sums, levels_with_counts, root_level)
        # Create list with averages for using both dictionaries
        averages = [levels_with_sums.get(level) / levels_with_counts.get(level) for level in levels_with_sums.keys()]
        return averages

