    ans = []
    while queue:
        size = len(queue)
        level_sum = 0
        for i in range(size):
            node = queue.pop(0)
            level_sum += node.val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        ans.append(level_sum / size)
