class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        """
        Notes:
            - operator follow their operands
            - when we see an operator, use it against last two values
            
            time complexity: o(n)
            space complexity: o(n)               
        """
        q = deque(tokens)
        
        while len(q) > 1:
            c = q.popleft()
            
            if self.is_operator(char=c):
                second = q.pop()
                first = q.pop()
                value = self.find_value(first=first, second=second, operator=c)
                q.append(value)
            else:
                q.append(c)
        
        return int(q.pop())
        
    def is_operator(self, char: str) -> bool:
        return char == "+" or char == "-" or char == "*" or char == "/"
    
    def find_value(self, first: str, second: str, operator: str) -> int:
        f, s = int(first), int(second)
        
        if operator == "+":
            return f+s
        if operator == "-":
            return f-s
        if operator == "*":
            return f*s
        if operator == "/":
            return int(f/s)
        raise ValueError(f"something is wrong, operator={operator}")

