            edges[y-1][x-1] = True
        for node in range(n):
            adj = edges[node]
            blocked = [False]*n
            size = 4
            for x in adj:
                if colour[x] != None:blocked[colour[x]-1] = True
            if blocked[0] == False:
                colour[node] = 1
            elif blocked[1] == False:
                colour[node] = 2
            elif blocked[2] == False:
                colour[node] = 3
            elif blocked[3] == False:
                 colour[node] = 4
