class Solution:
    def countBalls(self, lowLimit: int, highLimit: int) -> int:
        h = defaultdict(int)
        
        # find the first box number
        s = 0
        temp = lowLimit
        while temp > 0:
            s += temp % 10
            temp = temp // 10
        h[s] += 1
        
        x = lowLimit + 1
        while x <= highLimit:
            # check rightmost digit
            if 1 <= x % 10 <= 9:
                s = s+1
            else:
                s = s - 8
                temp = x // 10
                while temp > 0 and temp % 10 == 0:
                    s -= 9
                    temp = temp // 10
                    
            h[s] += 1
            x += 1
        return max(h.values())

