# Send the list containing the integers to this function that will return the second max value. 

def find_second_max(x):
    
    max_1 = -1
    max_2 = -1
    
    for i in range(len(x)):
        
        if max_1 <= x[i]:
            
            max_2 = max_1
            
            max_1 = x[i]
            
        elif (max_2 <= x[i]) and (x[i] <= max_1):
            
            max_2 = x[i]
            
    return max_2


