def smallestDistancePair(nums, k):
    nums.sort()
    low, high = 0, nums[-1] - nums[0]
    while low < high:
        mid = (low + high) // 2
        count, left = 0, 0
        for right, num in enumerate(nums):
            while num - nums[left] > mid:
                left += 1
            count += right - left
        if count >= k:
            high = mid
        else:
            low = mid + 1
    return low

