class Solution:
def minDistance(self, x: str, y: str) -> int:
    #DP question because it asks 'optimal' = minimum
    #category of DP? LCS. why? because 2 strings are given and integer output is expected
    #this is exactly what the i/p and o/p was in case of LCS
    #matrix takes O(N^2) SPACE
    #time: O(N^2)
    
    def LCS(x,y,n,m):
        t = []
        for i in range(n+1):
            temp = []
            for j in range(m+1):
                temp.append(-1)
            b = temp[:]
            t.append(b)
        
        
        for i in range(n+1):
            for j in range(m+1):
                if i == 0 or j == 0:
                    t[i][j] = 0
    
        for i in range(1,n+1):
            for j in range(1,m+1):                        
                if x[i-1] == y[j-1]:
                    t[i][j] = 1 + t[i-1][j-1]
                else:
                    t[i][j] = max(t[i-1][j],t[i][j-1])
        return t[n][m]
        

    LCSlen = LCS(x,y,len(x),len(y))
    deletions = len(x) - LCSlen
    insertions = len(y) - LCSlen
    return deletions + insertions

