class Solution:
    def minCostSetTime(self, startAt: int, moveCost: int, pushCost: int, targetSeconds: int) -> int:
        mins1,secs1 = (0,targetSeconds) if targetSeconds<100 else (targetSeconds//60,targetSeconds%60)
        if mins1>99:
            mins1 -= 1
            secs1 += 60
        l = [(mins1,secs1)]
        if mins1>0 and secs1<40:
            mins2 = mins1-1
            secs2 = secs1+60
            l.append((mins2,secs2))
        if mins1<99 and secs1>=60:
            mins2 = mins1+1
            secs2 = secs1-60
            l.append((mins2,secs2))
        ret = inf
        for mins,secs in l:
            mins = str(mins) if mins>0 else ''
            if secs>=10:
                secs = str(secs)
            else:
                if mins:
                    secs = '0'+str(secs)
                else:
                    secs = str(secs)
            t = mins+secs
            #print(t)
            total = 0
            for i in range(len(t)):
                if i==0 and t[i]==str(startAt):
                    total += pushCost
                elif i>0 and t[i]==t[i-1]:
                    total += pushCost
                else:
                    total += moveCost + pushCost
            ret = min(ret,total)
        return ret

class Solution:
    def maxDistance(self, position: List[int], m: int) -> int:
        def verify(x):
            '''
            Returns true if we can put m balls in the buskets
            while maintining at least x distance between them
            '''
            count, prev = 1, position[0]
            for i in range(1, len(position)):
                if position[i]-prev >= x:
                    prev = position[i]
                    count += 1
            return count >= m
    
        position.sort()
        low, high, ret = 1, (position[-1]-position[0])//(m-1)+1, -1
        while low <= high:
            mid = low+(high-low)//2
            if verify(mid):
                # this is a solution but we are looking for the maximum
                # update ret and continue looking for a even larger one
                ret = mid
                low = mid+1
            else:
                high = mid-1
        return ret

