    def minNumberOfFrogs(self, croakOfFrogs: str) -> int:
        if len(croakOfFrogs) % 5 != 0:
            return -1
        croaks = {"c": 0, "r": 0, "o": 0, "a": 0, "k": 0}
        current_frogs = 0
        max_frogs = 0
        for i in range(len(croakOfFrogs)):
            if croakOfFrogs[i] not in croaks:
                return -1
            elif croakOfFrogs[i] == "c":
                croaks["c"] += 1
                current_frogs += 1
                max_frogs = max(max_frogs, current_frogs)
            elif croaks[croakOfFrogs[i]] > croaks[croakOfFrogs[i-1]]:
                croaks[croakOfFrogs[i]] += 1
            else:
                return -1
        if all(v == croaks["c"] for v in croaks.values()):
            return max_frogs
        return -1

