class Solution:
    def numOfWays(self, n: int) -> int:
        # create all possible combinations of 3 colors
        colors = ["RGB", "RBG", "GRB", "GBR", "BRG", "BGR"]
        
        # initialize dp array with all 3-color combinations for n=1
        dp = [[1, 1, 1] for _ in range(6)]
        
        for i in range(2, n+1):
            # create a new dp array for each row
            new_dp = [[0, 0, 0] for _ in range(6)]
            
            # iterate through each possible color combination
            for j in range(6):
                # find all valid color combinations for the current row
                for k in range(6):
                    if self.isValid(colors[j], colors[k]):
                        # update the new dp array with the sum of valid combinations from previous row
                        new_dp[j][0] += dp[k][0]
                        new_dp[j][1] += dp[k][1]
                        new_dp[j][2] += dp[k][2]
                
                # set the new values for the current combination to the dp array
                dp[j][0], dp[j][1], dp[j][2] = new_dp[j][0] % MOD, new_dp[j][1] % MOD, new_dp[j][2] % MOD
        
        # sum up all valid combinations from the last row
        return sum(dp[i][0] + dp[i][1] + dp[i][2] for i in range(6)) % MOD
        
    def isValid(self, color1: str, color2: str) -> bool:
        # check if two colors are valid based on adjacency condition
        for i in range(3):
            if color1[i] == color2[i]:
                return False
        return True

def knightProbability(n: int, k: int, row: int, column: int) -> float:
    dp = [[0 for i in range(n)] for j in range(n)]
    dp[row][column] = 1
    
    for s in range(k):
        temp = [[0 for i in range(n)] for j in range(n)]
        for i in range(n):
            for j in range(n):
                if dp[i][j] != 0:
                    moves = [[-2, -1], [-2, 1], [-1, -2], [-1, 2], [1, -2], [1, 2], [2, -1], [2, 1]]
                    for move in moves:
                        row_next = i + move[0]
                        col_next = j + move[1]
                        if row_next >=0 and col_next >=0  and row_next < n and col_next < n:
                            temp[row_next][col_next] += dp[i][j]/8
        dp = temp
    return sum(map(sum, dp))

