def canPartitionKSubsets(nums: List[int], k: int) -> bool:
    
    def dfs(pos, subsets):
        if pos == -1:
            return len(set(subsets)) == k
        
        for i in range(k):
            if subsets[i]+nums[pos] <= target_sum:
                subsets[i] += nums[pos]
                if dfs(pos-1, subsets):
                    return True
                subsets[i] -= nums[pos]
        return False
    
    total_sum = sum(nums)
    if total_sum % k != 0:
        return False
    
    target_sum = total_sum // k
    nums.sort()
    if nums[-1] > target_sum:
        return False
    
    return dfs(len(nums)-1, [0]*k)

