def isPalindrome(n):
    return str(n) == str(n)[::-1]

def nextPalindrome(n):
    while not isPalindrome(n):
        n += 1
    return n

def findPalindrome(queries, intLength):
    answer = []
    for i in range(len(queries)):
        count = 0
        current = 1
        while count < queries[i]:
            current = nextPalindrome(current + 1)
            if len(str(current)) == intLength:
                count += 1
        answer.append(current)
    return answer

