            res[0][i] = res[1][i] = 1
            upper -= 1
            lower -= 1
    if upper < 0 or lower < 0:
        return []
    for i in range(n):
        if colsum[i] == 1:
            if upper > 0:
                res[0][i] = 1
                upper -= 1
            elif lower > 0:
                res[1][i] = 1
                lower -= 1
            else:
                return []
    if upper > 0 or lower > 0:
        return []
    return res

