def reverse_odd_level(root):
    if root is None:
        return None
    queue = []
    queue.append(root)
    odd_level = False
    while queue:
        count = len(queue)
        level = []
        for i in range(count):
            node = queue.pop(0)
            level.append(node)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        if odd_level:
            for i in range(len(level)):
                if i % 2 == 0:
                    level[i].val, level[len(level) - 1 - i].val = level[len(level) - 1 - i].val, level[i].val
        odd_level = not odd_level
    return root

