        if (i, j, k_left) in cache:
            return cache[(i, j, k_left)]
        if k_left == 1:
            return int(apples > 0)
        cnt = 0
        for r in range(i+1, rows):
            if any(pizza[x][j] == 'A' for x in range(i, r)):
                cnt = (cnt + dfs(r, j, apples + sum(pizza[x][j] == 'A' for x in range(i, r)), k_left - 1, cache)) % MOD
