                cnt = (cnt + dfs(i, c, apples + sum(pizza[i][x] == 'A' for x in range(j, c)), k_left - 1, cache)) % MOD
        cache[(i, j, k_left)] = cnt
        return cnt

    rows, cols = len(pizza), len(pizza[0])
    cache = {}
    return dfs(0, 0, sum(pizza[i][j] == 'A' for i in range(rows) for j in range(cols)), k, cache)

