class Solution:
    def findDifference(self, nums1: List[int], nums2: List[int]) -> List[List[int]]:
        # have the result be a 2D array where the first element is unique in nums1 and the second is
        # unique in nums2
        # redefine nums1 &amp; nums2 of a set to find the intersection between them
        # iterate nums1 set and every number that is not in the intersection add to 1st element in res
        # iterate nums2 set and every number that is not in the intersection add to 2nd element in res
        # Time O(M + N) Space: O(M + N)
        
        nums1, nums2 = set(nums1), set(nums2)
        common = nums1.intersection(nums2)
        
        res = [[], []]
        
        for val in nums1:
            if val not in common:
                res[0].append(val)
        
        for val in nums2:
            if val not in common:
                res[1].append(val)
                
        return res

class Solution:
    def numSub(self, s: str) -> int:

        ans = 0
        n = len(s)
        i = 0
        while(i<n-1):
            l = 0 # reset the substring length having all 1s equal to 0
            if s[i] == '1':
                l += 1
                for j in range(i+1, n):
                    if(s[j] == '1'):
                        l += 1
                    else:
                        # We encounter '0' so we break and calculate the number of substrings.
                        break
                ans += l*(l+1)//2; # Calculate number of non-empty substrings using above formula.
		i = j + 1 # Update i-pointer to the next character where last '0' is found
            else:
                i += 1  # keep on incrementing untill '1' is not found.
                
                
        # Since i goes upto the second last character only we need to check if the last character was included or not.
        # It will not be included if the second last character is '0', so check if last character was '1' and second last character is '0'
        # we increment the answer by 1.
        if s[-1] == '1' and s[-2] == '0':
            ans += 1
            
        return ans%1000000007

