def min_operators(x, target):
    operators = ['+', '-', '*', '/']
    minimum = float('inf')
    
    def helper(expression):
        nonlocal minimum
        if len(expression) >= minimum:
            return
        if eval(expression) == target:
            minimum = len(expression)
            return
        for op in operators:
            for i in range(len(expression)):
                if expression[i].isdigit() and (i == 0 or not expression[i-1].isdigit()):
                    helper(expression[:i] + "(" + expression[i:])
                if expression[i].isdigit() and (i == len(expression)-1 or not expression[i+1].isdigit()):
                    helper(expression[:i+1] + ")" + expression[i+1:])
            helper(expression + op)
    
    helper(str(x))
    return -1 if minimum == float('inf') else minimum-1

def kth_bit(n, k):
    s = "0"
    for i in range(2, n+1):
        s = s + "1" + "".join(["0" if x == "1" else "1" for x in s[::-1]])
    return int(s[k-1])

