    def tictactoe(self, moves: List[List[int]]) -> str:
        grid = [[' ' for _ in range(3)] for _ in range(3)]
        
        def check_winner(char):
            for i in range(3):
                if grid[i][0] == grid[i][1] == grid[i][2] == char:
                    return True
                if grid[0][i] == grid[1][i] == grid[2][i] == char:
