def maxIncreaseKeepingSkyline(grid):
    n = len(grid)
    row_maxes = [max(row) for row in grid]
    col_maxes = [max(col) for col in zip(*grid)]
    ans = 0
    for r in range(n):
        for c in range(n):
            ans += min(row_maxes[r], col_maxes[c]) - grid[r][c]
    return ans

