import math

def max_score(nums):
    n = len(nums)//2
    score = 0
    for i in range(n):
        max_gcd = 0
        max_idx = -1
        for j in range(len(nums)):
            for k in range(len(nums)):
                if j != k:
                    curr_gcd = math.gcd(nums[j], nums[k])
                    if curr_gcd > max_gcd:
                        max_gcd = curr_gcd
                        max_idx = j
                        sec_idx = k
        
        score += max_gcd
        nums.pop(max_idx)
        nums.pop(sec_idx - (sec_idx > max_idx))
    return score

