from collections import defaultdict

class Solution:
    def getMaximumTotalImportance(self, n: int, roads: List[List[int]]) -> int:
        def dfs(x, parent):
            subtree_sum = 0
            for y in graph[x]:
                if y == parent:
                    continue
                subtree_sum += dfs(y, x)
            
            if not available_values:
                return subtree_sum
            
            node_value = available_values.pop()
            values[x] = node_value
            
            for y in graph[x]:
                if values[y] is not None:
                    edge_sum[values[x] + values[y]] += 1
            
            max_sum = subtree_sum
            for y in graph[x]:
                if values[y] is not None:
                    edge_sum[values[x] + values[y]] -= 1
                    max_sum = max(max_sum, dfs(y, x))
                    edge_sum[values[x] + values[y]] += 1
                    
            available_values.add(node_value)
            values[x] = None
            return max_sum
        
        graph = defaultdict(list)
        for x, y in roads:
            graph[x].append(y)
            graph[y].append(x)
        
        values = [None] * n
        edge_sum = defaultdict(int)
        available_values = set(range(1, n + 1))
        
        return dfs(0, None) + max(edge_sum.values())

