from fractions import Fraction

def fraction_addition(expression):
    sum = Fraction(0,1)
    for frac in expression.replace('+', ' +').replace('-', ' -').split():
        sum += Fraction(frac)
    if sum.denominator == 1:
        return str(sum.numerator)
    else:
        return str(sum.numerator) + '/' + str(sum.denominator)

