def diffWaysToCompute(expression):
    if expression.isdigit():
        return [int(expression)]
    
    res = []
    for i in range(len(expression)):
        if expression[i] in "+-*":
            left = diffWaysToCompute(expression[:i])
            right = diffWaysToCompute(expression[i+1:])
            for l in left:
                for r in right:
                    if expression[i] == "+":
                        res.append(l + r)
                    elif expression[i] == "-":
                        res.append(l - r)
                    else:
                        res.append(l * r)
                        
    return res

def uncommonWords(s1: str, s2: str) -> List[str]:
    s1_words = s1.split()
    s2_words = s2.split()

    uncommon_words = []

    for word in s1_words:
        if word not in s2_words and s1_words.count(word) == 1:
            uncommon_words.append(word)

    for word in s2_words:
        if word not in s1_words and s2_words.count(word) == 1:
