class Solution:
    def solver(self, cache, cur_n):
        if cache[cur_n] == 0:
            for i in range(1, cur_n + 1):
                if cache[cur_n] == 0:
                    cache[cur_n] = cur_n
                
                # max() - because we are interested in the worst case
                # + 1 - drop from cur floor
                # drop egg -> egg is break => worst case : validate every floor with help second egg: i - 1 steps
                # drom egg -> egg is not break => worst case: validate worst case for cur_n - i floors
                val = max(i - 1, self.solver(cache, cur_n - i)) + 1
                #print(i, "--->", cur_n, "--->", cache[cur_n], val)
                cache[cur_n] = min(cache[cur_n], val)
        
        return cache[cur_n]
        
    def twoEggDrop(self, n: int) -> int:
        cache = [0] * (n + 1)
        
        return self.solver(cache, n)

