def is_obstructed(guards, walls, r, c, dr, dc):
    for guard in guards:
        if guard[0] == r + dr and guard[1] == c + dc:
            return True
    for wall in walls:
        if wall[0] == r + dr and wall[1] == c + dc:
            return True
    return False

def get_guarded_cells(n, guards, walls):
    guarded = set()
    for guard in guards:
        r, c = guard
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            while nr >= 0 and nr < n and nc >= 0 and nc < n and not is_obstructed(guards, walls, r, c, dr, dc):
                guarded.add((nr, nc))
                nr += dr
                nc += dc
    return len(guarded)

