def max_edges_to_delete(n: int, nums: List[int], edges: List[List[int]]) -> int:
    # Build adjacency list graph and calculate node values
    graph = defaultdict(list)
    node_values = [0] * n
    for i in range(n):
        node_values[i] = nums[i]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    # Perform dfs to calculate subtree values and return answer
    def dfs(node, parent):
        subtree_sum = node_values[node]
        max_deleted_edges = 0
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            neighbor_subtree_sum, deleted_edges = dfs(neighbor, node)
            subtree_sum += neighbor_subtree_sum
            max_deleted_edges += deleted_edges

        if subtree_sum == 0:
            max_deleted_edges += 1

        return subtree_sum, max_deleted_edges

    ans = 0
    for node in range(n):
        if node_values[node] == 0:
            _, deleted_edges = dfs(node, -1)
            ans += deleted_edges

    return ans

