        n = len(prices)
        dp = [[0 for j in range(2)] for i  in range(n+1)]
        dp[n][0] = dp[n][1] = 0
        for  i in range(n-1 , -1 , -1):
            for j in range(2):
                if j == 0:
                    no = 0 + dp[i+1][0]
                    take = -prices[i] + dp[i+1][1]
                    profit = max(no , take)
                    dp[i][j] = profit
                if j == 1:
                    no = 0 + dp[i+1][1]
                    take = prices[i] + dp[i+1][0]
                    profit = max(no  , take)
                    dp[i][j] = profit
        return dp[0][0]


