def find_largest_divisor(str1, str2):
    if len(str1) > len(str2):
        shorter = str2
        longer = str1
    else:
        shorter = str1
        longer = str2
    
    for i in range(len(shorter), 0, -1):
        if shorter[:i] * (len(longer) // len(shorter[:i])) == longer:
            return shorter[:i]
        
    return ""

