class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        n = len(arr)
        
        if n == 1:
            return arr[:k]
        elif n == k:
            return arr
        
        arr.sort()
        m = arr[(n-1)//2]
        
        res = []
        i, j = 0, n-1
        while i < j:
            if abs(arr[i]-m) > abs(arr[j]-m):
                res.append(arr[i])
                i += 1
            elif abs(arr[i]-m) < abs(arr[j]-m):
                res.append(arr[j])
                j -= 1
            else: # abs(arr[i]-m) == abs(arr[j]-m)
                if arr[i] > arr[j]:
                    res.append(arr[i])
                    i += 1
                elif arr[i] < arr[j]:
                    res.append(arr[j])
                    j -= 1
                else:
                    res.append(arr[i])
                    i += 1
            if len(res) == k:
                return res

