class Node:
    def __init__(self, v, l=None, r=None):
        self.v = v
        self.l = l
        self.r = r
        self.score = v[1] - v[0]


class LinkedList:
    def __init__(self, arr=[]):
        self.head = None
        self.tail = None
        self.count = 0
        for val in arr:
            self.append(val)
    
    def append(self, val):
        if not self.head:
            self.head = self.tail = Node(val)
        else:
            self.tail.r = Node(val, l=self.tail)
            self.tail = self.tail.r
        self.count += 1
    
    def merge(self):
        worst = self.head if self.head.score < self.head.r.score else self.head.r
        best = self.head
        bs = (self.head.r.v[1] - self.head.v[0]) - (self.head.score + self.head.r.score)
        node = self.head.r
        while node.r:
            if worst.score > node.r.score:
                worst = node.r
            cur = (node.r.v[1] - node.v[0]) - (node.score + node.r.score)
            if cur > bs:
                best = node
                bs = cur
            node = node.r
        # we can merge two intervals into one or delete one interval
        if bs > - worst.score:
            node = best
            rnode = node.r
            node.r = rnode.r
            if rnode.r: rnode.r.l = node
            else: self.tail = node
            node.v[1] = rnode.v[1]
            node.score = node.v[1] - node.v[0]
            del rnode
        else:
            if not worst.l:
                self.head = worst.r
            else:
                worst.l.r = worst.r
            if not worst.r:
                self.tail = worst.l
            else:
                worst.r.l = worst.l
            del worst
        self.count -= 1
    
    def __len__(self):
        return self.count
    
    def __repr__(self):
        arr = []
        node = self.head
        while node:
            arr.append(node.v)
            node = node.r
        return str(arr)
    
    def sum(self):
        ret = 0
        node = self.head
        while node:
            ret += node.score
            node = node.r
        return ret

    
class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        if k == 0: return 0
        # store ascending intervals in format (low, high)
        lh = LinkedList()
        i = 1
        while i < len(prices):
			# skip descending
            while i < len(prices) and prices[i] < prices[i - 1]:
                i += 1
            if i == len(prices): break
            low = prices[i - 1]
            while i < len(prices) and prices[i] >= prices[i - 1]:
                i += 1
            if prices[i - 1] != low:
                lh.append([low, prices[i - 1]])
            
        # print(lh)
        # stacking ascending sequences to fit in k intervals
        while len(lh) > k:
            lh.merge()
        # print(lh)
        
        return lh.sum()

