class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        n = len(prices)
        if k >= n // 2:
            # if k is large, the problem becomes same as buying and selling as many times as you can
            max_profit = 0
            for i in range(n-1):
                if prices[i+1] > prices[i]:
                    max_profit += prices[i+1] - prices[i]
            return max_profit
        else:
            # using dynamic programming
            dp = [[0 for j in range(n)] for i in range(k+1)]
            for i in range(1, k+1):
                max_diff = -prices[0]
                for j in range(1, n):
                    dp[i][j] = max(dp[i][j-1], prices[j]+max_diff)
                    max_diff = max(max_diff, dp[i-1][j-1]-prices[j])
            return dp[k][n-1]

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
