class Solution:
    def canMakeFriends(self, n: int, restrictions: List[List[int]], requests: List[List[int]]) -> List[bool]:
        graph = [[] for _ in range(n)]
        for i, j in restrictions:
            graph[i].append(j)
            graph[j].append(i)
        res = []
        for u, v in requests:
            if v in graph[u] or self.hasCommonFriend(u, v, graph):
                res.append(False)
            else:
                graph[u].append(v)
                graph[v].append(u)
                res.append(True)
        return res
    
    def hasCommonFriend(self, u: int, v: int, graph: List[List[int]]) -> bool:
        visited = set()
        queue = collections.deque([u])
        while queue:
            cur = queue.pop()
            if cur == v:
                return True
            visited.add(cur)
            for neighbor in graph[cur]:
                if neighbor not in visited:
                    queue.appendleft(neighbor)
        return False

class Solution:
    def numMovesStonesII(self, stones: List[int]) -> List[int]:
        stones.sort()
        n = len(stones)
        max_moves = stones[-1] - stones[0] + 1 - n
        max_moves -= min(stones[1] - stones[0] - 1, stones[-1] - stones[-2] - 1)
        min_moves = max_moves
        i = 0
        for j in range(n):
            while stones[j] - stones[i] + 1 > n:
                i += 1
            if j - i + 1 == n - 1 and stones[j] - stones[i] + 1 == n - 1:
                min_moves = min(min_moves, 2)
            else:
                min_moves = min(min_moves, n - (j - i + 1))
        return [min_moves, max_moves]

