class Solution:
    def nearestExit(self, maze: List[List[str]], entrance: List[int]) -> int:
        queue = [(entrance, 0),]
        maze[entrance[0]][entrance[1]] = '+'
        
        while(not len(queue) == 0):
            (current, length) = queue.pop(0)
            
            if(current[1]+1 < len(maze[0])):
                if(maze[current[0]][current[1]+1] == '.'):
                    queue.append(([current[0],current[1]+1], length+1))
                    maze[current[0]][current[1]+1] = '+'
            else:
                if(length > 0):
                    return length
                
            if(current[1]-1 >= 0):
                if(maze[current[0]][current[1]-1] == '.'):
                    queue.append(([current[0],current[1]-1], length+1))
                    maze[current[0]][current[1]-1] = '+'
            else:
                if(length > 0):
                    return length
                
            if(current[0]+1 < len(maze)):
                if(maze[current[0]+1][current[1]] == '.'):
                    queue.append(([current[0]+1,current[1]], length+1))
                    maze[current[0]+1][current[1]] = '+'
            else:
                if(length > 0):
                    return length
                
            if(current[0]-1 >= 0):
                if(maze[current[0]-1][current[1]] == '.'):
                    queue.append(([current[0]-1,current[1]], length+1))
                    maze[current[0]-1][current[1]] = '+'
            else:
                if(length > 0):
                    return length
        
        return -1

class Solution:
    def getMinimumDifference(self, root: TreeNode) -> int:
        
        res = []
        
        def helper(node, vals, minn):
		    # If we find a min diff of 1 we can return (given properties of BST + abs diff)
			# we know this is the lowest result we can find.
            if minn == 1:
                return True
            if not node:
			    # If we run out of nodes append the min diff we found on this path 
				# and return False because we didn't find 1.
                res.append(minn)
                return False
			# Otherwise we see if theres a smaller difference with the current node and what we've seen so far.
            if vals:
                for i in vals:
                    if abs(node.val - i) < minn:
                        minn = abs(node.val - i)
			# Recurse subtrees and return if we found 1 in either subtree.
            return helper(node.left, vals + [node.val], minn) or \
            helper(node.right, vals + [node.val], minn)
         
		# We know we found 1 if our func. returns True else we'll take the min of the mins we found.
        return 1 if helper(root, [], float('inf')) else min(res)

