class Solution:
    def getMinimumDifference(self, root: Node) -> int:
        self.minDiff = float('inf')
        self.prev = float('-inf')
        self.inOrder(root)
        return self.minDiff
        
    def inOrder(self, node):
        if node:
            self.inOrder(node.left)
            self.minDiff = min(self.minDiff, node.val - self.prev)
            self.prev = node.val
            self.inOrder(node.right)

def smallest_level_sum_max(root):
    queue = [(root, 1)]
    level_sum = {}
    while queue:
        node, level = queue.pop(0)
        # Add node value to level sum
        level_sum[level] = level_sum.get(level, 0) + node.val
        # Add node children to the queue
        if node.left:
            queue.append((node.left, level+1))
        if node.right:
            queue.append((node.right, level+1))
    # Find smallest level with max node value
    min_level = min(level_sum, key=lambda x: (level_sum[x], -x))
    return level_sum[min_level]

