def last_day(row, col, cells):
    matrix = [[0] * col for _ in range(row)]
    for day, cell in enumerate(cells):
        r, c = cell[0]-1, cell[1]-1
        matrix[r][c] = 1
        if r > 0 and matrix[r-1][c] == 1:
            matrix[r][c] = matrix[r-1][c]
        if r < row-1 and matrix[r+1][c] == 1:
            matrix[r][c] = matrix[r+1][c]
        if c > 0 and matrix[r][c-1] == 1:
            matrix[r][c] = matrix[r][c-1]
        if c < col-1 and matrix[r][c+1] == 1:
            matrix[r][c] = matrix[r][c+1]
    last_day = 0
    for c in range(col):
        if matrix[0][c] == 0:
            continue
        stack = [(0, c)]
        visited = set(stack)
        while stack:
            r, c = stack.pop()
            if r == row-1:
                last_day = max(last_day, matrix[r][c])
            if r > 0 and matrix[r-1][c] > 0 and (r-1, c) not in visited:
                  stack.append((r-1, c))
                  visited.add((r-1, c))
            if r < row-1 and matrix[r+1][c] > 0 and (r+1, c) not in visited:
                  stack.append((r+1, c))
                  visited.add((r+1, c))
            if c > 0 and matrix[r][c-1] > 0 and (r, c-1) not in visited:
                  stack.append((r, c-1))
                  visited.add((r, c-1))
            if c < col-1 and matrix[r][c+1] > 0 and (r, c+1) not in visited:
                  stack.append((r, c+1))
                  visited.add((r, c+1))
    return last_day

