def delete_duplicate_folders(paths):
    def build_tree(paths):
        root = {}
        for path in paths:
            cur = root
            for folder in path.split("/")[1:]:
                if folder not in cur:
                    cur[folder] = {}
                cur = cur[folder]
        return root
    
    def mark_duplicates(tree):
        subtrees = {}
        for node in tree:
            subtree = tree[node]
            if subtree:
                subtree = tuple(mark_duplicates(subtree))
            if subtree in subtrees:
                subtrees[subtree].append(node)
            else:
                subtrees[subtree] = [node]
        for dupes in [subtrees[subtree] for subtree in subtrees if len(subtrees[subtree]) > 1]:
            for dupe in dupes:
                del tree[dupe]
        return tree
    
    def collect_paths(tree, path=""):
        paths = []
        for node in tree:
            paths.extend(collect_paths(tree[node], path + "/" + node))
        if path:
            paths.append(path)
        return paths
    
    tree = build_tree(paths)
    tree = mark_duplicates(tree)
    return [path.split("/") for path in collect_paths(tree)]

def repeat_limited_string(integer, repeat_limit):
    letter = "s"
    repeat_limited_string = letter * repeat_limit
    new_string = ''
    for i in range(integer):
        if i % repeat_limit == 0 and i + repeat_limit <= integer:
            new_string += repeat_limited_string
        else:
            new_string += letter
    return new_string[::-1]

def max_beauty(items, queries):
    answer = []
    max_beauty = 0
    for query in queries:
        for item in items:
            if item[0] <= query and item[1] > max_beauty:
                max_beauty = item[1]
        answer.append(max_beauty)
        max_beauty = 0
    return answer

