def smallestSum(arr):
    n = len(arr)
    dp = [[float('inf') for j in range(n)] for i in range(n)]
    for i in range(n):
        dp[i][i] = arr[i]
    for l in range(2, n+1):
        for i in range(n-l+1):
            j = i+l-1
            for k in range(i, j):
                left = dp[i][k]
                right = dp[k+1][j]
                val = max(left, right)
                dp[i][j] = min(dp[i][j], val*(arr[k]))
    return dp[0][n-1]

