def max_product(nums, k):
    mod = 10**9 + 7
    nums.sort()
    n = len(nums)
    if nums[-1] == 0 or k == 0:
        return 0
    if k >= n:
        prod = 1
        for num in nums:
            prod = (prod * num) % mod
        return prod
    neg_count = 0
    for num in nums:
        if num < 0:
            neg_count += 1
    if neg_count % 2 == 0:
        left, right = 0, n - 1
    else:
        left, right = 0, n - 2
    prod = 1
    while k > 0:
        if k == 1:
            prod = (prod * max(nums[left], nums[right])) % mod
        else:
            left_prod = nums[left] * nums[left + 1]
            right_prod = nums[right] * nums[right - 1]
            if left_prod > right_prod:
                prod = (prod * left_prod) % mod
                left += 2
            else:
                prod = (prod * right_prod) % mod
                right -= 2
        k -= 1
    return prod

