class Solution:
    def closeStrings(self, word1: str, word2: str) -> bool:
        cnt1, cnt2 = defaultdict(int), defaultdict(int)
        
        n1, n2 = defaultdict(int), defaultdict(int)
        s1, s2 = set(), set()
        
        for w in word1:
            cnt1[w] += 1
            s1.add(w)
            
        for w in word2:
            cnt2[w] += 1
            s2.add(w)
            
        for w in word1:
            if w not in word2:
                return False
        for w in word2:
            if w not in word1:
                return False 
            
        for k in cnt1:
            v = cnt1[k]
            n1[v] += 1
            
        for k in cnt2:
            v = cnt2[k]
            n2[v] += 1
        
        for k in n1:
            if k not in n2 or n1[k] != n2[k]:
                return False
        for k in n2:
            if k not in n1 or n2[k] != n1[k]:
                return False 
            
        return True

