class Solution:
    def minDiffInBST(self, root: TreeNode) -> int:
        minDiff = float('inf')
        curr = root
        
        while curr:
            if not curr.left:
                curr = curr.right
            else:
                prev = curr.left
                
                while prev.right and prev.right != curr:
                    prev = prev.right
                    
                if not prev.right:
                    prev.right = curr
                    curr = curr.left
                else:
                    prev.right = None
                    minDiff = min(minDiff, abs(prev.val - curr.val))
                    curr = curr.right
                    
        curr = root
        
        while curr:
            if not curr.right:
                curr = curr.left
            else:
                prev = curr.right
                
                while prev.left and prev.left != curr:
                    prev = prev.left
                    
                if not prev.left:
                    prev.left = curr
                    curr = curr.right
                else:
                    prev.left = None
                    minDiff = min(minDiff, abs(prev.val - curr.val))
                    curr = curr.left
                    
        return minDiff

