class Solution:
    def minDiffInBST(self, root: TreeNode) -> int:
        def inorder(root):
            if not root:
                return []
            return inorder(root.left) + [root.val] + inorder(root.right)

        inorder_list = inorder(root)
        min_diff = float('inf')
        for i in range(1, len(inorder_list)):
            diff = inorder_list[i] - inorder_list[i-1]
            if diff < min_diff:
                min_diff = diff
        return min_diff

