class Solution:
    def canMakePaliQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        n = len(s)
        freq = [[0]*26]
        for i in range(n):
            f = freq[-1][:]
            f[ord(s[i])-97] += 1
            freq.append(f)
        res = []
        for l, r, k in queries:
            if k >= (r-l+1)//2:
                res.append(True)
            else:
                cnt = [freq[r+1][i] - freq[l][i] for i in range(26)]
                odd = sum(i%2 for i in cnt)
                res.append(k >= odd//2)
        return res

