def bit_flip(start, goal):
    start_bin = bin(start)[2:].zfill(32)
    goal_bin = bin(goal)[2:].zfill(32)
    flips = 0
    for i in range(32):
        if start_bin[i] != goal_bin[i]:
            if i < 31 and start_bin[i+1] == goal_bin[i] and start_bin[i] == goal_bin[i+1]:
                start_bin = start_bin[:i] + goal_bin[i] + goal_bin[i+1] + start_bin[i+2:]
            else:
                start_bin = start_bin[:i] + goal_bin[i] + start_bin[i+1:]
            flips += 1
    return flips

def min_seconds_to_fill_cups(amount):
    def time_to_fill(num_cups, fill_rate):
        return (num_cups + fill_rate - 1) // fill_rate
    
    cold = amount[0]
    warm = amount[1]
    hot = amount[2]
    
    time_cold = time_to_fill(cold, 2)
    time_warm = time_to_fill(warm, 2)
    time_hot = time_to_fill(hot, 2)
    
    if cold % 2 == 1 or warm % 2 == 1 or hot % 2 == 1:
        time_single = max(1, time_to_fill(1, (cold%2 + warm%2 + hot%2)))
        return max([time_cold, time_warm, time_hot, time_single])
    
    return max([time_cold//2 + time_warm//2 + time_hot//2, time_cold+time_warm+time_hot])

