import heapq

def max_coin_value(piles, k):
    heap = []
    for pile in piles:
        for coin in reversed(pile):
            if len(heap) < k:
                heapq.heappush(heap, coin)
            elif coin > heap[0]:
                heapq.heappop(heap)
                heapq.heappush(heap, coin)
