class Solution(object):
    def maxDistToClosest(self, seats):
        
        ## Get the length and initialize the prefix and postfix arrays to know the closest person to left and right
        n=len(seats);
        pre,post=[-1]*n,[-1]*n;
        best = 0;
        MAX = 10000000;

        ## If there is a taken/not taken seat at the start, mark pre
        if seats[0] == 1:
            pre[0] = 0;
        else:
            pre[0] = MAX;

        ## If there is a taken/not taken seat at end, mark post
        if seats[n-1] == 1:
            post[n-1] = n-1;
        else:
            post[n-1] = MAX;

        ## Iterate over the seats to populate the pre and post arrays
        for x in range(1,n):
            
            ## If we find someone at the current seat, mark pre at current since we are iterating left to right
            if seats[x] == 1:
                pre[x] = x;
            ## If we don't, take the previous seat value.
            elif pre[x-1] != -1:
                pre[x] = pre[x-1];
            
            ## If we find someone at the current index from the right of the seats, mark post with shifted index.
            if seats[n-1-x] == 1:
                post[n-1-x] = n-1-x;
            ## If we don't, take next seat value
            elif post[n-x] != -1:
                post[n-1-x] = post[n-x];

        ## Iterate through the list
        ## We are trying to find the maximum distance we have from someone.
        ## So we check the minimum distance to someone from our left in pre and our right in post inclusive of current location
        ## It doesn't matter if there's a taken seat at index, it will just be 0
        ## Then we try to maximize that minimum at each location.
        for x in range(n):
            best = max( best, min( abs( x-pre[x] ), abs( x-post[x] ) ) );
            
        ## return answer
        return best;

