from collections import defaultdict, deque

class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: List[int], informTime: List[int]) -> int:
        # Create a dictionary to represent the subordination relationships
        subordinates = defaultdict(list)
        for i in range(n):
            if manager[i] != -1:
                subordinates[manager[i]].append(i)
        
        # Use BFS to traverse the tree and calculate the time needed to inform each employee
        queue = deque([(headID, 0)])
        time_needed = 0
        while queue:
            curr_employee, curr_time = queue.popleft()
            time_needed = max(time_needed, curr_time)
            for subordinate in subordinates[curr_employee]:
                queue.append((subordinate, curr_time + informTime[curr_employee]))
        
        return time_needed

