def productAbbreviation(left: int, right: int) -> str:
    def countTrailingZeros(num: int) -> int:
        count = 0
        while num % 10 == 0:
            count += 1
            num //= 10
        return count, num
    
    def abbreviate(num: int, count: int) -> str:
        num_str = str(num)
        if len(num_str) > 10:
            pre = num_str[:5]
            suf = num_str[-5:].rstrip('0')
            if suf == '':
                suf = '0'
            return pre + '...' + suf + 'e' + str(count)
        else:
            return str(num)
    
    product = 1
    for i in range(left, right+1):
        product *= i
    count, product = countTrailingZeros(product)
    return abbreviate(product, count)

class Solution:
    def earliestDayToBloom(self, n: int, plantTime: List[int], growTime: List[int]) -> int:
        
        def canBloom(day):
            bloom = [0]*n
            for i in range(n):
                if day >= plantTime[i]:
                    if (day-plantTime[i])//growTime[i] + 1 >= n:
                        bloom[i] = 1
            for i in range(n-1):
                if bloom[i] and bloom[i+1]:
                    return True
            return False
        
        left, right = max(plantTime), 10**9 + 1
        while left < right:
            mid = (left + right) // 2
            if canBloom(mid):
                right = mid
            else:
                left = mid + 1
        return left

