class Solution:
    def hasAlternatingBits(self, n: int) -> bool:
	
        #Use bit mask of 0b00000001
        mask = 1;
        
        #Find the starting condition
        #I use == 1 throughout. == 0 would yield the same result
        start = ( ( n &amp; mask ) == 1 );
		
        #bitshift n
        n = n >> 1;

        #Use the starting value as the previous value
        prev = start;
        #While n is greater than zero, we can keep bit shifting it right
        while n > 0:
            
            #Check to see if our mask matches 1 
            check = ( ( n &amp; mask ) == 1 );
            
            #We see if our current check matches the previous
            #If they do, then we return false
            #So if we have   ....00 we would be comparing False == False
            #And if we have  ....11 we would be comparing True == True
            if check == prev:
                return False;
            
            #Otherwise, bitshift n to the right to shrink the number
            n = n >> 1;
            #and update the previous to our current
            prev = check;
            
        #If we make it out of the while loop
        #It means we have processed all of the numbers
        #And they alternated
        return True;

