def is_complete_binary_tree(root): 
    if root is None: 
        return True
  
    queue = [] 
    queue.append(root) 
    is_non_full = False
  
    while len(queue) > 0: 
        current = queue.pop(0) 
  
        if current.left_child: 
            if is_non_full == True: 
                return False
            queue.append(current.left_child) 
        else: 
            is_non_full = True 
        
        if current.right_child: 
            if is_non_full == True: 
                return False
            queue.append(current.right_child) 
        else: 
            is_non_full = True 
        
    return True

