class Solution:
    def bfs(self,root):
        if(root==None):
            return []
        level=0
        queue=deque([(root,0)])
        visited=set()
        hashmap={}
        while queue:
            currentElement,level=queue.popleft()
            if(currentElement not in visited):
                visited.add(currentElement)
                if(level in hashmap):
                    hashmap[level]=max(currentElement.val,hashmap[level])
                else:
                    hashmap[level]=currentElement.val
                if(currentElement.left):
                    queue.append((currentElement.left,level+1))
                if(currentElement.right):
                    queue.append((currentElement.right,level+1))
        return [hashmap[keys] for keys in hashmap]

    def largestValues(self, root: Optional[TreeNode]) -> List[int]:
        return self.bfs(root)

