class Solution:
    def countValidWords(self, sentence: str) -> int:
        hold=sentence.split()        
        res=0
        for i in range(len(hold)):
            w=hold[i]
            w_stat=self.find(w)
            if w_stat['dig'] or len(w_stat['hyp'])>1 or len(w_stat['puc'])>1:
                continue
            if w_stat['hyp']:
                idx=w_stat['hyp'][0]
                if idx-1 not in w_stat['alp'] or idx+1 not in w_stat['alp']:
                    continue
            if w_stat['puc']:
                idx=w_stat['puc'][0]
                if idx!=len(w)-1:
                    continue
            res+=1  
        return res
        
    def find(self,w):
        stat={'alp':[], 'dig':[], 'hyp':[],'puc':[]}
        for i,c in enumerate(w):
            if c.isdigit():
                stat['dig'].append(i)
            elif c.isalpha():
                stat['alp'].append(i)
            elif c in ['!','.',',']:
                stat['puc'].append(i)
            else:
                stat['hyp'].append(i)
        return stat

