def valid_word(word):
    hyphen_count = word.count('-')
    punctuation_count = sum([1 for c in word if c in ['!', '.', ',']])
    lowercase_count = sum([1 for c in word if c.islower()])
    if hyphen_count != 1 or punctuation_count != 1 or lowercase_count == 0:
        return False
    if '-' in word:
        hyphen_index = word.index('-')
        if hyphen_index == 0 or hyphen_index == len(word) - 1:
            return False
        if not (word[hyphen_index - 1].islower() and word[hyphen_index + 1].islower()):
            return False
    if not (word[-1] in ['!', '.', ',']):
        return False
    return True

def count_valid_words(sentence):
    words = sentence.split()
    return sum([1 for word in words if valid_word(word)])

