class Solution:
    def minimumSwap(self, s1: str, s2: str) -> int:
        if s1 == s2:
            return 0
        else:
            count = 0
            d = {('xx','yy'):1,('xy','yx'):2,('yy','xx'):1,('yx','xy'):2}
            x = []
            y = []
            for i,j in zip(s1,s2):
                if i != j:
                    x.append(i)
                    y.append(j)
            x.sort()
            y.sort(reverse=True)
            i,j = 0,0
            if len(x)%2 != 0 or len(y)%2 != 0:
                return -1
            while i < len(x) and j < len(y):
                z = (''.join(x[i:i+2]),''.join(y[i:i+2]))
                if z not in d:
                    return -1
                else:
                    count += d[z]
                i += 2
                j += 2
            return count

