def select_one_index(word):
    freq = frequency_letters(word)
    values = list(freq.values())
    max_value = max(values)
    min_value = min(values)
    if max_value == min_value:
        return True
    elif values.count(max_value) == 1:
        idx = values.index(max_value)
        if values[idx] == min_value + 1 or values[idx] == max_value - 1:
            return True
    elif values.count(min_value) == 1:
        idx = values.index(min_value)
        if values[idx] == max_value or values[idx] == min_value + 1:
            return True
    return False

def split_fibonacci(num):
    res = []
    for i in range(1, len(num)):
        if num[0] == '0' and i > 1:
            break
        a = int(num[:i])
        for j in range(i+1, len(num)):
            if num[i] == '0' and j > i+1:
                break
            b = int(num[i:j])
            res = [a, b]
            k = j
            while k < len(num):
                c = res[-1] + res[-2]
                if c > 2**31-1:
                    break
                c_str = str(c)
                if num[k:].startswith(c_str):
                    res.append(c)
                    k += len(c_str)
                else:
                    break
            if k == len(num) and len(res) >= 3:
                return res
    return []

from collections import deque

def reachableNodes(edges: List[List[int]], maxMoves: int) -> int:
    graph = {}
    for u, v, cnt in edges:
        if u not in graph:
            graph[u] = {}
        if v not in graph:
            graph[v] = {}
        graph[u][v] = graph[v][u] = cnt
    
    visited = set()
    q = deque([(0, maxMoves)])
    count = 0
    
    while q:
        node, moves_left = q.popleft()
        if (node, moves_left) in visited:
            continue
        visited.add((node, moves_left))
        count += 1
        
        if moves_left > 0:
            for neighbor, cnt in graph[node].items():
                # count the nodes reachable using the original edge
                count += min(cnt, moves_left)
                # add the neighbor to the queue with updated moves_left
                q.append((neighbor, moves_left - cnt - 1))
                
        # check for nodes reachable using new edges
        for neighbor, cnt in graph.get(node, {}).items():
            if moves_left > cnt and (neighbor, moves_left - cnt - 1) not in visited:
                count += cnt
                visited.add((neighbor, moves_left - cnt - 1))
                
    return count

def pathInZigZagTree(label: int) -> List[int]:
    level = 1
    while 2 ** level - 1 < label:
        level += 1
    result = [0] * level
    for i in range(level - 1, -1, -1):
        result[i] = label
        label = 2 ** i - 1 - (label - 2 ** i) // 2
    return result

