import heapq

def minStones(piles, k):
    heap = [-p for p in piles]
    heapq.heapify(heap)
    
    for _ in range(k):
        num = -heapq.heappop(heap)
        new_num = num // 2
        heapq.heappush(heap, -new_num)
    
    return -sum(heap)

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def levelOrderBottom(root: TreeNode) -> List[List[int]]:
    if not root:
        return []
    res = []
    queue = []
    queue.append(root)
    while queue:
        size = len(queue)
        tmp = []
        for i in range(size):
            node = queue.pop(0)
            tmp.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        res.append(tmp)
    return res[::-1]

def hash(s, p, m):
    val = lambda x: ord(x) - 96 # mapping letter to alphabet number
    result = 0
    for i in range(len(s)):
        result += val(s[i]) * (p ** i)
    return result % m

def find_substring(power, modulo, k, hashValue, string):
    for i in range(len(string)-k+1):
        sub = string[i:i+k]
        if hash(sub, power, modulo) == hashValue:
            return sub

