def create_stack(target, n):
    stack = []
    operations = []
    num = 1
    for i in range(target):
        if not stack:
            stack.append(num)
            operations.append("Push")
            num += 1
        else:
            if stack[-1] == target - i:
                stack.pop()
                operations.append("Pop")
            else:
                stack.append(num)
                operations.append("Push")
                num += 1
    return operations

class Solution:
    def findLosingPlayers(self, matches: List[List[int]]) -> List[List[int]]:
        lost_matches = {}
        for match in matches:
            winner, loser = match
            if loser not in lost_matches:
                lost_matches[loser] = 1
            else:
                lost_matches[loser] += 1

        lost_once = []
        for player, matches_lost in lost_matches.items():
            if matches_lost == 1:
                lost_once.append(player)

        return [sorted(list(lost_matches.keys())), sorted(lost_once)]

