                return memo[(plot, prev_put)]
            
            cnt = 0
            if prev_put:
                cnt = dfs(plot-1, False)
            else:
                cnt = dfs(plot-1, False)
                cnt += dfs(plot-1, True)
            memo[(plot, prev_put)] = cnt
            return cnt
        
