import heapq

def minimum_maximum_working_time(jobs: List[int], k: int) -> int:
    def is_possible(max_time: int) -> bool:
        cur_worker_time = 0
        worker_count = 1
        for job in jobs:
            if job > max_time:
                return False
            if cur_worker_time + job <= max_time:
                cur_worker_time += job
            else:
                cur_worker_time = job
                worker_count += 1
            if worker_count > k:
                return False
        return True
    
    left, right = max(jobs), sum(jobs)
    while left < right:
        mid = (left + right) // 2
        if is_possible(mid):
            right = mid
        else:
            left = mid + 1
    return left

