def check_rotation(nums):
    n = len(nums)
    if n <= 1:
        return True
    
    i = 0
    while i < n - 1 and nums[i] <= nums[i+1]:
        i += 1
    
    if i == n - 1:
        return True
    
    j = (i + 1) % n
    while j != i:
        if nums[j] < nums[(j-1+n)%n]:
            return False
        j = (j + 1) % n
    
    return True

class Solution:
    def findMin(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]
        left, right = 0, len(nums)-1
        if nums[right] > nums[left]:
            return nums[left]
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] > nums[mid+1]:
                return nums[mid+1]
            if nums[mid] < nums[mid-1]:
                return nums[mid]
            if nums[mid] > nums[0]:
                left = mid + 1
            else:
                right = mid - 1

