import math

def lattice_points(circles):
    result = set()
    for circle in circles:
        x, y, r = circle
        for i in range(x-r, x+r+1):
            for j in range(y-r, y+r+1):
                if math.sqrt((i-x)**2 + (j-y)**2) <= r:
                    result.add((i,j))
    return len(result)

