def findMatchedWords(queries, dictionary):
    def findEditDistance(s1, s2):
        m, n = len(s1), len(s2)
        dp = [[0] * (n+1) for _ in range(m+1)]
        for i in range(m+1):
            dp[i][0] = i
        for j in range(n+1):
            dp[0][j] = j
        for i in range(1, m+1):
            for j in range(1, n+1):
                if s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1]
                else:
                    dp[i][j] = 1 + min(dp[i][j-1], dp[i-1][j], dp[i-1][j-1])
        return dp[m][n]
    
    def isEditDistanceOne(s1, s2):
        if len(s1) != len(s2):
            return False
        count = 0
        for i in range(len(s1)):
            if s1[i] != s2[i]:
                count += 1
            if count > 1:
                return False
        return count == 1
    
    def isEditDistanceTwo(s1, s2):
        if len(s1) != len(s2):
            return False
        count = 0
        for i in range(len(s1)):
            if s1[i] != s2[i]:
                count += 1
            if count > 2:
                return False
        return count == 2
    
    matchedWords = []
    for query in queries:
        for word in dictionary:
            if query == word:
                matchedWords.append(word)
            elif isEditDistanceOne(query, word):
                matchedWords.append(word)
            elif isEditDistanceTwo(query, word) and findEditDistance(query, word) <= 2:
                matchedWords.append(word)
    return matchedWords

