from collections import Counter

def min_consecutive_pairs(cards):
    if len(cards) % 2 != 0:
        return -1

    counter = Counter(cards)
    for card in counter:
        if counter[card] % 2 != 0:
            return -1

    pairs = []
    for i in range(0, len(cards), 2):
        pairs.append((cards[i], cards[i+1]))

    pairs.sort()
    count = 0
    for i in range(len(pairs)):
        if i == 0:
            count += 1
            continue
        if pairs[i][0] != pairs[i-1][0] or pairs[i][1] != pairs[i-1][1]:
            count += 1

    return count

