def min_operations(nums, start, goal):
    queue = [(start, 0)]
    visited = set([start])
    while queue:
        curr, ops = queue.pop(0)
        if curr == goal:
            return ops
        for num in nums:
            add = curr + num
            sub = curr - num
            xor = curr ^ num
            if add <= 1000 and add not in visited:
                visited.add(add)
                queue.append((add, ops+1))
            if sub >= 0 and sub not in visited:
                visited.add(sub)
                queue.append((sub, ops+1))
            if xor not in visited:
                visited.add(xor)
                queue.append((xor, ops+1))
    return -1

def palindrome_possible(a: str, b: str) -> bool:
    for i in range(len(a)+1):
        aprefix = a[:i]
        asuffix = a[i:]
        for j in range(len(b)+1):
            bprefix = b[:j]
            bsuffix = b[j:]
            if (aprefix + bsuffix) == (bprefix + asuffix)[::-1]:
                return True
    return False

def maxSubsequence(nums, queries):
    n = len(nums)
    m = len(queries)

    dp = [[0 for _ in range(n+1)] for _ in range(n+1)]

    for i in range(1, n+1):
        dp[i][i] = nums[i-1]

    for i in range(2, n+1):
        for j in range(1, n-i+2):
            dp[j][j+i-1] = dp[j][j+i-2] + nums[j+i-2]

    ans = []
    for q in queries:
        res = 0
        for i in range(1, n+1):
            for j in range(i, n+1):
                if dp[i][j] <= q:
                    res = max(res, j-i+1)
        ans.append(res)

    return ans

