def findLongestRepeatedSubsequence(s: str, k: int) -> str:
    def isSubsequence(sub: str) -> bool:
        j = 0
        for i in range(len(s)):
            if sub[j] == s[i]:
                j += 1
            if j == len(sub):
                break
        return j == len(sub)
    
    def countOccurrences(sub: str) -> int:
        count = 0
        j = 0
        for i in range(len(s)):
            if sub[j] == s[i]:
                j += 1
            if j == len(sub):
                count += 1
                j = 0
        return count
    
    def getSubsequence(length: int, sub: str) -> str:
        if length == 0:
            return sub
        for i in range(len(s)):
            sub = getSubsequence(length - 1, sub + s[i])
            if countOccurrences(sub) >= k and isSubsequence(sub * k):
                return sub
            else:
                sub = sub[:-1]
        return sub
    
    for length in range(len(s), 0, -1):
        sub = getSubsequence(length, "")
        if countOccurrences(sub) >= k and isSubsequence(sub * k):
            return sub
    return ""

