def min_rounds(tasks):
    sum_difficulty = sum(tasks)
    if sum_difficulty % 2 == 1:
        return -1
    target_difficulty = sum_difficulty // 2
    dp = [float("inf")] * (target_difficulty + 1)
    dp[0] = 0
    for task in tasks:
        for i in range(target_difficulty, task - 1, -1):
            dp[i] = min(dp[i], dp[i - task] + 1)
    return dp[target_difficulty] if dp[target_difficulty] != float("inf") else -1

