class Solution:
    def restoreArray(self, adjacentPairs: List[List[int]]) -> List[int]:
        d = {}
        for i in adjacentPairs:
            if i[0] not in d:
                d[i[0]] = [i[1]]
            else:
                d[i[0]].append(i[1])
                
            if i[1] not in d:
                d[i[1]] = [i[0]]
            else:
                d[i[1]].append(i[0])
        
        start = set(d.keys()) - set([i[1] for i in adjacentPairs])
        res = []
        def dfs(node):
            res.append(node)
            for nei in d[node]:
                d[nei].remove(node)
                if len(d[nei]) == 0:
                    del d[nei]
                    continue
                dfs(nei)
                
        dfs(start.pop())
        return res

def max_sum_rectangle(matrix, k):
    max_sum = float('-inf')
    rows = len(matrix)
    cols = len(matrix[0])
    for left in range(cols):
        temp = [0] * rows
        for right in range(left, cols):
            for i in range(rows):
                temp[i] += matrix[i][right]
            curr_sum = 0
            subarr_max = float('-inf')
            for val in temp:
                curr_sum = max(val, curr_sum + val)
                subarr_max = max(subarr_max, curr_sum)
            if subarr_max == k:
                return k
            elif subarr_max < k:
                max_sum = max(max_sum, subarr_max)
            else:
                temp_sum = float('-inf')
                for i in range(rows):
                    running_sum = 0
                    for j in range(i, rows):
                        running_sum += temp[j]
                        if running_sum > temp_sum and running_sum <= k:
                            temp_sum = running_sum
                        if temp_sum == k:
                            return k
                max_sum = max(max_sum, temp_sum)
    return max_sum

