import math

def find_gcd(nums):
    gcd = nums[0]
    for i in range(1, len(nums)):
        gcd = math.gcd(gcd, nums[i])
    return gcd

def find_smallest(nums):
    return min(nums)

def find_largest(nums):
    return max(nums)

nums = [10, 20, 30, 40, 50]
gcd = find_gcd(nums)
smallest = find_smallest(nums)
largest = find_largest(nums)

print("GCD:", gcd)
print("Smallest:", smallest)
print("Largest:", largest)

