class Solution:
    def maxProfit(self, inventory: List[int], orders: int) -> int:
        inventory.sort(reverse=True)
        inventory.append(0)
        p = 0
        for i in range(10**5):
            if inventory[i]>inventory[i+1]:
                if (i+1)*(inventory[i]-inventory[i+1])>=orders:
                    left, right = inventory[i+1]+1, inventory[i]
                    while left<=right:
                        mid = (left+right)//2
                        numBalls = (inventory[i]-mid+1)*(i+1)
                        if 0<=numBalls-orders<i+1:
                            k = numBalls-orders
                            p += ((inventory[i]+mid)*(inventory[i]-mid+1)//2)*(i+1)-(k*mid)
                            return p%1000000007
                        elif numBalls<orders:
                            right = mid-1
                        else:
                            left = mid+1
                else:
                    orders -= (i+1)*(inventory[i]-inventory[i+1])
                    p += ((inventory[i]+inventory[i+1]+1)*(inventory[i]-inventory[i+1])//2)*(i+1)

class Solution:
    def sortByBits(self, arr: List[int]) -> List[int]:
        bin_dict = {}
        count_dict = {}
        for num in arr:
            bin_dict[num] = str(bin(num)[2:]).count('1')
            count_dict[num] = count_dict.get(num,0) + 1
            
        bin_dict = dict(sorted(bin_dict.items(), key= lambda x : x[1]))
        final_arr = []
        lst = []
        last = None
        for key,val in bin_dict.items():
            if last == None:
                lst = lst + [key] * count_dict.get(key)
                last = val
            elif last == val:
                lst = lst + [key] * count_dict.get(key)
                last = val
            else:
                final_arr = final_arr + sorted(lst)
                lst = []
                lst = lst + [key] * count_dict.get(key)
                last = val
        
        return final_arr + sorted(lst)

class Solution:
    def shortestSequence(self, rolls: List[int], k: int) -> int:
        s = set()
        res = 0
        
        for r in rolls:
            s.add(r)
            if len(s) == k:        # All possible number has appeared once.
                res += 1           # So you must "at least" use one more place to store it.
                s.clear()          # Clear the set.
        
        
        return res + 1

class Solution:
    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        # n = no. of nodes in directed graph -> ( 0 to n - 1 )
        # each edge is either red or blue
        # there can be self edges and parallel edges
        # given two arrays :
        # 1. redEdges[i] = [a,b] means there is redEdge from a to b
        # 2. blueEdge[i] = [a,b] means there is blueEdge from a to b
        # return answer of length n where answer[x] is length of shortest path ..
        # from node 0 to node x such that the edge colors alternate along the path ...
        # -1 if papth does not exist
        canGo = defaultdict(list)
        red,blue = {},{}
        for i,j in redEdges:
            red[(i,j)] = True
            canGo[i].append(j)
        for i,j in blueEdges:
            blue[(i,j)] = True
            canGo[i].append(j)
        ans =[-1]*n
        ans[0] = 0
        
        for target in range(1,n):
            queue = [(0,0,None)]
            visited = {(0,None):True}
            while queue:
                node,dis,color = queue.pop(0)
                if node == target:
                    ans[target] = dis
                    break
                for nodes in canGo[node]:
                    b,r = (node,nodes) in blue, (node,nodes) in red
                    if color == 1:
                        # we can go with r
                        if r == False or (nodes,0) in  visited: continue
                        visited[(nodes,0)] = True
                        queue.append((nodes,dis+1,0))
                    elif color == 0:
                        # we can go with b
                        if b == False or (nodes,1) in visited: continue
                        visited[(nodes,1)] = True
                        queue.append((nodes,dis+1,1))
                    else:
                        # we can go with any of them
                        if r == True and (nodes,0) not in visited:
                            visited[(nodes,0)] = True
                            queue.append((nodes,dis+1,0))
                        if b == True and (nodes,1) not in visited:
                            visited[(nodes,1)] = True
                            queue.append((nodes,dis+1,1))
        return ans

