from collections import deque

def shortestAlternatingPaths(n: int, red_edges: List[List[int]], blue_edges: List[List[int]]) -> List[int]:
    red_adj_list = [[] for _ in range(n)]
    blue_adj_list = [[] for _ in range(n)]
    
    for u, v in red_edges:
        red_adj_list[u].append(v)
    for u, v in blue_edges:
        blue_adj_list[u].append(v)
    
    result = [-1]*n
    result[0] = 0
    
    def bfs(color):
        queue = deque([(0, 0)])
        visited = set()
        visited.add((0, color))
        steps = 0
        
        while queue:
            size = len(queue)
            
            for _ in range(size):
                node, prev_color = queue.popleft()
                
                for neighbor in (red_adj_list[node] if color == 'blue' else blue_adj_list[node]):
                    if (neighbor, color) not in visited:
                        visited.add((neighbor, color))
                        queue.append((neighbor, color))
                        
                        if result[neighbor] == -1:
                            result[neighbor] = steps + 1
                        elif (steps+1)%2 != (result[neighbor]%2):
                            result[neighbor] = steps + 1
            
            steps += 1
            
        return
                        
    bfs('red')
    bfs('blue')
    
    return result

