class Solution:
    
    
    def findLowPosition(self, low: int, hi: int, nums: List[int], target: int) -> int:
        ans = low
        
        while low <= hi:
            mid = (low+hi)//2

            if target >= nums[mid]:
                low = mid+1
            else:
                ans = mid
                hi = mid-1
        
        return ans
    
    
    
    def findHighPosition(self, low: int, hi: int, nums: List[int], target: int) -> int:
        ans = hi
        
        while low <= hi:
            mid = (low+hi)//2
            
            if target > nums[mid]:
                ans = mid
                low = mid+1
            else:
                hi = mid-1
        
        return ans
    
    
    # O(n) time,
    # O(1) space,
    # Approach: binary search,
    def findUnsortedSubarray(self, nums: List[int]) -> int:
        
        smallest = None
        end_of_sort1 = 0
        is_sorted = True
        
        for index in range(1, len(nums)):
            if nums[index] < nums[index-1]:
                if is_sorted:
                    is_sorted = False
                    smallest = nums[index]
                    end_of_sort1 = index-1
                else:
                    if nums[index] < smallest:
                        smallest = nums[index]
                        
        largest = None
        end_of_sort2 = 0
        is_sorted = True
        
        for index in range(len(nums)-2, -1, -1):
            if nums[index] > nums[index+1]:
                if is_sorted:
                    is_sorted = False
                    largest = nums[index]
                    end_of_sort2 = index+1
                else:
                    if nums[index] > largest:
                        largest = nums[index]
        
        if is_sorted:
            return 0
        
        start = self.findLowPosition(0, end_of_sort1, nums, smallest)
        end = self.findHighPosition(end_of_sort2, len(nums)-1, nums, largest)
        
        return end-start+1

