MOD = 10 ** 9 + 7

def num_ways(n, k):
    dp = [0 for _ in range(k+1)]
    dp[0] = 1
    for i in range(1, n+1):
        for j in range(1, k+1):
            dp[j] += dp[j//i]
            dp[j] %= MOD
    return dp[k]

def ways_to_place_integers(queries):
    result = []
    for query in queries:
        n, k = query
        result.append(num_ways(n, k))
    return result

