def largest_submatrix(matrix):
    num_rows, num_cols = len(matrix), len(matrix[0])
    max_area = 0
    for col_order in itertools.permutations(range(num_cols)):
        col_idx = {old_col: new_col for new_col, old_col in enumerate(col_order)}
        cols = [[matrix[row][col_idx[col]] for col in range(num_cols)] for row in range(num_rows)]
        for i in range(num_rows):
            for j in range(num_cols):
                if cols[i][j] == 1:
                    k = i
                    while k < num_rows and cols[k][j] == 1:
                        k += 1
                    max_area = max(max_area, (k-i)*(j+1))
    return max_area

def check_string(s):
    count_a = 0
    count_b = 0
    for ch in s:
        if ch == 'a':
            count_a += 1
        elif ch == 'b':
            count_b += 1
        if count_b > count_a:
            return False
    return count_a == count_b

