class Solution:
    def mergeTriplets(self, triplets: List[List[int]], target: List[int]) -> bool:
        possible_triplets = []

        for triplet in triplets:
            if triplet[0] <= target[0] and triplet[1] <= target[1] and triplet[2] <= target[2]:
                possible_triplets.append(triplet)

        x_possible = [triplet for triplet in possible_triplets if triplet[0] == target[0]]
        y_possible = [triplet for triplet in possible_triplets if triplet[1] == target[1]]
        z_possible = [triplet for triplet in possible_triplets if triplet[2] == target[2]]

        for x_triplet in x_possible:
            for y_triplet in y_possible:
                if y_triplet[0] >= x_triplet[0] and y_triplet[1] >= x_triplet[1]:
                    for z_triplet in z_possible:
                        if z_triplet[0] >= y_triplet[0] and z_triplet[1] >= y_triplet[1] and z_triplet[2] >= x_triplet[2]:
                            return True

        return False

