def partition_groups(s, k, fill):
    groups = []
    last_group = len(s) % k
    for i in range(0, len(s), k):
        group = s[i:i+k]
        if len(group) < k:
            group += fill * (k - len(group))
        groups.append(group)
    if last_group > 0:
        groups[-1] = groups[-1].rstrip(fill)
    return groups

