class Solution:
    def numberOfPairs(self, a: List[int], b: List[int], diff: int) -> int:
        l = len(a)
        c = [0] * l
        for i in range(l):
            c[i] = a[i] - b[i]
        
        minc = min(c)
        if minc <= 0:
            for i in range(l):
                c[i] = c[i] - minc + 1 # shift up to make sure all numbers are positive

        BIG = max(c)+abs(diff)+1
        t = [0] * (BIG+1)
        
        def update(c):
            while c <= BIG:
                t[c] += 1
                c += c &amp; -c
                
        def count(c):
            r = 0
            while c > 0:
                r += t[c]
                c -= c &amp; -c
            return r
        
        r = 0
        for i in range(l):
            r += count(c[i]+diff)
            update(c[i])
        
        return r

