def words_from_puzzle(puzzles, words):
    def count(s):
        # count the frequency of each character in s
        freq = [0] * 26
        for ch in s:
            freq[ord(ch) - ord('a')] += 1
        return freq

    # count the frequency of each character in each puzzle
    freqs = [count(p) for p in puzzles]

    # keep track of valid words for each puzzle
    ans = [0] * len(puzzles)

    # loop through each word and puzzle
    for i in range(len(puzzles)):
        for j in range(len(words)):
            # check if word first letter is in puzzle and all the letters in word are
            # in puzzle
            if words[j][0] == puzzles[i][0] and all(freqs[i][ord(ch) - ord('a')] >= words[j].count(ch) for ch in words[j]):
                ans[i] += 1

    return ans

