def uncover_artifacts(n, artifacts, dig):
    grid = [[0 for _ in range(n)] for _ in range(n)]
    for r1, c1, r2, c2 in artifacts:
        for i in range(r1, r2+1):
            for j in range(c1, c2+1):
                grid[i][j] += 1
    
    uncovered_artifacts = set()
    for r, c in dig:
        if grid[r][c] > 0:
            grid[r][c] = 0
            uncovered_artifacts.add(grid[r][c])
            for i in range(r-1, r+2):
                for j in range(c-1, c+2):
                    if i >= 0 and j >= 0 and i < n and j < n and grid[i][j] > 0:
                        uncovered_artifacts.add(grid[i][j])
                        grid[i][j] = 0
    
    return len(uncovered_artifacts)

