class Solution:
	#Function for checking number of different characters in both hashmap. if both are same return True else False
    def compare(self):
        dist1,dist2 = 0,0
        for key in self.first.keys():
            if key not in self.second:
                dist1 += 1
        for key in self.second.keys():
            if key not in self.first:
                dist2 += 1
        return True if dist1 == dist2 else False
    def numSplits(self, s: str) -> int:
        if len(s) == 1:
            return 0
        count = 0
        self.first = {}
        self.second = {}
        for i in range(len(s)):
            if(not self.first and not self.second):
                self.first = collections.Counter(s[:i+1])
                self.second = collections.Counter(s[i+1:])
            else:
                if s[i] in self.first:
                    self.first[s[i]] = self.first[s[i]] + 1
                else:
                    self.first[s[i]] = 1
                if self.second[s[i]] is not None and self.second[s[i]] <= 1:
                    self.second.pop(s[i])
                else:
                    self.second[s[i]] -= 1
            check = self.compare()
            if check:
                count += 1
        return count

class Solution:
    def __init__(self):
        self.res = 0
        self.word2score = collections.defaultdict(int)
    
    def is_key_valid(self, key, latters_key):
        for k in key:
            if k not in latters_key or key[k] > latters_key[k]:
                return False
        
        return True
    
    def get_word_score(self, key, score):
        cur_score = 0
        for k in key:
            cur_score += score[ord(k) - 97] * key[k]
        
        return cur_score
                
    
    def backtracking(self, words, word2key, latters_key, score, cur_sum_score):
        for i in range(len(words)):
            if self.is_key_valid(word2key[words[i]], latters_key):
                if words[i] not in self.word2score:
                    self.word2score[words[i]] = self.get_word_score(word2key[words[i]], score)
                    
                for c in words[i]:
                    latters_key[c] -= 1
                
                
                self.backtracking(words[:i] + words[i+1:], word2key, latters_key, score, [cur_sum_score[0] + self.word2score[words[i]]])
                
                for c in words[i]:
                    latters_key[c] += 1
                    
        self.res = max(self.res, cur_sum_score[0])
            
            
    def maxScoreWords(self, words: List[str], letters: List[str], score: List[int]) -> int:
        letters_key = collections.defaultdict(int)
        for c in letters:
            letters_key[c] += 1
        
        word2key = {}
        for word in words:
            key = collections.defaultdict(int)
            for c in word:
                key[c] += 1
            
            word2key[word] = key
        
        
        self.backtracking(words, word2key, letters_key, score, [0])
        
        return self.res

class Solution:
    def __init__(self):
        self.stack = []
        self.toRemove = 0
        
    def mostCompetitive(self, nums: List[int], k: int) -> List[int]:
        self.stack.append(nums[0])
        self.toRemove = len(nums) - k
        
        for i in range(1,len(nums)):
            while(self.stack and self.toRemove>0 and self.stack[-1]>nums[i]):
                self.toRemove -= 1
                self.stack.pop()
            self.stack.append(nums[i])
            
        while(self.toRemove>0 or len(self.stack)>k):
            self.toRemove -= 1
            self.stack.pop()
        return self.stack

