def transform(string):
    result = ""
    for letter in string:
        result += str(ord(letter)-96)
    return result

def sum_digits(num):
    return sum(int(digit) for digit in str(num))

def k_transform(string, k):
    for i in range(k):
        string = transform(string)
        num = int(string)
        string = str(sum_digits(num))
    return int(string)

def max_tasks_completed(tasks, workers, pills, strength):
    sorted_tasks = sorted(tasks)
    sorted_workers = sorted(workers)
    sorted_pills = sorted(pills, reverse=True)

    num_tasks_completed = 0
    for task in sorted_tasks:
        for i, worker in enumerate(sorted_workers):
            if worker >= task:
                sorted_workers.pop(i)
                num_tasks_completed += 1
                break
        else: # if no worker found
            for i, p in enumerate(sorted_pills):
                if strength + p >= task:
                    sorted_pills.pop(i)
                    num_tasks_completed += 1
                    break
            else: # if no worker or pill found
                break

    return num_tasks_completed

def max_consecutive_robots(n, chargeTimes, runningCosts, budget):
    l, r = 0, n
    max_consec = 0
    while l <= r:
        mid = (l + r) // 2
        costs = []
        for i in range(n - mid + 1):
            costs.append(max(chargeTimes[i:i+mid]) + mid * sum(runningCosts[i:i+mid]))
        if max(costs) <= budget:
            max_consec = mid
            l = mid + 1
        else:
            r = mid - 1
    return max_consec

