def max_subsequence(p: str, s: str, removable: List[int]) -> int:
    left = 0
    right = len(removable)
    while left <= right:
        mid = (left + right) // 2
        indices_to_remove = set(removable[:mid])
        i, j = 0, 0
        while i < len(p) and j < len(s):
            if p[i] == s[j] and i not in indices_to_remove:
                j += 1
            i += 1
        if j == len(s):
            left = mid + 1
        else:
            right = mid - 1
    return right

class Solution:
    def countStudents(self, students: List[int], sandwiches: List[int]) -> int:
        queue = students
        stack = sandwiches
        unable_to_eat = 0
        
        while queue:
            if queue[0] == stack[-1]:
                queue.pop(0)
                stack.pop()
                unable_to_eat = 0
            else:
                queue.append(queue.pop(0))
                unable_to_eat += 1
            
            if unable_to_eat == len(queue):
                return unable_to_eat
        
        return unable_to_eat

