class Solution:
    def movesToMakeZigzag(self, nums: List[int]) -> int:
        if len(nums) <= 2:
            return 0
        
        # check for even-indexed elements
        even_moves = 0
        for i in range(0, len(nums), 2):
            left = nums[i-1] if i > 0 else float('inf')
            right = nums[i+1] if i < len(nums)-1 else float('inf')
            target = min(left, right) - 1
            if nums[i] > target:
                even_moves += nums[i] - target
        
        # check for odd-indexed elements
        odd_moves = 0
        for i in range(1, len(nums), 2):
            left = nums[i-1] if i > 0 else float('inf')
            right = nums[i+1] if i < len(nums)-1 else float('inf')
            target = min(left, right) - 1
            if nums[i] > target:
                odd_moves += nums[i] - target
        
        return min(even_moves, odd_moves)

