def maxCandies(status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
    boxes = set(initialBoxes)
    candies_collected = 0
    keys_collected = set()
    while boxes:
        box = boxes.pop()
        if status[box] == 1 or box in keys_collected:
            candies_collected += candies[box]
            keys_collected.update(keys[box])
            boxes.update(containedBoxes[box])
        else:
            boxes.add(box)
    return candies_collected

