def k_distant_indices(nums, k, key):
    result = []
    for i in range(len(nums)):
        for j in range(max(0, i - k), min(len(nums), i + k + 1)):
            if nums[j] == key and abs(i - j) <= k:
                result.append(j)
                break
    result.sort()
    return result

