def evaluate_string(s, knowledge):

    knowledge_dict = dict(knowledge)
    str_lst = list(s)
    open_bracket = False
    current_key = ''
    
    for i in range(len(str_lst)):
        if str_lst[i] == "(":
            open_bracket = True
        elif str_lst[i] == ")":
            open_bracket = False
            if current_key in knowledge_dict:
                str_lst[i-len(current_key)-1:i+1] = knowledge_dict[current_key]
            else:
                str_lst[i-len(current_key)-1:i+1] = "?"
            current_key = ""
        elif open_bracket:
            current_key += str_lst[i]
    return "".join(str_lst)

