class Solution:
    def maxScore(self, s: str) -> int:
        max_score = 0
        for i in range(1, len(s)):
            zeros = s[:i].count('0')
            ones = s[i:].count('1')
            max_score = max(max_score, zeros+ones)
        return max_score

