def min_swaps(n, grid):
    count = 0
    for i in range(n):
        if grid[i][i] == 1:
            for j in range(i + 1, n):
                if grid[j][i] == 0 and grid[i][j] == 0:
                    grid[i], grid[j] = grid[j], grid[i]
                    count += 1
                    break
            else:
                return -1
    return count

