class Solution:
    def bstToGst(self, root: TreeNode) -> TreeNode:
        stack = [root]
        values = []
        
        def inorder(node):
            if node:
                inorder(node.left)
                values.append(node.val)
                inorder(node.right)
                
        inorder(root)
        prefix = [0]
        for val in values:
            prefix.append(prefix[-1] + val)
        s = sum(values)
     
        d = {}
        
        for i in range(len(values)):
            val = values[i]
            d[val] = i 
        
        stack = [root]
        while stack:
            node = stack.pop()
            node.val = s - prefix[d[node.val]]
            if node.left:
                stack.append(node.left)
            if node.right:
                stack.append(node.right)
            
        return root

