def max_points_gain(s: str, x: int, y: int, number: int) -> int:

    def remove_ab(s: str) -> Tuple[str, int]:
        points = 0
        while "ab" in s:
            s = s.replace("ab", "", 1)
            points += x
        return s, points

    def remove_ba(s: str) -> Tuple[str, int]:
        points = 0
        while "ba" in s:
            s = s.replace("ba", "", 1)
            points += y
        return s, points

    max_points = 0
    for i in range(number+1):
        s_temp = s
        points = 0
        for j in range(i):
            s_temp, p = remove_ab(s_temp)
            points += p
        for k in range(number-i):
            s_temp, p = remove_ba(s_temp)
            points += p
        max_points = max(max_points, points)
    return max_points

class Solution:
    def __init__(self):
        self.graph = defaultdict(list)
        self.res = float('inf')

    def minimumXORSum(self, nums: List[int], edges: List[List[int]]) -> int:
        
        for a, b in edges:
            self.graph[a].append(b)
            self.graph[b].append(a)
        
        total = sum(nums)
        self.dfs(nums, 0, total)
        
        return self.res
    
    def dfs(self, nums, node, total):
        visited = set()
        queue = deque([[node, 0]])
        
        while queue:
            curr, xorVal = queue.popleft()
            visited.add(curr)
            xorVal ^= nums[curr]
            
            if len(visited) == len(nums):
                self.res = min(self.res, total - 2 * xorVal)
            
            for neighbor in self.graph[curr]:
                if neighbor not in visited:
                    queue.append([neighbor, xorVal])

