def closest_sum(arr, target):
    diff = target - sum(arr) 
    arr.sort(reverse=True)
    idx = 0
    while diff > 0:
        if idx < len(arr) and arr[idx] - 1 >= diff:
            arr[idx] -= diff
            diff = 0
        else:
            diff -= (arr[idx] - 1)
            arr[idx] = 1
            idx += 1
    return sum(arr)

