def interval_queries(intervals, queries):
    result = []
    for query in queries:
        smallest = float('inf')
        for interval in intervals:
            if interval[0] <= query <= interval[1]:
                smallest = min(smallest, interval[1] - interval[0] + 1)
        result.append(-1 if smallest == float('inf') else smallest)
    return result

