def count_squares(matrix):
    count = 0
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    count += 1
                else:
                    val = min(matrix[i-1][j], matrix[i][j-1], matrix[i-1][j-1]) + matrix[i][j]
                    count += val
                    matrix[i][j] = val
    return count

class Solution:
    def networkBecomesIdle(self, edges: List[List[int]], patience: List[int]) -> int:
        n = len(patience)
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        dist = [float("inf") for _ in range(n)]
        dist[0] = 0
        q = deque([0])
        while q:
            node = q.popleft()
            for nei in graph[node]:
                if dist[node] + 1 < dist[nei]:
                    dist[nei] = dist[node] + 1
                    q.append(nei)
        
        time = 0
        for i in range(1, n):
            t = 2 * dist[i]
            while t < patience[i]:
                t += 2 * dist[i]
            time = max(time, t)
        return time + 1

