class Solution:
    def minDominoRotations(self, A: List[int], B: List[int]) -> int:
        if not(A and B):
            return 0
		# A set that store the first dominoe
		# One of them must appears in all dominoes
        ab0 = (A[0], B[0])
		# Count the number of A[0] appears [ top half, bottom half ]
        a0 = [1,0]
		# Count the number of B[0] appears [ top half, bottom half ]
        b0 = [0,1]
        
        length = len(A)
        
        for i in range(1,length):
			# If A[0] doesn't exist in both A and B in i-th index
			# That number cannot form a equal row
            if ab0[0] != A[i] and ab0[0] != B[i]:
                a0 = [0]
			# If B[0] doesn't exist in both A and B in i-th index
			# That number cannot form a equal row
            if ab0[1] != A[i] and ab0[1] != B[i]:
                b0 = [0]
			# If both A[0] and B[0] are not possible to form equal row, End of world :)
            if a0 == [0] and b0 == [0]:
                return -1
			# Below just do the count of A[0]/B[0] occurance in row A/B
            if a0 != [0] and A[i] == ab0[0]:
                a0[0] += 1
            if a0 != [0] and B[i] == ab0[0]:
                a0[1] += 1
            if b0 != [0] and A[i] == ab0[1]:
                b0[0] += 1
            if b0 != [0] and B[i] == ab0[1]:
                b0[1] += 1
        
        return length-max(max(a0),max(b0))

