class Solution:
    def sum_subtree(self, root):
        if not root:
            return [0, 0]
        left_sum, left_count = self.sum_subtree(root.left)
        right_sum, right_count = self.sum_subtree(root.right)
        total_sum = root.val + left_sum + right_sum
        total_count = 1 + left_count + right_count
        return [total_sum, total_count]

    def find_nodes(self, root, total_sum, total_count):
        if not root:
            return 0
        current_sum = root.val
        current_count = 1
        if root.left:
            current_sum += self.find_nodes(root.left, total_sum, total_count)
            current_count += self.sum_subtree(root.left)[1]
        if root.right:
            current_sum += self.find_nodes(root.right, total_sum, total_count)
            current_count += self.sum_subtree(root.right)[1]
        avg = round(total_sum / total_count)
        if current_sum == avg * current_count:
            return current_count
        return 0

    def equalToAverge(self, root: TreeNode) -> int:
        total_sum, total_count = self.sum_subtree(root)
        res = self.find_nodes(root, total_sum, total_count)
        return res

