def split_max_unique_even(finalSum):
    def generate_splits(current_sum, start_num, remaining_nums):
        if current_sum == finalSum:
            all_splits.append(split_so_far)
            return
        if current_sum > finalSum or not remaining_nums:
            return
        # Add the next even number
        if start_num % 2 == 0:
            generate_splits(current_sum + start_num, start_num + 2, remaining_nums - 1)
        # Skip the next odd number
        generate_splits(current_sum, start_num + 1, remaining_nums)
    all_splits = []
    for num_evens in range(1, finalSum // 2 + 1):
