def countPaths(n: int, roads: List[List[int]]) -> int:
    graph = defaultdict(list)
    for u, v, t in roads:
        graph[u].append((v, t))
        graph[v].append((u, t))
    
    dist = [float('inf')] * n
    ways = [0] * n
    dist[0] = 0
    ways[0] = 1
    
    heap = [(0, 0)]
    while heap:
        d, node = heappop(heap)
        if d > dist[node]:
            continue
        for neighbor, time in graph[node]:
            if dist[node] + time < dist[neighbor]:
                dist[neighbor] = dist[node] + time
                ways[neighbor] = ways[node]
                heappush(heap, (dist[neighbor], neighbor))
            elif dist[node] + time == dist[neighbor]:
                ways[neighbor] = (ways[neighbor] + ways[node]) % MOD
    
    return ways[n-1]

class Solution:
    def shipWithinDays(self, weights: List[int], days: int) -> int:
        left, right = max(weights), sum(weights)
        
        while left < right:
            mid = (left + right) // 2
            curr_weight = 0
            needed_days = 1
            
            for weight in weights:
                if curr_weight + weight > mid:
                    needed_days += 1
                    curr_weight = 0
                curr_weight += weight
            
            if needed_days <= days:
                right = mid
            else:
                left = mid + 1
                
        return left

