class Solution:
def deleteMiddle(self, head: Optional[ListNode]) -> Optional[ListNode]:
    
    if head.next == None:
        return None
    elif head.next.next == None:
        head.next = None
        return head
    else:
        
        slow = head
        fast = head.next.next
        
        while(fast != None):
            
            fast = fast.next
            if fast == None:
                slow.next = slow.next.next
                return head
            fast = fast.next
            slow = slow.next
        
        slow.next = slow.next.next
        return head

