class Node:
    def __init__(self, val, prev=None, next=None, child=None):
        self.val = val
        self.prev = prev
        self.next = next
        self.child = child

def flatten(head):
    if not head:
        return None
    
    stack = [head]
    prev = Node(None)
    
    while stack:
        curr = stack.pop()
        
        if curr.next:
            stack.append(curr.next)
        if curr.child:
            stack.append(curr.child)
            curr.child = None
        
        curr.prev = prev
        prev.next = curr
        prev = curr
    
    head.prev = None
    
    return head

