class Solution:
    def sortEvenOdd(self, nums: List[int]) -> List[int]:
        self.evencount(nums)
        self.oddcount(nums)
        return nums
        
    def evencount(self, arr: List[int]) -> List[int]:
        valToFre = [0] * 101
        for i in range(0, len(arr), 2):
            valToFre[arr[i]] += 1
        i = 0
        for val, fre in enumerate(valToFre):
            times = fre
            while times:
                arr[i] = val
                times -= 1
                i += 2
        return arr
    
    def oddcount(self, arr: List[int]) -> List[int]:
        valToFre = [0] * 101
        for i in range(1, len(arr), 2):
            valToFre[arr[i]] += 1
        val = 100
        i = 1
        while val >= 0:
            fre = valToFre[val]
            while fre:
                arr[i] = val
                fre -= 1
                i += 2
            val -= 1
        return arr

class Solution:
    def largestComponentSize(self, nums: List[int]) -> int:
        
