class Solution:
    def largestComponentSize(self, nums: List[int]) -> int:
        def gcd(a, b):
            if b == 0:
                return a
            return gcd(b, a % b)
        
        uf = {}
        def find(x):
            uf.setdefault(x, x)
            if uf[x] != x:
                uf[x] = find(uf[x])
            return uf[x]
        
        prime_factors = {}
        def get_prime_factors(num):
            if num in prime_factors:
                return prime_factors[num]
            res = set()
            for i in range(2, num+1):
                if i * i > num:
                    break
                if num % i == 0:
                    res.add(i)
                    res |= get_prime_factors(num // i)
                    break
            if not res:
                res.add(num)
            prime_factors[num] = res
            return res
        
        for num in nums:
            factors = get_prime_factors(num)
            for f in factors:
                uf.setdefault(num, num)
                uf.setdefault(f, f)
                uf[find(num)] = find(f)
        
        cnt = {}
        for num in nums:
            f = find(num)
            cnt.setdefault(f, 0)
            cnt[f] += 1
        
        return max(cnt.values())

def min_flips(a: int, b: int, c: int) -> int:
    xor = b ^ c
    count = 0
    while xor:
        if xor & 1:
            if c & 1:
                count += 1
            elif a & 1:
                count += 1
        xor >>= 1
        a >>= 1
        b >>= 1
        c >>= 1
    return count

