# Python code for finding the largest color value valid path

from collections import defaultdict

def largest_color_value(n: int, colors: str, edges: List[List[int]]) -> int:
    # Create graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
    
    # DFS traversal to find the maximum color value
    visited = [0] * n
    color_counts = [0] * 26
    max_color_count = 0  # maximum color value found so far
    def dfs(node):
        nonlocal max_color_count
        visited[node] = 1
        color_counts[ord(colors[node]) - 97] += 1  # add color count for current node
        max_color_count = max(max_color_count, color_counts[ord(colors[node]) - 97])  # update max color value
        for neighbor in graph[node]:
            if visited[neighbor] == 0:
                dfs(neighbor)
            elif visited[neighbor] == 1:
                return -1  # cycle detected
        visited[node] = 2
    
    # Call DFS on every node
    for i in range(n):
        if visited[i] == 0:
            if dfs(i) == -1:
                return -1  # cycle detected
    return max_color_count

