import heapq
def kthSmallest(matrix, k):
    n = len(matrix)
    min_heap = []
    for i in range(n):
        heapq.heappush(min_heap, (matrix[0][i], 0, i))
    count = 0
    while min_heap:
        val, row, col = heapq.heappop(min_heap)
        count += 1
        if count == k:
            return val
        if row < n-1:
            heapq.heappush(min_heap, (matrix[row+1][col], row+1, col))

