class Solution:
    def maxScore(self, cardPoints: List[int], k: int) -> int:
        n = len(cardPoints)
        left_sum = [0] * (k + 1)
        right_sum = [0] * (k + 1)
        for i in range(1, k + 1):
            left_sum[i] = left_sum[i - 1] + cardPoints[i - 1]
            right_sum[i] = right_sum[i - 1] + cardPoints[n - i]
        max_score = 0
        for i in range(k + 1):
            max_score = max(max_score, left_sum[i] + right_sum[k - i])
        return max_score

