def replace_non_digits(word):
    digits = []
    updated_word = ""
    for char in word:
        if char.isdigit():
            updated_word += char
        else:
            updated_word += " "
    integers = updated_word.split()
    for integer in integers:
        if integer not in digits:
            digits.append(integer)
    return len(digits)

def is_balanced(num):
    for i in str(num):
        if i != str(num).count(i) * i:
            return False
    return True

def next_balanced_number(n):
    n += 1
    while not is_balanced(n):
        n += 1
    return n

