def minObstacles(grid):
    m = len(grid)
    n = len(grid[0])
    dp = [[float('inf') for j in range(n)] for i in range(m)]
    dp[0][0] = 0 if grid[0][0] == 0 else 1
    for i in range(1, m):
        dp[i][0] = dp[i-1][0] if grid[i][0] == 0 else dp[i-1][0]+1
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] if grid[0][j] == 0 else dp[0][j-1]+1
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1])
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + 1
    return dp[-1][-1]

def remove_minimum_parentheses(string):
    stack = []
    removals = set()
    for i, char in enumerate(string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if not stack:
                removals.add(i)
            else:
                stack.pop()
    removals = removals.union(stack)
    result = ''
    for i in range(len(string)):
        if i not in removals:
            result += string[i]
    return result

