class Solution:
    def numberOfWays(self, corridor: str) -> int:

        # go through the corridor and count seats
        # after that check whether there are plants
        # and we have several places to divide

        # go through the chairs and count
        chairs = 0
        positions = 1
        plants = 1
        for idx, element in enumerate(corridor):

            # check if we reached two chairs
            if chairs > 0 and chairs % 2 == 0:

                # check if current element is plant
                if element == 'S':
                    positions *= plants
                    plants = 1
                
                elif element == 'P':
                    plants += 1

            # count the chairs
            if element == 'S':
                chairs += 1
        return (positions % 1_000_000_007) if chairs > 0 and chairs % 2 == 0 else 0

class Solution:
    def secondMinimum(self, n: int, edges: List[List[int]], time: int, change: int) -> int:
        g = defaultdict(set)
        for u, v in edges:
            g[u].add(v)
            g[v].add(u)              
        
        q = deque([(1, 0)])
        # to store the two minimum node counts for each visited node
        vis = defaultdict(set, {0: {0}})
        minval = set()
        while q:
            node, cnt = q.popleft()
            if node == n:
                minval.add(cnt)
                if len(minval) == 2: break
            for nei in g[node]:
                if len(vis[nei]) > 1 and cnt + 1 >= max(vis[nei]): continue
                vis[nei] = {min(vis[nei])} | {cnt + 1} if vis[nei] else {cnt + 1}
                q.append((nei, cnt + 1))
        
        minval = sorted(minval)
        def helper(nodes):
            t = 0
            while nodes > 0:
                t += time
                nodes -= 1
                if nodes == 0: break
                # if current time exceeds change and change frequency is odd
                if t >= change and (t // change) % 2:
                    t = (t // change + 1) * change
            return t
        
        if len(minval) == 1:
            return helper(minval[0] + 2)
        
        # either use the 2nd minimum path or the 1st path add two more nodes (like example 2)
        return min(helper(minval[0]+2), helper(minval[1]))

