def secondMinTime(n: int, edges: List[List[int]], time: int, change: int) -> int:

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    
    dists = [float('inf')] * (n+1)
    dists[1] = 0
    
    def get_time(u: int, v: int, curr_time: int) -> int:
        if (curr_time // change) % 2 == 1:
            curr_time += change - (curr_time % change)
        return curr_time + time
    
    heap = [(0, 1)]
    while heap:
        curr_dist, curr_node = heappop(heap)
        if curr_node == n:
            return curr_dist
        for neighbor in graph[curr_node]:
            time_to_neighbor = get_time(curr_node, neighbor, curr_dist)
            if time_to_neighbor < dists[neighbor]:
                dists[neighbor] = time_to_neighbor
                heappush(heap, (dists[neighbor], neighbor))
    
    return -1

