def sufficient_nodes(root, limit):
    if not root:
        return None
    root.left = sufficient_nodes(root.left, limit - root.val)
    root.right = sufficient_nodes(root.right, limit - root.val)
    if not root.left and not root.right:
        return None if root.val < limit else root
    return root

