class Solution:
    def zigzagLevelOrder(self, root):
        if not root:
            return []
        queue, result, level = [root], [], 1
        while queue:
            cur_level, size = [], len(queue)
            for i in range(size):
                node = queue.pop(0)
                cur_level.append(node.val)
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            if level % 2 == 0:
                cur_level.reverse()
            result.append(cur_level)
            level += 1
        return result

