class Solution:
    def lcaDeepestLeaves(self, root: TreeNode) -> TreeNode:
        import collections
        class DSU:
            def __init__(self):
                self._to_parent = dict()
                self._to_lvl = dict()
            
            def make(self, x, lvl):
                self._to_parent[x] = x
                self._to_lvl[x] = lvl
            
            def lvl(self, x):
                return self._to_lvl[x]
            
            def find(self, x):
                if self._to_parent[x] is x:
                    return x
                self._to_parent[x] = self.find(self._to_parent[x])
                return self._to_parent[x]
            
            def union(self, x, y):
                import random
                x_mark = self.find(x)
                y_mark = self.find(y)
                if random.randint(0, 1):
                    self._to_parent[x_mark] = y_mark
                else:
                    self._to_parent[y_mark] = x_mark
        
        dsu = DSU()
        to_parent = dict()
        q = collections.deque()
        to_parent[root] = None
        q.appendleft((root, 0))
        deepest_leaves = []
        max_lvl = -1
        while len(q) > 0:
            v, lvl = q.pop()
            if max_lvl < lvl:
                max_lvl = lvl
                deepest_leaves = [v]
            else:
                deepest_leaves.append(v)
                
            for ch in (v.left, v.right):
                if ch is not None:
                    to_parent[ch] = v
                    q.appendleft((ch, lvl+1))
        
        node = deepest_leaves[0]
        dsu.make(node, max_lvl)
        lvl = max_lvl
        while node is not None:
            prev = node
            node = to_parent[node]
            lvl -= 1
            
            def dfs(v):
                if v is None or v is prev:
                    return
                
                dsu.make(v, lvl)
                if v is not node:
                    dsu.union(node, v)
                dfs(v.left)
                dfs(v.right)
            dfs(node)
        
        target_lvl = min(dsu.lvl(leave) for leave in deepest_leaves)
        lvl = max_lvl
        node = deepest_leaves[0]
        while lvl != target_lvl:
            lvl -= 1
            node = to_parent[node]
        return node

GPT Answer:
def lcaDeepestLeaves(root):
    def depth(node):
        if not node: return 0
        return 1 + max(depth(node.left), depth(node.right))
    
    def lca(node, d):
        if not node or depth(node) == d: return node
        
        left, right = lca(node.left, d), lca(node.right, d)
        if left and right: return node
        return left or right
    
    d = depth(root)
    return lca(root, d)

