class Solution:
    def threeWayPartition(self, nums: List[int], pivot: int) -> None:
        less = 0
        equal = 0
        greater = len(nums) - 1
        
        while equal <= greater:
            if nums[equal] < pivot:
                nums[less], nums[equal] = nums[equal], nums[less]
                less += 1
                equal += 1
            elif nums[equal] == pivot:
                equal += 1
            else:
                nums[equal], nums[greater] = nums[greater], nums[equal]
                greater -= 1

