    def kidsWithCandies(self, candies: List[int], extraCandies: int) -> List[bool]:
        
        #Find the current non adjust max number of candies
        non_adjusted_max = max( candies );
        
        LENGTH = len ( candies );
        
        
        #Make an array for each kid at index i
        bool_array = [ None for _ in range( LENGTH  ) ];
        
        
        #Go through each candy count
        for i in range( LENGTH ):
            
            #Adjust the current number by the extra candies
            current_adjusted = candies[ i ] + extraCandies;
            
            #See if the adjusted is greater than the max
            #If it is, set the bool_array at the ith index to True
            if current_adjusted >= non_adjusted_max:
                bool_array[ i ] = True;
            #Otherwise, set it to False
            else:
                bool_array[ i ] = False;
        return bool_array;

