def maxAbsDiff(nums):
    n = len(nums)
    ans = 0
    for i in range(n-1):
        ans += abs(nums[i] - nums[i+1])
    best = 0
    for i in range(1, n):
        if nums[i] < nums[i-1]:
            best = max(best, ans - 2*abs(nums[i-1] - nums[i]))
    if best != 0:
        reverseSubarray(nums, 0, n-1)
        for i in range(1, n):
            if nums[i] < nums[i-1]:
                best = max(best, ans - 2*abs(nums[i-1] - nums[i]))
        ans = best
    return ans

