from typing import List

def rhombus_sum(grid: List[List[int]]) -> List[int]:
    n = len(grid)
    m = len(grid[0])
    rhombus_sums = set()
    for i in range(n):
        for j in range(m):
            for k in range(1, n, 2):
                for l in range(1, m, 2):
                    if i-k+1>=0 and i+k< n and j-l+1>=0 and j+l<m:
                        rhombus_sum = sum(grid[i-k+1][j:j+l+1]) + sum(grid[i+k][j:j+l+1]) + \
                                     sum(grid[i-k+1:i+1:k][j-l+1]) + sum(grid[i-k+1:i+1:k][j+l])
                        rhombus_sums.add(rhombus_sum)
    return sorted(list(rhombus_sums), reverse=True)[:3]

