class Solution:
    def numSubarrayBoundedMax(self, nums: List[int], left: int, right: int) -> int:
        def count(max_val):
            res, cur = 0, 0
            for num in nums:
                cur = cur + 1 if num <= max_val else 0
                res += cur
            return res
        
        return count(right) - count(left - 1)

def max_substrings(text):
    def is_valid(substrings):
        if not substrings:
            return False
        full_text = ''.join(substrings)
        return full_text == text and all(len(substring) >= 1 for substring in substrings) and substrings[0] == substrings[-1] + 1

    for k in range(len(text), 0, -1):
        for substrings in itertools.combinations(text, k):
            if is_valid(substrings):
                return k

    return 0

def numSubmatrixSumTarget(matrix: List[List[int]], target: int) -> int:
    n, m = len(matrix), len(matrix[0])
    for i in range(n):
        for j in range(1, m):
            matrix[i][j] += matrix[i][j-1]
    res = 0
    for i in range(m):
        for j in range(i, m):
            preSum = {0: 1}
            cur = 0
            for k in range(n):
                cur += matrix[k][j] - (matrix[k][i-1] if i > 0 else 0)
                res += preSum.get(cur - target, 0)
                preSum[cur] = preSum.get(cur, 0) + 1
    return res

def is_possible_split(nums):
    start = None
    seq_len = 0
    for i in range(len(nums)):
        if start is None:
            start = i
            seq_len = 1
        elif nums[i] == nums[i-1]+1:
            seq_len += 1
        else:
            if seq_len >= 3:
                start = i - 1
                seq_len = 2
            else:
                start = i
                seq_len = 1
    return seq_len >= 3

