class Solution:
    def minimumDeletions(self, s: str) -> int:
        # consider each index as b start
        # count left_a, left_b, right_a, right_b on L/R at each point
        # num_changes = left_b + right_a
        counts = {}
        n = len(s)
        left_a, left_b, right_a, right_b = 0, 0, s.count('a'), s.count('b')
        for i in range(n):
            counts[i] = (left_a, left_b, right_a, right_b)
            if s[i] == 'a':
                left_a += 1
                right_a -= 1
            elif s[i] == 'b':
                left_b += 1
                right_b -= 1
        counts[n] = (left_a, left_b, right_a, right_b)
        min_changes = float('inf')
        for i in range(n + 1):
            left_b, right_a = counts[i][1], counts[i][2]
            min_changes = min(min_changes, left_b + right_a)
        return min_changes

