def min_deletions(s):
    n = len(s)
    a_count = b_count = 0
    for i in range(n):
        if s[i] == 'a':
            a_count += 1
        elif s[i] == 'b':
            b_count += 1
    
    if a_count != b_count:
        return abs(a_count - b_count)
    
    a_indices = []
    b_indices = []
    for i in range(n):
        if s[i] == 'a':
            a_indices.append(i)
        elif s[i] == 'b':
            b_indices.append(i)
    
    min_deletions = 0
    j = 0
    for i in range(len(a_indices)):
        while j < len(b_indices) and b_indices[j] < a_indices[i]:
            j += 1
        if j == len(b_indices):
            break
        min_deletions += b_indices[j] - a_indices[i] - 1
    return min_deletions

def delete_and_divide(nums, numsDivide):
    min_num_deletions = float('inf')
    for num in nums:
        num_deletions = 0
        for n in numsDivide:
            if n % num != 0:
                num_deletions += 1
        min_num_deletions = min(min_num_deletions, num_deletions)
    if min_num_deletions == len(numsDivide):
        return -1
    return min_num_deletions

