def longest_subarray(nums):
    max_and = max(nums)
    while max_and:
        count = 0
        for num in nums:
            if num & max_and == max_and:
                count += 1
            else:
                count = 0
            if count == 2:
                return 2
        if count == 1:
            return 1
        max_and &= (max_and - 1)
    return 0

