class Solution:
    def findLengthOfLCIS(self, nums: List[int]) -> int:
        
        #Get the length
        LENGTH = len ( nums );
        
        #Keep track of the max and the current streak
        maxStreak = 1;
        streak = 1;
        
        #Point at the first index
        pointer = 1;
        
        #Because previous starts out at the zeroth index
        prev = nums[ 0 ];
        while pointer < LENGTH:
            #Use the pointer to get the current value
            current = nums[ pointer ];
            
            #Check the current against the previous value
            if current > prev:
                streak += 1;
            else:
                streak = 1;
                
            #Update the streak
            maxStreak = max( streak, maxStreak );
            
            #Update the previous to current and increment the pointer
            prev = current;
            pointer += 1;
        
        #Return the max
        return maxStreak;

