def findLengthOfLCIS(nums):
    if len(nums) == 0:
        return 0
    max_length = 1
    length = 1
    for i in range(1, len(nums)):
        if nums[i] > nums[i-1]:
            length += 1
        else:
            max_length = max(max_length, length)
            length = 1
    return max(max_length, length)

from collections import Counter

def balance_string(s: str) -> int:
    count = Counter(s)
    n = len(s)
    target = {'Q': n//4, 'W': n//4, 'E': n//4, 'R': n//4}
    if count == target:
        return 0
    
    i = 0
    res = n
    for j in range(n):
        target[s[j]] -= 1
        while i <= j and all(c <= 0 for c in target.values()):
            res = min(res, j-i+1)
            target[s[i]] += 1
            i += 1
            
    return res

import heapq

def kthSmallestProduct(nums1, nums2, k):
    min_heap = []
    for i in nums1:
        for j in nums2:
            heapq.heappush(min_heap, i * j)
    
    for _ in range(k-1):
        heapq.heappop(min_heap)
    
    return heapq.heappop(min_heap)

