class Solution:
    def sortedListToBST(self, head: Optional[ListNode]) -> Optional[TreeNode]:
        # I have taken a dummy node of value 69 and we will return tree.left which is our actual root
        tree = TreeNode(69)
        def helper(start,tree, isLeft):
            if start is None:
                return 
            
            prev, slow, fast = None, start, start
            while fast and fast.next:
                prev = slow
                slow = slow.next
                fast = fast.next.next
            startOne = None if start == slow else start
            startTwo = slow.next
            slow.next = None
            if prev:
                prev.next = None
            if isLeft:
                tree.left = TreeNode(slow.val)
            if not isLeft:
                tree.right = TreeNode(slow.val)
            if tree.left and isLeft:
                helper(startOne, tree.left, True)
                helper(startTwo, tree.left, False)
            if tree.right and not isLeft:
                helper(startOne, tree.right, True)
                helper(startTwo, tree.right, False)
        helper(head, tree, True)
        return tree.left

