class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def sortedListToBST(head):
    if not head:
        return None
    
    if not head.next:
        return TreeNode(head.val)
    
    # find the middle of the linked list
    slow, fast = head, head.next.next
    while fast and fast.next:
        fast = fast.next.next
        slow = slow.next
    
    # create a treeNode with middle val
    curr = TreeNode(slow.next.val)
    # break linked list into two smaller lists
    right_head = slow.next.next
    slow.next = None
    
    # recursively create left and right subtrees
    curr.left = sortedListToBST(head)
    curr.right = sortedListToBST(right_head)
    
    return curr

def minDeletions(nums):
    deletions = 0
    for i in range(len(nums)):
        if i % 2 == 0:
            if nums[i] % 2 == 0:
                deletions += 1
        else:
            if nums[i] % 2 != 0:
                deletions += 1
    return deletions

