class Solution:
    def sumEvenGrandparent(self, root: TreeNode) -> int:
		#global variable to count values
        self.c = 0
        def rec(root):
            if root:
			   #check if value is even
                if root.val%2==0:
					#find the values of grandchildren
                    k = value(root)
                    self.c+=k
                rec(root.left)
                rec(root.right)
                            
        def value(root):
            temp = 0
			#check if the root has has left present so it doesn't return None
            if root.left:
                if root.left.left:
                    temp+=root.left.left.val
                if root.left.right:
                    temp+=root.left.right.val
			#check if the root has has left present so it doesn't return None
            if root.right:
                if root.right.left:
                    temp+=root.right.left.val
                if root.right.right:
                    temp+=root.right.right.val
            return temp
                
        rec(root)
        return self.c

