def sum_even_grandparent(root):
    def dfs(node, parent, grandparent):
        if not node:
            return 0
        val = dfs(node.left, node.val, parent) + dfs(node.right, node.val, parent)
        if grandparent and grandparent % 2 == 0:
            val += node.val
        return val
    return dfs(root, None, None)

