def minKBitFlips(nums, k):
    n = len(nums)
    flip = [0] * n
    res = cnt = 0
    
    for i in range(n):
        if i >= k:
            cnt -= flip[i-k]
        if cnt % 2 == nums[i]:
            if i + k > n:
                return -1
            res += 1
            cnt += 1
            flip[i] = 1
    
    return res

def countWeakCharacters(properties):
    count = 0
    for i in range(len(properties)):
        for j in range(len(properties)):
            if properties[i][0] < properties[j][0] and properties[i][1] < properties[j][1]:
                count += 1
                break
    return count

def max_distance(nums1, nums2):
    i = j = max_dist = 0
    while i < len(nums1) and j < len(nums2):
        if nums1[i] <= nums2[j]:
            max_dist = max(max_dist, j - i)
            j += 1
        else:
            i += 1
    return max_dist

