def min_moves(nums: List[int], limit: int) -> int:
    complement_dict = {}
    count = 0
    for i in range(len(nums)//2):
        complement = limit - abs(nums[i] - nums[-i-1])
        if complement not in complement_dict:
            complement_dict[complement] = 0
        complement_dict[complement] += 1
        min_val = min(nums[i], nums[-i-1])
        max_val = max(nums[i], nums[-i-1])
        if min_val + complement <= limit:
            complement_dict[limit - min_val - complement] -= 1
        if max_val + complement <= limit:
            complement_dict[limit - max_val - complement] -= 1
        count += 1
    res = float('inf')
    cur_count = 0
    for k, v in complement_dict.items():
        cur_count += v
        res = min(res, cur_count)
    return res

