class Solution:
    def verticalTraversal(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return [[]]  # if root is null, return empty list
        
        queue = deque()
        dict = defaultdict(list) # just an ordinary dictionary/hashmap
        queue.append([root, 0, 0]) # Appending [node, coloumn, row] in queue
        leftMost, rightMost = 0, 0 # to determine the leftmost and rightmost coloumn number
        
        while queue:
            node, col, row = queue.popleft()
            dict[col].append([row, node.val]) # on the key of coloumn, we are appending values like [row, node value]
            
            if node.left:
                queue.append([node.left, col-1, row+1])
                leftMost = min(leftMost, col - 1) # Getting the left most coloumn number
            if node.right:
                queue.append([node.right, col+1, row+1])
                rightMost = max(rightMost, col + 1) # Getting the right most coloumn number
        
        ans = [] # Initializing the answer list
        
        for i in range(leftMost, rightMost+1):
            if dict[i]: # Checking if this coloumn has any value
                dict[i] = sorted(dict[i], key= lambda x: (x[0], x[1])) # sorting the values firstly with respect to level and after that with respect to node value
                tempArr = []
                for j in dict[i]:
                    tempArr.append(j[1]) # appending node values in temporary array
                ans.append(tempArr) # appending temporary array values in answer array
        return ans

