def can_construct(target: List[int], n: int) -> bool:
    arr = [1] * n
    while sum(arr) != sum(target):
        x = sum(arr)
        if x >= n:
            return False
        arr[x] = target[x] - sum(arr[:x] + arr[x+1:])
    return True

