def get_lexicographically_smallest(n, k):
    # create a list of tuples containing the numeric value and corresponding alphabet character
    chars = [(i + 1, chr(ord('a') + i)) for i in range(26)]
    # create a list of lists to store all possible combinations of characters with length n
    combinations = [[]]
    # loop through each character in the alphabet
    for value, char in chars:
        # loop through each combination in the list of combinations
        for i in range(len(combinations)):
            # get the sum of the numeric values of the characters in the combination
            total_value = sum([c[0] for c in combinations[i]])
            # if the sum plus the current character's value equals k
            if total_value + value == k:
                # add the character to the end of the current combination
                combinations[i].append((value, char))
            # if the sum plus the current character's value is less than k
            elif total_value + value < k:
                # create a new combination with the current character and add it to the list of combinations
                new_combination = combinations[i] + [(value, char)]
                combinations.append(new_combination)
    # sort the list of combinations lexicographically
    combinations.sort()
    # return the lexicographically smallest combination with length n
    for combination in combinations:
        if len(combination) == n:
            return ''.join([c[1] for c in combination])

