def countOrders(n: int, prevRoom: List[int]) -> int:
    dp = [1] * (n+1)
    for i in range(2, n+1):
        for j in range(1, i):
            if prevRoom[i-1] == j-1:
                dp[i] = (dp[i] + dp[j]*dp[i-j]) % MOD
    return dp[n]

