def swap(num):
    num = str(num)
    even = []
    odd = []
    for i in num:
        if int(i) % 2 == 0:
            even.append(i)
        else:
            odd.append(i)
    if len(even) == 0 or len(odd) == 0:
        return int(num)
    else:
        max_even = max(even)
        min_odd = min(odd)
        max_even_index = num.rfind(max_even)
        min_odd_index = num.rfind(min_odd)
        num_list = list(num)
        num_list[max_even_index] = min_odd
        num_list[min_odd_index] = max_even
        return int(''.join(num_list))

from collections import defaultdict
import heapq

def minFuel(seats, n, roads):
    graph = defaultdict(list)
    for road in roads:
        graph[road[0]].append((road[1], abs(road[0]-road[1])))
        graph[road[1]].append((road[0], abs(road[0]-road[1])))
    
    heap = [(0,0)] #(fuel, node)
    visited = set()
    
    while heap:
        cur_fuel, cur_node = heapq.heappop(heap)
        if cur_node == 0:
            return cur_fuel
        
        visited.add(cur_node)
        for neighbor, dist in graph[cur_node]:
            if neighbor not in visited:
                fuel = (dist - 1) // seats + 1
                heapq.heappush(heap, (cur_fuel + fuel, neighbor))

