def min_skips(hoursBefore: int, dist: List[int], speed: int, meeting: int) -> int:
    total_time = sum([d / speed for d in dist])
    rest_time = sum([math.ceil(d / speed) - d / speed for d in dist[:-1]])
    if total_time + rest_time > hoursBefore + meeting:
        return -1
    skips = 0
    curr_time = 0
    for i in range(len(dist)):
        curr_time += dist[i] / speed
        wait_time = math.ceil(curr_time) - curr_time
        if wait_time > 0:
            if skips == len(dist) - 1:
                curr_time -= wait_time
            else:
                if curr_time + wait_time + sum([math.ceil(d / speed) for d in dist[i+1:]]) <= hoursBefore + meeting:
                    curr_time += wait_time
                    skips += 1
                else:
                    curr_time -= wait_time
    return skips

