        for i in range(len(nums)):
            if nums[i] > mid:
                return -1
            if count + nums[i] <= mid:
                count += nums[i]
            else:
                moves += 1
                count = nums[i]
        moves += 1
        if moves > k:
            low = mid
        else:
            high = mid - 1
    return low

