def max_num_of_substrings(target: str) -> int:
    dic = {}
    for i in range(len(target)):
        if target[i] not in dic:
            dic[target[i]] = []
        dic[target[i]].append(i)
    res = []
    for arr in dic.values():
        j = arr[0]
        for k in range(1, len(arr)):
            if arr[k] != arr[k - 1] + 1:
                res.append((j, arr[k - 1]))
                j = arr[k]
        res.append((j, arr[-1]))
    while True:
        to_remove = []
        for i in range(len(res)):
            for j in range(i + 1, len(res)):
                if res[j][0] <= res[i][1] and res[i][0] <= res[j][1]:
                    if res[i][1] - res[i][0] >= res[j][1] - res[j][0]:
                        to_remove.append(i)
                    else:
                        to_remove.append(j)
        if not to_remove:
            break
        to_remove = set(to_remove)
        new_res = []
        for i in range(len(res)):
            if i not in to_remove:
                new_res.append(res[i])
        res = new_res
    return len(res)

def max_sum(nums):
