def smallestChair(times: List[List[int]], targetFriend: int) -> int:
    import heapq
    arrivals = [(t[0], i) for i, t in enumerate(times)]
    heapq.heapify(arrivals)
    chairs = []
    for i in range(len(times)):
        chairs.append(i)
    occupied = {}
    while arrivals:
        _, friend = heapq.heappop(arrivals)
        if friend == targetFriend:
            return chairs.pop(0)
        if occupied:
            chair = min(occupied, key=occupied.get)
            chairs.append(occupied[chair])
            del occupied[chair]
        chairs.sort()
        occupied[chairs[0]] = friend
    return -1

