class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None
        self.next = None
        
def connect(root: Node) -> Node:
    if root is None:
        return root
    
    leftmost = root
    while leftmost.left:
        curr = leftmost
        while curr:
            curr.left.next = curr.right
            if curr.next:
                curr.right.next = curr.next.left
            curr = curr.next
        leftmost = leftmost.left
    return root

def countPaths(m, n, grid, k):
    MOD = 10**9 + 7
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1
    for i in range(m):
        for j in range(n):
            if i > 0:
                dp[i][j] += dp[i-1][j]
            if j > 0:
                dp[i][j] += dp[i][j-1]
            if i > 0 or j > 0:
                dp[i][j] %= MOD
            if dp[i][j] % k == 0 and (i != m-1 or j != n-1):
                dp[i][j] = 0
    return dp[m-1][n-1] % MOD

