def num_pairs_divisible_by_k(nums: List[int], k: int) -> int:
    count = 0
    mod_counts = [0] * k
    
    for num in nums:
        mod_counts[num % k] += 1
        
    for i in range(1, k//2):
        count += mod_counts[i] * mod_counts[k-i]
        
    count += (mod_counts[0] * (mod_counts[0]-1)) // 2
    if k % 2 == 0:
        count += (mod_counts[k//2] * (mod_counts[k//2]-1)) // 2
        
    return count

