def min_days_to_disconnect(grid):
    # find the position of all 1's in the grid
    ones = []
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                ones.append((i,j))
    
    # check if the grid is already disconnected
    count = 0
    visited = set()
    for i,j in ones:
        if (i,j) not in visited:
            count += 1
            dfs(i,j,visited,grid)
    if count > 1:
        return 0
    
    # try changing each land cell to water and check if the grid becomes disconnected
    for i,j in ones:
        grid[i][j] = 0
        count = 0
        visited = set()
        for r,c in ones:
            if grid[r][c] == 1 and (r,c) not in visited:
                count += 1
                dfs(r,c,visited,grid)
        if count > 1:
            grid[i][j] = 1
        else:
            return 1
    return 2

# helper function to perform dfs traversal
def dfs(i,j,visited,grid):
    visited.add((i,j))
    if i > 0 and grid[i-1][j] == 1 and (i-1,j) not in visited:
        dfs(i-1,j,visited,grid)
    if i < len(grid)-1 and grid[i+1][j] == 1 and (i+1,j) not in visited:
        dfs(i+1,j,visited,grid)
    if j > 0 and grid[i][j-1] == 1 and (i,j-1) not in visited:
        dfs(i,j-1,visited,grid)
    if j < len(grid[0])-1 and grid[i][j+1] == 1 and (i,j+1) not in visited:
        dfs(i,j+1,visited,grid)

