def concatenate_binary(n):
    MOD = 10**9+7
    binary = ""
    for i in range(1, n+1):
        binary += bin(i)[2:]
    return int(binary, 2) % MOD

def longest_word(dict, string):
    longest = ""
    for word in dict:
        if all(char in word for char in string) and len(word) > len(longest):
            longest = word
        if all(char in word for char in string) and len(word) == len(longest) and word < longest:
            longest = word
    return longest.translate({ord(char): None for char in string}) if longest else ""

def smallest_subsequence(s):
    stack = []
    seen = set()
    for i, char in enumerate(s):
        if char not in seen:
            while stack and char < stack[-1] and s.find(stack[-1], i) != -1:
                seen.remove(stack.pop())
            seen.add(char)
            stack.append(char)
    return ''.join(stack)

def min_elements(nums, limit, goal):
    total = sum(nums)
    diff = abs(goal - total)
    count = 0
    if diff == 0:
        return count
    
    nums.sort(key=abs, reverse=True)
    for num in nums:
        if abs(total + num - goal) < diff:
            total += num
            diff = abs(goal - total)
            count += 1
        if diff == 0:
            return count
        
    return count

import math

def countPoints(points, queries):
    answer = []
    for query in queries:
        count = 0
        for point in points:
            if math.sqrt((point[0] - query[0])**2 + (point[1] - query[1])**2) <= query[2]:
                count += 1
        answer.append(count)
    return answer

