class Solution:
    def removeStones(self, stones: List[List[int]]) -> int:
        graph = defaultdict(list)
        for i, (x1, y1) in enumerate(stones):
            for j in range(i):
                x2, y2 = stones[j]
                if x1 == x2 or y1 == y2:
                    graph[i].append(j)
                    graph[j].append(i)
        visited = [False] * len(stones)
        def dfs(node):
            visited[node] = True
            count = 1
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    count += dfs(neighbor)
            return count 
        ans = 0
        for i in range(len(stones)):
            if not visited[i]:
                ans += dfs(i) - 1
        return ans

def smallestDivisor(nums: List[int], threshold: int) -> int:
    def division_sum(divisor: int) -> int:
        return sum([(num-1) // divisor + 1 for num in nums])
    
    left, right = 1, max(nums)
    while left < right:
        mid = (left + right) // 2
        if division_sum(mid) > threshold:
            left = mid + 1
        else:
            right = mid
    return left

