import heapq

def get_k_items(grid, pricing, start, k):
    low, high = pricing
    heap = []
    visited = set()
    heapq.heappush(heap, (0, -grid[start[0]][start[1]], start[0], start[1]))
    while heap:
        distance, price, row, col = heapq.heappop(heap)
        if grid[row][col] > 1 and low <= grid[row][col] <= high:
            visited.add((row, col))
            if len(visited) == k:
                break
        for dx, dy in [(0,1), (1,0), (0,-1), (-1,0)]:
            new_row, new_col = row + dx, col + dy
            if 0 <= new_row < len(grid) and 0 <= new_col < len(grid[0]) and grid[new_row][new_col] != 0 and (new_row, new_col) not in visited:
                heapq.heappush(heap, (distance+1, -grid[new_row][new_col], new_row, new_col))
    return sorted(list(visited))

