class Solution:
    def areNumbersAscending(self, s: str) -> bool:
        def getTokens(s):
            i = 0
            currentToken = []
            while i < len(s):
                if s[i] != ' ':
                    currentToken.append(s[i])
                else:
                    yield ''.join(currentToken)
                    currentToken = []

                i += 1
            
            if currentToken:
                yield ''.join(currentToken)
                
        
        prev = None
        for token in getTokens(s):
            try:
                num = int(token)
            except:
                continue

            if prev:
                if num <= prev:
                    return False

            prev = num
        
        return True

