from collections import defaultdict, deque

def sort_items(n, m, group, beforeItems):
    # build the graph
    graph = defaultdict(list)
    in_degree = [0] * n
    for i in range(n):
        for j in beforeItems[i]:
            graph[j].append(i)
            in_degree[i] += 1
    
    # perform topological sorting for each group
    sorted_items = []
    for g in range(m):
        group_items = [i for i in range(n) if group[i] == g]
        group_graph = defaultdict(list)
        group_in_degree = [0] * len(group_items)
        for i in group_items:
            for j in beforeItems[i]:
                if group[j] == g:
                    group_graph[j].append(i)
                    group_in_degree[group_items.index(i)] += 1
        q = deque([i for i in group_items if group_in_degree[group_items.index(i)] == 0])
        while q:
            curr = q.popleft()
            sorted_items.append(curr)
            for neighbor in group_graph[curr]:
                idx = group_items.index(neighbor)
                group_in_degree[idx] -= 1
                if group_in_degree[idx] == 0:
                    q.append(neighbor)
    
    # check if all items were sorted
    if len(sorted_items) != n:
        return []
    
    return sorted_items

from typing import List

def longest_working_employee(logs: List[List[int]]) -> int:
    employee_times = {}
    for log in logs:
        employee = log[0]
        time = log[1]
        if employee in employee_times:
            employee_times[employee] += time
        else:
            employee_times[employee] = time
    max_time = max(employee_times.values())
    employees_with_max_time = []
    for employee in employee_times:
        if employee_times[employee] == max_time:
            employees_with_max_time.append(employee)
    return min(employees_with_max_time)

