def max_non_empty_substrings(s, c):
    count = 0
    substrings = []
    for i in range(len(s)):
        for j in range(i+1, len(s)+1):
            if c in s[i:j]:
                substrings.append(s[i:j])
    substrings = sorted(substrings, key=len)
    while substrings:
        count += 1
        i = 0
        while i < len(substrings)-1:
            if substrings[i][-1] >= substrings[i+1][0]:
                substrings.pop(i+1)
            else:
                i += 1
    return count

