def displayTable(orders):
    table_items = {}
    for order in orders:
        table_number = int(order[1])
        item = order[2]
        if table_number in table_items:
            table_items[table_number].append(item)
        else:
            table_items[table_number] = [item]

    all_items = set()
    for table_item in table_items.values():
        for item in table_item:
            all_items.add(item)
    
    header = sorted(['Table'] + list(all_items))
    result = [header]
    
    for table_number in sorted(table_items.keys()):
        row_items = table_items[table_number]
        row_items_count = {item: str(row_items.count(item)) for item in all_items}
        
        row = [str(table_number)]
        for item in header[1:]:
            row.append(row_items_count.get(item, '0'))
            
        result.append(row)
        
    return result

