def minCost(startPos, homePos, rowCosts, colCosts):
    m, n = len(rowCosts), len(colCosts)
    dp = [[float('inf')] * n for _ in range(m)]
    dp[startPos[0]][startPos[1]] = 0
    
    for i in range(startPos[0]+1, m):
        dp[i][startPos[1]] = dp[i-1][startPos[1]] + rowCosts[i-1]
    for i in range(startPos[0]-1, -1, -1):
        dp[i][startPos[1]] = dp[i+1][startPos[1]] + rowCosts[i]
    for j in range(startPos[1]+1, n):
        dp[startPos[0]][j] = dp[startPos[0]][j-1] + colCosts[j-1]
    for j in range(startPos[1]-1, -1, -1):
        dp[startPos[0]][j] = dp[startPos[0]][j+1] + colCosts[j]
        
    for i in range(startPos[0]+1, m):
        for j in range(n):
            dp[i][j] = min(dp[i][j], dp[i-1][j] + rowCosts[i-1], dp[i][j-1] + colCosts[j-1], dp[i][j+1] + colCosts[j])
    for i in range(startPos[0]-1, -1, -1):
        for j in range(n):
            dp[i][j] = min(dp[i][j], dp[i+1][j] + rowCosts[i], dp[i][j-1] + colCosts[j-1], dp[i][j+1] + colCosts[j])
            
    return dp[homePos[0]][homePos[1]]

