class Solution:
    def maxSumTwoNoOverlap(self, A: List[int], L: int, M: int) -> int:
        n = len(A)
        left_max_l = [-float("inf") for _ in range(n)]
        right_max_l = [-float("inf") for _ in range(n)]
        #maximum L subarrays from left
        cur = ma = sum(A[: L])
        for i in range(L - 1, len(A)):
            if i > L -1:
                cur += A[i] - A[i - L]
            ma = max(ma, cur)
            left_max_l[i] = ma
        #maximum L subarrays from right
        cur = ma = sum(A[n - L:])
        for i in range(n - L, -1, -1):
            if i < n - L:
                cur += A[i] - A[i + L]
            ma = max(cur, ma)
            right_max_l[i] = ma
        
        left_max = -float("inf")
        right_max = -float("inf")
        res = -float("inf")
        cur = sum(A[: M])
        #scan over all M subarrays, look for its left and right max L subarrays
        for i in range(M - 1, n):
            if i > M - 1:
                cur += A[i] - A[i - M]
            if M + L - 1 <= i <= n - L - 1 :
                left_max = left_max_l[i - M]
                right_max = right_max_l[i + 1]
                res = max(res, cur + max(left_max, right_max))
            elif M + L - 1 <= i:
                res = max(res, cur + left_max_l[i - M])
            elif i <= n - L - 1:
                res = max(res, cur + right_max_l[i + 1])
        
        return res

class Solution:
    def minimumMoves(self, grid: List[List[int]]) -> int:
        n = len(grid)
        
        def findNeighbors(head, state):
            actual = []
            x, y = head
            if state == 'H':
                # go right when horizontal
                if y + 1 <= n - 1 and grid[x][y + 1] == 0:
                    actual.append((x, y + 1, 'H'))
                    
                # go down when horizontal
                if x + 1 <= n - 1 and grid[x + 1][y] == 0 and grid[x + 1][y - 1] == 0:
                    actual.append((x + 1, y, 'H'))
                    
                    # can rotate clkwise here
                    actual.append((x + 1, y - 1, 'V'))
                    
            else:
                # go down when vertical
                if x + 1 <= n - 1 and grid[x + 1][y] == 0:
                    actual.append((x + 1, y, 'V'))
                    
                # go right when vertical
                if y + 1 <= n - 1 and grid[x][y + 1] == 0 and grid[x - 1][y + 1] == 0:
                    actual.append((x, y + 1, 'V'))
                    
                    # can rotate anti clkwise here
                    actual.append((x - 1, y + 1, 'H'))
                    
            return actual
        
        visited = set()
        q = deque()
        q.append((0, 1, 'H', 0))
        
        while q:
            x, y, state, dist = q.popleft()
            if (x, y, state) == (n - 1, n - 1, 'H'):
                return dist
            
            if (x, y, state) in visited:
                continue
                
            visited.add((x, y, state))
            
            for nx, ny, ndir in findNeighbors((x, y), state):
                q.append((nx, ny, ndir, dist + 1))
                
        return -1

