def minimum_moves(grid):
    n = len(grid)
    moves = [[float('inf') for _ in range(n)] for _ in range(n)]
    moves[0][0] = 0
    queue = [(0, 0, 0, 1, 0)] # r1, c1, r2, c2, moves_so_far
    while queue:
        r1, c1, r2, c2, cur_moves = queue.pop(0)
        if cur_moves > moves[r1][c1]:
            continue
        if (r1, c1) == (n-1, n-2) and (r2, c2) == (n-1, n-1):
            return cur_moves
        # move right
        if c1 < n-1 and not grid[r1][c1+1] and not grid[r2][c2+1]:
            if cur_moves+1 < moves[r1][c1+1]:
                moves[r1][c1+1] = cur_moves+1
                queue.append((r1, c1+1, r2, c2+1, cur_moves+1))
        # move down
        if r1 < n-1 and not grid[r1+1][c1] and not grid[r2+1][c2]:
            if cur_moves+1 < moves[r1+1][c1]:
                moves[r1+1][c1] = cur_moves+1
                queue.append((r1+1, c1, r2+1, c2, cur_moves+1))
        # move up
        if r1 > 0 and not grid[r1-1][c1] and not grid[r2-1][c2]:
            if cur_moves+1 < moves[r1-1][c1]:
                moves[r1-1][c1] = cur_moves+1
                queue.append((r1-1, c1, r2-1, c2, cur_moves+1))
        # rotate clockwise
        if r1 == r2 and c2-c1 == 1 and r1 < n-1 and not grid[r1+1][c1] and not grid[r2+1][c2] and not grid[r1+1][c1+1]:
            if cur_moves+1 < moves[r1+1][c1]:
                moves[r1+1][c1] = cur_moves+1
                queue.append((r1, c1, r1+1, c1+1, cur_moves+1))
        # rotate counterclockwise
        if r1 == r2 and c2-c1 == 1 and c1 > 0 and not grid[r1][c1-1] and not grid[r2][c2-1] and not grid[r2-1][c2-1]:
            if cur_moves+1 < moves[r1][c1-1]:
                moves[r1][c1-1] = cur_moves+1
                queue.append((r1, c1-1, r1-1, c1, cur_moves+1))
    return -1

