def minimum_connection_cost(size1, size2, cost):
    dp = [[float('inf')] * (1 << size2) for _ in range(size1)]
    dp[0][0] = 0
    for mask in range(1, 1 << size2):
        for j in range(size2):
            if mask & (1 << j) == 0:
                continue
            for i in range(size1):
                dp[i][mask] = min(dp[i][mask], cost[i][j] + (dp[i - 1][mask ^ (1 << j)] if i > 0 else 0))
    return dp[-1][(1 << size2) - 1]

