def ways_to_partition(nums: List[int], k: int) -> int:
    n = len(nums)
    left_sum = [0] * n
    right_sum = [0] * n
    
    left_sum[0] = nums[0]
    right_sum[n-1] = nums[n-1]
    
    for i in range(1, n):
        left_sum[i] = left_sum[i-1] + nums[i]
    
    for i in range(n-2, -1, -1):
        right_sum[i] = right_sum[i+1] + nums[i]
    
    pivot_count = 0
    for i in range(1, n):
        if left_sum[i-1] == right_sum[i]:
            pivot_count += 1
            
    max_pivot = pivot_count
    for i in range(n):
        if i == k:
            continue
        delta = nums[i] - nums[k]
        temp = left_sum[i] + delta - right_sum[i]
        if temp == 0:
            pivot = i
            count = pivot_count
            if pivot > 0 and left_sum[pivot-1] == right_sum[pivot] + delta:
                count -= 1
            if pivot < n-1 and left_sum[pivot] == right_sum[pivot+1] - delta:
                count -= 1
            max_pivot = max(max_pivot, count)
    
    return max_pivot

