class Solution:
    """Quick Sort Algorithm"""
    # Position of pivot element
    def pivot_place(self, array: List[int], first: int, last: int) -> int:
        pivot = array[first]
        left = first + 1
        right = last
        while True:
            while left <= right and array[left] <= pivot:
                left += 1
            while left <= right and array[right] >= pivot:
                right -= 1
            if left > right:
                break
            else:
                array[left], array[right] = array[right], array[left]
        array[first], array[right] = array[right], array[first]
        return right
    # Divide and Conquer
    def quick_sort(self, array: List[int], first: int, last: int) -> None:
        if first <= last:
            p = self.pivot_place(array, first, last)
            self.quick_sort(array, first, p-1)
            self.quick_sort(array, p+1, last)
    def canBeEqual(self, target: List[int], arr: List[int]) -> bool:
        n = len(arr)
        m = len(target)
        self.quick_sort(arr, 0, n-1)
        self.quick_sort(target, 0, m-1)
        if target == arr:
            return True
        return False

