class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
        
def max_ancestor_diff(root: TreeNode) -> int:
    max_val = 0
        
    def dfs(node, min_val, max_val):
        if not node:
            return max_val
        
        max_val = max(max_val, abs(node.val - min_val), abs(node.val - max_val))
        min_val = min(min_val, node.val)
        max_val = max(max_val, dfs(node.left, min_val, max_val), dfs(node.right, min_val, max_val))
        
        return max_val
        
    return dfs(root, root.val, root.val)

