    def isPossibleDivide(self, nums: List[int], k: int) -> bool:
        if len(nums) % k != 0:
            return False
        nums.sort()
        counts = {}
        for num in nums:
            if num not in counts:
                counts[num] = 0
            counts[num] += 1
        for i in range(len(nums)):
            if counts[nums[i]] > 0:
                count = 1
                start = nums[i]
                counts[nums[i]] -= 1
                for j in range(i+1, len(nums)):
                    if nums[j] == start + 1 and counts[nums[j]] > 0:
                        count += 1
                        start += 1
                        counts[nums[j]] -= 1
                        if count == k:
                            break
                if count != k:
                    return False
        return True

