class Solution:
    def minMoves(self, nums: List[int], k: int) -> int:
        ones = [i for i in range(len(nums)) if nums[i] == 1]
        # Create a prefix sum array to calculate ranges efficiently.
        prefix_sum = [0] * (len(ones) + 1)
        for i in range(1, len(ones) + 1):
            prefix_sum[i] = prefix_sum[i-1] + ones[i-1]

        # Define range_sum function to calculate sum of elements in a range efficiently.
        def range_sum(l, r):
            return prefix_sum[r+1] - prefix_sum[l]

        # Define cost function to calculate the cost of changing one element to 1 in a range.
        def cost(i, j):
            middle = (i+j) // 2
            return (middle - i) * (ones[middle] - (i + j)//2) - range_sum(i, middle-1) + range_sum(middle+1, j)

        # Use dynamic programming to find the minimum cost of achieving k consecutive 1's.
        dp = [0] + [float('inf')] * len(ones)
        for i in range(1, len(ones) + 1):
            for j in range(i-1, -1, -1):
                if ones[i] - ones[j] + 1 <= k:
                    dp[i] = min(dp[i], dp[j] + cost(j, i))

        return dp[-1]

