def search_bst(root, vals):
    answer = []
    for val in vals:
        mini = -1
        maxi = -1
        node = root
        while node is not None:
            if node.val <= val:
                mini = node.val
                node = node.right
            else:
                maxi = node.val
                node = node.left
        answer.append([mini, maxi])
