def swap_and_find(text):
    for i in range(len(text)):
        for j in range(i+1, len(text)):
            swapped_text = text[:i] + text[j] + text[i+1:j] + text[i] + text[j+1:]
            repeated_substring = ""
            for k in range(len(swapped_text)):
                for l in range(k+1, len(swapped_text)):
                    substring = swapped_text[k:l+1]
                    if len(substring) > len(repeated_substring) and all(substring[m] == substring[m+1] for m in range(len(substring)-1)):
                        repeated_substring = substring
            if repeated_substring:
                return len(repeated_substring)
