def check_contiguous(s):
    s = list(s)
    ones = []
    zeroes = []
    count = 0
    
    for i in range(len(s)):
        if s[i] == '1':
            count += 1
        else:
            ones.append(count)
            count = 0
    ones.append(count)
    
    count = 0
    for i in range(len(s)):
        if s[i] == '0':
            count += 1
        else:
            zeroes.append(count)
            count = 0
    zeroes.append(count)
    
    return max(ones) > max(zeroes)

