def maxHappyGroups(batchSize, groups):
    freq = [0] * batchSize
    for group in groups:
        freq[group % batchSize] += 1
    happy = freq[0]
    freq[0] = 0
    for i in range(1, batchSize // 2 + 1):
        if i == batchSize - i:
            happy += freq[i] // 2
        else:
            happy += min(freq[i], freq[batchSize - i])
    return happy

