    for edge in edges:
        if edge[0] not in trio_dict:
            trio_dict[edge[0]] = set()
        if edge[1] not in trio_dict:
            trio_dict[edge[1]] = set()
        trio_dict[edge[0]].add(edge[1])
        trio_dict[edge[1]].add(edge[0])
    min_degree = float("inf")
    for node in trio_dict:
        connected_triangles = set()
        for neighbor in trio_dict[node]:
            if neighbor > node:
                for other_neighbor in trio_dict[neighbor]:
                    if other_neighbor > node and other_neighbor in trio_dict[node]:
                        connected_triangles.add((node, neighbor, other_neighbor))
        degree = len(connected_triangles)
        min_degree = min(min_degree, degree)
    if min_degree == float("inf"):
        return -1
    return min_degree

