from collections import deque

def findSmallestReachableSet(n, edges):
    # topological sort to get nodes in order
    graph = {i: [] for i in range(n)}
    in_degrees = [0] * n
    for u, v in edges:
        graph[u].append(v)
        in_degrees[v] += 1
    
    queue = deque()
    for i in range(n):
        if in_degrees[i] == 0:
            queue.append(i)
    
    visited = set()
    while queue:
        node = queue.popleft()
        visited.add(node)
        for neighbor in graph[node]:
            in_degrees[neighbor] -= 1
            if in_degrees[neighbor] == 0:
                queue.append(neighbor)
                
    return sorted(list(visited))

