class Solution:
    def findSpecialInteger(self, arr: List[int]) -> int:
		# Setting equal to the first element 
		# since length of the array can be 1
        maxInt = arr[0]
        maxCount = 1
        currInt = arr[0]
        currCount = 1
        
		# O(N) linear scan
        for i in range(1, len(arr)):
            # print (f"arr[i]: {arr[i]}, currInt: {currInt}, currCount: {currCount}, maxInt: {maxInt}, maxCount: {maxCount}")
            if arr[i] == currInt:
                currCount += 1
            else:
                if currCount > maxCount:
                    maxCount = currCount
                    maxInt = currInt
                else:
					# refreshing out curr values and setting them 
					# equal to the new value we just encountered
                    currCount = 1
                    currInt = arr[i]
        
		# For the edge case where the solution 
		# happens to be towards the end
        if currCount > maxCount:
            return currInt
        else:
            return maxInt

