            if heap == []:
                heapq.heappush(heap, interval[1])
            else:
                minvalue = heapq.heappop(heap)
                if interval[0] > minvalue:
                    heapq.heappush(heap, interval[1])
                else:
                    heapq.heappush(heap, minvalue)
                    heapq.heappush(heap, interval[1])
                    number += 1
        
