class Solution:
    def minOperationsMaxProfit(self, customers: List[int], boardingCost: int, runningCost: int) -> int:
        
         
        n=len(customers)
        dp=[]
        reserved=0
        on_board=0
        rotation=0
        for i in range(n):
            if reserved!=0:
                if reserved>=4:
                    on_board+=4
                    reserved += customers[i]-4
                else:
                    new_customers=4-reserved
                    if customers[i]>=new_customers:
                        on_board+=4
                        reserved=customers[i]-new_customers
                    else:
                        on_board+=reserved+customers[i]
                        reserved=0
            else:
                if customers[i]>=4:
                    on_board+=4
                    reserved+=customers[i]-4
                else:
                    on_board+=customers[i]
            rotation+=1
            
            dp.append(on_board*boardingCost - rotation*runningCost)
        
        for i in range(reserved//4 + 1):
            if reserved>=4:
                on_board+=4
                reserved-=4
            else:
                on_board+=reserved
                reserved=0
            rotation+=1
            dp.append(on_board*boardingCost - rotation*runningCost)
        
        maxim=max(dp)
        return dp.index(maxim)+1 if maxim>=0 else -1

class Solution:
    def dfs(self, comp, idx, visited, graph):
        visited[idx] = True
        comp.append(idx)
        
        for neighbour in graph[idx]:
            if visited[neighbour] is False:
                comp = self.dfs(comp, neighbour, visited, graph)
        
        return comp
                
        
    def makeConnected(self, n: int, connections: List[List[int]]) -> int:
        graph = {}
        for i in range(n):
            graph[i] = []
            
        for connection in connections:
            graph[connection[0]].append(connection[1])
            graph[connection[1]].append(connection[0])
            
        totalEdges = 0
        for key, value in graph.items():
            totalEdges += len(value)
        
        totalEdges = totalEdges//2
        
        visited = [False]*n
        connectedComponents = []
        
        for i in range(n):
            if len(graph[i]) > 0 and visited[i] is False:
                component = []
                connectedComponents.append(self.dfs(component, i, visited, graph))
            
            elif len(graph[i]) == 0:
                connectedComponents.append([i])
                
        totalComponents = len(connectedComponents)
        
        redundantEdges = totalEdges - ((n - 1) - (totalComponents - 1)) 
        
        requiredEdges = totalComponents - 1
        
        if redundantEdges >= requiredEdges:
            return requiredEdges
        else:
            return -1

