from collections import defaultdict

class Solution:
    def __init__(self):
        self.parent = {}
        self.rank = {}
    
    def make_set(self, v):
        self.parent[v] = v
        self.rank[v] = 0
        
    def find_set(self, v):
        if v != self.parent[v]:
            self.parent[v] = self.find_set(self.parent[v])
        return self.parent[v]
    
    def union_sets(self, a, b):
        a = self.find_set(a)
        b = self.find_set(b)
        if a != b:
            if self.rank[a] < self.rank[b]:
                a, b = b, a
            self.parent[b] = a
            if self.rank[a] == self.rank[b]:
                self.rank[a] += 1
                
    def make_connected(self, n: int, connections: List[List[int]]) -> int:
        for i in range(n):
            self.make_set(i)
            
        for a, b in connections:
            self.union_sets(a, b)
        
        num_components = defaultdict(int)
        for i in range(n):
            num_components[self.find_set(i)] += 1
        
        cables_to_remove = 0
        extra_computers = 0
        for i in range(n):
            if i == self.parent[i]:
                required_connections = num_components[i] - 1
                if required_connections == 0:
                    extra_computers += 1
                else:
                    cables_to_remove += required_connections
        
        if extra_computers == 0:
            return cables_to_remove
        elif cables_to_remove >= extra_computers - 1:
            return extra_computers - 1
        else:
            return -1

def max_weeks(milestones):
    milestones.sort(reverse=True)
    total_milestones = sum(milestones)
    weeks = 0
    
    while total_milestones > 0:
        for i in range(min(total_milestones, len(milestones))):
            if milestones[i] > 0:
                total_milestones -= 1
                milestones[i] -= 1
        weeks += 1
        
        if sum(milestones[:2]) > 1:
            break
        
    return weeks

