class Solution:
    def maxLengthBetweenEqualCharacters(self, s: str) -> int:
        """
        Time Complexity: O(n)
        Space Complexity: O(n)
        """
        # Create a dictionary to store the index of the first occurence of each character
        # and a dictionary to store the index of the last occurence of each character
        first_occurence = {}
        last_occurence = {}
        for i, c in enumerate(s):
            if c not in first_occurence:
                first_occurence[c] = i
            last_occurence[c] = i
        # Iterate through the dictionary to find the maximum length
        max_length = -1
        for c in first_occurence:
            max_length = max(max_length, last_occurence[c] - first_occurence[c] - 1)
        return max_length

