def maxFruits(fruits, startPos, k):
    left = startPos - k
    right = startPos + k
    maxFruits = 0
    i = 0
    j = 0
    currFruits = 0
    
    while j < len(fruits):
        if fruits[j][0] <= right:
            currFruits += fruits[j][1]
            j += 1
        else:
