def dfs(tree, nums, ans, root):
    min_num = min(nums[root], *(nums[node] for node in tree[root]))
    max_num = max(nums[root], *(nums[node] for node in tree[root]))
    for node in tree[root]:
        dfs(tree, nums, ans, node)
    for i in range(min_num, max_num):
        if i not in nums:
            ans[root] = i
            return
    ans[root] = max_num

