def lowestCommonAncestor(root: 'Node', p: 'Node', q: 'Node') -> 'Node':
    if not root:
        return None
 
    if root.val == p.val or root.val == q.val:
        return root
 
    left = lowestCommonAncestor(root.left, p, q)
    right = lowestCommonAncestor(root.right, p, q)
 
    if left and right:
        return root
    else:
        return left or right

