class Solution:
    def checkAlmostEquivalent(self, word1: str, word2: str) -> bool: 
        d1={}
        d2={} 

        #FREQUENCIES OF WORD1 CHARACTERS
        for i in word1:
            if i in d1:
                d1[i]+=1
            else:
                d1[i]=1 

        #FREQUENCIES OF WORD2 CHARACTERS
        for i in word2:
            if i in d2:
                d2[i]+=1
            else:
                d2[i]=1 

        #CHECK IF EQUAL CHARACTERS OF WORD1 AND WORD2 HAVING FREQUENCY DIFFERENCE AT MOST 3
