        #IF CHARACTERS PRESENT IN d2 BUT NOT d1 ,CHECK FRQUENCY OF d2 CHARACTERS SHOULD BE AT MOST 3 
        #AS FREQUENCY - 0(COZ NOT PRESENT IN D1) 
        for i in d2.keys():
            if i not in d1:
