def equivalent(word1, word2):
    if len(word1) != len(word2):
        return False

    freq1 = [0] * 26
    freq2 = [0] * 26
    
    for i in range(len(word1)):
        freq1[ord(word1[i]) - ord('a')] += 1
        freq2[ord(word2[i]) - ord('a')] += 1
    
    diff = 0
    for i in range(26):
        if abs(freq1[i] - freq2[i]) > 3:
            return False
        diff += abs(freq1[i] - freq2[i])
    
    return diff < 6

