def longest_path_in_tree(n, s, parent):
    # Build tree structure
    tree = [[] for _ in range(n)]
    for i in range(1, n):
        tree[parent[i]].append(i)

    # DFS to find the longest path
    def dfs(node):
        nonlocal max_path
        first_max = second_max = 0
        for child in tree[node]:
            child_path = dfs(child)
            if child_path > second_max:
                if child_path > first_max:
                    second_max = first_max
                    first_max = child_path
                else:
                    second_max = child_path
        max_path = max(max_path, first_max + second_max)
        return first_max + (s[node] == 'F')

    # Start DFS from root node
    max_path = 0
    dfs(0)
    return max_path

