def minWhiteTiles(floor: str, numCarpets: int, carpetLen: int) -> int:
    black_tiles = [i for i in range(len(floor)) if floor[i] == '0']
    total_white_tiles = floor.count('1')
    min_visible_white_tiles = total_white_tiles
    
    for i in range(numCarpets):
        for j in range(len(floor)-carpetLen+1):
            if all(k in black_tiles for k in range(j, j+carpetLen)): # Check if the carpet overlaps only black tiles
                visible_white_tiles = total_white_tiles - floor[j:j+carpetLen].count('1')
                min_visible_white_tiles = min(min_visible_white_tiles, visible_white_tiles)
    
    return min_visible_white_tiles

def canThreePartsEqualSum(arr):
    total_sum = sum(arr)
    if total_sum % 3 != 0:
        return False
    target_sum = total_sum // 3
    current_sum, count = 0, 0
    for i in arr:
        current_sum += i
        if current_sum == target_sum:
            count += 1
            current_sum = 0
    return count == 3

def numOfWays(nums):
    def countBST(nums):
        if len(nums) <= 2:
            return 1
        root = nums[0]
        left = [n for n in nums if n < root]
        right = [n for n in nums if n > root]
        return comb(len(left) + len(right), len(left)) * countBST(left) * countBST(right) % (10**9 + 7)
    return (countBST(nums) - 1) % (10**9 + 7)

