class Solution:
    def countKDifference(self, nums: List[int], k: int) -> int:
        
        m, cnt = {nums[0] : 1}, 0

        for i in range(1, len(nums)):
            # Solution for the equation |x - y| = k
            # either x - y = k or x - y = -k
            t1, t2 = nums[i] - k, nums[i] + k

            if t1 in m and t1 > 0:
                cnt += m[t1]
            if t2 in m and t2 > 0:
                cnt += m[t2]

            if nums[i] not in m:
                m[nums[i]] = 1
            else:
                m[nums[i]] += 1

        return cnt

