        nums.sort()
        if len(nums) == 0:
            return 0
        ans = 1
        currmax = None
        currmin = None
        for n in nums:
            if currmax is None and currmin is None:
                currmax = currmin = n
            if n > currmax:
                currmax = n
            if n < currmin:
                currmin = n
            
            if currmax - currmin > k:
                ans += 1
                currmax = currmin = n
        
