class Solution:
    def maxSubsequence(self, nums: List[int], k: int) -> List[int]:
        temp = nums[:]
        shuffle(temp)
        
        def part(lo, hi): 
            """Return partition of nums[lo:hi]."""
            i, j = lo+1, hi-1
            while i <= j: 
                if temp[i] < temp[lo]: i += 1
                elif temp[j] > temp[lo]: j -= 1
                else: 
                    temp[i], temp[j] = temp[j], temp[i]
                    i += 1
                    j -= 1
            temp[lo], temp[j] = temp[j], temp[lo]
            return j 
        
        lo, hi = 0, len(temp)
        while lo <= hi: 
            mid = part(lo, hi)
            if mid < len(temp)-k: lo += 1
            elif mid == len(temp)-k: break 
            else: hi = mid 
        threshold = temp[mid]
        
        larger = sum(x > threshold for x in nums)
        equal = k - larger
        
        ans = []
        for x in nums: 
            if x > threshold: ans.append(x)
            elif x == threshold: 
                if equal: 
                    equal -= 1
                    ans.append(x)
        return ans

