def findMaxSubsequence(nums: List[int], k: int) -> List[int]:
    dp = [[float('-inf') for _ in range(k+1)] for _ in range(len(nums)+1)]
    for i in range(len(nums)+1):
        dp[i][0] = 0
        
    for i in range(1, len(nums)+1):
        for j in range(1, k+1):
            dp[i][j] = max(dp[i-1][j], dp[i-1][j-1]+nums[i-1])
    
    res = []
    i = len(nums)
    j = k
    while j > 0:
        if dp[i][j] == dp[i-1][j]:
            i -= 1
        else:
            res.append(nums[i-1])
            i -= 1
            j -= 1
    
    return res[::-1]

