def minWeightSubgraph(n, edges, src1, src2, dest):
    # create adjacency matrix
    adjMat = [[float('inf') for i in range(n)] for j in range(n)]
    for edge in edges:
        adjMat[edge[0]][edge[1]] = edge[2]

    # initialize dp matrix
    dp = [[[float('inf') for i in range(n)] for j in range(n)] for k in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                dp[i][j][0] = 0
            else:
                dp[i][j][0] = adjMat[i][j]

    # fill dp matrix
    for l in range(1, n):
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    dp[i][j][l] = min(dp[i][j][l], dp[i][k][l-1] + dp[k][j][0])

    # find minimum weight subgraph
    minSubgraphWeight = float('inf')
    for i in range(n):
        for j in range(n):
            if i == j or adjMat[i][j] == float('inf'):
                continue
            if dp[i][j][n-1] != float('inf') and dp[src1][i][n-1] != float('inf') and dp[src2][j][n-1] != float('inf'):
                minSubgraphWeight = min(minSubgraphWeight, dp[src1][i][n-1] + adjMat[i][j] + dp[j][src2][n-1])

    if minSubgraphWeight == float('inf'):
        return -1
    else:
        return minSubgraphWeight

