class Solution:
    def minimumDistance(self, word: str) -> int:
        locations = {}
        x, y = 0, 0
        for i in range(65, 91):
            locations[chr(i)] = (x, y)
            y += 1
            if y > 5:
                x += 1
                y = 0
        
        #print(locations)
        @lru_cache(None)
        def func(idx, f1, f2):
            if idx == len(word):
                return 0
            
            # use f1
            if f1 == '':
                x1, y1 = locations[word[idx]]
            else:
                x1, y1 = locations[f1]
                
            x, y = locations[word[idx]]
            dist1 = abs(x1 - x) + abs(y1 - y)
            useF1 = dist1 + func(idx + 1, word[idx], f2)
            
            if f2 == '':
                x2, y2 = locations[word[idx]]
            else:
                x2, y2 = locations[f2]
                
            dist2 = abs(x2 - x) + abs(y2 - y)
            useF2 = dist2 + func(idx + 1, f1, word[idx])
            
            return min(useF1, useF2)
        
        return func(0, '', '')

