            res = []
            for i in nums:
                low,high = 0, len(res)
                while low < high:
                    mid = (low+high)//2
                    
                    if res[mid] <= i:
                        low = mid + 1
                        
                    else:
                        
                        high = mid


                if low == len(res):
                    res.append(i)
                else:

                    res[low] = i
                    
                    


            return len(res)
        
