        for i in range(k):
            bucket = []
            startingIdx = i
            while startingIdx < len(arr):
                bucket.append(arr[startingIdx])
                startingIdx += k
                
            
                
                
            ans += len(bucket) - LIS(bucket)
                
                
        return ans

