def countRestrictedPaths(n: int, edges: List[List[int]]) -> int:
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u-1].append((v-1, w))
        graph[v-1].append((u-1, w))

    heap = [(0, n-1)]
    dist = [float('inf')] * n
    dist[n-1] = 0
    while heap:
        d, u = heapq.heappop(heap)
        for v, w in graph[u]:
            if dist[v] > d + w:
                dist[v] = d + w
                heapq.heappush(heap, (dist[v], v))

    dp = [0] * n
    dp[0] = 1
    ranks = sorted(range(n), key=lambda x: dist[x])
    for u in ranks:
        for v, w in graph[u]:
            if dist[u] > dist[v]:
                dp[u] = (dp[u] + dp[v]) % MOD

    return dp[n-1]

def min_operations(blocks: str, k: int) -> int:
    n = len(blocks)
    num_consecutive_black = [0] * n
    for i in range(n):
        if blocks[i] == 'B':
            num_consecutive_black[i] = num_consecutive_black[i - 1] + 1
        else:
            num_consecutive_black[i] = 0

    # If it's impossible to get k consecutive black blocks, just return -1
    if max(num_consecutive_black) < k:
        return -1

    # Initialize variables
    left, right = 0, k
    current_ops = n + 1
    num_black = num_consecutive_black[k - 1]

    # Try to find a substring of k consecutive black blocks
    while right < n:
        if num_black < k:
            num_black = num_consecutive_black[right]
            right += 1
        elif num_black == k:
            current_ops = min(current_ops, right - left - k)
            num_black = num_consecutive_black[left + k - 1]
            left += 1

    return current_ops

