class Solution:
    def longestSubsequence(self, s: str, k: int) -> int:
        k_bit = bin(k)[2:]
        m = len(k_bit)
        n = len(s)
        
        @lru_cache(None)
        # flag is to indicate whether '1' included
        def dp(i, j, flag):
            if i == m or j == n:
                return 0

            if s[j] == '0':
                if not flag:
                    return 1 + dp(i, j + 1, flag) # include as many zero as possible if not leading "1"
                else:
                    # if current target bit is "1" then takes rest of the strings since it will guarantee smaller than k
                    return 1 + dp(i + 1, j + 1, flag) if k_bit[i] == '0' else min(m - i, n - j) 
            elif k_bit[i] == '1':
                return max(1 + dp(i + 1, j + 1, True), dp(i, j + 1, flag))
            else:
                # include one less digit is only way to make smaller if digit in s is '1' and in k is '0'
                return max(dp(i, j + 1, flag), min(m - i - 1, n - j))

        
        if '1' not in s or m > n: return n
        
        return dp(0, 0, False)

