def minOperations(nums1: List[int], nums2: List[int]) -> int:
    sum1 = sum(nums1)
    sum2 = sum(nums2)
    if sum1 == sum2:
        return 0
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1
        sum1, sum2 = sum2, sum1
    diff = abs(sum1 - sum2)
    if diff > (len(nums2) - len(nums1)) * 6:
        return -1
    res = 0
    freq = [0] * 7
    for val in nums1 + nums2:
        freq[val] += 1
    for i in range(5, 0, -1):
        while diff > 0 and freq[i]:
            diff -= i - 1
            freq[i] -= 1
            res += 1
    return res + (diff + 5) // 6

def remove_zero_sequences(head):
    dummy = ListNode(0)
    dummy.next = head
    current = dummy
    while current.next:
        sum = 0
        node = current.next
        sequence = []
        while node:
            sum += node.val
            sequence.append(node)
            if sum == 0:
                break
            node = node.next
        if sum == 0:
            for n in sequence:
                current.next = n.next
        else:
            current = current.next
    return dummy.next

def min_insertions_to_balance(s):
    """
    :type s: str
    :rtype: int
    """
    stack = []
    insertions = 0
    i = 0
    while i < len(s):
        if s[i] == '(':
            stack.append(s[i])
            i += 1
        else:
            if i + 1 < len(s) and s[i+1] == ')':
                if stack:
                    stack.pop()
                else:
                    insertions += 1
                i += 2
            else:
                if stack:
                    insertions += 1
                    stack.pop()
                else:
                    insertions += 2
                i += 1
    return insertions + len(stack) * 2

