class Solution:
    def reverseParentheses(self, s: str) -> str:
		#Take an empty stack for iteration
        stack = []
        for i in range(0, len(s)):
			# If the current charector is anything other than closing bracket append it
            if s[i] != ')':
                stack.append(s[i])
            else:
                k = []
				#pop the elements from the stack and reverse place it back to the stack until the opening brace is found
                while len(stack)!=0 and stack[-1]!='(':
                    k.append(stack.pop())
				#Pop the ')' opening brace
                stack.pop()
                k = k[::-1]
                while len(k)!=0:
                    stack.append(k.pop())
