def reverseParentheses(s):
    stack = []
    for i in range(len(s)):
        if s[i] == '(':
            stack.append(i)
        elif s[i] == ')':
            j = stack.pop()
            s = s[:j] + s[j:i+1][::-1] + s[i+1:]
    return s

def numPairsDivisibleBy60(time):
    count = 0
    remainders = [0] * 60
    for t in time:
        if t % 60 == 0:
            count += remainders[0]
        else:
            count += remainders[60 - t % 60]
        remainders[t % 60] += 1
    return count

