class Solution:
    def minimizeResult(self, expression: str) -> str:
        res = {}
        addPos = expression.index('+')
        for i in range(len(expression)):
            if i >= addPos: break
            for j in range(i+1, len(expression)):
                if j <= addPos: continue
                newEx = expression[:i]+'('+expression[i:j+1]+')'+expression[j+1:]
                ans = self.calculate(newEx)
                res[ans] = newEx
        return res[min(res)]
    def str2int(self, arr):
        return int(''.join([str(ch) for ch in arr]))
    def calculate(self, ex):
        digits = []
        mulStack = []
        addStack = []
        i = 0
        L = len(ex)
        while i < L:
            c = ex[i]
            if c.isdigit():
                digits.append(c)
            else:
                if c == '(':
                    if digits:
                        mulStack.append(self.str2int(digits))
                        digits = []
                    subAddStack = []
                    subDigits = []
                    j = i+1
                    while ex[j] != ')':
                        if ex[j].isdigit():
                            subDigits.append(ex[j])
                        else: # +
                            thisNum = self.str2int(subDigits)
                            subAddStack.append(thisNum)
                            subDigits = []
                        j += 1
                    if subDigits:
                        subAddStack.append(self.str2int(subDigits))
                    num = sum(subAddStack)
                    mulStack.append(num)
                    i = j
                elif c == '+':
                    num = 1
                    if digits:
                        num = self.str2int(digits)
                        digits = []
                    if mulStack:
                        for p in mulStack:
                            num *= p
                        mulStack = []
                    addStack.append(num)
            i += 1
        if not digits and not mulStack: return sum(addStack)
        num = 1
        if digits:
            num = self.str2int(digits)
            digits = []
        if mulStack:
            for p in mulStack:
                num *= p
            mulStack = []
        addStack.append(num)
        return sum(addStack)

class Solution:
    def countSubTrees(self, n: int, edges: List[List[int]], labels: str) -> List[int]:
        graph = self.build_graph(edges)
        res = [0] * n
        visited = set()
		
        def add(seen1, seen2):
            seen = [0] * 26
            for i in range(26):
                seen[i] = seen1[i] + seen2[i]
            return seen
        
        def index(char):
            return ord(char) - ord('a')
        
        def dfs(node):
		    # Maintain a visited since the edge is represented in both directions in the graph
            visited.add(node)
            seen = [0] * 26
            for neigh in graph.get(node, []):
                if not neigh in visited:
                    seen = add(seen, dfs(neigh))
                
            seen[index(labels[node])] += 1
            res[node] = seen[index(labels[node])]
            return seen
        
        dfs(0)
        return res
        
    def build_graph(self, edges):
        graph = {}
        for edge in edges:
		     # Include edges in both directions since ordering of edges is not guaranteed
			 # e.g. case [[0, 2], [0, 3], [1, 2]]
			 # In above example we should traverse from 2 to 1.
            graph.setdefault(edge[0], []).append(edge[1])
            graph.setdefault(edge[1], []).append(edge[0])
        return graph

