class Solution:
    def countSubTrees(self, n: int, edges: List[List[int]], labels: str) -> List[int]:
        graph = defaultdict(list)
        for a, b in edges:
            graph[a].append(b)
            graph[b].append(a)
        
        def traverse(node, parent):
            counts = [0] * 26
            char_index = ord(labels[node]) - 97
            counts[char_index] += 1
            for child in graph[node]:
                if child == parent:
                    continue
                child_counts = traverse(child, node)
                for i in range(26):
                    counts[i] += child_counts[i]
            ans[node] = counts[char_index]
            return counts
        
        ans = [0] * n
        traverse(0, -1)
        return ans

