class Solution:
    def minSteps(self, s: str, t: str) -> int:
        if s == t:
            return 0
        d_s = dict(collections.Counter(s))
        d_t = dict(collections.Counter(t))
        for i in range(len(t)): # adding the rest of elements from "t" to d_s with all the values = 0 (because they are not in s)
            if t[i] not in d_s:
                d_s[t[i]] = 0
        for i in range(len(s)): # same for this one 
            if s[i] not in d_t:
                d_t[s[i]] = 0
        count = 0  # counting how many letters are different (the letters that are in one dictionary but not in the other, same for the latter)
        for i, ele in enumerate(d_s):
            count += abs(d_s[ele] - d_t[ele])
        return count // 2  # we return count // 2 because if you got a number of letters you will always need to make number/2 moves to equilibrate the strings

