    for char in s:
        s_dict[char] = s_dict.get(char, 0) + 1
    for char in t:
        t_dict[char] = t_dict.get(char, 0) + 1
    steps = 0
    for char in s_dict.keys():
        if char not in t_dict:
            steps += s_dict[char]
        else:
