def numberWays(n: int, hats: List[List[int]]) -> int:
    MOD = 10**9 + 7
    dp = [0] * (1 << n)
    dp[0] = 1
    # hatToPerson stores the list of people who prefer a certain hat
    hatToPerson = [set() for _ in range(41)]
    for i in range(n):
        for hat in hats[i]:
            hatToPerson[hat].add(i)
    
    for hat in range(1, 41):
        # for each hat, calculate the number of ways to assign it to a group of people
        for mask in range((1 << n) - 1, -1, -1):
            for person in hatToPerson[hat]:
                if mask & (1 << person):
                    # if person already has a hat, skip
                    continue
                new_mask = mask | (1 << person)
                dp[new_mask] = (dp[new_mask] + dp[mask]) % MOD
    
    return dp[(1 << n) - 1] % MOD

