class Solution:
    def minimumBuckets(self, street: str) -> int:
        l=list(street.strip())
        c=0
        n=len(street)
        i=1
        while i < len(street)-1:#fill the buckets containg houses on both sides and change H to T
            if l[i-1]=="H" and l[i+1]=="H" and l[i]==".":
                l[i-1]="T"
                l[i+1]="T"
                l[i]="B"
