            if i-1>=0:
                if l[i-1]=="H":
                    if l[i]==".":
                        c+=1
                        l[i-1]="T"
                        l[i]="B"
            if i+1<len(l):
                if l[i+1]=="H":
                    if l[i]==".":
                        c+=1
                        l[i]="B"
                        l[i+1]="T"
            i+=1
        if "H" in l:
            return -1
        return c

