def min_work_sessions(tasks, sessionTime):
    time_left = [0] * sessionTime
    
    for task in sorted(tasks, reverse=True):
        for i in range(sessionTime-1, -1, -1):
            if time_left[i] <= task:
                task -= time_left[i]
                time_left[i] = sessionTime
                if task == 0:
                    break
        if task > 0:
            return -1
        
    return sum(1 for t in time_left if t == sessionTime)

def minOperations(nums, target):
    nums_sum = sum(nums)
    target_sum = sum(target)
    if nums_sum == target_sum:
        return 0
    if nums_sum < target_sum:
        nums, target = target, nums
    
    nums_dict = {}
    for num in nums:
        if num in nums_dict:
            nums_dict[num] += 1
        else:
            nums_dict[num] = 1
    
    diff = nums_sum - target_sum
    op_count = 0
    for key in sorted(nums_dict.keys(), reverse=True):
        if key <= target_sum // len(target):
            break
        if diff <= 0:
            break
        if key - target_sum // len(target) >= diff // nums_dict[key] + 1:
            op_count += diff // (key - target_sum // len(target))
            diff = diff % (key - target_sum // len(target))
    return op_count if diff == 0 else -1

