from collections import deque

def minimum_swaps(s):
    stack = deque()
    swaps = 0
    for c in s:
        if c == '[':
            stack.append(c)
        else:
            if not stack:
                swaps += 1
                stack.append('[')
            else:
                stack.pop()
    return swaps // 2  # divide by 2 since each swap involves 2 brackets

