def calculate_cost(expression, target_value):
    current_value = evaluate_expression(expression)
    if current_value == target_value:
        return 0
    if current_value == int(not(target_value)):
        return 1
    if '|' not in expression and '&' not in expression:
        return 1
    cost = float('inf')
    for i in range(len(expression)):
        if expression[i] == '1':
            new_expression = expression[:i] + '0' + expression[i+1:]
            cost_with_change = 1 + calculate_cost(new_expression, target_value)
            cost = min(cost, cost_with_change)
        elif expression[i] == '0':
            new_expression = expression[:i] + '1' + expression[i+1:]
            cost_with_change = 1 + calculate_cost(new_expression, target_value)
            cost = min(cost, cost_with_change)
        elif expression[i] == '&':
            new_expression = expression[:i] + '|' + expression[i+1:]
            cost_with_change = 1 + calculate_cost(new_expression, target_value)
            cost = min(cost, cost_with_change)
            new_expression = expression[:i] + '(' + expression[i:i+3] + ')' + expression[i+3:]
            cost_with_change = 1 + calculate_cost(new_expression, target_value)
            cost = min(cost, cost_with_change)
        elif expression[i] == '|':
            new_expression = expression[:i] + '&' + expression[i+1:]
            cost_with_change = 1 + calculate_cost(new_expression, target_value)
            cost = min(cost, cost_with_change)
            new_expression = expression[:i] + '(' + expression[i:i+3] + ')' + expression[i+3:]
            cost_with_change = 1 + calculate_cost(new_expression, target_value)
            cost = min(cost, cost_with_change)
    return cost

def evaluate_expression(expression):
    stack = []
    i = 0
    while i < len(expression):
        if expression[i].isdigit():
            stack.append(int(expression[i]))
        elif expression[i] == '(':
            stack.append(expression[i])
        elif expression[i] in {'&', '|'}:
            stack.append(expression[i])
        elif expression[i] == ')':
            while stack[-1] != '(':
                op = stack.pop()
                op1 = stack.pop()
                op2 = stack.pop()
                res = apply_operation(op, op1, op2)
                stack.append(res)
            stack.pop()
        i += 1
    while len(stack) != 1:
        op = stack.pop()
        op1 = stack.pop()
        op2 = stack.pop()
        res = apply_operation(op, op1, op2)
        stack.append(res)
    return stack.pop()

def apply_operation(op, op1, op2):
    if op == '&':
        return op1 & op2
    else:
        return op1 | op2

