class Solution:
    def groupThePeople(self, groupSizes: List[int]) -> List[List[int]]:
        #We are wanting to return a list of groups, where each group is a list that contains IDs of persons. A person's
        #ID is equal to their index in the groupSizes list (which is the input parameter to this function).
        groupsOfPeople = list()
        
        #Dictionary to track the occurrences for each group size
        groupSizeToOccurrences = dict()
        
        #Count the occurrences and populate the dictionary
        for i in range(len(groupSizes)):
            groupSize = groupSizes[i]
            personId = i
            if groupSize in groupSizeToOccurrences:
                groupSizeToOccurrences[groupSize] += 1
            else:
                groupSizeToOccurrences[groupSize] = 1
        
        #Make the groups    
        for groupSize in groupSizeToOccurrences:
            groupSizeOccurrences = groupSizeToOccurrences[groupSize]
            numGroupsToCreate = groupSizeOccurrences//groupSize
            groupsList = self.getListOfGroups(groupSize, numGroupsToCreate, groupSizes)
            groupsOfPeople += groupsList
            
        return groupsOfPeople
    
    def getListOfGroups(self, groupSize: int, numGroupsToCreate: int, groupSizes: List[int]) -> List[List[int]]:
        listOfGroups = self.createEmptyListOfGroups(numGroupsToCreate)
        for i in range(len(groupSizes)):
            #Only look at the groupSize that matches the input parameter to this function
            if(groupSizes[i] == groupSize):
                #Get the index (personId) and put it into a list
                personId = i
                nextGroup = self.getNextGroup(listOfGroups, groupSize)
                nextGroup.append(personId)
        return listOfGroups
    
    def getNextGroup(self, listOfGroups: List[List[int]], groupSize):
        #Get the next group that has not yet reached it's expected size and return it
        for i in range(len(listOfGroups)):
            hasReachedGroupSize = (len(listOfGroups[i]) == groupSize)
            if not hasReachedGroupSize:
                return listOfGroups[i]
            
    def createEmptyListOfGroups(self, numGroupsToCreate: int):
        emptyGroups = list()
        for i in range(numGroupsToCreate):
            emptyGroups.append(list())
        return emptyGroups

