class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.s = [0]*n
        # for i in range(1,n):
        #    self.add(i, t[i])
    
    def add(self, i, x):
        while i < self.n:
            self.s[i] += x
            i += i &amp; -i # Add lsb of i

    def get(self, i):
        return self.prefix_sum(i)

    def interval_add(self, a, b, x):
        self.add(a, x)
        self.add(b+1, -x)

    def interval_sum(self, a, b):
        return self.prefix_sum(b) - self.prefix_sum(a-1)

    def prefix_sum(self, i):
        ans = 0
        while i > 0:
            ans += self.s[i]
            i -= (i &amp; -i)

        return ans

    def __str__(self):
        return str(self.s)

