def longest_palindrome(words):
    palindromes = set()
    for word in words:
        if word[::-1] in palindromes:
            palindromes.remove(word[::-1])
        else:
            palindromes.add(word)
    result = ""
    for palindrome in sorted(palindromes):
        result += palindrome
    if result == result[::-1]:
        return len(result)
    else:
        return 0

