class Solution:
    def findRotation(self, mat: List[List[int]], target: List[List[int]]) -> bool:
        for i in range(4):
            if self.same(mat, target):
                # Checking each time? whether the martrices are equal or not
                return True
            mat = self.rotate(mat)
            # calling the 'same' function 3 times cuz after 4 rotation it'll be 360 rotation which will give us the default matrix
        return False
    
    def rotate(self, mat) -> [list[list]]:
        """This takes matrix as an input and rotates it."""
        n = len(mat)
        m = len(mat[0])
        matb = [[0 for _ in range(n)] for _ in range(m)] # O(m * n)
        for i in range(n): # O(m * n)
            for j in range(m):
                matb[j][n - i - 1] = mat[i][j]
        return matb
    
    def same(self, mat, target):
        """This function checks whether the given two matrices are same or not?"""
        if len(mat) == len(target) and len(mat[0]) == len(target[0]):
            for i in range(len(mat)):
                for j in range(len(mat[0])):
                    if mat[i][j] != target[i][j]:
                        return False
        return True

