class Solution:
    def canEat(self, candiesCount: List[int], queries: List[List[int]]) -> List[bool]:
        n = len(candiesCount)
        prefix_sum = [0] * n
        prefix_sum[0] = candiesCount[0]
        for i in range(1, n):
            prefix_sum[i] = prefix_sum[i-1] + candiesCount[i]
        
        ans = []
        for fav_type, fav_day, limit in queries:
            earliest_day = prefix_sum[fav_type-1] // limit
            latest_day = prefix_sum[fav_type] - 1
            ans.append(earliest_day <= fav_day <= latest_day)
        
        return ans

