def minPushes(grid):
    rows = len(grid)
    cols = len(grid[0])
    box_pos = None
    target_pos = None
    player_pos = None
    walls = set()

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'B':
                box_pos = (i,j)
            elif grid[i][j] == 'T':
                target_pos = (i,j)
            elif grid[i][j] == 'S':
                player_pos = (i,j)
            elif grid[i][j] == '#':
                walls.add((i,j))

    def adjacent_positions(pos):
        (x,y) = pos
        return [(x-1,y), (x+1,y), (x,y-1), (x,y+1)]

    def move_player(pos, direction):
        (x,y) = pos
        (dx,dy) = direction
        new_pos = (x+dx, y+dy)
        if new_pos in walls:
            return None
        elif new_pos == box_pos:
            new_box_pos = (x+2*dx, y+2*dy)
            if new_box_pos in walls or new_box_pos == box_pos:
                return None
            else:
                return (new_pos, new_box_pos)
        else:
            return (new_pos, box_pos)

    queue = [(player_pos, box_pos)]
    distances = {(player_pos, box_pos): 0}

    while queue:
        (cur_player_pos, cur_box_pos) = queue.pop(0)
        cur_dist = distances[(cur_player_pos, cur_box_pos)]
        for direction in [(0,-1),(0,1),(1,0),(-1,0)]:
            new_positions = move_player(cur_player_pos, direction)
            if new_positions is not None and new_positions not in distances:
                distances[new_positions] = cur_dist + 1
                queue.append(new_positions)
                if new_positions[1] == target_pos:
                    return cur_dist + 1

    return -1

def subarray(nums, k, threshold):
    curr_sum = sum(nums[:k])
    count = 0
    for i in range(k, len(nums)):
        if curr_sum < threshold:
            curr_sum += nums[i] - nums[i-k]
        if curr_sum >= threshold*k:
            count += 1
    return count if count > 0 else -1

