def minSpaceWasted(nums: List[int], k: int) -> int:
    def wasted(space: int) -> bool:
        count = cur = 0
        for num in nums:
            if cur + num > space:
                count += 1
                cur = 0
            cur += num
        count += 1
        return count <= k
    
    l, r = max(nums), sum(nums)
    while l < r:
        mid = (l + r) // 2
        if wasted(mid):
            r = mid
        else:
            l = mid + 1
    ans = cur = 0
    for num in nums:
        if cur + num > l:
            ans += cur
            cur = 0
        cur += num
    ans += cur * (cur > 0)
    ans += (l - cur) * (k - len(nums))
    return ans

