class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        class Node:
            def __init__(self, n):
                self.n = n
                self.neighbors = []
                self.is_visit = False
                
            def neighbors_gen(self):
                def gen(neighbors=self.neighbors):
                    for n in self.neighbors:
                        yield n
                        
                return gen()
            
        dirt_set = set()
        node_dict = {}
        ''' key as n; value as corresponding node obj'''
        
        for s, e in connections:
            if s not in node_dict:
                node_dict[s] = Node(s)
                
            if e not in node_dict:
                node_dict[e] = Node(e)
                
            node_dict[s].neighbors.append(node_dict[e])
            node_dict[e].neighbors.append(node_dict[s])
            dirt_set.add((s, e))
            
        # BFS
        ans = 0
        znode = node_dict[0]
        queue = [znode]
        reverse_set = set()
        while queue:
            n = queue.pop(0)
            if n.is_visit:
                continue
                
            n.is_visit = True
            for nn in n.neighbors_gen():
                if not nn.is_visit:
                    queue.append(nn)
                    path = (nn.n, n.n)
                    if path not in dirt_set and path not in reverse_set:
                        # print(f"Path found: {path}")
                        ans += 1
                        reverse_set.add(path)
                        
        return ans

