class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        graph = defaultdict(list)
        for c in connections:
            graph[c[0]].append((c[1], 1))  # current direction
            graph[c[1]].append((c[0], 0))  # opposite direction

        visited = set()
        count = 0

        def dfs(curr):
            nonlocal count
            visited.add(curr)
            for neigh, is_forward in graph[curr]:
                if neigh not in visited:
                    if not is_forward:  # need to change direction
                        count += 1
                    dfs(neigh)

        dfs(0)
        return count

