def paint_maximum(cost: List[int], target: int) -> str:
    dp = [[0 for _ in range(target+1)] for _ in range(len(cost)+1)]
    for i in range(1, len(cost)+1):
        for j in range(1, target+1):
            if cost[i-1] > j:
                dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-cost[i-1]]+1)
    if dp[len(cost)][target] == 0:
        return "0"
    # Construct the actual answer array
    ans = ""
    i, j = len(cost), target
    while i > 0 and j > 0:
        if dp[i][j] == dp[i-1][j]:
            i -= 1
        else:
            ans += str(i)
            j -= cost[i-1]
    while len(ans) < len(cost):
        ans += "0"
    return ans[::-1]

