class Solution:
    def __init__(self):
        self.max_size = 0
    
    def bitwiseCombinations(self, candidates: List[int], index: int, current_combination: int) -> None:
        # Base case
        if index == len(candidates):
            # Evaluate the current combination
            current_bitwise = current_combination
            for num in candidates:
                current_bitwise &= num
            # Update max size if current combination bitwise is greater than 0
            if current_bitwise > 0:
                self.max_size = max(self.max_size, bin(current_combination).count('1'))
            return
        
        # Include the current number in the combination
        self.bitwiseCombinations(candidates, index+1, current_combination | candidates[index])
        
        # Exclude the current number from the combination
        self.bitwiseCombinations(candidates, index+1, current_combination)
        
    def largestBitwise(self, nums: List[int]) -> int:
        self.max_size = 0
        self.bitwiseCombinations(nums, 0, 0)
        return self.max_size

