class Solution:
	def checkOnesSegment(self, s: str) -> bool:
		count = allones = 0
		length = len(s)
		# code is simple, just check for inflection points as it would be a different segment
		# however, in the case where no inflection points exists, utilize allones to return True
		for i in range(length-1):
			if s[i] == "1" and s[i+1] == "0": 
				count+=1

			elif s[i] == "0" and s[i+1] == "1":
				count+=1

			if s[i] == "1":
				allones+=1

		# let s=="1110" or s=="1111", it handles both cases as no new segments are made.
		# why add 1 to allones? Cuz the loop above was length-1 so it excluded the last digit. It doesn't matter whether its "0" or "1" for the last digit as there would still be one segment only: e.g. "1110" or "1111"
		if allones+1 == length:
			return True

		return count == 1 # one inflection point as the question requires only one segment

