                        r+=1
                        count+=1
                    else:
                        ans.append(count)
                        count = 0
                        break
                elif s[j]=="U":
                    if r>0:
                        r-=1
                        count+=1
                    else:
                        ans.append(count)
                        count = 0
                        break
            if count==len(s):
                ans.append(count)
                count = 0
            r = startPos[0]
            c = startPos[1]
            s = s[1:]
        return ans

