def robotGrid(n, startPos, s):
    row, col = startPos
    directions = {'L': (0, -1), 'R': (0, 1), 'U': (-1, 0), 'D': (1, 0)}
    answer = []
    for i in range(len(s)):
        move = directions[s[i]]
        newRow = row + move[0]
        newCol = col + move[1]
        if newRow < 0 or newRow >= n or newCol < 0 or newCol >= n:
            break
        row, col = newRow, newCol
        answer.append(i+1)
    return answer

def f(s):
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1
    min_char, min_freq = None, float('inf')
    for char in sorted(freq):
        if freq[char] < min_freq:
            min_char = char
            min_freq = freq[char]
    return min_freq

def count_words(words, query):
    count = 0
    for word in words:
        if f(query) < f(word):
            count += 1
    return count

