    while len(set(values)) != 1:
        maxFreq = max(freq.values())
        for key, value in freq.items():
            if value == maxFreq:
                freq[key] -= 1
                count += 1
                if freq[key] == 0:
                    del freq[key]
                    values.remove(maxFreq)
                    break
                values[values.index(maxFreq)] -= 1
                break
    return count

