def max_score(nums: List[int], multipliers: List[int]) -> int:
    memo = {}
    m = len(multipliers)
    n = len(nums)
    
    def dfs(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        
        k = n - (j - i + 1)
        if k == m:
            return 0
        
        res = max(multipliers[k] * nums[i] + dfs(i+1, j),
                  multipliers[k] * nums[j] + dfs(i, j-1))
        memo[(i, j)] = res
        return res
    
    return dfs(0, n-1)

