def intersect(quadTree1, quadTree2):
    if quadTree1.isLeaf:
        return quadTree1 if quadTree1.val or not quadTree2.isLeaf or not quadTree2.val else quadTree2
    elif quadTree2.isLeaf:
        return quadTree2 if quadTree2.val or not quadTree1.isLeaf or not quadTree1.val else quadTree1
    else:
        topLeft = intersect(quadTree1.topLeft, quadTree2.topLeft)
        topRight = intersect(quadTree1.topRight, quadTree2.topRight)
        bottomLeft = intersect(quadTree1.bottomLeft, quadTree2.bottomLeft)
        bottomRight = intersect(quadTree1.bottomRight, quadTree2.bottomRight)
        if topLeft.isLeaf and topRight.isLeaf and bottomLeft.isLeaf and bottomRight.isLeaf and topLeft.val == topRight.val == bottomLeft.val == bottomRight.val:
            return Node(topLeft.val, True)
        else:
            return Node(False, False, topLeft, topRight, bottomLeft, bottomRight)

def min_sum_of_lengths(arr, target):
    left = {0: 0}
    right = {}
    sums = 0
    pos = float('inf')
    res = float('inf')
    for i, num in enumerate(arr):
        sums += num
        if sums - target in left:
            pos = min(pos, i - left[sums - target] + 1)
        left[sums] = i + 1
        if sums - target in right:
            res = min(res, right[sums - target] + i + 1)
        right[sums] = min(right.get(sums, float('inf')), i)
    return res if res != float('inf') and pos != float('inf') else -1

