def min_time_to_remove_illegal_cars(s):
    l, r = 0, len(s)-1
    while l <= r and s[l] == '0':
        l += 1
    while r >= l and s[r] == '0':
        r -= 1
    if l > r:
        return 0
    ones = 0
    for i in range(l, r+1):
        if s[i] == '1':
            ones += 1
    if ones == 0:
        return 0
    if ones == r - l + 1:
        return r - l + 1
    res = float('inf')
    for i in range(l, r+1):
        j = i
        while j <= r and s[j] == '1':
            j += 1
        res = min(res, j-i-1+min(i-l, r-j))
        i = j
    return res

