import heapq

def min_difficulty(nums, k):
    if len(nums) < k:
        return -1
    nums.sort()
    heap = []
    for i in range(k):
        heapq.heappush(heap, nums[i])
    res = float('inf')
    for i in range(k, len(nums)):
        res = min(res, heapq.heappop(heap))
        heapq.heappush(heap, nums[i])
    while heap:
        res = min(res, heapq.heappop(heap))
    return res

