def numWays(steps: int, arrLen: int) -> int:
    MOD = 10**9 + 7
    maxPos = min(steps, arrLen-1)
    dp = [0] * (maxPos + 1)
    dp[0] = 1
    for i in range(steps):
        nextDp = [0] * (maxPos + 1)
        for j in range(maxPos+1):
            nextDp[j] = dp[j]
            if j > 0:
                nextDp[j] = (nextDp[j] + dp[j-1]) % MOD
            if j < maxPos:
                nextDp[j] = (nextDp[j] + dp[j+1]) % MOD
        dp = nextDp
    return dp[0]

