    n = len(boxes)
    left = [0] * n
    right = [0] * n
    ans = [0] * n
    if boxes[0] == '1':
        left[0] = 1
    if boxes[n-1] == '1':
        right[n-1] = 1
    for i in range(1, n):
        if boxes[i] == '1':
            left[i] = left[i-1] + 1
        else:
            left[i] = left[i-1]
    for i in range(n-2, -1, -1):
        if boxes[i] == '1':
            right[i] = right[i+1] + 1
        else:
            right[i] = right[i+1]
    for i in range(n):
        ans[i] = left[i] + right[i]
    return ans

