def smallest_subsequence(s, k, letter, repetition):
    freq = s.count(letter)
    if freq < repetition:
        return ""
    idx = s.index(letter)
    while freq > repetition and idx != -1:
        s = s[idx+1:]
        idx = s.find(letter)
        freq -= 1
    if freq < repetition:
        return ""
    subseq = ""
    for i, char in enumerate(s):
        if char == letter:
            if k == 1:
                return subseq + letter
            subseq += letter + smallest_subsequence(s[i+1:], k-1, letter, repetition-1)
            break
    if not subseq:
        return ""
    if len(subseq) < k:
        diff = k - len(subseq)
        subseq += s[:diff]
    return subseq

