        cols = len(mat[0])
        dp = [[False for _ in range(5001)] for _ in range(rows)]
        dp[0] = [False] * 5001
        for j in range(cols):
            dp[0][mat[0][j]] = True
        
        for i in range(1, rows):
            for j in range(cols):
                for k in range(5001):
                    if dp[i - 1][k]:
                        dp[i][k + mat[i][j]] = True
        ans = float("inf")
