def find_shortest_path(root, startValue, destValue):
    def get_path(node, path, destValue):
        if not node:
            return False
        path.append(node.value)
        if node.value == destValue:
            return True
        if (node.left and get_path(node.left, path, destValue)) or (node.right and get_path(node.right, path, destValue)):
            return True
        path.pop()
        return False

    path1 = []
    get_path(root, path1, startValue)

    path2 = []
    get_path(root, path2, destValue)

    i = 0
    while i < len(path1) and i < len(path2) and path1[i] == path2[i]:
        i += 1

    path = path1[i - 1::-1] + path2[i:]

    directions = ''
    for i in range(1, len(path)):
        if root.left and path[i] == root.left.value:
            root = root.left
            directions += 'L'
        elif root.right and path[i] == root.right.value:
            root = root.right
            directions += 'R'
        else:
            root = root.left if root.left and path[i] in get_path(root.left, [], path[i + 1]) else root.right
            directions += 'U'

    return directions

def min_abs_diff(nums):
    n = len(nums) // 2
    sums = [0] * (n+1)
    for i in range(1, n+1):
        sums[i] = sums[i-1] + nums[i-1]
    for i in range(1, n+1):
        sums[i] += nums[n+i-1]
    dp = [[float("inf")] * (sums[-1]+1) for _ in range(n+1)]
    dp[0][0] = 0
    for i in range(1, n+1):
        for j in range(sums[i-1]+1):
            if j >= nums[i-1]:
                dp[i][j] = min(dp[i][j], dp[i-1][j-nums[i-1]])
            dp[i][j] = min(dp[i][j], dp[i-1][j] + nums[i-1])
    return dp[n][sums[-1] // 2]

