class Solution:
    def winnerOfGame(self, colors: str) -> bool:
        if len(colors) < 3:
            return False
        bobsTurn = []
        alicesTrun = []
        currLetter = colors[0]
        count = 0
        for i in range(len(colors)):
            if colors[i] == currLetter:
                count +=1
                if i+1 >= len(colors):
                    if currLetter == 'B':
                        bobsTurn.append(count)
                    else:
                        alicesTrun.append(count)
                continue
            else:
                if currLetter == 'B':
                    bobsTurn.append(count)
                else:
                    alicesTrun.append(count)
                currLetter = colors[i]
                count = 1
                continue
        
        bobTotal = 0
        aliceTotal = 0
        for i in bobsTurn:
            p = i - 2
            if p < 0 : continue
            bobTotal += i - 2
        for i in alicesTrun:
            p = i - 2
            if p < 0 : continue
            aliceTotal += i - 2
 
        return aliceTotal > bobTotal

