class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> TreeNode:
        def buildTreeRec(preorder, inorder):
            if not inorder:
                return None
            root = TreeNode(preorder.pop(0))
            index = inorder.index(root.val)
            root.left = buildTreeRec(preorder, inorder[:index])
            root.right = buildTreeRec(preorder, inorder[index+1:])
            return root
        
        return buildTreeRec(preorder, inorder)

