def palindrome(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = True
    for i in range(n - 1):
        dp[i][i + 1] = (s[i] == s[i + 1])
    for k in range(3, n + 1):
        for i in range(n - k + 1):
            j = i + k - 1
            dp[i][j] = dp[i + 1][j - 1] and (s[i] == s[j])
    return dp

def max_product(s):
    dp = palindrome(s)
    n = len(s)
    res = 0
    for i in range(n):
        for j in range(i + 1, n):
            if dp[i][j]:
                for k in range(j + 2, n):
                    for l in range(k + 1, n):
                        if dp[k][l]:
                            res = max(res, (j - i + 1) * (l - k + 1))
    return res

