def find_smallest_string(s, b, num_operations):
    min_s = s
    for i in range(num_operations):
        s_add = apply_operation(s, b, i+1)
        s_rotate = apply_operation(s[::-1], b, i+1)[::-1]
        min_s = min(min_s, s_add, s_rotate)
    return min_s

def minSwaps(root):
    levels = []
    queue = [(root, 0)]
    while queue:
        node, level = queue.pop(0)
        if len(levels) <= level:
            levels.append([])
        levels[level].append(node)
        if node.left:
            queue.append((node.left, level + 1))
        if node.right:
            queue.append((node.right, level + 1))
    result = 0
    for level in range(1, len(levels)):
        for i in range(len(levels[level])):
            if levels[level][i].val < levels[level-1][i//2].val:
                j = i
                while j > 0 and levels[level][j].val < levels[level-1][(j-1)//2].val:
