def minOperation(s): 
    n = len(s) 
  
    # make string alternating 
    s1 = '' 
    s2 = '' 
    for i in range(n): 
        s1 += '01'[i % 2] 
        s2 += '10'[i % 2] 
  
    # count number of type-2 operations needed to make s alternating with s1 
    cnt1 = 0
    for i in range(n): 
        if s[i] != s1[i]: 
            cnt1 += 1
  
    # count number of type-2 operations needed to make s alternating with s2 
    cnt2 = 0
    for i in range(n): 
        if s[i] != s2[i]: 
            cnt2 += 1
  
    return min(cnt1, cnt2)

def min_swaps(s):
