def max_product_palindromic_subsequences(s):
    def is_palindrome(sub):
        return sub == sub[::-1]
    
    subsets = set()
    for i in range(len(s)):
        for j in range(i+1, len(s)):
            if s[i] == s[j]:
                sub = s[i:j+1]
                if is_palindrome(sub):
                    subsets.add(sub)
                    
    max_product = 0
    for sub1 in subsets:
        for sub2 in subsets:
            if set(sub1).isdisjoint(set(sub2)):
                product = len(sub1) * len(sub2)
                if product > max_product:
                    max_product = product
                    
    return max_product

