class Solution:
    def numOfPairs(self, nums: List[str], target: str) -> int:
        import collections
        
        
        def prefix_function(string: str) -> list[int]:
            """Return prefix function for string. O(n)

            :param string: input string.
            :return:
            """
            result = [0] * len(string)

            result[0] = 0
            for i in range(1, len(string)):
                k = result[i - 1]
                while k > 0 and string[i] != string[k]:
                    k = result[k-1]
                if string[i] == string[k]:
                    k += 1
                result[i] = k

            return result
        
        def string_period(string: str) -> int:
            """Return length period of string. O(n)

            :param string: input string.
            :return: 
            """
            pi = prefix_function(string)

            n = len(string)
            k = n - pi[-1]
            if n % k == 0:
                return k
            else:
                return n
            
        # First step
        content = []
        for num in nums:
            if target.startswith(num):
                is_prefix = True
            else:
                is_prefix = False
            
            if target.endswith(num):
                is_suffix = True
            else:
                is_suffix = False
            
            content.append((len(num), is_prefix, is_suffix))
        
		# Second step
        cnt = collections.Counter()
        for length, is_prefix, _ in content:
            if is_prefix:
                cnt[length] += 1
        
		# Third step
        n = len(target)
        period = string_period(target)
        result = 0
        for length, is_prefix, is_suffix in content:
            if is_suffix:
                value = cnt[n - length]
                
                if value > 0:
                    if n == 2*length and length % period == 0:
                        value -= 1

                    result += value
        
        return result

