class Solution:
    def getConcatenation(self, nums: List[str], target: str) -> List[Tuple[int, int]]:
        num_indices = {}
        for i, num in enumerate(nums):
            num_indices[num] = i
        result = []
        for i, num in enumerate(nums):
            for j, digit in enumerate(num):
                # If the digit is at the end of the number or the number
                # is shorter than the target, skip it
                if j == len(num) - 1 or len(num) < len(target):
                    continue
                # Get the remaining digits after the current digit
                remainder = num[j+1:]
                # If the remaining digits are in the num_indices dict,
                # check if their concatenated string equals target
                if remainder in num_indices:
                    index = num_indices[remainder]
                    if num + nums[index] == target:
                        result.append((i, index))
        return result

