from collections import deque

class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])
        q = deque([(mat, 0)])
        visited = set()

        while q:
            curr_mat, steps = q.popleft()
            if self.is_zero_mat(curr_mat):
                return steps

            for i in range(m):
                for j in range(n):
                    nxt_mat = self.flip_neighbors(curr_mat, i, j)
                    if str(nxt_mat) not in visited:
                        visited.add(str(nxt_mat))
                        q.append((nxt_mat, steps+1))

        return -1

    def flip_neighbors(self, mat, i, j):
        nxt_mat = [row[:] for row in mat]
        directions = [(0,1), (1,0), (-1,0), (0,-1)]

        nxt_mat[i][j] ^= 1
        for dx, dy in directions:
            nxt_i, nxt_j = i + dx, j + dy
            if 0 <= nxt_i < len(mat) and 0 <= nxt_j < len(mat[0]):
                nxt_mat[nxt_i][nxt_j] ^= 1

        return nxt_mat

    def is_zero_mat(self, mat):
        return all(all(cell == 0 for cell in row) for row in mat)

