def findCriticalAndPseudoCriticalEdges(n: int, edges: List[List[int]]) -> List[List[int]]:
    def find(parent, i):
        if parent[i] != i:
            parent[i] = find(parent, parent[i])
        return parent[i]
    def union(parent, rank, x, y):
        x_root, y_root = find(parent, x), find(parent, y)
        if x_root == y_root:
            return False
        if rank[x_root] < rank[y_root]:
            parent[x_root] = y_root
        elif rank[x_root] > rank[y_root]:
            parent[y_root] = x_root
        else:
            parent[y_root] = x_root
            rank[x_root] += 1
        return True

    N = len(edges)
    for i in range(N):
        edges[i].append(i)
    
    edges.sort(key=lambda x:x[2])

    mst_value = 0
    parent = [i for i in range(n)]
    rank = [1 for i in range(n)]
    for i in range(N):
        if union(parent, rank, edges[i][0], edges[i][1]):
            mst_value += edges[i][2]

    critical = set()
    pseudo_critical = set()

    for k in range(N):
        # try removing edge k
        value_without_edge_k = 0
        parent = [i for i in range(n)]
        rank = [1 for i in range(n)]
        for i in range(N):
            if i == k:
                continue
            if union(parent, rank, edges[i][0], edges[i][1]):
                value_without_edge_k += edges[i][2]

        if mst_value != value_without_edge_k:
            critical.add(edges[k][3])
            continue

        # if k is not a critical edge, check if it is a pseudo-critical edge
        parent = [i for i in range(n)]
        rank = [1 for i in range(n)]
        union(parent, rank, edges[k][0], edges[k][1])
        value_with_edge_k = edges[k][2]
        for i in range(N):
            if i == k:
                continue
            if union(parent, rank, edges[i][0], edges[i][1]):
                value_with_edge_k += edges[i][2]

        if value_with_edge_k == mst_value:
            pseudo_critical.add(edges[k][3])

    return [list(critical), list(pseudo_critical)]

