def count_ways(n,k):
    dp = [[0 for _ in range(k+1)] for __ in range(n+1)]
    dp[1][0] = 1
    for i in range(2,n+1):
        for j in range(k+1):
            for l in range(1,i):
                if j-l >= 0:
                    dp[i][j] = (dp[i][j] + dp[i-l][j-l]) % MOD
    return dp[n][k]

