def minimumInteger(num: str, k: int) -> str:
    num = list(num)
    n = len(num)
    for i in range(n):
        if k == 0:
            break
        if i == n - 1:
            if k % 2 == 1:
                num[n-1], num[n-2] = num[n-2], num[n-1]
            break
        min_idx = i
        for j in range(i+1, min(n, i+k+1)):
            if num[j] < num[min_idx]:
                min_idx = j
        k -= min_idx - i
        while min_idx > i:
            num[min_idx], num[min_idx-1] = num[min_idx-1], num[min_idx]
            min_idx -= 1
    return "".join(num)

