                name_time[name] = []
            name_time[name].append(time)
        
        for name in name_time:
            times = sorted(name_time[name])
            for i in range(2, len(times)):
                if self.is_alert(times[i-2], times[i]):
                    alerts.append(name)
                    break
        
        return sorted(set(alerts))
    
    def is_alert(self, t1: str, t2: str) -> bool:
        time1 = self.to_minutes(t1)
        time2 = self.to_minutes(t2)
        return time2 - time1 <= 60
    
    def to_minutes(self, t: str) -> int:
        h, m = map(int, t.split(':'))
        return h * 60 + m

