class Solution:
    def getProbability(self, balls: List[int]) -> float:
        n = sum(balls)//2
        
        @cache 
        def fn(i, s0, s1, c0, c1):
            """Return number of ways to distribute boxes successfully (w/o considering relative order)."""
            if s0 > n or s1 > n: return 0 # impossible 
            if i == len(balls): return int(c0 == c1)
            ans = 0 
            for x in range(balls[i]+1): 
                ans += fn(i+1, s0+x, s1+balls[i]-x, c0+(x > 0), c1+(x < balls[i])) * comb(balls[i], x)
            return ans
        
        return fn(0, 0, 0, 0, 0) / comb(2*n, n)

GPT Answer:
from math import comb

def getProbability(balls):
    n = len(balls) // 2
    total_comb = comb(sum(balls), n)
    box1 = {}
    box2 = {}
    for ball, count in enumerate(balls):
        for i in range(count):
            if len(box1.get(ball, [])) < n:
                box1.setdefault(ball, []).append(i)
            else:
                box2.setdefault(ball, []).append(i)
    box1_distinct = len(box1)
    box2_distinct = len(box2)
    if box1_distinct + box2_distinct < n:
        return 0
    box1_comb = sum(comb(len(position), n) for position in box1.values())
    box2_comb = sum(comb(len(position), n) for position in box2.values())
    valid_distribution_comb = box1_comb * box2_comb
    prob = valid_distribution_comb / total_comb
    return round(prob, 5)

