class Solution:
    def nodesBetweenCriticalPoints(self, head: Optional[ListNode]) -> List[int]:
        '''
        5->3->1->2->5->1->2
              C     C. C
        c = [2,4,5]
        '''
        if head.next.next is None:
            return [-1,-1]
        
        def calc(head):
            prev = head
            temp = head.next
            while temp:
                next_node = temp.next
                if next_node is not None:
                    if prev.val > temp.val < next_node.val or prev.val < temp.val > next_node.val:
                        break
                    prev,temp = temp,next_node
                else:
                    break
            
            max_dis = 0
            min_dis = pow(10,5)+1
            count = 0
            mi_count = pow(10,5)+1
            while temp:
                next_node = temp.next
                if next_node is not None:
                    if prev.val > temp.val < next_node.val or prev.val < temp.val > next_node.val:
                        max_dis = count
                        min_dis = min(min_dis,mi_count)
                        mi_count = 0
                    count += 1
                    mi_count += 1
                    prev,temp = temp,next_node
                else:
                    break
            
            if max_dis != 0 and min_dis != pow(10,5)+1:        
                return [min_dis,max_dis]
            return [-1,-1]
			
        return calc(head)

class Solution:
    def minDifference(self, nums: List[int]) -> int:
        # do not need to keep indices, can safely remove duplicates
        top_vals = [float("-inf")] * 4
        bot_vals = [float("inf")] * 4

        if len(nums) <= 4:
            return 0

        def _shift_right(q, el, st):
            for l in range(len(q) - 1, st, -1):
                q[l] = q[l - 1]
            q[st] = el

        def _push_item_top(n, q):
            if n > q[0]:
                _shift_right(q, n, 0)
                return

            for i in range(0, len(q) - 1):
                if q[i + 1] < n <= q[i]:
                    _shift_right(q, n, i + 1)
                    break


        def _push_item_bot(n, q):
            if n < q[0]:
                _shift_right(q, n, 0)
                return
            
            for i in range(0, len(q) - 1):
                if q[i + 1] > n >= q[i]:
                    _shift_right(q, n, i + 1)
                    break
        
        for num in nums:
            _push_item_top(num, top_vals)
            _push_item_bot(num, bot_vals)

        ans = float("inf")
        for top_rem in range(0, 4):
            bot_rem = 3 - top_rem
            diff = top_vals[top_rem] - bot_vals[bot_rem]
            if diff >= 0 and diff < ans:
                ans = diff
        return ans

