            while(temp.next.next != None):
              temp = temp.next
            lastNode = temp.next
            temp.next = None
            lastNode = None
      #delete at given location
    def delete_at_position(self, position):
        if self.head is None:
            return
        if position == 0:
            self.head = self.head.next
            return self.head
        index = 0
        current = self.head
        prev = self.head
        temp = self.head
        while current is not None:
            if index == position:
                temp = current.next
                break
            prev = current
            current = current.next
            index += 1
        prev.next = temp
        return prev
