def find_quadruplets(arr, n, target):
    if n < 4:
        return []
    quadruplets = set()
    arr.sort()
    for i in range(n-3):
        for j in range(i+1, n-2):
            left = j+1
            right = n-1
            while left < right:
                curr_sum = arr[i] + arr[j] + arr[left] + arr[right]
                if curr_sum == target:
                    quadruplets.add((arr[i], arr[j], arr[left], arr[right]))
                    left += 1
                    right -= 1
                elif curr_sum < target:
                    left += 1
                else:
                    right -= 1
    return list(quadruplets)

