def sieve_of_eratosthenes(n):
    primes = [True] * (n+1)
    p = 2
    while p**2 <= n:
        if primes[p]:
            for i in range(p**2, n+1, p):
                primes[i] = False
        p += 1
    prime_list = []
    for i in range(2, n+1):
        if primes[i]:
            prime_list.append(i)
    return prime_list

