import itertools

def hamming(n):
    queue = []
    heapq.heappush(queue, 1)
    for _ in itertools.count():
        number = heapq.heappop(queue)
        if _ == n-1:
            return number
        for factor in [2, 3, 5]:
            heapq.heappush(queue, number * factor)

