# Tree_sort algorithm
# Build a BST and in order traverse.
class node():
    # BST data structure
    def __init__(self, val):
        self.val = val
        self.left = None 
        self.right = None 
    
    def insert(self,val):
        if self.val:
            if val < self.val:
                if self.left is None:
                    self.left = node(val)
                else:
                    self.left.insert(val)
            elif val > self.val:
                if self.right is None:
                    self.right = node(val)
                else:
                    self.right.insert(val)
        else:
            self.val = val
def inorder(root, res):
    # Recursive travesal 
    if root:
        inorder(root.left,res)
        res.append(root.val)
        inorder(root.right,res)
def treesort(arr):
    # Build BST
    if len(arr) == 0:
        return arr
    root = node(arr[0])
    for i in range(1,len(arr)):
        root.insert(arr[i])
    # Traverse BST in order. 
    res = []
    inorder(root,res)
    return res
print(treesort([7,1,5,2,19,14,17]))

GPT Answer:
def tree_sort(lst):
    class Node:
        def __init__(self, val=None):
            self.left = None
            self.right = None
            self.val = val
        
        def insert(self, val):
            if self.val is None:
                self.val = val
                return self
            if val < self.val:
                if self.left is None:
                    self.left = Node(val)
                    return self.left
                else:
                    return self.left.insert(val)
            else:
                if self.right is None:
                    self.right = Node(val)
                    return self.right
                else:
                    return self.right.insert(val)
        
        def inorder(self):
            if self.left is not None:
                yield from self.left.inorder()
            if self.val is not None:
                yield self.val
            if self.right is not None:
                yield from self.right.inorder()
    
    root = Node()
    for x in lst:
        root.insert(x)
    return list(root.inorder())

