def bitonic_sort(arr, direction):
    def merge(arr, direction):
        if len(arr) > 1:
            half = len(arr)//2
            arr_left = arr[:half]
            arr_right = arr[half:]
            if direction == "up":
                arr_left = bitonic_sort(arr_left, "up")
                arr_right = bitonic_sort(arr_right, "down")
            else:
                arr_left = bitonic_sort(arr_left, "down")
                arr_right = bitonic_sort(arr_right, "up")
            arr = arr_left + arr_right
            if direction == "up":
                arr = arr[::-1]
        return arr
    
    if len(arr) > 1:
        half = len(arr)//2
        arr_left = arr[:half]
        arr_right = arr[half:]
        if direction == "up":
            arr_left = bitonic_sort(arr_left, "up")
            arr_right = bitonic_sort(arr_right, "down")
        else:
            arr_left = bitonic_sort(arr_left, "down")
            arr_right = bitonic_sort(arr_right, "up")
        arr = merge(arr_left + arr_right, direction)
    return arr

