    if len(string) >= minimum_length:
        for char in string:
            if char.isupper():
                has_capital_letter = True
            elif char.islower():
                has_lowercase_letter = True
            elif char.isdigit():
                has_number = True
    return has_capital_letter and has_lowercase_letter and has_number

