    sum = 0
    for i in range(1, (num//2)+1):
        if(num%i==0):
            sum += i
    return sum

def are_amicable(num1, num2):
    sum1 = get_factor_sum(num1)
    sum2 = get_factor_sum(num2)
    if (sum1 == num2) and (sum2 == num1):
        return True
    else:
        return False

def sum_amicable_numbers(n):
    amicable_list = []
    for i in range(1, n+1):
        for j in range(i+1, n+1):
            if are_amicable(i,j):
                amicable_list.append(i)
                amicable_list.append(j)
