class KeyGroupIterator:
    def __init__(self, iterable):
        self.iterable = iterable
        self.index = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.index >= len(self.iterable):
            raise StopIteration

        start = self.index
        while self.index < len(self.iterable) - 1 and self.iterable[self.index] + 1 == self.iterable[self.index + 1]:
            self.index += 1

        end = self.index
        self.index += 1

        return tuple(self.iterable[start:end+1])

