def closest_sum(arr, target):
    arr.sort()
    n = len(arr)
    closest_sum = float('inf')

    for i in range(n - 2):
        left, right = i + 1, n - 1

        while left < right:
            curr_sum = arr[i] + arr[left] + arr[right]
            if abs(target - curr_sum) < abs(target - closest_sum):
                closest_sum = curr_sum

            if curr_sum < target:
                left += 1
            else:
                right -= 1

    return closest_sum

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None
    
    def insert(self, val):
        if self.root is None:
            self.root = Node(val)
        else:
            self._insert(val, self.root)
    
    def _insert(self, val, curr_node):
        if val < curr_node.val:
            if curr_node.left is None:
                curr_node.left = Node(val)
            else:
                self._insert(val, curr_node.left)
        elif val > curr_node.val:
            if curr_node.right is None:
                curr_node.right = Node(val)
            else:
                self._insert(val, curr_node.right)

    def delete(self, val):
        if self.root is None:
            return None
        else:
            self.root = self._delete(val, self.root)
    
    def _delete(self, val, curr_node):
        if val == curr_node.val:
            if curr_node.left is None and curr_node.right is None:
                return None
            elif curr_node.left is None:
                return curr_node.right
            elif curr_node.right is None:
                return curr_node.left
            else:
                min_val = self._find_min(curr_node.right)
                curr_node.val = min_val
                curr_node.right = self._delete(min_val, curr_node.right)
        elif val < curr_node.val:
            curr_node.left = self._delete(val, curr_node.left)
        elif val > curr_node.val:
            curr_node.right = self._delete(val, curr_node.right)
        return curr_node
    
    def _find_min(self, curr_node):
        while curr_node.left is not None:
            curr_node = curr_node.left
        return curr_node.val

