def odd_even_sort(arr):
    n = len(arr)
    for i in range(n):
        if i % 2 == 0:
            for j in range(0, n-1, 2):
                if arr[j] > arr[j+1]:
                    arr[j], arr[j+1] = arr[j+1], arr[j]
        else:
            for j in range(1, n-1, 2):
                if arr[j] > arr[j+1]:
                    arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

