        self.val = val
        self.left = None
        self.right = None

def sortedArrToBST(arr):
    if not arr:
        return None

    mid = len(arr) // 2

    root = Node(arr[mid])

    root.left = sortedArrToBST(arr[:mid])

    root.right = sortedArrToBST(arr[mid+1:])

    return root

import itertools

def shortest_distance(s: str, c: str) -> List[int]:
    distances = []
    for i, j in itertools.combinations(range(len(s)), 2):
        if s[i] == c or s[j] == c:
            if s[i] == s[j]:
                distances.append(abs(i-j))
            else:
                distances.append(abs(i-j)//2)
    return distances

