import inspect

def count_local_vars(func):
    source_lines = inspect.getsource(func).split("\n")
    non_comment_lines = [line for line in source_lines if not line.strip().startswith("#")]
    variable_count = 0
    
    for line in non_comment_lines:
        if "=" in line:
            variable_count += 1
    
    return variable_count

