def replace_not_poor(string):
    index_not = string.find('not')
    index_poor = string.find('poor')
    if index_not != -1 and index_poor != -1 and index_not < index_poor:
        return string[:index_not] + 'good' + string[index_poor+4:]
    else:
        return string

