lst = [3, 6, 1, 8, 4, 9, 2]

def flip(lst, k):
    for i in range(k // 2):
        lst[i], lst[k-i-1] = lst[k-i-1], lst[i]

def pancake_sort(lst):
    for size in range(len(lst), 1, -1):
        max_index = max(range(size), key=lst.__getitem__)
        if max_index != size - 1:
            flip(lst, max_index+1)
            flip(lst, size)
    return lst

