#Python program to find first repeated character in a string

def first_repeated_char(str):
    # initialize a dictionary to keep track of frequency of characters
    char_freq = {}
    # loop through each character in the string
    for char in str:
        # if the character is already in the dictionary, it is repeated
        if char in char_freq:
            return char
        # if the character is not in the dictionary, add it with frequency 1
        else:
            char_freq[char] = 1
    # if no repeated characters are found, return None
    return None

