import numpy as np

def compute_e(n):
    e_values = np.zeros(n+1)
    for i in range(n+1):
        if i == 0:
            e_values[i] = 1
        else:
            e_values[i] = e_values[i-1] + 1/np.math.factorial(i)
    return e_values[n]

