def rotate(lst, k, direction):
    if direction == 'left':
        return lst[k:] + lst[:k]
    elif direction == 'right':
        return lst[-k:] + lst[:-k]
    else:
        return None


Note: The above code assumes that `lst` is a list, `k` is a positive integer representing the number of items to rotate, and `direction` is either the string `'left'` or `'right'`.

