def multiply(a, b):
  result = 0
  sign = 1 if a * b >= 0 else -1
  a, b = abs(a), abs(b)
  while b:
    if b % 2 == 1:
      result += a
    a *= 2
    b //= 2
  return sign * result

import numpy as np

def largest_integer_division(inputs):
    arr = np.array(inputs)
    max_division = arr.min() - 1
    for x in range(arr.min() - 1, 0, -1):
        if np.remainder(arr, x).sum() == 0:
            max_division = x
            break
    return max_division

