import bisect

def find_triplet(lst):
    lst.sort()
    n = len(lst)
    for i in range(n-2):
        left = i+1
        right = n-1
        while left < right:
            total = lst[i] + lst[left] + lst[right]
            if total == 0:
                return [lst[i], lst[left], lst[right]]
            elif total < 0:
                left += 1
            else:
                right -= 1
    return []

arr = [1,-2,3,-1,0,-3]
triplet = find_triplet(arr)
