def min_window(s: str, t: str) -> str:
    if not s or not t:
        return ""

    freq_t = {}
    for char in t:
        if char in freq_t:
            freq_t[char] += 1
        else:
            freq_t[char] = 1

    l, r = 0, 0
    freq_s = {}
    formed = 0
    required = len(freq_t)
    ans = float("inf"), None, None

    while r < len(s):
        char = s[r]
        if char in freq_s:
            freq_s[char] += 1
        else:
            freq_s[char] = 1

        if char in freq_t and freq_s[char] == freq_t[char]:
            formed += 1

        while l <= r and formed == required:
            char = s[l]

            if r - l + 1 < ans[0]:
                ans = (r - l + 1, l, r)

            freq_s[char] -= 1
            if char in freq_t and freq_s[char] < freq_t[char]:
                formed -= 1

            l += 1

        r += 1

    return "" if ans[0] == float("inf") else s[ans[1] : ans[2] + 1]

