def exists_once(list1, list2, func):
    """Returns a list of elements that exist in both list1 and list2 only once
    after applying the provided function to each element"""
    
    count1 = {}
    count2 = {}
    result = []
    
    for elem in list1:
        if elem not in count1:
            count1[elem] = 1
        else:
            count1[elem] += 1
    
    for elem in list2:
        if elem not in count2:
            count2[elem] = 1
        else:
            count2[elem] += 1
    
    for elem in set(list1+list2):
        if elem in count1 and count1[elem] == 1 and elem in count2 and count2[elem] == 1:
            result.append(func(elem))
            
    return result

import itertools 

def successive_permutations(items):
    perms = itertools.permutations(items)
    for perm in perms:
        for i in range(len(items)-1):
            perm_copy = list(perm)
            perm_copy[i], perm_copy[i+1] = perm_copy[i+1], perm_copy[i]
            yield tuple(perm_copy)

