import json

def check_complexity(input_string):
    try:
        json_obj = json.loads(input_string)
        if type(json_obj) == dict:
            for key in json_obj:
                if type(json_obj[key]) in [list, dict]:
                    return True
            return False
        elif type(json_obj) == list:
            for item in json_obj:
                if type(item) in [list, dict]:
                    return True
            return False
        else:
            return False
    except json.JSONDecodeError:
        return False

