import numpy as np

def gaussian(x,y,mu,sigma):
    return np.exp(-(x-mu)**2/(2*sigma**2) - (y-mu)**2/(2*sigma**2))

def gaussian_array(n,mu=0,sigma=1):
    x,y = np.meshgrid(np.arange(n),np.arange(n))
    return gaussian(x,y,mu,sigma)

