def find_max_values(d, n):
    sorted_vals = sorted(d.values(), reverse=True)
    max_vals = []
    for val in sorted_vals:
        if len(max_vals) == n:
            break
        for key, value in d.items():
            if value == val:
                max_vals.append((key, val))
                break
    return max_vals

