def find_triplets(arr):
    n = len(arr)
    arr.sort()
    
    triplets = []
    
    for i in range(n-2):
        if i > 0 and arr[i] == arr[i-1]:
            continue
        
        j = i+1
        k = n-1
        
        while j < k:
            s = arr[i] + arr[j] + arr[k]
            if s == 0:
                triplets.append([arr[i], arr[j], arr[k]])
                j += 1
                k -= 1
                while j < k and arr[j] == arr[j-1]:
                    j += 1
                while j < k and arr[k] == arr[k+1]:
                    k -= 1
            elif s < 0:
                j += 1
            else:
                k -= 1
    
    return triplets

