def comb_sort(lst):
    shrink_factor = 1.3
    gap = len(lst)
    sorted_list = False

    while not sorted_list:
        gap = int(gap / shrink_factor)
        if gap <= 1:
            gap = 1
            sorted_list = True

        i = 0
        while i + gap < len(lst):
            if lst[i] > lst[i + gap]:
                lst[i], lst[i + gap] = lst[i + gap], lst[i]
                sorted_list = False
            i += 1

    return lst

