import datetime

def group_dates(dates, k):
    groups = []
    if len(dates) % k != 0:
        dates.extend([None] * (k - (len(dates) % k))) # pad with None values to make len(dates) a multiple of k
    for i in range(0, len(dates), k):
        group = []
        for j in range(k):
            if dates[i+j] is not None:
                group.append(datetime.datetime.strptime(dates[i+j], '%Y-%m-%d'))
        groups.append(group)
    return groups

# Given a list of integers and a target number, find all unique combinations in the list where the sum of the combination equals the target number. 
# Each number in the list may only be used once in the combination.

def combinationSum(candidates, target):
    candidates.sort()
    res = []
    def dfs(nums, target, path):
        if target < 0:
            return
        if target == 0:
            res.append(path)
            return 
        for i in range(len(nums)):
            if i > 0 and nums[i] == nums[i-1]:
                continue
            dfs(nums[i+1:], target-nums[i], path+[nums[i]])
    dfs(candidates, target, [])
    return res

