    binary1_count = {}
    binary2_count = {}
    for i in range(len(binary1)):
        if binary1[i] in binary1_count:
            binary1_count[binary1[i]] += 1
        else:
            binary1_count[binary1[i]] = 1
    for i in range(len(binary2)):
        if binary2[i] in binary2_count:
            binary2_count[binary2[i]] += 1
        else:
            binary2_count[binary2[i]] = 1
    if binary1_count == binary2_count:
        return True
    else:
        return False

