def pairwise_distance(points):
    return [[math.sqrt((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2) for b in points] for a in points]

def kth_closest(points, k):
    distances = pairwise_distance(points)
    flatten_dists = [d for row in distances for d in row]
    sorted_dists = sorted(flatten_dists)
    kth_dist = sorted_dists[k - 1]
    for i, row in enumerate(distances):
        for j, dist in enumerate(row):
            if dist == kth_dist:
                return (points[i], points[j])

