class Node:
    def __init__(self, data):
        self.data = data
        self.next = None
        self.prev = None

class Stack:
    def __init__(self):
        self.head = None
        self.tail = None
        self.count = 0
    
    def is_empty(self):
        return self.count == 0
    
    def push(self, data):
        new_node = Node(data)
        if self.count == 0:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.prev = self.tail
            self.tail.next = new_node
            self.tail = new_node
        self.count += 1
    
    def pop(self):
        if self.count == 0:
            return None
        elif self.count == 1:
            data = self.head.data
            self.head = None
            self.tail = None
            self.count = 0
            return data
        else:
            data = self.tail.data
            self.tail = self.tail.prev
            self.tail.next = None
            self.count -= 1
            return data
    
    def peek(self):
        if self.count == 0:
            return None
        else:
            return self.tail.data
    
    def size(self):
        return self.count

def print_number_diamond(n):
    # Print the top half of the diamond
    for i in range(1, n+1):
        # Print the spaces
        for j in range(n-i):
            print(' ', end='')
        # Print the numbers in increasing order
        for j in range(1, i+1):
            print(j, end='')
        # Print the numbers in decreasing order
        for j in range(i-1, 0, -1):
            print(j, end='')
        # Print the spaces
        for j in range(n-i):
            print(' ', end='')
        print()

    # Print the bottom half of the diamond
    for i in range(n-1, 0, -1):
        # Print the spaces
        for j in range(n-i):
            print(' ', end='')
        # Print the numbers in increasing order
        for j in range(1, i+1):
            print(j, end='')
        # Print the numbers in decreasing order
        for j in range(i-1, 0, -1):
            print(j, end='')
        # Print the spaces
        for j in range(n-i):
            print(' ', end='')
        print()

