import datetime

def last_business_day(year, month):
    last_day = datetime.date(year, month+1, 1) - datetime.timedelta(days=1)
    while last_day.weekday() >= 5:
        last_day -= datetime.timedelta(days=1)
    holiday_list = [datetime.date(year, month, 1), datetime.date(year, month, 5)] # Add any other holidays in the month here
    while last_day in holiday_list:
        last_day -= datetime.timedelta(days=1)
    return last_day

