void string_k(string s, int k)
{
    // create the empty string
    string w = "";
    // iterate the loop till every space
    for(int i = 0; i < s.size(); i++)
    {
        if(s[i] != ' ')
         
            // append this sub string in
            // string w
            w = w + s[i];
        else {
             
            // if length of current sub
            // string w is greater than
            // k then print
            if(w.size() > k)
                cout << w << " ";
                w = "";
        }
    }
}
