# Rabin-Karp Algorithm for Pattern Searching

def rabin_karp(text, pattern):
    n = len(text)
    m = len(pattern)
    p = 0   # hash value for pattern
    t = 0   # hash value for text
    h = 1   # hash value for calculating rolling hash
    
    # hash function using ascii values of characters
    for i in range(m):
        p += ord(pattern[i])
        t += ord(text[i])
        if i != m-1:
            h = h << 1
            
    # sliding pattern over the text
    for i in range(n-m+1):
        if p == t:
            # check if pattern matches the current window
            match = True
            for j in range(m):
                if text[i+j] != pattern[j]:
                    match = False
                    break
            if match:
                print("Pattern found at index:", i)
                
        if i < n-m:
            # recalculate hash value for the next window
            t = (t - ord(text[i]) + ord(text[i+m])) * 2**1
            # to avoid negative hash value
            if t < 0:
                t += 2**64
                
