# Python code to pretty print a singly linked list

class Node:
    
    def __init__(self, val):
        self.val = val
        self.next = None
    
class LinkedList:
    
    def __init__(self):
        self.head = None
        
    def addElement(self, val):
        temp = Node(val)
        if self.head is None:
            self.head = temp
            return
        curr = self.head
        while curr.next is not None:
            curr = curr.next
        curr.next = temp
        
    def prettyPrint(self):
        curr = self.head
        while curr is not None:
            print(curr.val, end=' -> ')
            curr = curr.next
        print('NULL')
        
