def remove_duplicates(string, k):
    stack = []
    
    for i in string:
        if not stack or stack[-1][0] != i:
            stack.append([i, 1])
        else:
            last_element = stack.pop()
            last_element[1] += 1
            if last_element[1] != k:
                stack.append(last_element)
    
    result = ""
    for element in stack:
        result += element[0] * element[1]
    
    return result

