def swap(d):
    result = {}
    for key in d.keys():
        for subkey in d[key].keys():
            if subkey not in result:
                result[subkey] = {}
            result[subkey][key] = d[key][subkey]
    return result

def anagram_substring_search(txt, pat):
    pat = sorted(pat)
    result = []
    for i in range(len(txt)-len(pat)+1):
        if sorted(txt[i:i+len(pat)]) == pat:
            result.append(i)
    return result

