class CircularLinkedList:
    def __init__(self):
        self.head = None

    def add_at_beginning(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            new_node.next = self.head
        else:
            temp = self.head
            while temp.next != self.head:
                temp = temp.next
            temp.next = new_node
            new_node.next = self.head
            self.head = new_node

    def search(self, val):
        if self.head is None:
            return "Circular Linked List is empty"
        temp = self.head
        while True:
            if temp.data == val:
                return "Found"
            temp = temp.next
            if temp == self.head:
                break
        return "Not Found"

