def countDistinctSubstring(text):
    q = 101 
    d = 256 
    p = 10**9 + 7 
    n = len(text)
    h = 1
    s = set()
    for i in range(n-1):
        h = (h*d)%p
    hash_val = 0
    for i in range(n):
        hash_val = (hash_val*d + ord(text[i]))%p
        if i>=n-q:
            if hash_val in s:
                hash_val = (hash_val - ord(text[i-n+q])*h%p + p)%p
            else:
                s.add(hash_val)
                hash_val = (hash_val - ord(text[i-n+q])*h%p + p)%p
    s.add(hash_val)
    return len(s)
 
