def combSort(lst): 
    n = len(lst) 
    gap = n 
    swaps = True
    while gap != 1 or swaps == 1: 
        gap = int((gap / 1.3)) 
        if gap < 1: 
            gap = 1
        i = 0
        swaps = False
        while i+gap<n: 
            if lst[i] > lst[i + gap]: 
                lst[i], lst[i + gap] = lst[i + gap], lst[i] 
                swaps = True
            i += 1
    return lst

