def find_nth_hashed_number(n):
    hashed_numbers = [0] * (n + 1)
    h1, h2, h3 = 1, 5, 10
    i1, i2, i3 = 1, 1, 1
    for i in range(1, n + 1):
        hashed_numbers[i] = min(h1, h2, h3)
        if hashed_numbers[i] == h1:
            i1 += 1
            h1 = hashed_numbers[i1] * 2 + 1
        if hashed_numbers[i] == h2:
            i2 += 1
            h2 = hashed_numbers[i2] * 5 + 1
        if hashed_numbers[i] == h3:
            i3 += 1
            h3 = hashed_numbers[i3] * 10 + 1
    return hashed_numbers[n]

