# Node class
class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None
    
class BinaryTree:
    def __init__(self):
        self.root = None
    
    def insert(self, value):
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert(value, self.root)
    
    def _insert(self, value, curr_node):
        if value < curr_node.value:
            if curr_node.left is None:
                curr_node.left = Node(value)
            else:
                self._insert(value, curr_node.left)
        
        elif value > curr_node.value:
            if curr_node.right is None:
                curr_node.right = Node(value)
            else:
                self._insert(value, curr_node.right)
        
        else:
            print("Value already in tree!")
    
    def display(self):
        if self.root is not None:
            self._display(self.root)
    
    def _display(self, curr_node):
        if curr_node is not None:
            self._display(curr_node.left)
            print(curr_node.value)
            self._display(curr_node.right)
    
    def delete(self, value):
        if self.root is not None:
            self.root = self._delete(value, self.root)
    
    def _delete(self, value, curr_node):
        if curr_node is None:
            return curr_node
        
        if value < curr_node.value:
            curr_node.left = self._delete(value, curr_node.left)
        
        elif value > curr_node.value:
            curr_node.right = self._delete(value, curr_node.right)
        
        else:
            if curr_node.left is None:
                temp = curr_node.right
                curr_node = None
                return temp
            
            elif curr_node.right is None:
                temp = curr_node.left
                curr_node = None
                return temp
            
            temp = self._get_min_value_node(curr_node.right)
            curr_node.value = temp.value
            curr_node.right = self._delete(temp.value, curr_node.right)
        
        return curr_node
    
    def _get_min_value_node(self, curr_node):
        while curr_node.left is not None:
            curr_node = curr_node.left
        
        return curr_node
    
