def cutRod(price, n):

	memo = [0]*(n+1)

	def cutRodMemoized(price, n, memo):

		if memo[n]>0:
			return memo[n]

		if n==0:
			return 0
		max_val = float('-inf')
		for i in range(n):
			max_val = max(max_val, price[i]+cutRodMemoized(price, n-i-1, memo))

		memo[n] = max_val
		return max_val

	return cutRodMemoized(price, n, memo)

