class FibonacciHeap:
    class Node:
        def __init__(self, key):
            self.key = key
            self.degree = 0
            self.marked = False
            self.parent = self.child = self.left = self.right = self

        def fibonacci_link(self, node):
            node.left.right, self.right.left = self.right, node.left
            self.right, node.left = node, self
            node.parent, self.marked = self, False
            self.degree += 1

    def __init__(self):
        self.min_node = None
        self.num_nodes = 0

    def minimum(self):
        return self.min_node.key

    def insert(self, key):
        node = FibonacciHeap.Node(key)
        self.min_node = self._meld_lists(node, self.min_node)
        self.num_nodes += 1
        return node

    def extract_minimum(self):
        z = self.min_node
        if z is not None:
            for child in self._children_generator(z.child):
                self.min_node = self._meld_lists(self.min_node, child)
                child.parent = None
            self._remove_from_list(z)
            if z == z.right:
                self.min_node = None
            else:
                self.min_node = z.right
                self._consolidate()
            self.num_nodes -= 1
        return z

    def union(self, other):
        self.min_node = self._meld_lists(self.min_node, other.min_node)
        self.num_nodes += other.num_nodes

    def decrease_key(self, node, new_key):
        if new_key > node.key:
            raise ValueError("new key is greater than current key")
        node.key = new_key
        parent = node.parent
        if parent is not None and node.key < parent.key:
            self._cut(node, parent)
            self._cascading_cut(parent)
        if node.key < self.min_node.key:
            self.min_node = node

    def delete(self, node):
        self.decrease_key(node, float('-inf'))
        self.extract_minimum()

    def _meld_lists(self, a, b):
        if a is None:
            return b
        if b is None:
            return a
        a_right, b_right = a.right, b.right
        a.right, b.right = b_right, a_right
        a_right.left, b_right.left = b, a
        return a if a.key < b.key else b

    def _children_generator(self, first_child):
        if first_child is not None:
            current = first_child
            while True:
                yield current
                current = current.right
                if current == first_child:
                    break

    def _remove_from_list(self, node):
        node.left.right, node.right.left = node.right, node.left

    def _consolidate(self):
        max_degree = int(self.num_nodes.bit_length())
        a = [None] * (max_degree + 1)
        nodes = [node for node in self._children_generator(self.min_node)]
        for current in nodes:
            degree = current.degree
            while a[degree] is not None:
                other = a[degree]
                if current.key > other.key:
                    current, other = other, current
                current.fibonacci_link(other)
                a[degree] = None
                degree += 1
            a[degree] = current
        self.min_node = None
        for node in a:
            if node is not None:
                self.min_node = self._meld_lists(node, self.min_node)

    def _cut(self, node, parent):
        self._remove_from_list(node)
        parent.degree -= 1
        self.min_node = self._meld_lists(self.min_node, node)
        node.parent, node.marked = None, False

    def _cascading_cut(self, node):
        parent = node.parent
        if parent is not None:
            if not node.marked:
                node.marked = True
            else:
                self._cut(node, parent)
                self._cascading_cut(parent)

