def longest_palindrome(s):
    n = len(s)
    if n < 2:
        return s
    start = 0
    maxlen = 1
    dp = [[False] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = True
    for j in range(1, n):
        for i in range(j):
            if s[i] == s[j]:
                if j - i < 3:
                    dp[i][j] = True
                else:
                    dp[i][j] = dp[i + 1][j - 1]
            else:
                dp[i][j] = False
            if dp[i][j]:
                currlen = j - i + 1
                if currlen > maxlen:
                    start = i
                    maxlen = currlen
    return s[start:start + maxlen]

def binary_to_decimal(binary):
    if binary == 0:
        return 0
    else:
        return binary % 10 + 2 * binary_to_decimal(int(binary / 10))

def decimal_to_binary(decimal):
    if decimal == 0:
        return 0
    else:
        return decimal % 2 + 10 * decimal_to_binary(int(decimal / 2))

def max_diff(arr):
    n = len(arr)
    max_diff = arr[1] - arr[0]
    min_element = arr[0]
    for i in range(1, n):
        if (arr[i] - min_element > max_diff):
            max_diff = arr[i] - min_element
        if (arr[i] < min_element):
            min_element = arr[i]
    return max_diff

