def bidirectional_bubble_sort(arr):
    n = len(arr)
    left = 0
    right = n - 1

    while left < right:
        # Sort from left to right
        for i in range(left, right):
            if arr[i] > arr[i+1]:
                arr[i], arr[i+1] = arr[i+1], arr[i]

        # Decrease the right index to ignore the already sorted elements
        right -= 1

        # Sort from right to left
        for i in range(right, left, -1):
            if arr[i-1] > arr[i]:
                arr[i-1], arr[i] = arr[i], arr[i-1]

        # Increase the left index to ignore the already sorted elements
        left += 1

    return arr

