class Node:
    def __init__(self, data):
        self.left = None
        self.right = None
        self.data = data

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, data):
        if self.root is None:
            self.root = Node(data)
        else:
            self._insert(data, self.root)

    def _insert(self, data, current_node):
        if data < current_node.data:
            if current_node.left is None:
                current_node.left = Node(data)
            else:
                self._insert(data, current_node.left)
        elif data > current_node.data:
            if current_node.right is None:
                current_node.right = Node(data)
            else:
                self._insert(data, current_node.right)
        else:
            print("Value is already present in tree.")

    def search(self, data):
        if self.root:
            result = self._search(data, self.root)
            if result:
                return True
            else:
                return False
        else:
            return False

    def _search(self, data, current_node):
        if data == current_node.data:
            return True
        elif data < current_node.data and current_node.left is not None:
            return self._search(data, current_node.left)
        elif data > current_node.data and current_node.right is not None:
            return self._search(data, current_node.right)
        return False

    def delete(self, data):
        if self.root is not None:
            self.root = self._delete(data, self.root)

    def _delete(self, data, current_node):
        if current_node is None:
            return current_node

        if data == current_node.data:
            if current_node.left is None and current_node.right is None:
                return None
            elif current_node.left is None:
                return current_node.right
            elif current_node.right is None:
                return current_node.left
            else:
                temp_node = current_node.right
                while temp_node.left is not None:
                    temp_node = temp_node.left

                current_node.data = temp_node.data
                current_node.right = self._delete(temp_node.data, current_node.right)

        elif data < current_node.data:
            current_node.left = self._delete(data, current_node.left)
        else:
            current_node.right = self._delete(data, current_node.right)

        return current_node

