        if self.head == node:
            curr = self.head
            while curr.next != self.head:
                curr = curr.next
            if curr == self.head:
                self.head = None
            else:
                curr.next = self.head.next
                self.head = curr.next
        else:
            prev = None
            curr = self.head
            while curr != node:
                prev = curr
                curr = curr.next
            prev.next = curr.next

    def josephus(self, n, k):
        if not self.head:
            return
        curr = self.head
        while n > 1:
            count = 1
            while count != k:
                curr = curr.next
                count += 1
            self.delete_node(curr)
            curr = curr.next
            n -= 1
        print("The safe position is:", self.head.data)

