# Python program to find all the connected components of an undirected graph using Depth First Search (DFS)

class Graph:
    def __init__(self, V):
        self.V = V
        self.adj = [[] for i in range(V)]

    def addEdge(self, u, v):
        self.adj[u].append(v)
        self.adj[v].append(u)

    def DFS(self, v, visited, component):
        visited[v] = True
        component.append(v)
        for i in self.adj[v]:
            if not visited[i]:
                self.DFS(i, visited, component)

    def connectedComponents(self):
        visited = [False] * self.V
        components = []
        for v in range(self.V):
            if not visited[v]:
                component = []
                self.DFS(v, visited, component)
                components.append(component)
        return components

