class CircularLinkedList:
    def __init__(self):
        self.head = None
 
    # Method to add a new node at the end of the circular linked list
    def add(self, data):
        node = Node(data)
        if not self.head:
            self.head = node
            self.head.next = self.head
        else:
            current = self.head
            while current.next != self.head:
                current = current.next
            current.next = node
