    # Method to interchange two adjacent nodes in the circular linked list
    def interchange_adjacent(self, x):
        if not self.head:
            print('List is empty')
        else:
            current = self.head
            while current.next != self.head:
                if current.data == x:
                    temp = current.data
                    current.data = current.next.data
                    current.next.data = temp
                    break
                current = current.next
            if current.next.data == x:
