def radixSort(nums):
    max_num = max(nums)
    exp = 1
    while max_num // exp > 0:
        bucket = [[] for _ in range(10)]
        for num in nums:
            bucket[(num // exp) % 10].append(num)
        nums = [num for bucket_list in bucket for num in bucket_list]
        exp *= 10
    return nums

def count_set_bits(num):
