class Node:
    def __init__(self, data):
        self.data = data
        self.next = None
        
class LinkedList:
    def __init__(self):
        self.head = None
        
    def addNode(self, data):
        newNode = Node(data)
        if self.head == None:
            self.head = newNode
        else:
            last = self.head
            while last.next:
                last = last.next
            last.next = newNode
    
    def count_occurrences(self, node, data):
        if not node:
            return 0
        if node.data == data:
            return 1 + self.count_occurrences(node.next, data)
        else:
            return self.count_occurrences(node.next, data)
    
