def digits_count(n: int) -> int:
    return len(str(n))
  
def is_disarium(n: int) -> bool:
    digits = digits_count(n)
    temp = n
    total_sum = 0
    while temp > 0:
        rem = temp % 10
        total_sum += rem ** digits
        digits -= 1
        temp //= 10
    return n == total_sum

def find_nth_disarium(n: int) -> int:
    count = 0
    num = 0
    while count < n:
        num += 1
        if is_disarium(num):
            count += 1
    return num

Python Code:
def select(alist, start, end, i):
    """Find ith largest element in alist[start... end-1]."""
    if end - start <= 1:
        return alist[start]
    pivot = partition(alist, start, end)
 
    # number of elements in alist[pivot... end - 1]
    k = end - pivot
 
    if i < k:
        return select(alist, pivot + 1, end, i)
    elif i > k:
        return select(alist, start, pivot, i - k)
 
    return alist[pivot]
 
def partition(alist, start, end):
    pivot = alist[start]
    i = start + 1
    j = end - 1
 
    while True:
        while (i <= j and alist[i] <= pivot):
            i = i + 1
        while (i <= j and alist[j] >= pivot):
            j = j - 1
 
        if i <= j:
            alist[i], alist[j] = alist[j], alist[i]
        else:
            alist[start], alist[j] = alist[j], alist[start]
            return j
 
 
