def sort_descending(arr):
    n = len(arr)
    if n <= 1:
        return arr
    else:
        pivot = arr.pop()
        greater = []
        lesser = []
        for element in arr:
            if element > pivot:
                greater.append(element)
            else:
                lesser.append(element)
        return sort_descending(greater) + [pivot] + sort_descending(lesser)
    
