def is_prime(num, divisor=2):
    if num <= 2:
        return num == 2
    if num % divisor == 0:
        return False
    if divisor ** 2 > num:
        return True
    return is_prime(num, divisor + 1)

def print_primes(n, current=2):
    if current <= n:
        if is_prime(current):
            print(current)
        print_primes(n, current + 1)

