class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def insert(root, val):
    if not root:
        return Node(val)
    elif val < root.val:
        root.left = insert(root.left, val)
    else:
        root.right = insert(root.right, val)
    return root

def inorder(root, arr):
    if not root:
        return arr
    inorder(root.left, arr)
    arr.append(root.val)
    inorder(root.right, arr)
    return arr

def sort(arr):
    root = None
    for val in arr:
        root = insert(root, val)
    return inorder(root, [])

