def findMedianSortedArrays(nums1, nums2):
    # Combine both arrays into one sorted array
    arr = sorted(nums1 + nums2)
    n = len(arr)
    
    # Determine the median of the combined array
    if n % 2 == 0:
        return (arr[n // 2 - 1] + arr[n // 2]) / 2
    else:
        return arr[n // 2]

