def closest_to_zero(nums):
    nums.sort()
    left, right = 0, len(nums)-1
    closest_sum = float('inf')
    closest_pair = None
    
    while left < right:
        curr_sum = nums[left] + nums[right]
        if abs(curr_sum) < abs(closest_sum):
            closest_sum = curr_sum
            closest_pair = (nums[left], nums[right])
        if curr_sum < 0:
            left += 1
        else:
            right -= 1
    
    return closest_pair

