def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

def is_strong_number(n):
    if n == 0:
        return False
    sum = 0
    for digit in str(n):
        sum += factorial(int(digit))
    if sum == n:
        return True
    else:
        return False

