def num_digits(num):
    return len(str(num))

def is_armstrong(num):
    n = num_digits(num)
    temp = num
    sum = 0
    while temp > 0:
        digit = temp % 10
        sum += digit ** n
        temp //= 10
    if num == sum:
        return True
    else:
        return False

def find_nth_armstrong(n):
    count = 0
    num = 0
    while count < n:
        num += 1
        if is_armstrong(num):
            count += 1
    return num

