def odd_even_sort(arr):
    n = len(arr)
    sorted = False

    while not sorted:
        sorted = True

        # sort even elements
        for i in range(0, n-1, 2):
            if arr[i] > arr[i+1]:
                arr[i], arr[i+1] = arr[i+1], arr[i]
                sorted = False

        # sort odd elements
        for i in range(1, n-1, 2):
            if arr[i] > arr[i+1]:
                arr[i], arr[i+1] = arr[i+1], arr[i]
                sorted = False

    return arr

