# finding perfect squares
def perfect_squares(start, end):
    output = []
    for i in range(start, end+1):
        if (i**0.5) % 1 == 0:
            output.append(i)
    return output

# summing digits of a number less than 10
def sum_digits_less_than_10(num):
    if num < 10:
        return num
    else:
        total = 0
        while num > 0:
            total += num % 10
            num = num // 10
        return total

# combining functions to find numbers in a range that are perfect squares and have a sum of digits less than 10
def find_numbers(start, end):
    output = []
    squares = perfect_squares(start, end)
    for num in squares:
        if sum_digits_less_than_10(num) < 10:
            output.append(num)
    return output

