class TernaryHeap:
    def __init__(self):
        self.heap = []

    def parent(self, i):
        return (i - 1) // 3

    def left_child(self, i):
        return 3 * i + 1

    def middle_child(self, i):
        return 3 * i + 2

    def right_child(self, i):
        return 3 * i + 3

    def insert(self, k):
        self.heap.append(k)
        self.heapify_up(len(self.heap) - 1)

    def heapify_up(self, i):
        while i > 0 and self.heap[i] < self.heap[self.parent(i)]:
            self.heap[i], self.heap[self.parent(i)] = self.heap[self.parent(i)], self.heap[i]
            i = self.parent(i)

    def delete(self, i):
        self.heap[i], self.heap[-1] = self.heap[-1], self.heap[i]
        deleted_node = self.heap.pop()
        self.heapify_down(i)
        return deleted_node

    def heapify_down(self, i):
        while self.left_child(i) < len(self.heap):
            smallest_child = self.get_smallest_child(i)
            if self.heap[i] > self.heap[smallest_child]:
                self.heap[i], self.heap[smallest_child] = self.heap[smallest_child], self.heap[i]
                i = smallest_child
            else:
                break

    def get_smallest_child(self, i):
        children = [self.left_child(i), self.middle_child(i), self.right_child(i)]
        children = [x for x in children if x < len(self.heap)]
        return min(children, key=lambda x: self.heap[x])

