def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

def is_strong(num):
    temp = num
    sum = 0
    while temp > 0:
        digit = temp % 10
        sum += factorial(digit)
        temp //= 10
    if num == sum:
        return True
    else:
        return False
    
n = int(input("Enter a limit: "))
print("Strong numbers between 1 and ", n, " are:")
for i in range(1,n+1):
    if is_strong(i):
        print(i)

