def sum_divisors(num):
    total = 0
    for i in range(1, num):
        if num % i == 0:
            total += i
    return total

def amicable_pairs(num1, num2):
    if sum_divisors(num1) == num2 and sum_divisors(num2) == num1:
        return True
    else:
        return False

def find_amicable_pairs(start, end):
    amicable_list = []
    for i in range(start, end):
        for j in range(i+1, end):
            if amicable_pairs(i,j):
                amicable_list.append((i,j))
    return amicable_list

