def capitalize_first_last(string):
    words = string.split()
    for i in range(len(words)):
        if len(words[i]) > 1:
            words[i] = words[i][0].upper() + words[i][1:-1] + words[i][-1].upper()
        else:
            words[i] = words[i].upper()
    return ' '.join(words)

