def DFS_PostOrder(graph, start):
    visited = set()
    traverse_order = []
    
    def DFS(node):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                DFS(neighbor)
        traverse_order.append(node)
    
    DFS(start)
    
    return traverse_order[::-1]

