def lexicographic_rank(s):
    n = len(s)
    str_list = sorted(s)
    rank = 0
    
    for i in range(n):
        index = str_list.index(s[i])
        rank += index * factorial(n-1-i)
        str_list.remove(s[i])
        
    return rank + 1

def factorial(n):
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n-1)

def is_automorphic(n):
    square = n*n
    while n > 0:
        if n % 10 != square % 10:
            return False
        n //= 10
        square //= 10
    return True

def automorphic_numbers(start, end):
    result = []
    for i in range(start, end+1):
        if is_automorphic(i):
            result.append(i)
    return result

