def octalToDecimal(octal):
    decimal = 0
    length = len(octal)
    for i in range(length):
        digit = int(octal[length - 1 - i])
        decimal += digit * pow(8, i)
    return decimal

def decimalToOctal(decimal):
    if decimal == 0:
        return '0'
    octal = ''
    while decimal > 0:
        remainder = decimal % 8
        octal = str(remainder) + octal
        decimal //= 8
    return octal

def octalToDecimalRecursion(octal):
    length = len(octal)
    if length == 0:
        return 0
    return int(octal[length - 1]) * pow(8, length - 1) + octalToDecimalRecursion(octal[:length - 1])

