def detect_cycle(node, visited, parent, graph):
    visited[node] = True
    for neighbor in graph[node]:
        if not visited[neighbor]:
            if detect_cycle(neighbor, visited, node, graph):
                return True
        elif parent != neighbor:
            return True
    return False

def is_undirected_graph_contain_cycle(n, edges):
    graph = [[] for _ in range(n)]
    visited = [False] * n
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    for i in range(n):
        if not visited[i]:
            if detect_cycle(i, visited, -1, graph):
                return True
    return False

