def get_divisors_sum(n):
    div_sum = 1
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            div_sum += i
            if n // i != i:
                div_sum += n // i
    return div_sum

def find_nth_abundant_number(n):
    abundant_numbers = []
    num = 1
    while len(abundant_numbers) < n:
        if get_divisors_sum(num) > num:
            abundant_numbers.append(num)
        num += 1
    return abundant_numbers[n-1]

