def bfs_traversal(root):
    if not root:
        return []
    queue = [root]
    result = []
    while queue:
        level_size = len(queue)
        level = []
        for i in range(level_size):
            node = queue.pop(0)
            level.append(node.val)
            for child in node.children:
                queue.append(child)
        result.append(level)
    return result

