class DaryHeap:
    def __init__(self, d):
        self.heap = []
        self.d = d

    def parent(self, i):
        return (i - 1) // self.d

    def child(self, i, c):
        return self.d * i + c + 1

    def get_max(self):
        return self.heap[0]

    def extract_max(self):
        max_elem = self.heap[0]
        last_elem = self.heap.pop()
        if self.heap:
            self.heap[0] = last_elem
            self.max_heapify(0)
        return max_elem

    def insert(self, item):
        self.heap.append(item)
        i = len(self.heap) - 1
        self.sift_up(i)

    def sift_up(self, i):
        parent = self.parent(i)
        if i > 0 and self.heap[parent] < self.heap[i]:
            self.heap[parent], self.heap[i] = self.heap[i], self.heap[parent]
            self.sift_up(parent)

    def max_heapify(self, i):
        largest = i 
        for c in range(self.d):
            child = self.child(i, c)
            if child < len(self.heap) and self.heap[child] > self.heap[largest]:
                largest = child
        if i != largest:
            self.heap[i], self.heap[largest] = self.heap[largest], self.heap[i]
            self.max_heapify(largest)

