def factorial(n):
    if n == 1:
        return n
    else:
        return n * factorial(n-1)

def factorial(num):
    if num == 0:
        return 1
    else:
        return num * factorial(num - 1)

def is_strong(num):
    sum = 0
    temp = num
    while temp > 0:
        digit = temp % 10
        sum += factorial(digit)
        temp //= 10
    return sum == num

def nth_strong(n):
    count = 0
    num = 1
    while count < n:
        if is_strong(num):
            count += 1
        num += 1
    return num - 1

