def isHappy(n):
    s = set()
    while n != 1:
        n = sum(int(i) ** 2 for i in str(n))
        if n in s:
            return False
        s.add(n)
    return True


def findNthHappyNumber(n):
    count = 0
    num = 1
    while count < n:
        if isHappy(num):
            count += 1
        num += 1
    return num - 1

