def is_bipartite(graph):
    colors = {} # store color of each vertex
    # Do a depth first search on the graph, assigning colors to each vertex
    def dfs(v, color):
        colors[v] = color
        for neighbor in graph[v]:
            if neighbor not in colors:
                if not dfs(neighbor, 1 - color):
                    return False
            elif colors[neighbor] == color:
                return False
        return True

    # check bipartite from each connected component
    for vertex in graph:
        if vertex not in colors:
            if not dfs(vertex, 0):
                return False
    return True

