GPT Answer:
def lcs(X, Y, m, n, memo):
    
    if m == 0 or n == 0:
        return 0
    
    if memo[m-1][n-1] != -1:
        return memo[m-1][n-1]
        
    if X[m-1] == Y[n-1]:
        memo[m-1][n-1] = 1 + lcs(X, Y, m-1, n-1, memo)
        return memo[m-1][n-1]
    else:
        memo[m-1][n-1] = max(lcs(X, Y, m, n-1, memo), lcs(X, Y, m-1, n, memo))
        return memo[m-1][n-1]

def find_lcs(X, Y):
    m = len(X)
    n = len(Y)
    memo = [[-1 for i in range(n)] for j in range(m)]
    lcs_length = lcs(X, Y, m, n, memo)
    
    LCS = [''] * (lcs_length)
    i = m - 1
    j = n - 1
    while i >= 0 and j >= 0:
        if X[i] == Y[j]:
            LCS[lcs_length-1] = X[i]
            i -= 1
            j -= 1
            lcs_length -= 1
        elif memo[i-1][j] > memo[i][j-1]:
            i -= 1
        else:
            j -= 1
    
    return "".join(LCS)
    
X = "AGGTAB"
Y = "GXTXAYB"
print("Longest Common Subsequence is", find_lcs(X, Y))

