def select_ith_smallest(lst, i):
    # Use quickselect algorithm to find ith smallest element
    pivot = lst[0]
    left = []
    right = []
    equal = []
    for e in lst:
        if e < pivot:
            left.append(e)
        elif e > pivot:
            right.append(e)
        else:
            equal.append(e)
    k = len(left)
    if i < k:
        return select_ith_smallest(left, i)
    elif i < k + len(equal):
        return equal[0]
    else:
        return select_ith_smallest(right, i - k - len(equal))

