        j += 1
    return False

def solve_n_queen(board, row, n):
    if(row == n):
        return True
    for col in range(n):
        if(is_attack(board, row, col)):
            continue
        board[row][col] = 1
        if(solve_n_queen(board, row+1, n)):
            return True
        board[row][col] = 0
    return False

