        color = {}
        for node in self.nodes:
            color[node] = -1
        
        q = deque()
        visited = set()
        
        for node in self.nodes:
            if node not in visited:
                q.append(node)
                color[node] = 0
                
                while len(q) > 0:
                    current_node = q.popleft()
                    visited.add(current_node)
                    
