def is_prime(n, divisor=2):
    if n <= 2:
        return n == 2
    if n % divisor == 0:
        return False
    if divisor * divisor > n:
        return True
    return is_prime(n, divisor+1)

def prime_recursion(n):
    if n == 1:
        return False
    return is_prime(n) 

